  setSidebarWidth: (w: number) => void;
  saveSidebarWidth: (w: number) => void;
  showSidebar: boolean;
  setShowSidebar: (v: boolean | ((prev: boolean) => boolean)) => void;
  sidebarCollapsed: boolean;
  setSidebarCollapsed: (v: boolean | ((prev: boolean) => boolean)) => void;
}

type SettingsPage =
