        (p) => p.id.toLowerCase() === providerValue.trim().toLowerCase(),
      );
      if (match) {
        setIsCustomProvider(false);
        setCustomInputFocused(false);
        setLocalConfig((prev) => ({
          ...prev,
          provider: match.id,
