  const handleBackToList = useCallback(() => {
    setApiView("list");
    setEditingProfileId(null);
  }, []);

  const handleSaveApi = useCallback(async () => {
    if (!localConfig.baseUrl.trim()) {
      showToast({ type: "error", title: "请填写 Base URL" });
      return;
    }
    if (!localConfig.model.trim()) {
      showToast({ type: "error", title: "请填写模型名称" });
      return;
    }
    if (
      localConfig.contextWindow !== undefined &&
      (!Number.isFinite(localConfig.contextWindow) ||
        !Number.isInteger(localConfig.contextWindow) ||
        localConfig.contextWindow <= 0)
    ) {
      showToast({ type: "error", title: "上下文窗口必须是正整数" });
      return;
    }
    const keyMissing = !localConfig.apiKey.trim();
    // Store ONLY the single chosen model — NOT the full fetched list. The model
    // list is fetched live when the selector is opened (renderModelSelector), so
    // persisting the fetched list here would only create a stale cache that hides
    // newly-added models (e.g. a freshly added DeepSeek variant) until the next manual refresh.
    const profileModels = [localConfig.model].filter(Boolean) as string[];
    // Bind to current profile: update the active one, otherwise reuse a matching
    // profile or create a new named one.
    if (editingProfileId) {
      updateApiProfileConfig(editingProfileId, localConfig, profileModels);
      setActiveProfile(editingProfileId);
    } else {
      const dup = apiProfiles.find(
        (p) =>
          p.config.baseUrl === localConfig.baseUrl &&
          p.config.apiKey === localConfig.apiKey,
      );
      if (dup) {
        // Same endpoint — merge models into existing profile
        const mergedModels = [
          ...new Set([...(dup.models || []), ...profileModels]),
        ];
        updateApiProfileConfig(dup.id, localConfig, mergedModels);
        setActiveProfile(dup.id);
      } else {
        const name = deriveProviderName(
          localConfig.baseUrl,
          localConfig.model
            ? `配置 · ${localConfig.model}`
            : `配置 ${apiProfiles.length + 1}`,
        );
        const id = addApiProfile(name, localConfig, profileModels);
        setActiveProfile(id);
      }
    }
    setApiConfig(localConfig);
    // Keep activeModel in sync with the saved model. Without this the chat
    // dropdown highlight (activeModel-first) and the settings backend mirror
    // (which guards on activeModel || cur.model) would keep pinning the
    // PREVIOUS model — e.g. after saving deepseek-v4-flash while a different
    // model was active, the dropdown would never highlight it and the mirror
    // would revert the backend model back. Use the POST-snap apiConfig.model (setApiConfig
    // may correct a model/baseUrl mismatch), so activeModel can't drift from it.
    // Also re-anchor activeProviderId to the endpoint just saved: leaving it at
    // the PREVIOUS provider makes the chat dropdown's open-refetch hit the wrong
    // endpoint and scopes providerModels reads to the wrong key — the "fetched 2
    // models, selector shows only 1" bug.
    useHelixStore.setState((s) => {
      const pid = s.providers.find(
        (p) => p.baseUrl === s.apiConfig.baseUrl,
      )?.id;
      return {
        activeModel: s.apiConfig.model,
        ...(pid ? { activeProviderId: pid } : {}),
      };
    });
    // Persist the snapped (mismatch-corrected) config into history so a
    // model/baseUrl split can never be re-saved as a new history entry.
    const snapped = useHelixStore.getState().apiConfig;
    addApiHistory(snapped);
    // Clear any stale per-provider fetched model cache for this endpoint so the
    // next open of the chat model selector re-fetches live (per user request:
    // "保存时不存储模型列表"). The live fetch on open repopulates it.
    {
      const st = useHelixStore.getState();
      const pid = st.providers.find(
        (p) => p.baseUrl === localConfig.baseUrl,
      )?.id;
      if (pid) st.clearProviderModels(pid);
    }
    await persistToStorage();

    // Sync to Helix if running in Electron or Tauri
    const helix = (window as any).electron?.helix;
    if (isElectron() || helix?.setConfig) {
      try {
        const cfg = {
          model: localConfig.model,
          provider:
            localConfig.provider && localConfig.provider !== "__custom__"
              ? localConfig.provider
              : "custom",
          baseUrl: localConfig.baseUrl,
          apiKey: localConfig.apiKey,
          contextWindow: localConfig.contextWindow,
        };
        await helix.setConfig(cfg);
        // Persist the active profile so the next cold start re-asserts it
        // into Helix config.yaml (no hardcoded pin, free switching preserved).
        await (window as any).electron?.profile?.cacheConfig?.(cfg);
        // Invalidate the cached session so the next prompt creates a fresh one
        // with the updated config. Without this, a stale session ID could be
        // reused against a restarted gateway, producing 401 errors.
        useGatewayStore.getState().setHelixSessionId(null);
        showToast({
          type: "success",
          title: keyMissing
            ? "已保存并同步到 Helix（复用其已配置密钥）"
            : "API 配置已保存（已同步到 Helix）",
        });
      } catch (err) {
        showToast({
          type: "warning",
          title: "API 配置已保存（Helix 同步失败）",
        });
      }
    } else {
      showToast({ type: "success", title: "API 配置已保存" });
    }
    setApiView("list");
  }, [
    localConfig,
    editingProfileId,
    apiProfiles,
    setApiConfig,
    addApiProfile,
    updateApiProfileConfig,
    setActiveProfile,
    addApiHistory,
    persistToStorage,
    showToast,
  ]);

  const hasApiConfig = !!apiConfig.apiKey;

  // ── MCP handlers ─────────────────────────────────────────────────────────
  const mcpArgText = useCallback((v: unknown) => {
    if (typeof v === "string") return v;
    if (v === null || v === undefined) return "";
    try {
      return JSON.stringify(v);
    } catch {
      return String(v);
    }
  }, []);

  const handleReloadMcp = useCallback(async () => {
    if (reloadingMcp) return;
    setReloadingMcp(true);
    try {
      await helixApi()!.send("reload.mcp", {
        session_id: helixSessionId,
        confirm: true,
      });
      showToast({
        type: "success",
        title: "MCP 工具已重新加载",
        description: "新的工具 schema 将应用到当前会话",
      });
      setTimeout(fetchMcpStatus, 1000);
    } catch (e: any) {
      showToast({
        type: "error",
        title: "MCP 重新加载失败",
        description: String(e?.message || e),
      });
    } finally {
      setReloadingMcp(false);
    }
  }, [reloadingMcp, helixSessionId, showToast, fetchMcpStatus]);

  const resetMcpForm = useCallback(() => {
    setMcpForm({ name: "", type: "local", command: "", url: "", args: "" });
  }, []);

  const handleSaveMcp = useCallback(async () => {
    const name = mcpForm.name.trim();
    if (!name) {
      showToast({ type: "error", title: "请填写服务器名称" });
      return;
    }
    if (mcpForm.type === "local" && !mcpForm.command.trim()) {
      showToast({ type: "error", title: "请填写启动命令" });
      return;
    }
    if (mcpForm.type === "remote" && !mcpForm.url.trim()) {
      showToast({ type: "error", title: "请填写 URL" });
      return;
    }
    const api = (window as any).electron?.mcpConfig;
    if (!api?.save) {
      showToast({ type: "error", title: "当前环境不支持写入 mcp.json" });
      return;
    }
    const cmdParts = [
      mcpForm.command.trim(),
      ...mcpForm.args.trim().split(/\s+/),
    ].filter(Boolean);
    const nextCwd =
      mcpServers[editingMcpName || name]?.cwd || resolveDefaultMcpCwd();
    const old = mcpServers[editingMcpName || name] || {};
    const gatewayEntry: Record<string, any> = {
      enabled: old.enabled ?? true,
      ...(mcpForm.type === "remote"
        ? { url: mcpForm.url.trim() }
        : { command: cmdParts[0] || "" }),
      ...(mcpForm.type === "local" && cmdParts.length > 1
        ? { args: cmdParts.slice(1) }
        : {}),
      ...(Object.keys(old.environment || {}).length > 0
        ? { env: old.environment }
        : {}),
      ...(old.envPassthrough ? { env_passthrough: true } : {}),
      ...(mcpForm.type === "local" && nextCwd ? { cwd: nextCwd } : {}),
      ...(Object.keys(old.headers || {}).length > 0
        ? { headers: old.headers }
        : {}),
      ...(typeof old.timeout === "number" ? { timeout: old.timeout } : {}),
    };
    const servers: Record<string, any> = { ...gatewayMcp };
    if (editingMcpName && editingMcpName !== name)
      delete servers[editingMcpName];
    servers[name] = gatewayEntry;

    try {
      const r = await api.save(servers);
      if (!r?.ok) {
        showToast({
          type: "error",
          title: `保存失败：${r?.error || "未知错误"}`,
        });
        return;
      }
      // 新加的服务器只留在 config.yaml（网关级），不重复放进应用列表。
      if (editingMcpName && editingMcpName !== name)
        removeMcpServer(editingMcpName);
      else if (mcpServers[name]) removeMcpServer(name);
      await persistToStorage();
      await reloadGatewayMcp();
      showToast({
        type: "success",
        title: `服务器 "${name}" 已保存到 config.yaml`,
      });
      setEditingMcpName(null);
      setIsAddingMcp(false);
      resetMcpForm();
      setTimeout(fetchMcpStatus, 1000);
    } catch (e) {
      showToast({
        type: "error",
        title: `保存失败：${(e as Error)?.message || e}`,
      });
    }
  }, [
    mcpForm,
    editingMcpName,
    mcpServers,
    gatewayMcp,
    removeMcpServer,
    persistToStorage,
    reloadGatewayMcp,
    showToast,
    resetMcpForm,
    fetchMcpStatus,
    resolveDefaultMcpCwd,
  ]);

  const handleEditMcp = useCallback(
    (name: string) => {
      const config = mcpServers[name];
      if (!config) return;
      setEditingMcpName(name);
      const cmdParts = Array.isArray(config.command)
        ? config.command
        : config.command
          ? [config.command]
          : [];
      setMcpForm({
        name,
        type: config.type,
        command: cmdParts[0] || "",
        url: config.url || "",
        args: cmdParts.slice(1).map(mcpArgText).filter(Boolean).join(" "),
      });
    },
    [mcpServers, setEditingMcpName, mcpArgText],
  );

  const handleDeleteMcp = useCallback(
    async (name: string) => {
      removeMcpServer(name);
      await persistToStorage();
      showToast({ type: "info", title: `服务器 "${name}" 已删除` });
    },
    [removeMcpServer, persistToStorage, showToast],
  );

  const handleToggleMcp = useCallback(
    async (name: string) => {
      toggleMcpServer(name);
      await persistToStorage();
    },
    [toggleMcpServer, persistToStorage],
  );

  // ── Gateway MCP (config.yaml mcp_servers) edit handlers ────────────────
  const handleEditGatewayMcp = useCallback(
    (name: string) => {
      const cfg = gatewayMcp[name];
      if (!cfg) return;
      setGatewayEditing(name);
      const cmdParts = Array.isArray(cfg.command)
        ? cfg.command
        : cfg.command
          ? [cfg.command]
          : [];
      const argsArr = Array.isArray(cfg.args) ? cfg.args : [];
      setMcpForm({
        name,
        type: cfg.url ? "remote" : "local",
        command: cmdParts[0] || "",
        url: cfg.url || "",
        args: [...cmdParts.slice(1), ...argsArr]
          .map(mcpArgText)
          .filter(Boolean)
          .join(" "),
      });
    },
    [gatewayMcp, mcpArgText],
  );

  const handleSaveGatewayMcp = useCallback(async () => {
    const name = mcpForm.name.trim();
    if (!name) {
      showToast({ type: "error", title: "请填写服务器名称" });
      return;
    }
    if (mcpForm.type === "local" && !mcpForm.command.trim()) {
      showToast({ type: "error", title: "请填写启动命令" });
      return;
    }
    if (mcpForm.type === "remote" && !mcpForm.url.trim()) {
      showToast({ type: "error", title: "请填写 URL" });
      return;
    }
    const api = (window as any).electron?.mcpConfig;
    if (!api?.save) {
      showToast({ type: "error", title: "当前环境不支持保存" });
      return;
    }

    const cmdParts = [
      mcpForm.command.trim(),
      ...mcpForm.args.trim().split(/\s+/),
    ].filter(Boolean);
    const oldName = gatewayEditing;
    const oldCfg = (oldName && gatewayMcp[oldName]) || {};

    // Full-block write: carry over the original cfg so scalar overrides
    // (enabled/timeout/auth/headers) survive an edit; delete keys the form
    // cleared. env is NOT sent when untouched — the Rust side then carries
    // the old env block over, so secrets never get clobbered by a display
    // round trip (config.yaml env values are hidden from the renderer).
    const merged: Record<string, any> = { ...oldCfg };
    if (mcpForm.type === "remote") {
      merged.url = mcpForm.url.trim();
      delete merged.command;
      delete merged.args;
    } else {
      merged.command = cmdParts[0] || "";
      if (cmdParts.length > 1) merged.args = cmdParts.slice(1);
      else delete merged.args;
    }
    const nextCwd = oldCfg.cwd || resolveDefaultMcpCwd();
    if (nextCwd) merged.cwd = nextCwd;
    else delete merged.cwd;

    const servers: Record<string, any> = { ...gatewayMcp };
    if (oldName && oldName !== name) delete servers[oldName];
    servers[name] = merged;

    try {
      const r = await api.save(servers);
      if (!r?.ok) {
        showToast({
          type: "error",
          title: `保存失败：${r?.error || "未知错误"}`,
        });
        return;
      }
      showToast({ type: "success", title: `服务器 "${name}" 已保存` });
      setGatewayEditing(null);
      setIsAddingMcp(false);
      resetMcpForm();
      await reloadGatewayMcp();
      setTimeout(fetchMcpStatus, 1000);
    } catch (e) {
      showToast({
        type: "error",
        title: `保存失败：${(e as Error)?.message || e}`,
      });
    }
  }, [
    mcpForm,
    gatewayEditing,
    gatewayMcp,
    showToast,
    resetMcpForm,
    reloadGatewayMcp,
    fetchMcpStatus,
    resolveDefaultMcpCwd,
  ]);

  const handleDeleteGatewayMcp = useCallback(
    async (name: string) => {
      const api = (window as any).electron?.mcpConfig;
      if (!api?.save) {
        showToast({ type: "error", title: "当前环境不支持保存" });
        return;
      }
      const servers: Record<string, any> = { ...gatewayMcp };
      delete servers[name];
      try {
        const r = await api.save(servers);
        if (!r?.ok) {
          showToast({
            type: "error",
            title: `删除失败：${r?.error || "未知错误"}`,
          });
          return;
        }
        await reloadGatewayMcp();
        setTimeout(fetchMcpStatus, 1000);
        showToast({ type: "info", title: `服务器 "${name}" 已删除` });
      } catch (e) {
        showToast({
          type: "error",
          title: `删除失败：${(e as Error)?.message || e}`,
        });
      }
    },
    [gatewayMcp, reloadGatewayMcp, fetchMcpStatus, showToast],
  );

  const handleMcpFormChange = useCallback((patch: Partial<McpFormData>) => {
    setMcpForm((prev) => ({ ...prev, ...patch }));
  }, []);

  const handleDeleteArchive = useCallback(
    async (id: string) => {
      await persistence.deleteSession(id);
      showToast({ type: "success", title: "已删除" });
      await loadArchives();
    },
    [showToast, loadArchives],
  );

  const handleLoadArchive = useCallback(
    async (sessionId: string) => {
      const sessions = await persistence.loadSessions();
      const session = sessions.find((s) => s.id === sessionId);
      if (!session) {
        showToast({ type: "error", title: "加载失败" });
        return;
      }
      const msgs = session.chatMessages.map((msg) => ({
        id: msg.id,
        role: msg.role as "user" | "assistant" | "system",
        content: msg.content,
        timestamp: msg.timestamp,
        reasoning: msg.reasoning,
        steps: msg.steps,
        fileChanges: msg.fileChanges,
        blocks: msg.blocks,
      }));
      useHelixStore.getState().clearExecutionFlow();
      useHelixStore.setState({
        chatMessages: msgs,
        activeSessionWorkDir: session.workDir ?? null,
      });
      // selectedWorkDir 同步到恢复的对话所属项目，让 Git 分支选择器等 UI 跟随对话。
      if (session.workDir) {
        useHelixStore.getState().setSelectedWorkDir(session.workDir);
      }
      useHelixStore.getState().setCurrentSessionId(session.id);
      // 恢复 = 取消归档：把 isArchived 置回 false，让会话回到侧边栏主列表。
      // 之前只加载内容不改归档标记 → toast 显示"已恢复"但会话仍留在归档里，
      // 主列表看不到 → "实际没效果"。恢复不是新对话——savedAt 保持最后一条
      // 消息的时间。
      if (session.isArchived) {
        await persistence.saveSession({
          ...session,
          isArchived: false,
        });
      }
      await persistToStorage();
      await loadArchives();
      showToast({
        type: "success",
        title: "已恢复",
        description: session.label,
      });
    },
    [showToast, persistToStorage, loadArchives],
  );

  // ── Shared components ─────────────────────────────────────────────────────
  const SettingRow = ({
    icon,
    label,
    children,
  }: {
    icon: React.ReactNode;
    label: string;
    children: React.ReactNode;
  }) => (
    <div className="flex items-center justify-between px-4 py-3 border-b border-border/40 last:border-b-0 gap-3 transition-colors duration-150">
      <div className="flex items-center gap-3 flex-1 min-w-0">
        <span className="text-muted-foreground shrink-0">{icon}</span>
        <div className="min-w-0">
          <p className="text-[length:var(--helix-transcript-size)] font-medium text-foreground">
            {label}
          </p>
        </div>
      </div>
      <div className="shrink-0">{children}</div>
    </div>
  );

  const InputField = React.forwardRef<
    HTMLInputElement,
    {
      value: string;
      onChange: (v: string) => void;
      placeholder?: string;
      type?: string;
      className?: string;
      prefix?: React.ReactNode;
      suffix?: React.ReactNode;
    }
  >(
    (
      {
        value,
        onChange,
        placeholder,
        type = "text",
        className = "",
        prefix,
        suffix,
      },
      ref,
    ) => (
      <div
        className={`flex items-center gap-0 bg-muted/50 border border-border/50 rounded-lg focus-within:ring-2 focus-within:ring-ring ${className}`}
      >
        {prefix && <span className="pl-3 text-muted-foreground">{prefix}</span>}
        <input
          ref={ref}
          type={type}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className="flex-1 px-3 py-2 bg-transparent text-[length:var(--helix-transcript-size)] text-foreground placeholder:text-muted-foreground/40 font-mono"
        />
        {suffix && <span className="pr-3">{suffix}</span>}
      </div>
    ),
  );
  InputField.displayName = "InputField";

  // ── Render content ────────────────────────────────────────────────────────
  const ModelHistoryList = () => {
    if (apiHistory.length === 0) {
      return null;
    }

    // Group by baseUrl (preserve first-appearance order). Within a group the
    // entries share the same endpoint but may carry different apiKeys — the
    // addApiHistory dedup already collapses same baseUrl+apiKey, so each item
    // here is a distinct (baseUrl, apiKey) pair. Grouping keeps one endpoint's
    // many keys visually together instead of scattered across the flat list.
    type HistoryItem = { h: (typeof apiHistory)[number]; index: number };
    const groups: { baseUrl: string; items: HistoryItem[] }[] = [];
    const groupPos = new Map<string, number>();
    apiHistory.forEach((h, index) => {
      const url = h.baseUrl || "(无 baseUrl)";
      let pos = groupPos.get(url);
      if (pos === undefined) {
        pos = groups.length;
        groupPos.set(url, pos);
        groups.push({ baseUrl: url, items: [] });
      }
      groups[pos].items.push({ h, index });
    });

    // Whether the CURRENT connection (baseUrl + apiKey) exists in history at
    // all. Computed ONCE per render, not per entry (renderItem). The list
    // groups entries by baseUrl only, so one endpoint can hold entries saved
    // under different apiKeys. When the current connection IS present, highlight
    // only the exact key; when it's NOT (legacy keys only), fall back to
    // baseUrl+model so the highlight never orphans the whole group.
    const activeCfg = useHelixStore.getState().apiConfig;
    const connPresent =
      !!activeCfg?.baseUrl &&
      !!activeCfg?.apiKey &&
      apiHistory.some(
        (x) => x.baseUrl === activeCfg.baseUrl && x.apiKey === activeCfg.apiKey,
      );

    const renderItem = ({ h, index }: HistoryItem) => {
      // Use the same unified criterion as the chat input's model selector
      // (activeModel || apiConfig.model) so both pages always agree on which
      // model is "current". Without this, selecting a model in chat would leave
      // the settings list highlighting a stale entry (or nothing at all).
      const store = useHelixStore.getState();
      const displayModel = store.activeModel || apiConfig.model;
      const isActive =
        !!activeCfg?.baseUrl &&
        activeCfg.baseUrl === h.baseUrl &&
        displayModel === h.model &&
        (connPresent ? !!h.apiKey && h.apiKey === activeCfg.apiKey : true);
      return (
        <div
          key={index}
          onClick={async () => {
            // Write the history entry through setApiConfig first: it guards
            // against model/baseUrl mismatches (poisoned history) and snaps
            // the model to the endpoint it actually belongs to.
            setApiConfig({ ...h });
            // Then anchor activeModel/activeProviderId directly to this history
            // entry's endpoint. Don't use setActiveModel here: its model-name-based
            // resolution can pick the wrong provider when a model name also exists
            // in another provider's fetched list (e.g. cross-endpoint pollution),
            // causing an explicit deepseek click to snap back to a different provider.
            const state = useHelixStore.getState();
            let match = state.providers.find((p) => p.baseUrl === h.baseUrl);
            if (!match) {
              // This endpoint lives only in history (no saved Profile). Upsert a
              // runtime provider so the input-bar model list can resolve to it and
              // the active model stays pinned instead of snapping to the default
              // provider (a runtime-synthesized entry) after a refresh.
              const exists = state.providers.some(
                (p) => p.baseUrl === h.baseUrl,
              );
              useHelixStore.setState((s) => ({
                providers: exists
                  ? s.providers.map((p) =>
                      p.baseUrl === h.baseUrl
                        ? {
                            ...p,
                            models: Array.from(
                              new Set([...(p.models || []), h.model]),
                            ),
                          }
                        : p,
                    )
                  : [
                      ...s.providers,
                      {
                        id: `hist-${h.baseUrl}`,
                        name:
                          h.provider ||
                          (() => {
                            try {
                              return new URL(h.baseUrl).hostname;
                            } catch {
                              return "配置";
                            }
                          })(),
                        baseUrl: h.baseUrl,
                        apiKey: h.apiKey || "",
                        models: [h.model],
                        isDefault: false,
                      } as any,
                    ],
              }));
              match = useHelixStore
                .getState()
                .providers.find((p) => p.baseUrl === h.baseUrl) as any;
            }
            useHelixStore.setState({
              activeModel: h.model,
              activeProviderId: match?.id || null,
              apiConfig: {
                ...state.apiConfig,
                ...h,
                provider: match?.name || h.provider || "custom",
                model: h.model,
              },
            });
            const final = useHelixStore.getState().apiConfig;
            setLocalConfig({ ...final });
            await persistToStorage();
            const helix = (window as any).electron?.helix;
            if (isElectron() || helix?.setConfig) {
              try {
                const cfg = {
                  model: final.model,
                  provider:
                    final.provider && final.provider !== "__custom__"
                      ? final.provider
                      : "custom",
                  baseUrl: final.baseUrl,
                  apiKey: final.apiKey,
                };
                await helix.setConfig(cfg);
                await (window as any).electron?.profile?.cacheConfig?.(cfg);
                useGatewayStore.getState().setHelixSessionId(null);
              } catch { /* empty */}
            }
            showToast({ type: "success", title: `已切换到 ${final.model}` });
          }}
          className={`flex items-center justify-between px-3 py-1.5 rounded-xl bg-card shadow-sm cursor-pointer transition-colors group ${isActive ? "ring-1 ring-primary/30 bg-primary/5" : "hover:bg-muted/40"}`}
        >
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              {isActive && (
                <span className="size-1.5 rounded-full bg-primary shrink-0" />
              )}
              <p
                className={`text-[length:var(--helix-transcript-size)] truncate ${isActive ? "font-semibold text-primary" : "font-medium text-foreground"}`}
              >
                {h.model}
              </p>
            </div>
            <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/60 truncate mt-0.5 font-mono">
              {h.baseUrl}
            </p>
          </div>
          <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-all">
            <button
              onClick={(e) => {
                e.stopPropagation();
                setLocalConfig({ ...h });
                setShowAddModelModal(true);
              }}
              className="ml-2 p-1 rounded text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/20 hover:text-foreground hover:bg-accent transition-all"
            >
              编辑
            </button>
            <button
              onClick={async (e) => {
                e.stopPropagation();
                removeApiHistory(index);
                await persistToStorage();
              }}
              className="ml-1 p-1 rounded text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/20 hover:text-red-500 transition-all"
            >
              删除
            </button>
          </div>
        </div>
      );
    };

    return (
      <div className="space-y-1.5">
        {groups.flatMap((g) => g.items).map(renderItem)}
      </div>
    );
  };

  const renderContent = () => {
    switch (page) {
      case "general":
        return <GeneralSettingsPanel />;

      case "appearance":
        return (
          <AppearanceSettingsPanel
            themeStyle={themeStyle}
            onSelectThemeStyle={onSelectThemeStyle}
          />
        );

      case "api":
        return (
          <div className="space-y-6">
            {/* Title + add model */}
            <div className="flex items-center justify-between">
              <h1 className="ui-title font-semibold text-foreground tracking-tight">
                模型设置
              </h1>
              {modelTab === "main" && !showAddModelModal && (
                <button
                  onClick={() => {
                    setLocalConfig({
                      provider: "",
                      apiKey: "",
                      baseUrl: "",
                      model: "",
                    });
                    setIsCustomProvider(false);
                    setAvailableModels([]);
                    setShowModelDropdown(false);
                    setShowAddModelModal(true);
                  }}
                  className="flex items-center gap-1.5 text-[length:var(--helix-transcript-size)] font-medium text-primary hover:text-primary/80 transition-colors"
                >
                  添加模型
                </button>
              )}
              {modelTab === "main" && showAddModelModal && (
                <button
                  onClick={() => setShowAddModelModal(false)}
                  className="text-[length:var(--helix-transcript-size)] text-foreground/50 hover:text-foreground hover:bg-accent/60 rounded-lg px-2 py-1 transition-colors"
                  data-tip="关闭"
                >
                  关闭
                </button>
              )}
            </div>

            {/* Sub-tabs: 对话 / 视觉 */}
            <div className="flex items-center gap-1 bg-muted/60 rounded-full p-1 w-fit">
              <button
                onClick={() => setModelTab("main")}
                className={`px-3.5 py-1 text-[calc(var(--helix-transcript-size)*0.8571)] font-medium rounded-full transition-colors ${
                  modelTab === "main"
                    ? "bg-background text-foreground shadow-sm"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                对话
              </button>
              <button
                onClick={() => setModelTab("vision")}
                className={`px-3.5 py-1 text-[calc(var(--helix-transcript-size)*0.8571)] font-medium rounded-full transition-colors ${
                  modelTab === "vision"
                    ? "bg-background text-foreground shadow-sm"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                视觉
              </button>
              <button
                onClick={() => setModelTab("image")}
                className={`px-3.5 py-1 text-[calc(var(--helix-transcript-size)*0.8571)] font-medium rounded-full transition-colors ${
                  modelTab === "image"
                    ? "bg-background text-foreground shadow-sm"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                生图
              </button>
            </div>

            {modelTab === "main" ? (
              !showAddModelModal ? (
                <div className="max-w-3xl space-y-6">
                  <ModelHistoryList />
                  <ModelUsageStats />
                </div>
              ) : (
                /* Add model form */
                <SettingGroup>
                  <div className="p-4 space-y-3">
                    {/* Provider */}
                    <div>
                      <label className="block ui-text font-medium text-foreground mb-1.5">
                        Provider
                      </label>
                      {!isCustomProvider ? (
                        <PopupSelect
                          value={localConfig.provider}
                          onChange={handleSelectProvider}
                          placeholder="请选择 Provider"
                          className="w-full ui-text text-foreground border border-border/50 bg-muted/50 rounded-lg px-3 py-2"
                          options={[
                            ...ALL_PROVIDERS.map((p) => ({
                              label: `${p.name} (${p.id})`,
                              value: p.id,
                            })),
                            { label: "＋ 自定义", value: CUSTOM_PROVIDER_ID },
                          ]}
                        />
                      ) : (
                        <div className="flex gap-2">
                          <input
                            type="text"
                            value={localConfig.provider}
                            onChange={(e) =>
                              handleCustomProviderChange(e.target.value)
                            }
                            onFocus={() => setCustomInputFocused(true)}
                            onBlur={handleBlurCustomInput}
                            placeholder="输入 Provider 名称"
                            className="flex-1 px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
                            autoFocus
                          />
                          <button
                            type="button"
                            onClick={() => {
                              setIsCustomProvider(false);
                              setCustomInputFocused(false);
                            }}
                            className="px-3 py-2 bg-muted/50 border border-border/50 rounded-lg text-[length:var(--helix-transcript-size)] text-foreground hover:bg-accent/50 transition-colors"
                            data-tip="返回列表"
                          >
                            返回
                          </button>
                        </div>
                      )}
                    </div>

                    {/* Base URL */}
                    <div>
                      <label className="block ui-text font-medium text-foreground mb-1.5">
                        Base URL
                      </label>
                      <input
                        type="text"
                        value={localConfig.baseUrl}
                        onChange={(e) =>
                          setLocalConfig((prev) => ({
                            ...prev,
                            baseUrl: e.target.value,
                          }))
                        }
                        placeholder="https://api.openai.com/v1"
                        className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
                      />
                    </div>

                    {/* API Key */}
                    <div>
                      <label className="block ui-text font-medium text-foreground mb-1.5">
                        API Key
                      </label>
                      <div className="relative">
                        <input
                          type={showApiKey ? "text" : "password"}
                          value={localConfig.apiKey}
                          onChange={(e) =>
                            setLocalConfig((prev) => ({
                              ...prev,
                              apiKey: e.target.value,
                            }))
                          }
                          placeholder="sk-..."
                          className="w-full px-3 py-2 pr-10 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
                        />
                        <button
                          type="button"
                          onClick={() => setShowApiKey(!showApiKey)}
                          className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/50 hover:text-foreground transition-colors"
                        >
                          {showApiKey ? "隐藏" : "显示"}
                        </button>
                      </div>
                    </div>

                    {/* Context window */}
                    <div>
                      <label className="block ui-text font-medium text-foreground mb-1.5">
                        上下文窗口
                      </label>
                      <input
                        type="number"
                        min={1}
                        step={1000}
                        value={localConfig.contextWindow ?? ""}
                        onChange={(e) => {
                          const raw = e.target.value.trim();
                          setLocalConfig((prev) => ({
                            ...prev,
                            contextWindow: raw ? Number(raw) : undefined,
                          }));
                        }}
                        className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
                      />
                      <p className="mt-1 text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/70"></p>
                    </div>

                    {/* Model */}
                    <div>
                      <div className="flex items-center justify-between mb-1.5">
                        <label className="block ui-text font-medium text-foreground">
                          模型名称
                        </label>
                        <button
                          type="button"
                          onClick={handleFetchModels}
                          disabled={isLoadingModels}
                          className="flex items-center gap-1 text-[calc(var(--helix-transcript-size)*0.8571)] text-primary hover:text-primary/80 disabled:text-muted-foreground transition-colors"
                        >
                          {isLoadingModels ? "获取中..." : "获取模型列表"}
                        </button>
                      </div>
                      {availableModels.length > 0 ? (
                        <div className="relative" ref={modelDropdownRef}>
                          <button
                            type="button"
                            onClick={() =>
                              setShowModelDropdown(!showModelDropdown)
                            }
                            className="w-full flex items-center justify-between ui-text text-foreground border border-border/50 bg-muted/50 rounded-lg px-3 py-2 transition-colors"
                          >
                            <span>{localConfig.model || "选择模型"}</span>
                            <svg
                              className={`size-4 text-muted-foreground transition-transform ${showModelDropdown ? "rotate-180" : ""}`}
                              xmlns="http://www.w3.org/2000/svg"
                              width="14"
                              height="14"
                              viewBox="0 0 24 24"
                              fill="none"
                              stroke="currentColor"
                              strokeWidth="2"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            >
                              <path d="m6 9 6 6 6-6" />
                            </svg>
                          </button>
                          {showModelDropdown && (
                            <div className="absolute bottom-full left-0 right-0 mb-1 max-h-48 overflow-y-auto bg-card border border-border/50 rounded-lg shadow-lg z-50 p-1">
                              {availableModels.map((model) => (
                                <button
                                  key={model}
                                  type="button"
                                  onClick={() => {
                                    const metadata = piModels.find(
                                      (m) =>
                                        m.id === model &&
                                        m.provider ===
                                          localConfig.provider
                                            .trim()
                                            .replace(/^custom:/, ""),
                                    );
                                    setLocalConfig((prev) => ({
                                      ...prev,
                                      model,
                                      contextWindow: metadata?.contextWindow,
                                    }));
                                    setShowModelDropdown(false);
                                  }}
                                  className={`w-full text-left px-3 py-2 rounded-md text-[length:var(--helix-transcript-size)] font-mono transition-colors ${
                                    localConfig.model === model
                                      ? "bg-primary/10 text-primary"
                                      : "text-foreground/70 hover:bg-muted"
                                  }`}
                                >
                                  {model}
                                </button>
                              ))}
                            </div>
                          )}
                        </div>
                      ) : (
                        <input
                          type="text"
                          value={localConfig.model}
                          onChange={(e) =>
                            setLocalConfig((prev) => ({
                              ...prev,
                              model: e.target.value,
                            }))
                          }
                          className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground font-mono"
                        />
                      )}
                    </div>

                    {/* Save button — inside card, bottom-right */}
                    <div className="flex justify-end pt-2">
                      <Button
                        onClick={async () => {
                          await handleSaveApi();
                          setShowAddModelModal(false);
                        }}
                        size="sm"
                        variant="outline"
                      >
                        保存
                      </Button>
                    </div>
                  </div>
                </SettingGroup>
              )
            ) : modelTab === "vision" ? (
              <VisionModelSettings />
            ) : (
              <ImageModelSettings />
            )}
          </div>
        );

      case "shortcuts":
        return (
          <div className="max-w-3xl">
            <ShortcutsPage />
          </div>
        );

      case "mcp":
        return (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h3 className="text-[calc(var(--helix-transcript-size)*1.2857)] font-semibold text-foreground">
                MCP
              </h3>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => void handleReloadMcp()}
                  className="flex items-center gap-1.5 text-[length:var(--helix-transcript-size)] font-medium text-foreground/50 hover:text-foreground transition-colors"
                  data-tip="重新加载 MCP（应用到当前会话）"
                  disabled={reloadingMcp}
                >
                  <RefreshCw
                    size={13}
                    className={reloadingMcp ? "animate-spin" : ""}
                  />
                  {reloadingMcp ? "刷新中…" : "刷新"}
                </button>
                {!isAddingMcp && !editingMcpName && !gatewayEditing ? (
                  <button
                    onClick={() => {
                      setIsAddingMcp(true);
                      resetMcpForm();
                    }}
                    className="flex items-center gap-1.5 text-[length:var(--helix-transcript-size)] font-medium text-primary hover:text-primary/80 transition-colors"
                  >
                    添加服务器
                  </button>
                ) : (
                  <button
                    onClick={() => {
                      setIsAddingMcp(false);
                      setEditingMcpName(null);
                      setGatewayEditing(null);
                      resetMcpForm();
                    }}
                    className="text-[length:var(--helix-transcript-size)] text-foreground/50 hover:text-foreground hover:bg-accent/60 rounded-lg px-2 py-1 transition-colors"
                    data-tip="关闭"
                  >
                    关闭
                  </button>
                )}
              </div>
            </div>

            {/* Gateway-loaded MCP servers (config.yaml mcp_servers) — editable */}
            {gatewayMcpLoaded &&
              !isAddingMcp &&
              !editingMcpName &&
              !gatewayEditing && (
                <section className="space-y-2">
                  {Object.keys(gatewayMcp).length === 0 ? null : (
                    <div className="max-w-3xl space-y-2">
                      {Object.entries(gatewayMcp).map(([name, cfg]) => {
                        const st = mcpStatus[name];
                        const cmd = [cfg?.command, ...(cfg?.args || [])]
                          .filter(Boolean)
                          .join(" ");
                        return (
                          <div
                            key={name}
                            className="flex items-center gap-3 px-4 py-3 border border-border/20 bg-muted/20 rounded-lg group"
                          >
                            <div className="relative shrink-0">
                              <div
                                className={`w-2.5 h-2.5 rounded-full ${cfg?.enabled === false ? "bg-gray-300" : st === "connected" ? "bg-green-500" : st === "failed" ? "bg-red-400" : "bg-amber-400"}`}
                              />
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2">
                                <span className="text-[length:var(--helix-transcript-size)] font-medium text-foreground">
                                  {name}
                                </span>
                                <span
                                  className={`text-[calc(var(--helix-transcript-size)*0.7143)] px-1.5 py-0.5 rounded-full font-medium ${cfg?.url ? "bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300" : "bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300"}`}
                                >
                                  {cfg?.url ? "远程" : "本地"}
                                </span>
                              </div>
                              <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/70 font-mono truncate mt-0.5">
                                {cfg?.url || cmd || "(环境变量式配置)"}
                              </p>
                            </div>
                            <button
                              onClick={() => handleEditGatewayMcp(name)}
                              className="px-1.5 py-1 rounded-md text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/40 hover:text-foreground hover:bg-accent opacity-0 group-hover:opacity-100 transition-all shrink-0"
                            >
                              编辑
                            </button>
                            <button
                              onClick={() => handleDeleteGatewayMcp(name)}
                              className="px-1.5 py-1 rounded-md text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/40 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-950 opacity-0 group-hover:opacity-100 transition-all shrink-0"
                            >
                              删除
                            </button>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </section>
              )}

            {!isAddingMcp && !editingMcpName && !gatewayEditing ? (
              <>
                {/* Server list */}
                <div className="max-w-3xl space-y-2">
                  {mcpServerNames.map((name) => {
                    const config = mcpServers[name];
                    const st = mcpStatus[name];
                    return (
                      <div
                        key={name}
                        className="flex items-center gap-3 px-4 py-3 border-b border-border/30 last:border-b-0 hover:bg-muted/40 transition-colors group"
                      >
                        <div className="relative shrink-0">
                          <div
                            className={`w-2.5 h-2.5 rounded-full ${config.enabled === false ? "bg-gray-300" : st === "connected" ? "bg-green-500" : st === "failed" ? "bg-red-400" : "bg-amber-400"}`}
                          />
                          {config.enabled !== false && st === "connected" && (
                            <span className="absolute inset-0 w-2.5 h-2.5 rounded-full bg-green-500 animate-ping opacity-30" />
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <span className="text-[length:var(--helix-transcript-size)] font-medium text-foreground">
                              {name}
                            </span>
                            <span
                              className={`text-[calc(var(--helix-transcript-size)*0.7143)] px-1.5 py-0.5 rounded-full font-medium ${config.type === "local" ? "bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300" : "bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300"}`}
                            >
                              {config.type === "local" ? "本地" : "远程"}
                            </span>
                          </div>
                          <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/70 font-mono truncate mt-0.5">
                            {config.type === "local"
                              ? config.command?.join(" ")
                              : config.url}
                          </p>
                        </div>
                        <div className="flex items-center gap-1.5 shrink-0">
                          <Toggle
                            enabled={config.enabled !== false}
                            onToggle={() => handleToggleMcp(name)}
                          />
                          <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-all">
                            <button
                              onClick={() => handleEditMcp(name)}
                              className="px-1 py-1 rounded-md text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/40 hover:text-foreground hover:bg-accent transition-colors"
                            >
                              编辑
                            </button>
                            <button
                              onClick={() => handleDeleteMcp(name)}
                              className="px-1 py-1 rounded-md text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/40 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-950 transition-colors"
                            >
                              删除
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>

                {mcpServerNames.length === 0 && (
                  <div className="max-w-3xl flex flex-col items-center justify-center py-12 text-center">
                    <p className="text-[length:var(--helix-transcript-size)] font-medium text-foreground/60">
                      暂无 MCP 服务器
                    </p>
                  </div>
                )}
              </>
            ) : (
              /* Editor — centered card, similar to model add */
              <div className="flex justify-center py-4">
                <div className="w-full max-w-2xl">
                  <McpEditorForm
                    form={mcpForm}
                    onChange={handleMcpFormChange}
                    onSave={
                      gatewayEditing ? handleSaveGatewayMcp : handleSaveMcp
                    }
                    onCancel={() => {
                      setIsAddingMcp(false);
                      setEditingMcpName(null);
                      setGatewayEditing(null);
                      resetMcpForm();
                    }}
                  />
                </div>
              </div>
            )}
          </div>
        );

      case "archive":
        return (
          <div className="max-w-3xl space-y-6">
            <SectionTitle className="mb-0">历史归档</SectionTitle>

            {/* Archived sessions */}
            <section className="space-y-3">
              {archives.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                  <p className="text-[length:var(--helix-transcript-size)] font-medium text-foreground/60">
                    暂无归档记录
                  </p>
                </div>
              ) : (
                <div className="space-y-1.5">
                  {archives.map((a) => (
                    <div
                      key={a.id}
                      onClick={() => handleLoadArchive(a.id)}
                      className="flex items-center justify-between px-3 py-1.5 rounded-xl bg-card shadow-sm cursor-pointer transition-colors group hover:bg-muted/40"
                    >
                      <div className="flex-1 min-w-0">
                        <p className="text-[length:var(--helix-transcript-size)] font-medium text-foreground truncate">
                          {a.label}
                        </p>
                        <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/70 mt-0.5">
                          {a.messageCount} 条消息
                        </p>
                      </div>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDeleteArchive(a.id);
                        }}
                        className="p-1 rounded-md text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/20 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all shrink-0"
                      >
                        删除
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </section>
          </div>
        );

      case "usage":
        return (
          <div className="max-w-3xl space-y-6">
            <SectionTitle>用量</SectionTitle>
            <TokenUsagePanel />
          </div>
        );

      case "hook":
        return <HookSettings />;

      case "help":
        return (
          <div className="max-w-3xl space-y-8">
            <SectionTitle>帮助</SectionTitle>

            {/* About */}
            <section className="space-y-3">
              <div className="overflow-hidden">
                <button
                  className="w-full px-4 py-3 bg-muted/30 border-b border-border/50 flex items-center justify-between gap-2 hover:bg-muted/50 transition-colors"
                  onClick={() =>
                    setCollapsedSections((s) => {
                      const next = new Set(s);
                      next.has("about")
                        ? next.delete("about")
                        : next.add("about");
                      return next;
                    })
                  }
                ></button>
                <div></div>
              </div>
            </section>
          </div>
        );

      case "agents":
        return <AgentsSettings />;
    }
  };

  return (
    <div className="flex-1 min-h-0 flex flex-row">
      {/* Left nav — width synced with the main sidebar */}
      {showSidebar && (
        <div
          className={`helix-sidebar relative flex flex-col shrink-0 h-full overflow-hidden ${isResizing ? "" : "transition-[width] duration-200 ease-out"}`}
          style={{ width: sidebarCollapsed ? 48 : navVisualWidth }}
        >
          {sidebarCollapsed ? (
            <div className="flex-1 flex flex-col items-center pt-2 gap-1 overflow-y-auto">
              <button
                onClick={() => useHelixStore.getState().toggleSettings()}
                data-tip="返回"
                className="p-2.5 rounded-lg text-sidebar-foreground/60 hover:text-sidebar-foreground hover:bg-sidebar-accent/40 transition-colors"
              >
                <ChevronLeft className="size-[18px]" />
              </button>
              {NAV_GROUPS.flatMap((group) => group.items).map((item) => (
                <button
                  key={item.id}
                  onClick={() => {
                    setPage(item.id);
                    pushNavigation({ type: "settings", page: item.id });
                  }}
                  data-tip={item.label}
                  className={`p-2.5 rounded-lg transition-colors ${
                    page === item.id
                      ? "bg-sidebar-accent/70 text-sidebar-accent-foreground"
                      : "text-sidebar-foreground/60 hover:text-sidebar-foreground hover:bg-sidebar-accent/40"
                  }`}
                >
                  <item.icon className="size-[18px]" />
                </button>
              ))}
            </div>
          ) : (
            <>
              <div className="px-4 pt-2 pb-1 space-y-2">
                <button
                  onClick={() => useHelixStore.getState().toggleSettings()}
                  className="flex items-center gap-2 w-full px-3 py-2 text-[calc(var(--helix-transcript-size)*0.9286)] text-sidebar-foreground/60 hover:text-sidebar-foreground hover:bg-sidebar-accent/50 rounded-xl transition-colors"
                >
                  <ChevronLeft className="size-4" />
                  返回
                </button>
                <div className="flex items-center gap-2 w-full px-2.5 py-1.5 rounded-lg border border-sidebar-border/60 bg-sidebar/40 transition-all duration-150  hover:border-sidebar-border">
                  <Search className="size-3.5 text-muted-foreground/25 shrink-0" />
                  <input
                    ref={navSearchRef}
                    value={navSearch}
                    onChange={(e) => setNavSearch(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Escape") {
                        setNavSearch("");
                        (e.target as HTMLInputElement).blur();
                      }
                    }}
                    placeholder="搜索设置..."
                    className="flex-1 bg-transparent text-[calc(var(--helix-transcript-size)*0.9286)] text-sidebar-foreground placeholder:text-sidebar-foreground/30 min-w-0"
                  />
                  {navSearch && (
                    <button
                      onClick={() => setNavSearch("")}
                      className="text-sidebar-foreground/25 hover:text-sidebar-foreground/60 shrink-0"
                    >
                      <X className="size-3" />
                    </button>
                  )}
                </div>
              </div>
              {(() => {
                const q = navSearch.trim().toLowerCase();
                const filtered = q
                  ? NAV_GROUPS.map((g) => ({
                      ...g,
                      items: g.items.filter((i) =>
                        i.label.toLowerCase().includes(q),
                      ),
                    })).filter((g) => g.items.length)
                  : NAV_GROUPS;
                if (!filtered.length)
                  return (
                    <div className="px-5 py-8 text-center text-[calc(var(--helix-transcript-size)*0.9286)] text-sidebar-foreground/40">
                      未找到匹配项
                    </div>
                  );
                return (
                  <nav className="flex-1 overflow-y-auto pt-1 pb-2">
                    {filtered.map((group) => (
                      <div key={group.title} className="mb-2">
                        <p className="px-5 py-1.5 text-[calc(var(--helix-transcript-size)*0.9286)] font-semibold text-sidebar-foreground/40 uppercase tracking-[0.12em] select-none">
                          {group.title}
                        </p>
                        <div className="space-y-0.5 px-2">
                          {group.items.map((item) => (
                            <button
                              key={item.id}
                              onClick={() => {
                                setPage(item.id);
                                pushNavigation({
                                  type: "settings",
                                  page: item.id,
                                });
                                setNavSearch("");
                              }}
                              className={`w-full flex items-center gap-2.5 px-2.5 py-1.5 text-[calc(var(--helix-transcript-size)*0.9286)] rounded-lg transition-colors duration-100 ${
                                page === item.id
                                  ? "bg-sidebar-accent text-sidebar-accent-foreground font-medium"
                                  : "text-sidebar-foreground/70 hover:bg-sidebar-accent/50 hover:text-sidebar-foreground"
                              }`}
                            >
                              <item.icon className="size-4" />
                              {item.label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ))}
                  </nav>
                );
              })()}
            </>
          )}

          {/* Resize handle — drag to resize the settings nav (also resizes the
            main sidebar, since they share one width). */}
          {!sidebarCollapsed && (
            <div
              className={`absolute top-0 -right-1 w-2 h-full cursor-col-resize z-30 group ${
                isResizing ? "bg-primary/20" : ""
              }`}
              onMouseDown={startNavResize}
            >
              <div
                className={`absolute inset-y-0 left-1/2 -translate-x-1/2 w-0.5 transition-colors ${
                  isResizing
                    ? "bg-primary/40"
                    : "bg-transparent group-hover:bg-border/40"
                }`}
              />
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity">
                <GripVertical className="size-3 text-primary/60" />
              </div>
            </div>
          )}
        </div>
      )}

      {/* Right content — flat card, border-separated from the nav sidebar */}
      <div className="helix-surface flex-1 overflow-y-auto relative">
        <div className="flex justify-center">
          <div className="px-8 pt-10 pb-10 w-full max-w-3xl">
            {renderContent()}
          </div>
        </div>
      </div>
    </div>
  );
}

﻿"use client";

import { AlertTriangle, Check, Loader2, Pencil } from "lucide-react";
import React, { useState, useEffect, useCallback } from "react";
import { Button } from "@/components/ui/button";
import type { ApprovalLevel } from "@/stores/helix-types";

export interface ApprovalRequest {
  id: string;
  sessionId?: string;
  toolName: string;
  params: Record<string, unknown>;
  command?: string;
  allowPermanent?: boolean;
  timestamp: number;
}

function getApprovalTitle(toolName: string): string {
  // 后端项目外读取审批的 pattern_key 前缀（file_tools._check_approval_required_read）
  if (toolName.includes("read_file:outside_project")) {
    return "检测到工作空间外部文件读取";
  }
  switch (toolName) {
    case "terminal":
    case "run_bash":
    case "execute_code":
      return "检测到工作空间外部文件修改";
    default:
      return "需要你的批准";
  }
}

interface ApprovalBarProps {
  request: ApprovalRequest;
  onApprove: (level: ApprovalLevel) => void;
  pendingCount?: number;
  onApproveAll?: () => void;
  onRejectAll?: () => void;
}

/**
 * Inline approval card (light, non-blocking) — anchored to the bottom-center of
 * the panel via the parent <ApprovalDialog> absolute wrapper, so it is always
 * visible regardless of how long the message list is. No modal overlay, so the
 * user can still switch conversations while it is open.
 * Keyboard: ⌘/Ctrl+Enter = allow · Esc = deny · ↑/↓ = move selection · Enter = confirm.
 */
function ApprovalBar({
  request,
  onApprove,
  pendingCount,
  onApproveAll,
  onRejectAll,
}: ApprovalBarProps) {
  const [submitting, setSubmitting] = useState<ApprovalLevel | null>(null);
  const [selected, setSelected] = useState<ApprovalLevel>("once");
  const command =
    request.command ||
    (typeof request.params.command === "string" ? request.params.command : "");

  const handleApprove = useCallback(
    (level: ApprovalLevel) => {
      setSubmitting(level);
      onApprove(level);
    },
    [onApprove],
  );

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
        e.preventDefault();
        e.stopPropagation();
        handleApprove("once");
      } else if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        handleApprove("deny");
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelected((s) =>
          s === "deny" ? "session" : s === "session" ? "once" : "once",
        );
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelected((s) =>
          s === "once" ? "session" : s === "session" ? "deny" : "deny",
        );
      } else if (e.key === "Enter") {
        e.preventDefault();
        e.stopPropagation();
        handleApprove(selected);
      }
    };
    window.addEventListener("keydown", handler, true);
    return () => window.removeEventListener("keydown", handler, true);
  }, [handleApprove, selected]);

  const options: { key: string; level: ApprovalLevel; label: string }[] = [
    { key: "1", level: "once", label: "允许" },
    { key: "2", level: "session", label: "本次会话内始终允许该类命令" },
    { key: "3", level: "deny", label: "拒绝" },
  ];

  return (
    <div className="w-full max-w-[700px] mx-auto bg-popover text-foreground border border-border rounded-2xl shadow-2xl p-1.5">
      <div className="flex items-start justify-between gap-2 mb-2">
        <h3 className="text-[calc(var(--helix-transcript-size)*0.9286)] font-semibold leading-snug">
          {getApprovalTitle(request.toolName)}
          {typeof pendingCount === "number" && pendingCount > 1 && (
            <span className="ml-2 text-[calc(var(--helix-transcript-size)*0.7857)] font-normal text-foreground/50">
              还有 {pendingCount - 1} 个待确认
            </span>
          )}
        </h3>
        <span className="shrink-0 mt-0.5 text-[calc(var(--helix-transcript-size)*0.7143)] font-medium px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/25">
          等待确认
        </span>
      </div>
      {command && (
        <pre className="bg-muted rounded-xl p-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/80 font-mono whitespace-pre-wrap break-all mb-1.5 max-h-10 overflow-auto">
          {command}
        </pre>
      )}
      {/* onApproveAll / onRejectAll removed per user request */}
      <div className="flex flex-col gap-1">
        {options.map((o) => {
          const isSel = selected === o.level;
          return (
            <button
              key={o.key}
              type="button"
              onClick={() => handleApprove(o.level)}
              onMouseEnter={() => setSelected(o.level)}
              disabled={submitting !== null}
              className={
                "flex items-center gap-2.5 px-3 py-1.5 rounded-xl border text-left transition-colors disabled:opacity-60 " +
                (isSel
                  ? "border-ring bg-accent ring-1 ring-ring"
                  : "border-transparent hover:bg-accent/60")
              }
            >
              <span
                className={
                  "w-5 h-5 rounded-full flex items-center justify-center text-[calc(var(--helix-transcript-size)*0.7857)] font-semibold shrink-0 " +
                  (isSel
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-muted-foreground")
                }
              >
                {o.key}
              </span>
              <span className="text-[calc(var(--helix-transcript-size)*0.8571)]">
                {o.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

// Keep the old dialog for backwards compatibility — now renders the inline ApprovalBar
// as a bottom-anchored, non-blocking card (can switch conversations while open).
interface LegacyProps {
  request: ApprovalRequest;
  pendingCount?: number;
  // level 直接透传（once/session/always/deny），由父组件映射为 approval.respond 的
  // choice；不再折成 cache?: boolean（那会丢失 session/deny 语义，2026-08-17）。
  onApprove: (id: string, level: ApprovalLevel) => void;
  onReject: (id: string) => void;
  onApproveAll?: () => void;
  onRejectAll?: () => void;
}
export function ApprovalDialog(props: LegacyProps) {
  const { request, onApprove, onReject } = props;
  const handleApprove = useCallback(
    (level: ApprovalLevel) => {
      if (!request) return;
      onApprove(request.id, level);
    },
    [request, onApprove],
  );
  if (!request) return null;
  return (
    <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-50 w-full px-5 pointer-events-none">
      <div className="pointer-events-auto mx-auto max-w-[700px]">
        <ApprovalBar
          // key=request.id：连续多个审批时强制重挂载，重置 submitting/selected。
          // 否则第一个审批点击后 submitting 卡在非 null，第二个弹窗按钮全禁用、
          // 看起来"点了不消失也不切下一个"（2026-08-17 实录）。
          key={request.id}
          request={request}
          onApprove={handleApprove}
          pendingCount={props.pendingCount}
          onApproveAll={props.onApproveAll}
          onRejectAll={props.onRejectAll}
        />
      </div>
    </div>
  );
}

// ── Clarify 反问浮条 ─────────────────────────────────────────────────────
// 模型调用 clarify 工具反问你（给几个选项让你挑，或自由输入）。样式/位置与
// ApprovalDialog 的底部浮条一致。点选项或提交输入后 onRespond(requestId, answer)。

export interface ClarifyRequest {
  id: string;
  question: string;
  choices: string[] | null;
}

interface ClarifyBarProps {
  request: ClarifyRequest;
  onRespond: (requestId: string, answer: string) => void;
}

export function ClarifyBar({ request, onRespond }: ClarifyBarProps) {
  const [freeText, setFreeText] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const choices = request.choices || [];
  const [selectedIdx, setSelectedIdx] = useState<number | null>(
    choices.length > 0 ? 0 : null,
  );

  const submit = useCallback(
    (answer: string) => {
      const a = answer.trim();
      if (!a || submitting) return;
      setSubmitting(true);
      onRespond(request.id, a);
    },
    [request.id, onRespond, submitting],
  );

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelectedIdx((i) => {
          if (choices.length === 0) return null;
          if (i === null) return 0;
          return i > 0 ? i - 1 : 0;
        });
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelectedIdx((i) => {
          if (choices.length === 0) return null;
          if (i === null) return choices.length - 1;
          return i < choices.length - 1 ? i + 1 : choices.length - 1;
        });
      } else if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        e.stopPropagation();
        if (freeText.trim()) {
          submit(freeText);
        } else if (selectedIdx !== null && choices[selectedIdx]) {
          submit(choices[selectedIdx]);
        }
      }
    };
    window.addEventListener("keydown", handler, true);
    return () => window.removeEventListener("keydown", handler, true);
  }, [choices, freeText, selectedIdx, submit]);

  return (
    <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-50 w-full px-5 pointer-events-none">
      <div className="pointer-events-auto w-full max-w-[700px] mx-auto bg-popover text-foreground border border-border rounded-2xl shadow-2xl p-4">
        <div className="flex items-center justify-between gap-3 mb-2">
          <h3 className="text-[calc(var(--helix-transcript-size)*0.9286)] font-semibold leading-snug">
            需要你的确认
          </h3>
          <span className="shrink-0 text-[calc(var(--helix-transcript-size)*0.7143)] font-medium px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/25">
            等待确认
          </span>
        </div>

        <div className="bg-muted rounded-lg px-3 py-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/80 leading-relaxed whitespace-pre-wrap break-words mb-2 max-h-32 overflow-auto">
          {request.question || "模型需要你的选择"}
        </div>

        {choices.length > 0 && (
          <div className="flex flex-col gap-1.5 mb-2 max-h-40 overflow-y-auto pr-0.5">
            {choices.map((c, idx) => {
              const isSel = selectedIdx === idx;
              return (
                <button
                  key={c}
                  type="button"
                  onClick={() => submit(c)}
                  onMouseEnter={() => setSelectedIdx(idx)}
                  disabled={submitting}
                  className={
                    "flex items-center gap-2 px-3 py-1.5 rounded-lg border text-left transition-colors disabled:opacity-60 " +
                    (isSel
                      ? "border-ring bg-accent ring-1 ring-ring"
                      : "border-transparent hover:bg-accent/60")
                  }
                >
                  <span
                    className={
                      "w-5 h-5 rounded-full flex items-center justify-center text-[calc(var(--helix-transcript-size)*0.7857)] font-semibold shrink-0 " +
                      (isSel
                        ? "bg-primary text-primary-foreground"
                        : "bg-muted text-muted-foreground")
                    }
                  >
                    {idx + 1}
                  </span>
                  <span className="text-[calc(var(--helix-transcript-size)*0.9286)] truncate">
                    {c}
                  </span>
                </button>
              );
            })}
          </div>
        )}

        <div className="flex items-center gap-2">
          <input
            value={freeText}
            onChange={(e) => setFreeText(e.target.value)}
            disabled={submitting}
            placeholder={choices.length ? "或输入其他回答…" : "输入回答…"}
            className="flex-1 h-9 px-3 rounded-lg bg-background/60 border border-border/50 text-[calc(var(--helix-transcript-size)*0.9286)] text-foreground disabled:opacity-50"
          />
          <Button
            size="sm"
            disabled={submitting || !freeText.trim()}
            onClick={() => submit(freeText)}
            className="h-9 px-4 text-[calc(var(--helix-transcript-size)*0.9286)]"
          >
            {submitting ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              "回复"
            )}
          </Button>
        </div>

        <div className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/60 text-center mt-2">
          内容由 AI 生成，请核实重要信息 · ↑↓ 选择 · Enter 确认 · 也可自由输入
        </div>
      </div>
    </div>
  );
}

// ── 计划审查浮条（─────────────────────────────────────
// 计划模式下模型产完计划（本轮 run 结束）后弹出：用户批准后才开始真正执行。
// 批准 → 前端切到 accept_edits 并续发一条"请执行"指令触发新一轮 run；
// 继续调整 → 关闭浮条，保持计划模式，用户可继续对话修改方案。

export interface PlanReviewRequest {
  sessionId?: string;
  // 本轮模型产出的计划全文（用于预览）
  content: string;
}

interface PlanReviewBarProps {
  content: string;
  onApprove: () => void;
  /** 修改反馈：传字符串 → 自动作为 plan follow-up 重新规划；不传 → 仅关条。 */
  onAdjust: (feedback?: string) => void;
}

export function PlanReviewBar({
  content,
  onApprove,
  onAdjust,
}: PlanReviewBarProps) {
  const [submitting, setSubmitting] = useState<"approve" | "adjust" | null>(
    null,
  );

  const approve = useCallback(() => {
    if (submitting) return;
    setSubmitting("approve");
    onApprove();
  }, [submitting, onApprove]);

  const [showFeedback, setShowFeedback] = useState(false);
  const [feedback, setFeedback] = useState("");

  const submitFeedback = useCallback(() => {
    const fb = feedback.trim();
    if (!fb || submitting) return;
    setSubmitting("adjust");
    onAdjust(fb);
  }, [feedback, submitting, onAdjust]);

  const closeAdjust = useCallback(() => {
    setShowFeedback(false);
    setFeedback("");
    onAdjust();
  }, [onAdjust]);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
        e.preventDefault();
        e.stopPropagation();
        approve();
      } else if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        onAdjust();
      }
    };
    window.addEventListener("keydown", handler, true);
    return () => window.removeEventListener("keydown", handler, true);
  }, [approve, onAdjust]);

  return (
    <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-50 w-full px-5 pointer-events-none">
      <div className="pointer-events-auto w-full max-w-[700px] mx-auto bg-popover text-foreground border-2 border-primary/40 rounded-2xl shadow-2xl p-2">
        <div className="flex items-center justify-between gap-3 mb-1.5">
          <h3 className="text-[calc(var(--helix-transcript-size)*0.9286)] font-semibold leading-snug">
            计划已生成
          </h3>
          <span className="shrink-0 text-[calc(var(--helix-transcript-size)*0.7143)] font-medium px-2 py-0.5 rounded-full bg-sky-500/15 text-sky-600 dark:text-sky-400 border border-sky-500/25">
            待批准执行
          </span>
        </div>

        <div className="bg-muted rounded-lg px-2.5 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/80 leading-relaxed whitespace-pre-wrap break-words mb-1.5 max-h-64 overflow-auto">
          {content || "（模型未输出可见计划文本）"}
        </div>

        <div className="flex items-center gap-2">
          <Button
            size="sm"
            disabled={submitting !== null}
            onClick={approve}
            className="flex-1 h-8 text-[calc(var(--helix-transcript-size)*0.9286)]"
          >
            {submitting === "approve" ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <Check className="size-3.5" />
            )}
            批准并执行
          </Button>
          <Button
            size="sm"
            variant="ghost"
            disabled={submitting !== null}
            onClick={() => setShowFeedback((v) => !v)}
            className="flex-1 h-8 text-[calc(var(--helix-transcript-size)*0.9286)]"
          >
            <Pencil className="size-3.5" />
            修改计划
          </Button>
        </div>

        {showFeedback && (
          <div className="space-y-2">
            <textarea
              value={feedback}
              onChange={(e) => setFeedback(e.target.value)}
              placeholder="写修改意见，提交后 agent 基于意见重新规划…"
              rows={2}
              autoFocus
              className="w-full rounded-lg border border-border/60 bg-background px-2.5 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] resize-none"
            />
            <div className="flex items-center gap-2">
              <Button
                size="sm"
                onClick={submitFeedback}
                disabled={!feedback.trim() || submitting !== null}
                className="flex-1 h-8 text-[calc(var(--helix-transcript-size)*0.8571)]"
              >
                {submitting === "adjust" ? (
                  <Loader2 className="size-3.5 animate-spin" />
                ) : (
                  <Check className="size-3.5" />
                )}
                提交并重新规划
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={closeAdjust}
                className="h-8 text-[calc(var(--helix-transcript-size)*0.8571)]"
              >
                取消
              </Button>
            </div>
          </div>
        )}

        <div className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/60 text-center mt-1">
          批准后开始执行，危险操作仍需确认 · ⌘/Ctrl+Enter 批准 · Esc 修改计划
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  X,
  FolderOpen,
  FileText,
  ArrowUp,
  Loader2,
  ExternalLink,
  Folder,
} from "lucide-react";
import React, { useState, useEffect, useCallback } from "react";
import {
  electronFS,
  electronDialog,
  electronShell,
} from "@/lib/electron-bridge";

interface TreeNode {
  id: string;
  name: string;
  type: string;
  children?: TreeNode[];
}

// Browse artifact / generated files via the existing fs bridge. Default roots
// to the project workdir; supports navigating into folders.
export function ArtifactsBrowser({ onClose }: { onClose: () => void }) {
  const [root, setRoot] = useState<string>("");
  const [tree, setTree] = useState<TreeNode[]>([]);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [content, setContent] = useState<{ name: string; text: string } | null>(
    null,
  );

  const load = useCallback(async (dir: string) => {
    setLoading(true);
    setErr(null);
    setContent(null);
    try {
      const nodes = await electronFS.scanTree(dir || undefined);
      setTree(Array.isArray(nodes) ? (nodes as TreeNode[]) : []);
      setRoot(dir);
    } catch (e: any) {
      setErr(String(e?.message || e));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load("");
  }, [load]);

  const openDir = async () => {
    const dir = await electronDialog.openDirectory();
    if (dir) load(dir);
  };

  const readFile = async (path: string, name: string) => {
    setLoading(true);
    try {
      const text = await electronFS.readFile(path);
      setContent({
        name,
        text: typeof text === "string" ? text : String(text),
      });
    } catch (e: any) {
      setErr(String(e?.message || e));
    } finally {
      setLoading(false);
    }
  };

  const renderNodes = (nodes: TreeNode[], depth = 0) =>
    nodes.map((n) => (
      <div key={n.id}>
        <div
          className="flex items-center gap-2 px-2 py-1 rounded hover:bg-accent/30 cursor-pointer"
          style={{ paddingLeft: 8 + depth * 14 }}
          onClick={() =>
            n.type === "directory" ? load(n.id) : readFile(n.id, n.name)
          }
        >
          {n.type === "directory" ? (
            <Folder className="size-3.5 text-amber-400/80 shrink-0" />
          ) : (
            <FileText className="size-3.5 text-muted-foreground shrink-0" />
          )}
          <span className="text-[calc(var(--helix-transcript-size)*0.8571)] truncate flex-1">
            {n.name}
          </span>
          {n.type !== "directory" && (
            <button
              className="opacity-0 group-hover:opacity-100"
              onClick={(e) => {
                e.stopPropagation();
                electronShell.open(n.id);
              }}
            >
              <ExternalLink className="size-3 text-muted-foreground" />
            </button>
          )}
        </div>
        {n.children && renderNodes(n.children, depth + 1)}
      </div>
    ));

  return (
    <div className="fixed inset-0 z-[9998] flex justify-end">
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />
      <div className="relative w-full max-w-sm h-full bg-card border-l border-border/60 shadow-2xl flex flex-col">
        <div className="flex items-center justify-between px-4 py-3 border-b border-border/60">
          <div className="flex items-center gap-2">
            <FolderOpen className="size-4 text-primary" />
            <h2 className="text-[length:var(--helix-transcript-size)] font-semibold">
              产物浏览器
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted-foreground hover:bg-accent/60"
          >
            <X className="size-4" />
          </button>
        </div>
        <div className="px-3 py-2 border-b border-border/60 flex items-center gap-2 text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground/70">
          <button
            onClick={openDir}
            className="flex items-center gap-1 hover:text-foreground"
          >
            <FolderOpen className="size-3" /> 选择目录
          </button>
          <span className="truncate flex-1">{root || "（项目工作目录）"}</span>
          {root && (
            <button onClick={() => load("")} className="hover:text-foreground">
              <ArrowUp className="size-3" />
            </button>
          )}
        </div>
        <div className="flex-1 overflow-y-auto p-2">
          {loading ? (
            <div className="flex items-center gap-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/60 mt-6">
              <Loader2 className="size-3.5 animate-spin" /> 加载中…
            </div>
          ) : err ? (
            <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-red-400 mt-6">
              {err}
            </p>
          ) : content ? (
            <div>
              <div className="flex items-center justify-between px-1 py-1">
                <span className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium truncate">
                  {content.name}
                </span>
                <button
                  onClick={() => setContent(null)}
                  className="text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground hover:text-foreground"
                >
                  返回
                </button>
              </div>
              <pre className="text-[calc(var(--helix-transcript-size)*0.7857)] whitespace-pre-wrap break-all max-h-[60vh] overflow-auto bg-muted/40 rounded-lg p-2">
                {content.text.slice(0, 20000)}
              </pre>
            </div>
          ) : tree.length === 0 ? (
            <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/60 text-center mt-8">
              空目录
            </p>
          ) : (
            <div className="group">{renderNodes(tree)}</div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  Loader2,
  X,
  XCircle,
  CheckCircle2,
  Ban,
  Terminal,
  ScrollText,
} from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";

/** 后台任务记录（与 pi-background-tasks 扩展的 tasks.json schema 对齐，
 *  经 Rust tasks_list 命令读出——Rust 侧还会把 running 但进程已消失的
 *  任务就地标记为 failed，前端拿来即用）。 */
export interface BgTask {
  id: string;
  command: string;
  pid: number;
  session_id: string;
  started_at: number;
  status: "running" | "completed" | "failed" | "killed";
  exit_code?: number;
  finished_at?: number;
  output_file: string;
}

function formatDuration(ms: number): string {
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s} 秒`;
  const m = Math.floor(s / 60);
  const r = s % 60;
  return r > 0 ? `${m} 分 ${r} 秒` : `${m} 分`;
}

/** 后台任务面板：右上角「后台任务」按钮的弹出卡片。
 *  数据源 = pi-background-tasks 扩展的共享注册表（~/.pi/agent/tasks.json），
 *  由本组件自己轮询（3s），父组件只负责开合与当前会话过滤。 */
export function BackgroundTasksPanel({
  tasks,
  activeSessionId,
  onClose,
  onRefresh,
}: {
  tasks: BgTask[];
  activeSessionId: string | null;
  onClose: () => void;
  onRefresh: () => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [viewing, setViewing] = useState<BgTask | null>(null);
  const [outputText, setOutputText] = useState<string>("加载中…");
  const [, setTick] = useState(0);

  // 每秒 tick 刷新运行中任务的耗时显示
  useEffect(() => {
    const t = setInterval(() => setTick(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);

  // 点击外部关闭
  useEffect(() => {
    const onDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [onClose]);

  // 我的任务：当前会话的任务排前面；其余（别的会话 / 扩展没能记下会话的
  // "unknown" 任务）折叠在下面的「其他来源」区，而不是直接吞掉。
  const myTasks = activeSessionId
    ? tasks.filter((t) => t.session_id === activeSessionId)
    : tasks;
  const otherTasks = activeSessionId
    ? tasks.filter(
        (t) => t.session_id !== activeSessionId,
      )
    : [];
  const running = myTasks.filter((t) => t.status === "running");
  const done = myTasks.filter((t) => t.status !== "running");

  const openOutput = useCallback(
    async (task: BgTask) => {
      setViewing(task);
      setOutputText("加载中…");
      try {
        const api = (window as any).electron as any;
        const res = await api?.backgroundTasks?.read?.(task.id, 16384);
        if (res?.ok) {
          const text = (res.text || "").trim();
          const kb = res.total_bytes ? ` · 共 ${(res.total_bytes / 1024).toFixed(1)}KB` : "";
          if (text) {
            setOutputText(text + (kb ? `\n\n—— 输出末尾 16KB${kb}` : ""));
          } else {
            // 输出文件存在但为空：区分"还在跑没产出"和"秒退没吐任何东西"
            setOutputText(
              task.status === "running"
                ? "（任务运行中，暂无输出 —— 等它产出后点「刷新输出」）"
                : "（任务已结束，但未产生任何输出 —— 命令可能刚启动就退出了）",
            );
          }
        } else {
          const err = res?.error ?? "未知错误";
          setOutputText(
            err === "output file missing"
              ? "（输出日志文件已不存在 —— 任务是旧会话/重启前启动的，" +
                "扩展重启时清理了日志。之后启动的任务会正常保留输出。）"
              : `读取失败：${err}`,
          );
        }
      } catch (e) {
        setOutputText(`读取失败：${String(e)}`);
      }
    },
    [],
  );

  const killTask = useCallback(
    async (task: BgTask) => {
      try {
        const api = (window as any).electron as any;
        await api?.backgroundTasks?.kill?.(task.id);
      } catch { /* empty */}
      onRefresh();
    },
    [onRefresh],
  );

  if (viewing) {
    return (
      <div
        ref={ref}
        className="absolute right-0 top-[calc(100%+6px)] z-50 w-[30rem] max-w-[calc(100vw-2rem)] rounded-xl border border-border bg-popover text-popover-foreground shadow-xl flex flex-col max-h-[60vh]"
      >
        <div className="flex items-center justify-between px-3 py-2 border-b border-border shrink-0 gap-2">
          <span className="flex-1 min-w-0 truncate font-mono text-[calc(var(--helix-transcript-size)*0.7857)] text-foreground/80">
            {viewing.command}
          </span>
          <span
            className={`shrink-0 text-[calc(var(--helix-transcript-size)*0.7143)] ${
              viewing.status === "running"
                ? "text-primary"
                : viewing.status === "completed"
                  ? "text-emerald-500"
                  : "text-red-500"
            }`}
          >
            {viewing.status === "running"
              ? "运行中"
              : viewing.status === "completed"
                ? `完成 (exit 0)`
                : viewing.status === "killed"
                  ? "已终止"
                  : `失败${viewing.exit_code !== undefined ? ` (exit ${viewing.exit_code})` : ""}`}
          </span>
          <button
            onClick={() => setViewing(null)}
            className="p-1 rounded text-foreground/50 hover:text-foreground hover:bg-muted/40 shrink-0"
            data-tip="返回列表"
          >
            <X className="size-3.5" />
          </button>
        </div>
        <pre className="flex-1 overflow-auto min-h-0 px-3 py-2 text-[calc(var(--helix-transcript-size)*0.7143)] font-mono whitespace-pre-wrap break-all text-foreground/80">
          {outputText}
        </pre>
        {viewing.status === "running" && (
          <div className="px-3 py-2 border-t border-border shrink-0 flex gap-2">
            <button
              onClick={() => openOutput(viewing)}
              className="flex items-center gap-1 px-2 py-1 rounded text-[calc(var(--helix-transcript-size)*0.7143)] text-primary hover:bg-primary/10 transition-colors"
            >
              <ScrollText className="size-3" />
              刷新输出
            </button>
            <button
              onClick={() => {
                killTask(viewing);
                setViewing(null);
              }}
              className="flex items-center gap-1 px-2 py-1 rounded text-[calc(var(--helix-transcript-size)*0.7143)] text-red-500 hover:bg-red-500/10 transition-colors"
            >
              <Ban className="size-3" />
              终止任务
            </button>
          </div>
        )}
      </div>
    );
  }

  return (
    <div
      ref={ref}
      className="absolute right-0 top-[calc(100%+6px)] z-50 w-[26rem] max-w-[calc(100vw-2rem)] rounded-xl border border-border bg-popover text-popover-foreground shadow-xl flex flex-col max-h-[50vh]"
    >
      <div className="flex items-center justify-between px-3 py-2 border-b border-border shrink-0">
        <span className="text-[calc(var(--helix-transcript-size)*0.8571)] font-semibold">
          后台任务
          {running.length > 0 && (
            <span className="ml-1.5 text-[calc(var(--helix-transcript-size)*0.7143)] text-primary font-normal">
              {running.length} 运行中
            </span>
          )}
        </span>
        <button
          onClick={onClose}
          className="p-1 rounded text-foreground/50 hover:text-foreground hover:bg-muted/40"
          data-tip="关闭"
        >
          <X className="size-3.5" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto min-h-0">
        {myTasks.length === 0 && otherTasks.length === 0 && (
          <div className="px-3 py-6 text-center text-[calc(var(--helix-transcript-size)*0.7857)] text-foreground/40">
            当前对话没有后台任务。
            <br />
            <span className="text-[calc(var(--helix-transcript-size)*0.7143)]">
              提示模型使用 background 工具启动长任务，这里就能看到。
            </span>
          </div>
        )}
        {myTasks.length === 0 && otherTasks.length > 0 && (
          <div className="px-3 pt-3 text-[calc(var(--helix-transcript-size)*0.7857)] text-foreground/40">
            当前对话没有后台任务。
          </div>
        )}
        {[...running, ...done].map((task) => {
          const isRunning = task.status === "running";
          const durationMs =
            (task.finished_at ?? Date.now()) - task.started_at;
          return (
            <div
              key={task.id}
              className="flex items-center gap-2 px-3 py-2 border-b border-border/30 last:border-b-0 hover:bg-muted/20 transition-colors"
            >
              {isRunning ? (
                <Loader2 className="size-3.5 text-primary shrink-0 animate-spin" />
              ) : task.status === "completed" ? (
                <CheckCircle2 className="size-3.5 text-emerald-500 shrink-0" />
              ) : (
                <XCircle className="size-3.5 text-red-500 shrink-0" />
              )}
              <Terminal className="size-3.5 text-foreground/30 shrink-0" />
              <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.7857)] font-mono text-foreground/80">
                {task.command}
              </span>
              <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground shrink-0">
                {formatDuration(durationMs)}
              </span>
              <button
                onClick={() => openOutput(task)}
                className="p-0.5 rounded text-foreground/30 hover:text-foreground hover:bg-muted/40 transition-colors shrink-0"
                data-tip="查看输出"
              >
                <ScrollText className="size-3" />
              </button>
              {isRunning && (
                <button
                  onClick={() => killTask(task)}
                  className="p-0.5 rounded text-foreground/30 hover:text-red-500 hover:bg-red-500/10 transition-colors shrink-0"
                  data-tip="终止"
                >
                  <Ban className="size-3" />
                </button>
              )}
            </div>
          );
        })}

        {/* 其他来源：别的会话 / 扩展早期没记下会话 id 的任务。只列运行
            中的 + 最近 5 条已结束的，避免历史堆积把当前会话挤出视野。 */}
        {otherTasks.length > 0 && (
          <div className="border-t border-border/50">
            <div className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground bg-muted/30">
              其他来源（{otherTasks.length}）— 其他会话或未记录会话的后台任务
            </div>
            {[
              ...otherTasks.filter((t) => t.status === "running"),
              ...otherTasks.filter((t) => t.status !== "running").slice(0, 5),
            ].map((task) => {
              const isRunning = task.status === "running";
              const durationMs =
                (task.finished_at ?? Date.now()) - task.started_at;
              return (
                <div
                  key={task.id}
                  className="flex items-center gap-2 px-3 py-1.5 border-t border-border/20 hover:bg-muted/20 transition-colors"
                >
                  {isRunning ? (
                    <Loader2 className="size-3 text-primary shrink-0 animate-spin" />
                  ) : task.status === "completed" ? (
                    <CheckCircle2 className="size-3 text-emerald-500 shrink-0" />
                  ) : (
                    <XCircle className="size-3 text-red-500 shrink-0" />
                  )}
                  <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.7143)] font-mono text-foreground/60">
                    {task.command}
                  </span>
                  <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/70 shrink-0">
                    {formatDuration(durationMs)}
                  </span>
                  <button
                    onClick={() => openOutput(task)}
                    className="p-0.5 rounded text-foreground/30 hover:text-foreground hover:bg-muted/40 transition-colors shrink-0"
                    data-tip="查看输出"
                  >
                    <ScrollText className="size-3" />
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import {
  Loader2,
  WifiOff,
  RefreshCw,
  Package,
  X,
  CheckCircle2,
} from "lucide-react";
import React, { useEffect, useState, useRef } from "react";
import { useGatewayStore } from "@/stores/gateway-store";
import { useHelixStore } from "@/stores/helix-store";

/** Bootstrap stage reported by the Rust backend. */
type BootstrapStage = "preparing" | "done" | null;

const STAGE_LABELS: Record<string, string> = {
  preparing: "正在准备 Helix 运行环境...",
};

/**
 * BootOverlay — shown over the app while the Helix gateway is connecting or
 * when it fails/disconnects, mirroring the official app's boot/connecting
 * surface with clear recovery semantics.
 *
 * Also handles first-run bootstrap progress (extracting the bundled agent runtime).
 */
export function BootOverlay() {
  const status = useHelixStore((s) => s.gatewayStatus);
  const setGatewayStatus = useHelixStore((s) => s.setGatewayStatus);
  // Single source of truth for connectivity — the SAME field the sidebar
  // connection dot reads (gateway-store.helixConnected). Keying the overlay off
  // this instead of the separate helix-store.gatewayStatus guarantees the dot
  // and the overlay can never disagree, even across dev hot-reloads where the
  // two stores can momentarily desync. gatewayStatus is kept only to pick the
  // message/icon (connecting vs disconnected).
  const helixConnected = useGatewayStore((s) => s.helixConnected);
  const [bootstrapStage, setBootstrapStage] = useState<BootstrapStage>(null);
  const [bootstrapMessage, setBootstrapMessage] = useState("");
  const [isReady, setIsReady] = useState(false);
  const [isFadingOut, setIsFadingOut] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  // Handle fade-out animation when connected.
  // FIX: depend only on `helixConnected`. Previously `isFadingOut` was in the
  // dependency array, so flipping it to true re-ran the effect immediately and
  // the cleanup cleared the 800ms timer — `isReady` never became true and the
  // overlay stayed on screen forever even after the gateway was ready.
  useEffect(() => {
    if (helixConnected && !isFadingOut) {
      setShowSuccess(true);
      setIsFadingOut(true);
      const timer = setTimeout(() => {
        setIsReady(true);
      }, 800); // Fade out duration
      return () => clearTimeout(timer);
    }
  }, [helixConnected]);

  // Listen for bootstrap progress events from the Rust backend.
  useEffect(() => {
    let unlisten: (() => void) | undefined;
    const setup = async () => {
      try {
        const { listen } = await import("@tauri-apps/api/event");
        unlisten = await listen<{
          method: string;
          params: { stage: string; message: string };
        }>("helix:event", (event) => {
          if (event.payload.method === "bootstrap:progress") {
            const { stage, message } = event.payload.params;
            if (stage === "done") {
              setBootstrapStage("done");
              setBootstrapMessage("");
            } else {
              setBootstrapStage(stage as BootstrapStage);
              setBootstrapMessage(message);
            }
          }
        });
      } catch {
        // Non-Tauri environment (dev server without backend) — silently ignore.
      }
    };
    void setup();
    return () => {
      unlisten?.();
    };
  }, []);

  const [dismissed, setDismissed] = useState(false);

  if (isReady || dismissed) return null;

  const isConnecting = status === "connecting";
  const isBootstrapping =
    bootstrapStage !== null && bootstrapStage !== "done" && isConnecting;

  const retry = () => {
    setGatewayStatus("connecting");
    const helix = (window as any).electron?.helix;
    const probe = async (n = 0) => {
      try {
        const st = await helix?.status?.();
        if (st?.connected) {
          useHelixStore.getState().setGatewayStatus("ready");
          // Also nudge the shared connection flag so the overlay dismisses even
          // when the heartbeat probe is currently throttled.
          useGatewayStore.getState().setHelixConnected(true);
          return;
        }
      } catch { /* empty */}
      if (n < 20) setTimeout(() => probe(n + 1), 1500);
    };
    probe();
  };

  return (
    <div
      className={`fixed bottom-4 right-4 z-[10000] w-80 rounded-xl border bg-card shadow-lg transition-all duration-500 ${
        isFadingOut
          ? "opacity-0 translate-y-2 pointer-events-none"
          : "opacity-100"
      }`}
    >
      <div className="p-4 text-center relative">
        {/* Close button */}
        <button
          onClick={() => setDismissed(true)}
          className="absolute top-2 right-2 p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          data-tip="关闭"
        >
          <X className="size-3.5" />
        </button>

        <div className="mx-auto mb-3 w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
          {isBootstrapping ? (
            <Package className="size-5 text-primary animate-pulse" />
          ) : isConnecting ? (
            <Loader2 className="size-5 text-primary animate-spin" />
          ) : (
            <WifiOff className="size-5 text-destructive" />
          )}
        </div>

        <h1 className="text-[length:var(--helix-transcript-size)] font-semibold mb-1">
          {isBootstrapping
            ? (STAGE_LABELS[bootstrapStage!] ?? bootstrapMessage)
            : isConnecting
              ? "正在连接 Helix 网关…"
              : "无法连接到 Helix 网关"}
        </h1>
        <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground leading-relaxed">
          {isBootstrapping
            ? "首次启动需要安装运行环境，请耐心等待。"
            : isConnecting
              ? "正在启动 Helix Agent，请稍候。"
              : "网关未运行或已断开。"}
        </p>

        {!isConnecting && (
          <button
            onClick={retry}
            className="mt-3 mx-auto inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-primary text-primary-foreground text-[calc(var(--helix-transcript-size)*0.8571)] font-medium hover:bg-primary/90 transition-colors"
          >
            <RefreshCw className="size-3" />
            重试连接
          </button>
        )}

        {/* Bootstrap progress bar */}
        {isBootstrapping && bootstrapStage && (
          <div className="mt-3 w-full bg-muted rounded-full h-1 overflow-hidden">
            <div
              className="h-full bg-primary rounded-full transition-all duration-700"
              style={{
                width: bootstrapStage === "preparing" ? "50%" : "100%",
              }}
            />
          </div>
        )}

        {/* Success animation */}
        {showSuccess && (
          <div className="mt-3 flex items-center justify-center gap-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] text-green-500">
            <CheckCircle2 className="size-3.5" />
            启动成功
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { GitBranch, Search, Plus, Check, AlertCircle, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { isElectron, electronGit } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";

interface DirtyFile {
  name: string;
  added: number;
  removed: number;
}

interface BranchPickerProps {
  workDir: string | null;
  currentBranch: string | null;
  onBranchChange: (branch: string) => void;
  /** Popover direction relative to the trigger. 'down' for the conversation
   *  header (room below), 'up' for bottom-anchored bars. */
  drop?: "up" | "down";
  /** Optional extra classes for the trigger button. */
  className?: string;
}

/**
 * A clickable Git branch selector. The trigger shows the current branch;
 * clicking it opens a popover listing every local branch (with a search box),
 * lets you switch branches, and create + checkout a new one.
 *
 * When uncommitted changes exist and the user tries to switch branches,
 * a VSCode-style "Commit & Switch" modal is shown listing every affected
 * file with +/- line counts, offering "Cancel" or "Commit & Switch…".
 */
export function BranchPicker({
  workDir,
  currentBranch,
  onBranchChange,
  drop = "down",
  className,
}: BranchPickerProps) {
  const storeActions = useHelixStore.getState();
  const [open, setOpen] = useState(false);
  const [list, setList] = useState<string[]>([]);
  const [search, setSearch] = useState("");
  const [dirtyCount, setDirtyCount] = useState(0);
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState("");
  const ref = useRef<HTMLDivElement>(null);

  // ── "Commit & Switch" confirmation dialog state ──
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean;
    targetBranch: string;
    files: DirtyFile[];
    committing: boolean;
  }>({ open: false, targetBranch: "", files: [], committing: false });

  // Close on outside click.
  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node))
        setOpen(false);
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [open]);

  // Close confirm dialog on Escape.
  useEffect(() => {
    if (!confirmDialog.open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape")
        setConfirmDialog((prev) => ({ ...prev, open: false }));
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [confirmDialog.open]);

  const refresh = () => {
    if (!isElectron() || !workDir) return;
    electronGit
      .branchList(workDir)
      .then((res: { ok: boolean; branches?: string[]; error?: string }) => {
        if (res.ok && res.branches) setList(res.branches);
      })
      .catch(() => {});
    electronGit
      .status(workDir)
      .then((res: { ok: boolean; output?: string }) => {
        if (res.ok && res.output) {
          const lines = res.output.split("\n");
          const count = lines.filter((l) => /^[12]/.test(l)).length;
          setDirtyCount(count);
        } else {
          setDirtyCount(0);
        }
      })
      .catch(() => setDirtyCount(0));
  };

  /** Parse `git diff --numstat` output into DirtyFile[]. */
  const parseNumstat = (output: string): DirtyFile[] =>
    output
      .split("\n")
      .filter(Boolean)
      .map((line) => {
        const m = line.match(/^(\d+)\s+(\d+)\s+(.+)$/);
        if (!m) return null;
        return { name: m[3], added: Number(m[1]), removed: Number(m[2]) };
      })
      .filter((f): f is DirtyFile => f !== null);

  const handleOpen = () => {
    const willOpen = !open;
    setOpen(willOpen);
    setSearch("");
    setCreating(false);
    setNewName("");
    if (willOpen) refresh();
  };

  const handleSwitch = async (b: string) => {
    if (!isElectron() || !workDir) return;

    // If there are dirty files, show the confirmation dialog.
    if (dirtyCount > 0) {
      try {
        const res = await electronGit.diffNumstat(workDir);
        if (res.ok && res.output) {
          const files = parseNumstat(res.output);
          setConfirmDialog({
            open: true,
            targetBranch: b,
            files,
            committing: false,
          });
          setOpen(false);
          return;
        }
      } catch (_) {
        /* fall through to direct switch */
      }
    }

    // No dirty files (or fetch failed) — switch directly.
    doSwitch(b);
  };

  const doSwitch = async (b: string) => {
    const res = await electronGit.branchSwitch(b, workDir);
    if (res.ok) {
      onBranchChange(b);
      setOpen(false);
      storeActions.showToast({ type: "success", title: `已切换到 ${b}` });
    } else {
      storeActions.showToast({
        type: "error",
        title: "切换分支失败",
        description: res.error,
      });
    }
  };

  /** Commit all changes then switch to the target branch. */
  const commitAndSwitch = async () => {
    setConfirmDialog((prev) => ({ ...prev, committing: true }));
    const commitRes = await electronGit.commit(
      `chore: 切换前自动提交 (${new Date().toLocaleString("zh-CN")})`,
    );
    if (!commitRes.ok) {
      storeActions.showToast({
        type: "error",
        title: "提交失败",
        description: commitRes.error,
      });
      setConfirmDialog((prev) => ({ ...prev, committing: false }));
      return;
    }
    await doSwitch(confirmDialog.targetBranch);
    setConfirmDialog({
      open: false,
      targetBranch: "",
      files: [],
      committing: false,
    });
  };

  const handleCreate = async (name: string) => {
    if (!isElectron() || !workDir) return;
    const res = await electronGit.branchCreate(name, workDir);
    if (res.ok) {
      onBranchChange(name);
      setOpen(false);
      storeActions.showToast({
        type: "success",
        title: `已创建并检出 ${name}`,
      });
      // Refresh list so the new branch shows up next time.
      electronGit
        .branchList(workDir)
        .then((r: { ok: boolean; branches?: string[] }) => {
          if (r.ok && r.branches) setList(r.branches);
        })
        .catch(() => {});
    } else {
      storeActions.showToast({
        type: "error",
        title: "创建分支失败",
        description: res.error,
      });
    }
  };

  const popoverPosition =
    drop === "up" ? "bottom-full left-0 mb-1.5" : "top-full left-0 mt-1.5";

  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={handleOpen}
        disabled={!currentBranch}
        className={`flex items-center gap-1 text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/60 bg-accent/40 px-2 py-1 rounded-lg shrink-0 transition-colors hover:text-foreground hover:bg-accent/60 disabled:opacity-50 disabled:cursor-default ${className ?? ""}`}
        data-tip={currentBranch ? `当前分支：${currentBranch}` : undefined}
      >
        <GitBranch className="size-4 text-muted-foreground" />
        <span className="whitespace-nowrap">{currentBranch}</span>
      </button>
      {open && (
        <div
          className={`absolute ${popoverPosition} w-64 bg-popover rounded-xl border border-border shadow-lg z-50 flex flex-col max-h-80`}
        >
          {/* Search */}
          <div className="px-3 pt-2.5 pb-1.5 border-b border-border/20">
            <div className="flex items-center gap-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground">
              <Search className="size-3.5 shrink-0" />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="搜索分支"
                className="flex-1 bg-transparent outline-none placeholder:text-muted-foreground/50"
                autoFocus
              />
            </div>
          </div>

          {/* Branch list */}
          <div className="flex-1 overflow-y-auto py-1 min-h-0">
            <div className="px-3 py-1 text-[calc(var(--helix-transcript-size)*0.7857)] font-medium text-muted-foreground">
              分支
            </div>
            {list
              .filter(
                (b) =>
                  !search || b.toLowerCase().includes(search.toLowerCase()),
              )
              .map((b) => (
                <button
                  key={b}
                  type="button"
                  onClick={() => handleSwitch(b)}
                  className={`w-full flex items-center gap-2 text-[calc(var(--helix-transcript-size)*0.9286)] px-3 py-1.5 transition-colors ${b === currentBranch ? "bg-primary/8 text-primary" : "text-foreground/80 hover:bg-muted/40"}`}
                >
                  <GitBranch className="size-3.5 shrink-0 text-foreground/40" />
                  <span className="truncate flex-1 text-left">{b}</span>
                  {b === currentBranch && (
                    <div className="flex items-center gap-1.5 shrink-0">
                      {dirtyCount > 0 && (
                        <span className="text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground">
                          未提交：{dirtyCount}
                        </span>
                      )}
                      <Check
                        className="size-4 text-primary"
                        strokeWidth={2.5}
                      />
                    </div>
                  )}
                </button>
              ))}
          </div>

          {/* Create branch */}
          <div className="border-t border-border/20">
            {!creating ? (
              <button
                type="button"
                onClick={() => {
                  setCreating(true);
                  setNewName("");
                }}
                className="w-full flex items-center gap-2 text-[calc(var(--helix-transcript-size)*0.8571)] px-3 py-2 text-foreground/50 hover:text-foreground hover:bg-muted/30 transition-colors"
              >
                <Plus className="size-3" />
                创建并检出新分支...
              </button>
            ) : (
              <div className="px-3 py-2 space-y-1.5">
                <input
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && newName.trim())
                      handleCreate(newName.trim());
                    if (e.key === "Escape") setCreating(false);
                  }}
                  placeholder="新分支名称"
                  className="w-full text-[calc(var(--helix-transcript-size)*0.8571)] px-2 py-1 rounded-md bg-muted/40 border border-border/30"
                  autoFocus
                />
                <div className="flex gap-1.5">
                  <button
                    type="button"
                    onClick={() => handleCreate(newName.trim())}
                    disabled={!newName.trim()}
                    className="flex-1 text-[calc(var(--helix-transcript-size)*0.7857)] py-1 rounded-md bg-primary/15 text-primary hover:bg-primary/25 transition-colors disabled:opacity-30"
                  >
                    创建
                  </button>
                  <button
                    type="button"
                    onClick={() => setCreating(false)}
                    className="flex-1 text-[calc(var(--helix-transcript-size)*0.7857)] py-1 rounded-md bg-muted/40 text-foreground/70 hover:bg-muted/60 transition-colors"
                  >
                    取消
                  </button>
                </div>
              </div>
