            </div>
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import {
  defaultHighlightStyle,
  syntaxHighlighting,
} from "@codemirror/language";
import { loadLanguage } from "@uiw/codemirror-extensions-langs";
import CodeMirror from "@uiw/react-codemirror";
import { FileCode2, AlertTriangle } from "lucide-react";
import React, { useEffect, useMemo } from "react";
import { electronFS } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";

// Map a file extension to a CodeMirror language id (the keys accepted by
// `@uiw/codemirror-extensions-langs` loadLanguage).
const EXT_LANG: Record<string, string> = {
  ts: "typescript",
  tsx: "tsx",
  js: "javascript",
  jsx: "jsx",
  mjs: "javascript",
  cjs: "javascript",
  json: "json",
  py: "python",
  rs: "rust",
  go: "go",
  java: "java",
  c: "c",
  h: "c",
  cpp: "cpp",
  cc: "cpp",
  cxx: "cpp",
  hpp: "cpp",
  cs: "csharp",
  rb: "ruby",
  php: "php",
  swift: "swift",
  kt: "kotlin",
  scala: "scala",
  sh: "shell",
  bash: "shell",
  zsh: "shell",
  yml: "yaml",
  yaml: "yaml",
  toml: "toml",
  xml: "xml",
  html: "html",
  htm: "html",
  css: "css",
  scss: "sass",
  less: "less",
  md: "markdown",
  markdown: "markdown",
  sql: "sql",
  vue: "vue",
  svelte: "svelte",
  dart: "dart",
  lua: "lua",
  r: "r",
  pl: "perl",
  ex: "elixir",
  exs: "elixir",
  erl: "erlang",
  hs: "haskell",
  m: "objectivec",
  mm: "objectivec",
  proto: "protobuf",
  graphql: "graphql",
  gql: "graphql",
  dockerfile: "dockerfile",
  makefile: "makefile",
  cmake: "cmake",
  ini: "ini",
  conf: "nginx",
  log: "log",
  txt: "text",
  gitignore: "text",
  env: "shell",
};

function langFromName(name: string): string {
  const lower = name.toLowerCase();
  if (lower === "dockerfile" || lower === "makefile") return lower;
  const ext = lower.includes(".") ? lower.split(".").pop()! : "";
  return EXT_LANG[ext] || "text";
}

export function CodeEditorPanel({ onClose }: { onClose: () => void }) {
  const editorTabs = useHelixStore((s) => s.editorTabs);
  const activeId = useHelixStore((s) => s.activeEditorTabId);
  const editorTheme = useHelixStore((s) => s.editorTheme);
  const setActiveEditorTab = useHelixStore((s) => s.setActiveEditorTab);
  const closeEditorTab = useHelixStore((s) => s.closeEditorTab);
  const setPendingCloseId = useHelixStore((s) => s.setPendingCloseId);
  const pendingCloseId = useHelixStore((s) => s.pendingCloseId);
  const updateEditorTabContent = useHelixStore((s) => s.updateEditorTabContent);
  const markEditorTabSaved = useHelixStore((s) => s.markEditorTabSaved);
  const showToast = useHelixStore((s) => s.showToast);

  const active = editorTabs.find((t) => t.id === activeId) || null;

  // Self-heal a stale `activeEditorTabId`: the parent only renders this panel
  // when there is at least one open tab, so `active` being null here is always a
  // desync (e.g. the id pointing at a tab that was closed). Fall back to the
  // most recent tab instead of showing the "click a file to edit" placeholder.
  useEffect(() => {
    if (editorTabs.length > 0 && !editorTabs.some((t) => t.id === activeId)) {
      setActiveEditorTab(editorTabs[editorTabs.length - 1].id);
    }
  }, [editorTabs, activeId, setActiveEditorTab]);

  // Editor tab waiting for an unsaved-changes confirmation before it closes.
  const pendingClose = editorTabs.find((t) => t.id === pendingCloseId) || null;

  const handleSave = async (id: string): Promise<boolean> => {
    const tab = useHelixStore.getState().editorTabs.find((t) => t.id === id);
    if (!tab) return false;
    try {
      await electronFS.writeFile(tab.path, tab.content);
      markEditorTabSaved(id);
      showToast({ type: "success", title: "已保存", description: tab.name });
      return true;
    } catch (e: any) {
      showToast({
        type: "error",
        title: "保存失败",
        description: e?.message || "写入文件出错",
      });
      return false;
    }
  };

  const confirmSaveAndClose = async () => {
    if (!pendingCloseId) return;
    const id = pendingCloseId;
    const ok = await handleSave(id);
    if (ok) closeEditorTab(id);
    setPendingCloseId(null);
  };

  const confirmDiscardClose = () => {
    if (!pendingCloseId) return;
    closeEditorTab(pendingCloseId);
    setPendingCloseId(null);
  };

  // Ctrl/Cmd+S → save active tab
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        if (active && active.dirty) {
          e.preventDefault();
          handleSave(active.id);
        }
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active]);

  const langExt = useMemo(() => {
    const highlight = syntaxHighlighting(defaultHighlightStyle, {
      fallback: true,
    });
    if (!active) return [highlight];
    const ext = loadLanguage(
      langFromName(active.name) as Parameters<typeof loadLanguage>[0],
    );
    return ext ? [highlight, ext] : [highlight];
  }, [active]);

  const themeMode = editorTheme === "vs-dark" ? "dark" : "light";

  if (!active) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center text-muted-foreground/50 gap-2 bg-card">
        <FileCode2 className="size-10" />
        <p className="text-[length:var(--helix-transcript-size)]">
          从左侧文件树点击文件即可在此编辑
        </p>
        <button
          onClick={onClose}
          className="mt-2 px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] rounded-lg border border-border/60 hover:bg-accent/50 transition-colors"
        >
          关闭编辑器
        </button>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col h-full overflow-hidden bg-card">
      {/* Editor — the file name / close live in the unified right-sidebar tab
          strip (one row), so there is no duplicate per-file tab bar here. */}
      <div className="flex-1 min-h-0 overflow-hidden">
        <CodeMirror
          value={active.content}
          height="100%"
          theme={themeMode}
          extensions={langExt}
          onChange={(val) => updateEditorTabContent(active.id, val)}
          basicSetup={{
            lineNumbers: true,
            highlightActiveLine: true,
            highlightActiveLineGutter: true,
            foldGutter: true,
            autocompletion: true,
            bracketMatching: true,
            indentOnInput: true,
          }}
          style={{
            height: "100%",
            fontSize: "var(--helix-font-size, 13px)",
            fontFamily: "var(--helix-font-family, monospace)",
          }}
        />
      </div>

      {pendingClose && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/40">
          <div className="bg-card border border-border/80 rounded-lg shadow-xl w-[380px] p-5 flex flex-col gap-4">
            <div className="flex items-start gap-3">
              <AlertTriangle className="size-5 text-amber-400 shrink-0 mt-0.5" />
              <div className="min-w-0">
                <h3 className="text-[length:var(--helix-transcript-size)] font-medium text-foreground">
                  未保存的修改
                </h3>
                <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground mt-1 break-words">
                  <span className="font-mono text-foreground/80">
                    {pendingClose.name}
                  </span>{" "}
                  有未保存的修改，关闭前要保存吗？
                </p>
              </div>
            </div>
            <div className="flex items-center justify-end gap-2">
              <button
                onClick={() => setPendingCloseId(null)}
                className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] rounded-md text-muted-foreground/80 hover:bg-accent/60 transition-colors"
              >
                取消
              </button>
              <button
                onClick={confirmDiscardClose}
                className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] rounded-md text-destructive border border-destructive/40 hover:bg-destructive/10 transition-colors"
              >
                不保存
              </button>
              <button
                onClick={confirmSaveAndClose}
                className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] rounded-md bg-primary text-primary-foreground hover:opacity-90 transition-colors"
              >
                保存并关闭
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import {
  Search,
  FileCode,
  Plus,
  Terminal,
  MessageSquare,
  FolderPlus,
  Save,
  Trash2,
  Keyboard,
  Moon,
  Sun,
  Copy,
  Settings,
  Sparkles,
} from "lucide-react";
import React, {
  useState,
  useEffect,
  useRef,
  useMemo,
  useCallback,
} from "react";
import { useHelixStore, type FileNode } from "@/stores/helix-store";
import { DEFAULT_SHORTCUTS } from "@/stores/helix-types";

function getShortcutLabel(
  id: string,
  customShortcuts: Record<string, { keys: string[] }>,
): string {
  const entry = customShortcuts[id] || DEFAULT_SHORTCUTS[id];
  return entry?.keys?.join("+") || "";
}

interface CommandItem {
  id: string;
  label: string;
  description?: string;
  icon: React.ReactNode;
  action: () => void;
  category: "file" | "action";
  shortcut?: string;
  disabled?: boolean;
}

export function CommandPalette() {
  const {
    showCommandPalette,
    setCommandPaletteOpen,
    openFile,
    toggleTerminal,
    clearChat,
    createFile,
    files,
    showToast,
    markTabSaved,
    activeTabId,
    openTabs,
    editorTheme,
    setEditorTheme,
    getAllFiles,
    getFilePath,
    customShortcuts,
  } = useHelixStore();

  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const selectedIndexRef = useRef(0);

  const allFiles = useMemo(() => {
    const result: FileNode[] = [];
    const collect = (nodes: FileNode[]) => {
      for (const n of nodes) {
        if (n.type === "file") result.push(n);
        if (n.children) collect(n.children);
      }
    };
    collect(files);
    return result;
  }, [files]);

  const commands = useMemo<CommandItem[]>(() => {
    const fileItems: CommandItem[] = allFiles.map((f) => ({
      id: `file-${f.id}`,
      label: f.name,
      description: useHelixStore.getState().getFilePath(f.id),
      icon: <FileCode className="size-4 text-muted-foreground" />,
      action: () => {
        openFile(f.id);
        const expandParents = (
          nodes: FileNode[],
          targetId: string,
          parents: string[],
        ) => {
          for (const n of nodes) {
            if (n.id === targetId) {
              parents.forEach((pid) => {
                const s = useHelixStore.getState();
                if (!s.expandedFolders.has(pid)) s.toggleFolder(pid);
              });
              return true;
            }
            if (
              n.children &&
              expandParents(n.children, targetId, [...parents, n.id])
            )
              return true;
          }
          return false;
        };
        expandParents(useHelixStore.getState().files, f.id, []);
      },
      category: "file" as const,
    }));

    const actionItems: CommandItem[] = [
      {
        id: "action-new-file",
        label: "新建文件",
        description: "在根目录创建新文件",
        icon: <Plus className="size-4 text-emerald-400" />,
        action: () => {
          const name = prompt("输入文件名：");
          if (name?.trim()) {
            createFile(null, name.trim(), "file");
          }
        },
        category: "action",
        shortcut: "Ctrl+Shift+N",
      },
      {
        id: "action-new-folder",
        label: "新建文件夹",
        description: "在根目录创建新文件夹",
        icon: <FolderPlus className="size-4 text-amber-400" />,
        action: () => {
          const name = prompt("输入文件夹名：");
          if (name?.trim()) createFile(null, name.trim(), "folder");
        },
        category: "action",
      },
      {
        id: "action-toggle-terminal",
        label: "切换终端",
        description: "显示或隐藏终端面板",
        icon: <Terminal className="size-4 text-amber-400" />,
        action: toggleTerminal,
        category: "action",
        shortcut: getShortcutLabel("toggle-terminal", customShortcuts),
      },
      {
        id: "action-clear-chat",
        label: "清空对话",
        description: "清空 AI 对话历史",
        icon: <MessageSquare className="size-4 text-blue-400" />,
        action: clearChat,
        category: "action",
      },
      {
        id: "action-save",
        label: "保存当前文件",
        description: activeTabId
          ? `保存 ${openTabs.find((t) => t.id === activeTabId)?.name || ""}`
          : "没有打开的文件",
        icon: <Save className="size-4 text-blue-400" />,
        action: () => {
          if (activeTabId) {
            markTabSaved(activeTabId);
          }
        },
        category: "action",
        shortcut: "Ctrl+S",
        disabled: !activeTabId,
      },
      {
        id: "action-copy-path",
        label: "复制文件路径",
        description: activeTabId
          ? getFilePath(
              openTabs.find((t) => t.id === activeTabId)?.fileId || "",
            )
          : "没有打开的文件",
        icon: <Copy className="size-4 text-blue-400" />,
        action: () => {
          if (activeTabId) {
            const tab = openTabs.find((t) => t.id === activeTabId);
            if (tab) {
              const path = getFilePath(tab.fileId);
              navigator.clipboard.writeText(path);
            }
          }
        },
        category: "action",
        shortcut: "Ctrl+Shift+C",
        disabled: !activeTabId,
      },
      {
        id: "action-toggle-theme",
        label: "切换编辑器主题",
        description: `当前: ${editorTheme === "vs-dark" ? "深色" : "浅色"}`,
        icon:
          editorTheme === "vs-dark" ? (
            <Moon className="size-4 text-blue-400" />
          ) : (
            <Sun className="size-4 text-yellow-400" />
          ),
        action: () => {
          const next = editorTheme === "vs-dark" ? "light" : "vs-dark";
          setEditorTheme(next);
        },
        category: "action",
      },
      {
        id: "action-shortcuts",
        label: "键盘快捷键",
        description: "查看所有可用的快捷键",
        icon: <Keyboard className="size-4 text-cyan-400" />,
        action: () => {},
        category: "action",
      },
    ];

    return [...fileItems, ...actionItems];
  }, [
    allFiles,
    openFile,
    toggleTerminal,
    clearChat,
    createFile,
    files,
    showToast,
    markTabSaved,
    activeTabId,
    openTabs,
    editorTheme,
    setEditorTheme,
    getFilePath,
    customShortcuts,
  ]);

  // Fuzzy match
  const filtered = useMemo(() => {
    if (!query.trim()) return commands;
    const q = query.toLowerCase();

    return commands
      .map((item) => {
        const label = item.label.toLowerCase();
        const desc = (item.description || "").toLowerCase();
        const labelIdx = label.indexOf(q);
        const descIdx = desc.indexOf(q);

        // Fuzzy match for label
        let fuzzyScore = 0;
        let qi = 0;
        for (let i = 0; i < label.length && qi < q.length; i++) {
          if (label[i] === q[qi]) {
            fuzzyScore += (qi === 0 ? 10 : 1) + (i === qi ? 5 : 0);
            qi++;
          }
        }
        const fuzzyMatch = qi === q.length;

        if (labelIdx >= 0) return { item, score: 100 - labelIdx };
        if (descIdx >= 0) return { item, score: 50 - descIdx };
        if (fuzzyMatch) return { item, score: fuzzyScore };
        return null;
      })
      .filter(Boolean)
      .sort((a, b) => (b?.score || 0) - (a?.score || 0))
      .map((r) => r!.item);
  }, [query, commands]);

  // Reset selection when query changes
  const prevQueryRef = useRef(query);
  let effectiveIndex = selectedIndexRef.current;
  if (query !== prevQueryRef.current) {
    prevQueryRef.current = query;
    selectedIndexRef.current = 0;
    effectiveIndex = 0;
  }

  useEffect(() => {
    if (showCommandPalette) {
      setQuery("");
      selectedIndexRef.current = 0;
      // Delay focus to allow React to render the input
      setTimeout(() => inputRef.current?.focus(), 0);
    }
  }, [showCommandPalette]);

  const handleSelect = useCallback(
    (item?: CommandItem) => {
      const target = item || filtered[effectiveIndex];
      if (target && !("disabled" in target)) {
        target.action();
        setCommandPaletteOpen(false);
      }
    },
    [filtered, effectiveIndex, setCommandPaletteOpen],
  );

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        selectedIndexRef.current = Math.min(
          selectedIndexRef.current + 1,
          filtered.length - 1,
        );
        setQuery((q) => q);
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        selectedIndexRef.current = Math.max(selectedIndexRef.current - 1, 0);
        setQuery((q) => q);
      } else if (e.key === "Enter") {
        e.preventDefault();
        handleSelect();
      } else if (e.key === "Escape") {
        e.preventDefault();
        setCommandPaletteOpen(false);
      }
    },
    [filtered, handleSelect, setCommandPaletteOpen],
  );

  if (!showCommandPalette) return null;

  // Separate files and actions for grouped display
  const fileResults = filtered.filter((c) => c.category === "file");
  const actionResults = filtered.filter((c) => c.category === "action");

  const renderSection = (
    title: string,
    items: CommandItem[],
    offset: number,
  ) => {
    if (items.length === 0) return null;
    return (
      <div>
        {title && (
          <div className="px-4 py-1.5 text-[calc(var(--helix-transcript-size)*0.7143)] font-semibold uppercase tracking-wider text-muted-foreground/60 bg-muted/30">
            {title}
          </div>
        )}
        {items.map((item, idx) => {
          const globalIdx = offset + idx;
          const isActive = globalIdx === effectiveIndex;
          return (
            <div
              key={item.id}
              className={`flex items-center gap-3 px-4 py-2.5 cursor-pointer transition-colors ${
                isActive
                  ? "bg-accent text-accent-foreground"
                  : "text-foreground hover:bg-accent/50"
              }`}
              onClick={() => handleSelect(item)}
              onMouseEnter={() => {
                selectedIndexRef.current = globalIdx;
                setQuery((q) => q);
              }}
            >
              {item.icon}
              <div className="flex-1 min-w-0">
                <p className="text-[length:var(--helix-transcript-size)] font-medium truncate">
                  {item.label}
                </p>
                {item.description && (
                  <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground truncate">
                    {item.description}
                  </p>
                )}
              </div>
              {item.category === "file" && (
                <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground bg-muted/50 px-2 py-0.5 rounded">
                  文件
                </span>
              )}
              {item.shortcut && (
                <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/60 bg-muted/30 px-1.5 py-0.5 rounded hidden sm:block">
                  {item.shortcut}
                </span>
              )}
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[12vh]">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/50"
        onClick={() => setCommandPaletteOpen(false)}
      />
      {/* Palette */}
      <div className="relative w-full max-w-lg bg-card border border-border/60 rounded-2xl shadow-2xl overflow-hidden">
        {/* Search input */}
        <div className="flex items-center gap-3 px-4 border-b border-border/60">
          <Search className="size-4 text-muted-foreground shrink-0" />
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="搜索文件或输入命令..."
            className="flex-1 py-3.5 bg-transparent text-[length:var(--helix-transcript-size)] outline-none placeholder:text-muted-foreground"
          />
          <kbd className="hidden sm:flex items-center gap-0.5 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground bg-muted px-1.5 py-0.5 rounded">
            ESC
          </kbd>
        </div>
        {/* Results */}
        <div className="max-h-80 overflow-y-auto">
          {filtered.length === 0 && (
            <div className="px-4 py-8 text-center text-[length:var(--helix-transcript-size)] text-muted-foreground">
              没有找到匹配的结果
            </div>
          )}
          {renderSection("", fileResults, 0)}
          {fileResults.length > 0 && actionResults.length > 0 && (
            <div className="my-1 border-t border-border/30" />
          )}
          {renderSection("操作", actionResults, fileResults.length)}
        </div>
        {/* Footer */}
        <div className="flex items-center gap-4 px-4 py-2 border-t border-border/60 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground">
          <span className="flex items-center gap-1">
            <kbd className="bg-muted px-1 py-0.5 rounded">↑↓</kbd> 导航
          </span>
          <span className="flex items-center gap-1">
            <kbd className="bg-muted px-1 py-0.5 rounded">↵</kbd> 选择
          </span>
          <span className="flex items-center gap-1">
            <kbd className="bg-muted px-1 py-0.5 rounded">ESC</kbd> 关闭
          </span>
          <span className="ml-auto text-muted-foreground/50">
            {filtered.length} 个结果
          </span>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useRef, useEffect, useCallback } from "react";
import { captureContextBreakdown } from "@/lib/context-capture";
import { helixApi } from "@/lib/electron-bridge";
import { formatTokens } from "@/lib/format";
import { debug } from "@/lib/logger";
import { resolveBackendSid } from "@/lib/session-map";
import { mapBackendMessages } from "@/lib/session-resync";
import {
  resyncCurrentSessionFromBackend,
  isCurrentSessionRenderBroken,
} from "@/lib/session-resync";
import { useHelixStore } from "@/stores/helix-store";

// ---- Types ----

interface ContextBreakdown {
  id: string;
  label: string;
  tokens: number;
  color: string;
  /** 后端"整块占用"兜底项（会话文件还没落盘时给不出按内容的拆分） */
  aggregate?: boolean;
}

/** 兜底的"整块占用"：id/label 都对得上，或后端显式标了 aggregate。 */
function isAggregateCategory(c: ContextBreakdown): boolean {
  return (
    c.aggregate === true ||
    (c.id === "conversation" &&
      (c.label === "会话上下文" || c.label === "整体上下文占用"))
  );
}

/**
 * 选哪一套分类来渲染。
 *
 * 之前这里是「RPC categories 非空就顶替本地快照」，于是三套形态互相顶：
 * 分桶快照（上次 run 存的）→ 首轮里 RPC 的整块兜底 → 会话文件落盘后的分桶，
 * 每一步看着都像"分类自己变了"。现在按信息量排序：**分桶 > 整块兜底**，
 * 同级里实时数据优先；只有当两边都拿不出分桶时才显示整块兜底。
 */
function pickCategories(
  backend: ContextBreakdown[] | undefined,
  local: ContextBreakdown[] | undefined,
): ContextBreakdown[] {
  const live = backend?.length ? backend : undefined;
  const snap = local?.length ? local : undefined;
  const liveBuckets = live?.some((c) => !isAggregateCategory(c)) ? live : undefined;
  const snapBuckets = snap?.some((c) => !isAggregateCategory(c)) ? snap : undefined;
  // Prefer live buckets, then snapshot buckets, then any live data, then any
  // snapshot data. Within each tier, bucket data beats a single aggregate lump
  // so the panel never swaps between 分桶 and 整块 fallback in the same window.
  return liveBuckets ?? snapBuckets ?? live ?? snap ?? [];
}

function normalizeCategories(
  used: number,
  categories: ContextBreakdown[],
): Array<ContextBreakdown & { estimatedTokens: number }> {
  if (!used || categories.length === 0) return [];
  const visible = categories.filter((c) => c.tokens > 0);
  const estimatedTotal = visible.reduce((s, c) => s + c.tokens, 0);
  // The jsonl chars/4 estimate only counts message text blocks, not the
  // system prompt / tool schemas that dominate the real `used` figure. When
  // the estimate collapses to a tiny number (e.g. "回复 ~22" against a
  // 15.2K ring), the display looks broken. Floor each bucket's share of
  // `used` at its proportional estimate: display = max(estimate, used × share),
  // which keeps the bucket sum close to `used` while preserving the relative
  // split the estimate actually measured.
  return visible.map((category) => {
    const share = estimatedTotal > 0 ? category.tokens / estimatedTotal : 0;
    const proportional = Math.round(used * share);
    const displayTokens = Math.max(category.tokens, proportional);
    return { ...category, estimatedTokens: category.tokens, tokens: displayTokens };
  });
}

interface ContextUsageData {
  context_max: number;
  context_used: number;
  context_percent: number;
  estimated_total?: number;
  categories: ContextBreakdown[];
  toolsets?: Array<{
    toolset: string;
    tool_count: number;
    schema_tokens: number;
  }>;
}

// Backend categories use a chars/4 heuristic, while the top-level `used` is the
// provider-exact prompt+completion figure. For a coherent UI, categories are
// normalized to the real usage total; tooltips retain the original heuristic
// estimate. Compression decisions use the real usage figure, not this display
// normalization.

// ---- ContextUsageBar (segmented horizontal bar — Helix Desktop style) ----

function ContextUsageBar({
  used,
  total,
  categories,
}: {
  used: number;
  total: number;
  categories: ContextBreakdown[];
}) {
  const percentage = Math.min(Math.max((used / total) * 100, 0), 100);
  // Segment widths are proportional to each category's share, normalized to the
  // used fill — so the bar always reads as used/total regardless of whether the
  // category tokens come from the backend or the local session stats.
  const catTotal = categories.reduce((s, c) => s + c.tokens, 0) || 1;

  return (
    <div className="w-full">
      <div className="flex items-center justify-between mb-1.5">
        <span className="text-[length:var(--helix-transcript-size)] font-semibold text-foreground">
          ~{formatTokens(used)}
        </span>
        <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground">
          / {formatTokens(total)} &middot; {percentage.toFixed(1)}%
        </span>
      </div>
      {/* Segmented bar */}
      <div className="h-2 w-full bg-muted rounded-full overflow-hidden flex">
        {categories.map((cat) => {
          const catPercent =
            used > 0 ? (cat.tokens / catTotal) * percentage : 0;
          if (catPercent <= 0) return null;
          return (
            <div
              key={cat.id}
              className="h-full transition-all duration-300 first:rounded-l-full last:rounded-r-full"
              style={{
                width: `${Math.max(catPercent, 0.5)}%`,
                backgroundColor: cat.color,
              }}
              data-tip={`${cat.label}: ~${formatTokens(cat.tokens)}`}
            />
          );
        })}
      </div>
    </div>
  );
}

// ---- Panel (detailed breakdown popover) ----

function ContextUsagePanel({
  used,
  total,
  categories,
  toolsets,
  onClose,
}: {
  used: number;
  total: number;
  categories: ContextBreakdown[];
  toolsets?: Array<{
    toolset: string;
    tool_count: number;
    schema_tokens: number;
  }>;
  onClose: () => void;
}) {
  const [showToolsets, setShowToolsets] = useState(false);
  // Raw per-toolset schema estimates; they describe schema size, not the exact
  // provider token cost, so they remain unnormalized.
  const toolsetList = toolsets ?? [];
  const normalizedCategories = normalizeCategories(used, categories);
  // 后端在会话文件落盘前只能给出"整块占用"这一项 —— 明确说明，别让它看起来
  // 像某个内容分类（"对话中分类变成会话上下文"的观感来源）。
  const aggregateOnly =
    normalizedCategories.length > 0 &&
    normalizedCategories.every(isAggregateCategory);

  return (
    <div className="absolute bottom-full right-0 mb-2 w-72 bg-card border border-border/60 rounded-xl shadow-lg p-3 z-50">
      <ContextUsageBar
        used={used}
        total={total}
        categories={normalizedCategories}
      />
      {/* Legend list */}
      <div className="mt-3 space-y-1.5">
        {normalizedCategories.length === 0 ? (
          <div className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground">
            暂无上下文分类数据
          </div>
        ) : (
          normalizedCategories.map((item) => {
            return (
              <div key={item.id} className="flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                  <span
                    className="w-2 h-2 rounded-sm"
                    style={{ backgroundColor: item.color }}
                  />
                  <span className="text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground">
                    {item.label}
                  </span>
                </div>
                <span className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground tabular-nums">
                  ~{formatTokens(item.tokens)}
                </span>
              </div>
            );
          })
        )}
      </div>
      {aggregateOnly && (
        <div className="mt-2 text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground/80 leading-snug">
          整体占用：本轮会话记录尚未落盘，暂时拿不到按内容拆分的分类
        </div>
      )}
      {toolsetList.length > 0 && (
        <div className="mt-3 pt-2 border-t border-border/40">
          <button
            type="button"
            onClick={() => setShowToolsets((v) => !v)}
            className="w-full flex items-center justify-between text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/70 hover:text-foreground transition-colors cursor-pointer"
          >
            <span>工具集明细 ({toolsetList.length})</span>
            <span className="text-foreground/50">
              {showToolsets ? "收起" : "展开"}
            </span>
          </button>
          {showToolsets && (
            <div className="mt-2 space-y-1">
              {toolsetList.map((t) => (
                <div
                  key={t.toolset}
                  className="flex items-center justify-between gap-2 pl-2"
                >
                  <span className="text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground truncate">
                    {t.toolset}
                  </span>
                  <span className="text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground tabular-nums shrink-0">
                    {t.tool_count} 工具 · ~{formatTokens(t.schema_tokens)}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ---- Main indicator (button + popover combo) ----

export function ContextUsageIndicator() {
  const [open, setOpen] = useState(false);
  const [backendData, setBackendData] = useState<ContextUsageData | null>(null);
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (panelRef.current && !panelRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Auto-compaction: trigger when context usage exceeds 80% and setting is enabled
  const autoCompactCooldownRef = useRef(false);

  // Fetch context breakdown from backend via RPC
  const fetchContextData = useCallback(async () => {
    try {
      const currentSessionId = useHelixStore.getState().currentSessionId;
      // Only the backend sid mapped to THIS conversation — never fall back to
      // the global helixSessionId: that is whichever conversation ran LAST,
      // and querying it would write the GLOBAL session's usage/categories into
      // this conversation's snapshot (contextUsage), making the ring track
      // another conversation. Unmapped → render the persisted local snapshot.
      const sessionId = await resolveBackendSid(currentSessionId);
      if (!sessionId) {
        setBackendData(null);
        return;
      }
      const result = await helixApi()?.send("session.context_breakdown", {
        session_id: sessionId,
      });
      if (result && typeof result === "object") {
        const data = result as ContextUsageData;
        setBackendData(data);
        // 本地快照写回统一收敛到 captureContextBreakdown（context-capture.ts）：
        // - 仅当后端回报非零用量或分类非空才写，避免空会话把本地真实值覆盖成 0；
        // - size/used 用本地已有值兜底（used 取 max），避免估算偏低时把环缩水；
        // - 分类数据只要有就持久化（唯一来源，不写重启后必显示"暂无上下文分类数据"）。
        await captureContextBreakdown(currentSessionId, sessionId);

        // Auto-compaction check (Helix Desktop style)
        if (data.context_percent >= 80 && !autoCompactCooldownRef.current) {
          const {
            autoCompactContext,
            compressionBusy,
            showToast,
            streamingDrafts,
            isChatLoading,
          } = useHelixStore.getState();
          // Agent run-in-flight guard: the backend rejects session.compress with
          // "session busy" while a turn is running (methods_session.py). Firing
          // anyway burned the 60s cooldown on a doomed RPC and the empty catch
          // made the failure invisible — "自动压缩没动画/没效果"根因。静默跳过
          // （不消耗冷却）让 run 结束后的下一轮轮询真正触发压缩。
          const runInFlight =
            isChatLoading ||
            Object.values(streamingDrafts || {}).some((d) => d?.isAgentRunning);
          if (autoCompactContext && !compressionBusy && !runInFlight) {
            autoCompactCooldownRef.current = true;
            // Cooldown: don't trigger again for 60 seconds
            setTimeout(() => {
              autoCompactCooldownRef.current = false;
            }, 60_000);
            // 与手动 /compact 共用 busy 标记：避免后端压缩锁冲突
            useHelixStore.getState().setCompressionBusy(true);
            try {
              const result = await helixApi()?.send("session.compress", {
                session_id: sessionId,
              });
              if (result && typeof result === "object") {
                const r = result as any;
                if (r.status === "compressed" && Array.isArray(r.messages)) {
                  let anchorMessageId: string | undefined;
                  // Update frontend messages with compressed messages
                  const currentSessionId =
                    useHelixStore.getState().currentSessionId;
                  if (currentSessionId) {
                    const msgs = mapBackendMessages(
                      r.messages,
                      currentSessionId,
                    );
                    // 仅替换「当前会话」：chatMessages 是跨会话全局数组，整体覆盖会清掉
                    // 其他会话历史（"压缩后消息全空"）。与手动 /compact 的修复一致。
                    useHelixStore.setState((state) => ({
                      chatMessages: [
                        ...state.chatMessages.filter(
                          (m) =>
                            m.sessionId && m.sessionId !== currentSessionId,
                        ),
                        ...msgs,
                      ],
                    }));
                    anchorMessageId =
                      msgs.length > 0 ? msgs[msgs.length - 1].id : undefined;
                  }
                  // 自动压缩提示卡片：transcript 顶部可关闭，8s 自动消失
                  useHelixStore.getState().setCompressionNotice({
                    ts: Date.now(),
                    sessionId: currentSessionId || "__draft__",
                    source: "auto",
                    anchorMessageId,
                    removed: Number(r.removed) || undefined,
                    beforeTokens: Number(r.before_tokens) || undefined,
                    afterTokens: Number(r.after_tokens) || undefined,
                    messageCount: Number(r.after_messages) || undefined,
                  });
                  // 自动自愈：若压缩回包异常导致当前会话仍为空，直接异步从后端拉
                  // 权威历史覆盖，无需用户手动 /resync（"压缩后消息全空"兜底）。
                  if (isCurrentSessionRenderBroken(currentSessionId)) {
                    await resyncCurrentSessionFromBackend({
                      sessionId: currentSessionId || "",
                      showToast: true,
                      toastMessage: "压缩后消息异常，已自动从后端恢复",
                    });
                  }
                } else if (r.status === "aborted" || r.lock_held) {
                  // 后端没执行压缩（中止/锁被占）：不显示"已压缩"提示，说明原因
                  showToast({
                    type: "warning",
                    title: r.lock_held ? "压缩进行中" : "自动压缩已中止",
                    description:
                      r.message ||
                      (r.status === "aborted"
                        ? "后端中止了本次压缩"
                        : "另一个压缩任务正在运行"),
                  });
                }
              }
              debug(
                "[ContextUsage] auto-compaction triggered at",
                data.context_percent.toFixed(1),
                "%",
              );
            } catch (e) {
              // 自动压缩失败（超时/后端拒绝）：必须有可见反馈，否则表现为
              // "有动画但压缩没成功"——busy 一闪即逝，用户无从得知原因。
              showToast({
                type: "error",
                title: "自动压缩失败",
                description: String((e as Error)?.message ?? e),
              });
            } finally {
              useHelixStore.getState().setCompressionBusy(false);
            }
          }
        }
      }
    } catch {
      // Backend may not support this — degrade gracefully
    }
  }, []);

  // 打开弹层时查询，并在打开期间每 5s 刷新一次：后端 agent 可能刚构建完成，
  // 分类数据不会在会话创建瞬间就绪，只查一次容易永久停留在"暂无上下文分类数据"。
  useEffect(() => {
    if (!open) return;
    fetchContextData();
    const timer = setInterval(fetchContextData, 5000);
    return () => clearInterval(timer);
  }, [open, fetchContextData]);

  // Quietly capture the category breakdown once per new live Helix session and
  // persist it into the local snapshot — WITHOUT overriding the displayed ring
  // data (which reflects THIS conversation's persisted usage). Previously the
  // breakdown was only saved when the popover was opened mid-session, so a cold
  // restart always fell back to the "需要正在运行的 Helix 会话" empty state
  // even though the total percentage had been persisted.
  const currentSessionId = useHelixStore((s) => s.currentSessionId);
  // 防重位只在成功写入后才置：会话创建瞬间 agent 尚未构建，后端返回空分类，
  // 若此时标记"已捕获"，该 sid 永不重试——run 结束后的权威分类就丢了
  // （"重启后有的会话分类消失"根因之一）。留空可在下次 dep 变化（新 run 换
  // sid / 切换会话）时重试；run 结束的兜底捕获在 agent-flow-panel finally 里。
  const quietFetchedSidRef = useRef<string | null>(null);
  // 本对话映射到的后端 sid。用途是**统一本地快照的键**：历史上
  // captureContextBreakdown 在还没有 cid（draft）时会用 sid 作键，而读侧只按
  // cid 查 → 会话换绑/重启后环读到空值就显示 0（"有时候自动清零"）。这里记下
  // sid，读侧两键都查，并把落在 sid 键上的旧快照一次性搬到 cid 键。
  const [backendSid, setBackendSid] = useState<string | null>(null);
  useEffect(() => {
    let cancelled = false;
    const capture = async () => {
      // 与 fetchContextData 同口径：只认本对话映射到的 sid，绝不兜底全局
      // helixSessionId（跨会话污染）。
      const sid = await resolveBackendSid(currentSessionId);
      if (cancelled) return;
      setBackendSid(sid ?? null);
      if (!sid) return;
      // 键统一：sid 键上的旧快照搬到 cid 键（只在 cid 键还空着时，不覆盖更新的值）
      if (currentSessionId) {
        const st = useHelixStore.getState();
        const legacy = st.contextUsage[sid];
        if (legacy && !st.contextUsage[currentSessionId]) {
          st.setContextUsage(
            currentSessionId,
            legacy.size,
            legacy.used,
            legacy.categories,
            legacy.toolsets,
          );
        }
      }
      const key = `${currentSessionId ?? ""}:${sid}`;
      if (quietFetchedSidRef.current === key) return;
      const written = await captureContextBreakdown(currentSessionId, sid);
      if (written) quietFetchedSidRef.current = key;
    };
    capture();
    return () => {
      cancelled = true;
    };
  }, [currentSessionId]);

  // Prefer live backend RPC data. When there is no live Helix session
  // (app/gateway restarted, or the conversation was never run this session) fall
  // fallback to the locally persisted per-conversation store
  // (contextUsage[currentSessionId]) so the ring does NOT reset to 0 after a
  // restart. The snapshot is written by usage_prompt_complete (实测) AND
  // captureContextBreakdown (max 合并下一条 prompt 的真实估算).
  // (No client-side estimation - real saved values.)
  // 快照键可能是 cid（常规）或 sid（历史遗留 / draft 期写入）——两键都查。
  const localCtx = useHelixStore((s) => {
    const cid = s.currentSessionId;
    if (!cid) return backendSid ? s.contextUsage[backendSid] : undefined;
    return s.contextUsage[cid] ?? (backendSid ? s.contextUsage[backendSid] : undefined);
  });
  const estimatedTokens = useHelixStore((s) =>
    s.currentSessionId ? s.estimatedTokens[s.currentSessionId] : undefined,
  );
  const isChatLoading = useHelixStore((s) => s.isChatLoading);
  // 统一口径：环读数以本地每对话快照为唯一渲染来源（usage_prompt_complete
  // 实测值与 captureContextBreakdown 的 max 合并写回——后两者同语义，都是
  // 「下一条 prompt 的真实上下文」）。弹窗 RPC 不直接喂环：它通过
  // captureContextBreakdown 落盘后再反映到环，避免开/关弹窗读数乱跳。
  //
  // 如果请求正在进行中（isChatLoading），且有估算值，显示估算值（带 ~ 前缀）。
  // 请求完成后，显示真实的 context_used 值。
  const total = localCtx?.size || 0;
  const estimated =
    isChatLoading && estimatedTokens !== undefined && estimatedTokens > 0
      ? estimatedTokens
      : undefined;
  const used = estimated ?? (localCtx?.used || 0);

  // 分桶优先于"整块占用"兜底（见 pickCategories）：RPC 非空不再无条件顶替本地
  // 快照，否则首轮里后端只给得出「会话上下文」一块时，原本的分桶会被它顶掉，
  // 看起来就像分类自己变了。
  const categories: ContextBreakdown[] = pickCategories(
    backendData?.categories,
    localCtx?.categories,
  ).map((c) => ({ ...c }));

  const toolsets: Array<{
    toolset: string;
    tool_count: number;
    schema_tokens: number;
  }> = backendData?.toolsets?.length
    ? backendData.toolsets.map((t) => ({ ...t }))
    : localCtx?.toolsets?.length
      ? localCtx.toolsets.map((t) => ({ ...t }))
      : [];

  // When there's no backend data, the ring renders empty (progress arc at 0).

  return (
    <div className="relative" ref={panelRef}>
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="size-10 rounded-lg flex items-center justify-center text-foreground/50 hover:text-foreground hover:bg-muted/60 transition-colors"
        data-tip={`上下文使用情况${estimated ? `（${formatTokens(estimated)} 估算）` : ""}`}
      >
        <ContextUsageRing used={used} total={total} />
      </button>
      {open && (
        <ContextUsagePanel
          used={used}
          total={total}
          categories={categories}
          toolsets={toolsets}
          onClose={() => setOpen(false)}
        />
      )}
    </div>
  );
}

// ---- Ring component (small circular progress indicator) ----

function ContextUsageRing({ used, total }: { used: number; total: number }) {
  const safeTotal = total > 0 ? total : 1;
  const percentage = Math.min(Math.max((used / safeTotal) * 100, 0), 100);
  const radius = 7;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;
  const colorClass =
    percentage > 90
      ? "text-red-500"
      : percentage > 70
        ? "text-amber-500"
        : "text-primary";

  return (
    <div className="relative size-7 flex items-center justify-center">
      <svg className="size-6 -rotate-90" viewBox="0 0 20 20">
        <circle
          cx="10"
          cy="10"
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeOpacity="0.15"
          strokeWidth="3"
        />
        <circle
          cx="10"
          cy="10"
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeWidth="3"
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          className={`${colorClass} transition-all duration-300`}
        />
      </svg>
    </div>
  );
}

