/** 是否为真正的 unified diff：diff 头行（---/+++/@@）出现在文本前部，
 *  且后文存在 + / - 改动行。普通命令/ls 输出不满足（无 diff 头行）。 */
export function looksLikeUnifiedDiff(text: string): boolean {
  const lines = text.split("\n");
  const firstNonEmpty = lines.findIndex((l) => l.trim());
  if (firstNonEmpty === -1 || firstNonEmpty > 3) return false;
  const head = lines.slice(firstNonEmpty, firstNonEmpty + 4);
  const headerNearStart =
    head.some((l) => /^--- /.test(l)) ||
    head.some((l) => /^\+\+\+ /.test(l)) ||
    head.some((l) => /^@@ /.test(l));
  if (!headerNearStart) return false;
  return lines.some((l) => l.startsWith("+") || l.startsWith("-"));
}

// Renders a backend-provided unified diff string directly (Helix inline_diff).
// Lines carry their own +/-/context markers, so we colorize them instead of
// recomputing a diff from old/new content.
function UnifiedDiffTextViewer({ diff }: { diff: string }) {
  // Normalize \r\n to \n for consistent splitting across platforms
  const normalizedDiff = useMemo(
    () => diff.replace(/\r\n/g, "\n").replace(/\r/g, "\n"),
    [diff],
  );
  // 非 diff 形态（diff 头行缺失）时不逐行着色：整段按普通文本渲染，
  // 防止后端误发的非 diff 内容（如命令输出）被染成满屏 + 行。
  const isRealDiff = useMemo(() => looksLikeUnifiedDiff(normalizedDiff), [
    normalizedDiff,
  ]);
  const lines = useMemo(() => normalizedDiff.split("\n"), [normalizedDiff]);
  return (
    <div className="font-mono text-[calc(var(--helix-font-size,13px)*0.9231)]">
      <div className="max-h-[500px] overflow-y-auto">
        {lines.map((line, idx) => {
          // 非 diff 形态时整段按普通文本渲染，不做逐行着色。
          if (!isRealDiff) {
            return (
              <div key={idx} className="flex hover:bg-accent/20">
                <span className="px-2 flex-1 whitespace-pre-wrap text-muted-foreground/80">
                  {line}
                </span>
              </div>
            );
          }
          if (line.startsWith("+++") || line.startsWith("---")) {
            return (
              <div
                key={idx}
                className="flex bg-purple-500/10 px-2 py-0.5 text-purple-300"
              >
                <span className="px-2 flex-1 whitespace-pre-wrap">{line}</span>
              </div>
            );
          }
          if (line.startsWith("@@")) {
            return (
              <div
                key={idx}
                className="flex bg-sky-500/10 px-2 py-0.5 text-sky-300"
              >
                <span className="px-2 flex-1 whitespace-pre-wrap">{line}</span>
              </div>
            );
          }
          if (line.startsWith("+")) {
            return (
              <div
                key={idx}
                className="flex bg-emerald-500/10 border-l-2 border-emerald-500"
              >
                <span className="px-2 flex-1 whitespace-pre-wrap text-emerald-300">
                  {line}
                </span>
              </div>
            );
          }
          if (line.startsWith("-")) {
            return (
              <div
                key={idx}
                className="flex bg-red-500/10 border-l-2 border-red-500"
              >
                <span className="px-2 flex-1 whitespace-pre-wrap text-red-300">
                  {line}
                </span>
              </div>
            );
          }
          return (
            <div key={idx} className="flex hover:bg-accent/20">
              <span className="px-2 flex-1 whitespace-pre-wrap text-muted-foreground/80">
                {line}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/** Count +added / -removed lines from a unified diff or old/new content pair. */
export function countDiffLines(change: DiffChange): {
  added: number;
  removed: number;
} {
  // unifiedDiff 须通过严格形态校验才逐行数 +/−；异常注入的非 diff 文本
  // 回退到 old/new 内容重算（都缺时 0/0），避免把命令输出里的 + 行误计。
  if (change.unifiedDiff && looksLikeUnifiedDiff(change.unifiedDiff)) {
    let added = 0,
      removed = 0;
    for (const line of change.unifiedDiff.split("\n")) {
      if (line.startsWith("+") && !line.startsWith("+++")) added++;
      else if (line.startsWith("-") && !line.startsWith("---")) removed++;
    }
    return { added, removed };
  }
  if (change.oldContent || change.newContent) {
    const diff = computeDiff(change.oldContent, change.newContent);
    return {
      added: diff.filter((l) => l.type === "add").length,
      removed: diff.filter((l) => l.type === "remove").length,
    };
  }
  return { added: 0, removed: 0 };
}

export function DiffPreview({
  changes,
  onApply,
  onApplyAll,
  onReject,
  onRejectAll,
  onClose,
  onNavigateToLine,
  onOpenFile,
}: DiffPreviewProps) {
  const [activeIndex, setActiveIndex] = useState(0);
  const [viewMode, setViewMode] = useState<"unified" | "side-by-side">(
    "side-by-side",
  );

  const activeChange = changes[activeIndex];

  // Per-file line-change counts (memoized so file list doesn't recompute on every render)
  const perFileStats = useMemo(() => changes.map(countDiffLines), [changes]);

  // Active file stats (for the header badge)
  const stats = activeChange
    ? countDiffLines(activeChange)
    : { added: 0, removed: 0 };

  if (changes.length === 0 || !activeChange) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/30" onClick={onClose} />
      <div className="relative w-full max-w-4xl max-h-[85vh] bg-card border border-border/60 rounded-2xl shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-border/60 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" />
            <span className="text-[length:var(--helix-transcript-size)] font-semibold">
              代码更改预览
            </span>
            <span className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground bg-muted px-2 py-0.5 rounded-full">
              {changes.length} 个文件
            </span>
            <div className="flex items-center gap-2 text-[calc(var(--helix-transcript-size)*0.7143)]">
              <span className="text-emerald-500">+{stats.added}</span>
              <span className="text-red-500">-{stats.removed}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {/* View mode toggle */}
            <div className="flex items-center gap-1 bg-muted rounded-lg p-0.5">
              <button
                onClick={() => setViewMode("unified")}
                className={`p-1.5 rounded transition-colors ${
                  viewMode === "unified"
                    ? "bg-background shadow-sm text-foreground"
                    : "text-muted-foreground hover:text-foreground"
                }`}
                data-tip="统一视图"
              >
                <Rows3 className="size-3.5" />
              </button>
              <button
                onClick={() => setViewMode("side-by-side")}
                className={`p-1.5 rounded transition-colors ${
                  viewMode === "side-by-side"
                    ? "bg-background shadow-sm text-foreground"
                    : "text-muted-foreground hover:text-foreground"
                }`}
                data-tip="并排视图"
              >
                <Split className="size-3.5" />
              </button>
            </div>
            <button onClick={onClose} className="p-1 hover:bg-accent rounded">
              <X className="size-4" />
            </button>
          </div>
        </div>

        {/* File tabs */}
        {changes.length > 1 && (
          <div className="flex items-center gap-1 px-3 py-1.5 border-b border-border overflow-x-auto">
            <button
              onClick={() => setActiveIndex(Math.max(0, activeIndex - 1))}
              disabled={activeIndex === 0}
              className="p-1 hover:bg-accent rounded disabled:opacity-30"
            >
              <ChevronLeft className="size-3.5" />
            </button>
            {changes.map((c, idx) => {
              const isNew = c.oldContent.trim() === "" && !c.unifiedDiff;
              const fs = perFileStats[idx];
              return (
                <div
                  key={c.fileId}
                  onClick={() => setActiveIndex(idx)}
                  className={`flex items-center gap-1.5 px-2.5 py-1 text-[calc(var(--helix-transcript-size)*0.8571)] rounded-md transition-colors whitespace-nowrap cursor-pointer select-none ${
                    idx === activeIndex
                      ? "bg-accent text-accent-foreground"
                      : "text-muted-foreground hover:bg-accent/50"
                  }`}
                >
                  <FileCode className="size-3 shrink-0" />
                  <span className="truncate max-w-[150px]">{c.fileName}</span>
                  <span className="shrink-0 tabular-nums ml-auto">
                    <span className="text-emerald-500">+{fs.added}</span>
                    <span className="text-red-500 ml-1">-{fs.removed}</span>
                  </span>
                </div>
              );
            })}
            <button
              onClick={() =>
                setActiveIndex(Math.min(changes.length - 1, activeIndex + 1))
              }
              disabled={activeIndex === changes.length - 1}
              className="p-1 hover:bg-accent rounded disabled:opacity-30"
            >
              <ChevronRight className="size-3.5" />
            </button>
          </div>
        )}

        {/* Diff content */}
        <div className="flex-1 overflow-hidden">
          {activeChange.unifiedDiff ? (
            <UnifiedDiffTextViewer diff={activeChange.unifiedDiff} />
          ) : viewMode === "side-by-side" ? (
            <SideBySideDiffViewer
              change={activeChange}
              onNavigateToLine={onNavigateToLine}
            />
          ) : (
            <UnifiedDiffViewer
              change={activeChange}
              onNavigateToLine={onNavigateToLine}
            />
          )}
        </div>

        {/* Actions */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-border shrink-0">
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                onReject(activeChange);
                if (changes.length <= 1) onClose();
              }}
              className="text-[calc(var(--helix-transcript-size)*0.8571)]"
            >
              <X className="size-3.5 mr-1" />
              拒绝
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={onRejectAll}
              className="text-[calc(var(--helix-transcript-size)*0.8571)] text-destructive hover:text-destructive"
            >
              <RotateCcw className="size-3.5 mr-1" />
              全部拒绝
            </Button>
          </div>
          <div className="flex items-center gap-2">
            <Button
              size="sm"
              onClick={onApplyAll}
              className="text-[calc(var(--helix-transcript-size)*0.8571)]"
            >
              <Check className="size-3.5 mr-1" />
              全部应用
            </Button>
            <Button
              size="sm"
              onClick={() => {
                onApply(activeChange);
                if (changes.length <= 1) onClose();
              }}
              className="text-[calc(var(--helix-transcript-size)*0.8571)]"
              variant="outline"
            >
              <Check className="size-3.5 mr-1" />
              应用此文件
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { FileCode, Undo2 } from "lucide-react";
import React, { useMemo, useState } from "react";
import { countDiffLines } from "./diff-preview";
import { electronFS } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";
import type { PendingChange } from "@/stores/helix-types";

function reverseUnifiedDiff(
  diff: string,
  currentContent: string,
): string | null {
  const hunks: Array<{ newStart: number; newCount: number; body: string[] }> =
    [];
  for (const raw of diff.split("\n")) {
    const line = raw.replace(/\r$/, "");
    if (line.startsWith("@@ ")) {
      const m = line.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/);
      if (!m) return null;
      hunks.push({
        newStart: Number(m[1]),
        newCount: m[2] ? Number(m[2]) : 1,
        body: [],
      });
    } else if (
      hunks.length > 0 &&
      !line.startsWith("---") &&
      !line.startsWith("+++")
    ) {
      if (line.startsWith("\\")) continue;
      hunks[hunks.length - 1].body.push(line);
    }
  }

  const result = currentContent.split("\n");
  for (let i = hunks.length - 1; i >= 0; i--) {
    const hunk = hunks[i];
    const start = hunk.newStart - 1;
    const end = start + hunk.newCount;
    if (start < 0 || end > result.length) return null;
    const oldSegment: string[] = [];
    for (const bodyLine of hunk.body) {
      if (bodyLine.startsWith("+")) continue;
      if (bodyLine.startsWith("-")) oldSegment.push(bodyLine.slice(1));
      else if (bodyLine.startsWith(" ")) oldSegment.push(bodyLine.slice(1));
      else oldSegment.push(bodyLine);
    }
    result.splice(start, hunk.newCount, ...oldSegment);
  }
  return result.join("\n");
}

/**
 * 单条回复末尾的修改汇总卡片：外层卡片 + 每个文件一行，点击行展开该文件的 diff。
 */
export function FileChangeSummaryCard({
  changes,
}: {
  changes: PendingChange[];
}) {
  const [undone, setUndone] = useState<Set<string>>(new Set());
  const [undoing, setUndoing] = useState(false);
  const visibleChanges = useMemo(
    () => changes.filter((c) => !undone.has(c.fileId)),
    [changes, undone],
  );
  const stats = useMemo(
    () => visibleChanges.map(countDiffLines),
    [visibleChanges],
  );

  if (visibleChanges.length === 0) return null;

  const totalAdded = stats.reduce((sum, s) => sum + s.added, 0);
  const totalRemoved = stats.reduce((sum, s) => sum + s.removed, 0);

  const undoChange = async (change: PendingChange) => {
    if (!change.filePath) throw new Error("缺少文件路径");
    const st = useHelixStore.getState();
    const workDir = st.selectedWorkDir ?? st.activeSessionWorkDir ?? "";
    const absolutePath =
      /^[A-Za-z]:[\\/]/.test(change.filePath) || change.filePath.startsWith("/")
        ? change.filePath
        : workDir
          ? `${workDir.replace(/[\\/]+$/, "")}/${change.filePath}`
          : change.filePath;

    const isNewFile = change.unifiedDiff?.includes("--- /dev/null") === true;
    let restored: string | null | undefined = change.oldContent;

    if (isNewFile) {
      await electronFS.deleteFile(absolutePath);
    } else if (restored) {
      await electronFS.writeFile(absolutePath, restored);
    } else if (change.unifiedDiff) {
      const current = await electronFS.readFile(absolutePath);
      restored = reverseUnifiedDiff(change.unifiedDiff, current);
      if (restored == null) throw new Error("无法解析 diff，无法撤销");
      await electronFS.writeFile(absolutePath, restored);
    } else {
      throw new Error("缺少可撤销的更改内容");
    }

    useHelixStore.setState((s) => ({
      pendingChanges: s.pendingChanges.filter(
        (c) => c.fileId !== change.fileId || (c.workDir ?? "") !== workDir,
      ),
    }));

    const existing = useHelixStore.getState().findFileByPath(absolutePath);
    if (existing) {
      if (restored != null)
        useHelixStore.getState().applyFileChange(existing.id, restored);
      else useHelixStore.getState().deleteFile(existing.id);
    }
  };

  const openChange = async (change: PendingChange) => {
    const st = useHelixStore.getState();
    const workDir = st.selectedWorkDir ?? st.activeSessionWorkDir ?? "";
    const absolutePath =
      /^[A-Za-z]:[\\/]/.test(change.filePath) || change.filePath.startsWith("/")
        ? change.filePath
        : workDir
          ? `${workDir.replace(/[\\/]+$/, "")}/${change.filePath}`
          : change.filePath;

    // 右侧栏由 rightSidebarTab 控制显隐，先切到 code 视图再建编辑器 tab。
    st.setRightSidebarTab("code");
    const createdEmpty = st.ensureEditorTab(absolutePath, change.fileName);
    try {
      const content = await electronFS.readFile(absolutePath);
      if (content == null) throw new Error("读取为空");
      if (content.length > 1_000_000) {
        st.showToast({
          type: "error",
          title: "文件过大",
          description: `${change.fileName} 超过 1MB，暂不支持在编辑器打开`,
        });
        if (createdEmpty) st.closeEditorTab(absolutePath);
        return;
      }
// eslint-disable-next-line no-control-regex
      if (/[\u0000-\u0008]/.test(content.slice(0, 4096))) {
        st.showToast({
          type: "error",
          title: "无法编辑",
          description: `${change.fileName} 不是文本文件`,
        });
        if (createdEmpty) st.closeEditorTab(absolutePath);
        return;
      }
      if (createdEmpty) st.fillEditorTabContent(absolutePath, content);
    } catch (e: any) {
      // 诊断：把实际尝试读取的绝对路径与 workDir 带出来，便于定位是路径拼错还是编码/权限问题
      console.warn("[Helix] openChange failed:", {
        rawFilePath: change.filePath,
        workDir: st.selectedWorkDir ?? st.activeSessionWorkDir ?? "(空)",
        absolutePath,
        error: e,
      });
      // Tauri invoke 对 Result::Err 的 reject 是字符串（没有 .message），需按字符串取
      const errText =
        (typeof e === "string" ? e : e?.message) || "读取文件出错";
      // 按错误文本分类：ENOENT（文件已被清理/未落盘）→ 友好提示；
      // 沙箱拒绝（safe_path 白名单外）→ 明确说无权读取；其余原样带出。
      const notFound =
        /os error 2|cannot find|No such file|找不到|不存在/i.test(errText);
      const outside = /outside working directory/i.test(errText);
      st.showToast({
        type: "error",
        title: "打开失败",
        description: notFound
          ? `文件已不存在（可能已被后端清理）: ${absolutePath}`
          : outside
            ? `文件在工作区外，编辑器无权读取: ${absolutePath}`
            : `${errText}｜尝试读取: ${absolutePath}`,
      });
      if (createdEmpty) st.closeEditorTab(absolutePath);
    }
  };

  const handleUndoAll = async () => {
    if (undoing || visibleChanges.length === 0) return;
    setUndoing(true);
    const failed: string[] = [];
    const restoredIds: string[] = [];
    for (const change of visibleChanges) {
      try {
        await undoChange(change);
        restoredIds.push(change.fileId);
      } catch (e) {
        failed.push(`${change.fileName}（${String(e)}）`);
      }
    }
    setUndone((prev) => new Set([...prev, ...restoredIds]));
    setUndoing(false);

    const st = useHelixStore.getState();
    if (failed.length === 0) {
      st.showToast({
        type: "success",
        title: "已撤销",
        description: `已恢复本次回复修改的 ${restoredIds.length} 个文件`,
      });
    } else {
      st.showToast({
        type: "error",
        title: "部分撤销失败",
        description: failed.join("；"),
      });
    }
  };

  return (
    <div className="overflow-hidden rounded-lg border border-border/40 bg-card/40">
      <div className="flex items-center gap-2 px-3 py-1.5 border-b border-border/30 text-[length:var(--helix-transcript-size)] text-foreground/70">
        <span className="font-medium">已修改</span>
        <span className="text-[length:var(--helix-transcript-size)] text-muted-foreground">
          {visibleChanges.length} 个文件
        </span>
        <span className="ml-auto flex items-center gap-2 text-[length:var(--helix-transcript-size)] tabular-nums">
          {totalAdded > 0 && (
            <span className="text-emerald-500">+{totalAdded}</span>
          )}
          {totalRemoved > 0 && (
            <span className="text-red-500">-{totalRemoved}</span>
          )}
        </span>
        <button
          type="button"
          onClick={handleUndoAll}
          disabled={undoing}
          className="ml-1.5 flex items-center gap-1 px-1.5 py-0.5 rounded text-[length:var(--helix-transcript-size)] text-foreground/50 hover:text-foreground hover:bg-red-500/10 disabled:opacity-50 transition-colors"
          data-tip={undoing ? "撤销中" : "撤销本次回复的全部修改"}
        >
          <Undo2 className={`size-3.5 ${undoing ? "animate-pulse" : ""}`} />
          {undoing ? "撤销中" : "撤销"}
        </button>
      </div>
      {visibleChanges.map((change, idx) => {
        const s = stats[idx];
        return (
          <div
            key={change.fileId}
            className="border-b border-border/20 last:border-b-0"
          >
            <div className="flex items-center hover:bg-muted/40 transition-colors">
              <button
                type="button"
                onClick={() => openChange(change)}
                className="flex flex-1 min-w-0 items-center gap-1.5 px-3 py-1.5 text-left"
                data-tip="在侧边栏打开"
              >
                <FileCode className="size-3.5 shrink-0 text-sky-500/80" />
                <span className="break-all font-mono text-[length:var(--helix-transcript-size)] text-foreground/70">
                  {change.fileName}
                </span>
                <span className="shrink-0 tabular-nums text-[length:var(--helix-transcript-size)]">
                  {s.added > 0 && (
                    <span className="text-emerald-500 mr-1.5">+{s.added}</span>
                  )}
                  {s.removed > 0 && (
                    <span className="text-red-500">-{s.removed}</span>
                  )}
                </span>
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

