  // Apply the selected theme style (Catppuccin flavor or built-in cream) by
  // writing inline CSS variables onto <html>. Runs on mount and whenever the
  // style changes — including when the light/dark toggle switches to a paired
  // flavor.
  useEffect(() => {
    applyHelixPalette(themeStyle);
  }, [themeStyle]);

  // Editor theme follows the resolved light/dark state of <html>. Snapshot it
  // on mount, then watch the class attribute so a 深色 flavor → 内置 switch (or
  // any theme toggle) re-syncs the editor immediately.
  useEffect(() => {
    const syncEditorTheme = () =>
      storeActions.setEditorTheme(
        document.documentElement.classList.contains("dark")
          ? "vs-dark"
          : "light",
      );

    syncEditorTheme();
    const observer = new MutationObserver(syncEditorTheme);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => observer.disconnect();
  }, []);

  // Re-assert the frontend's restored model config into Helix on startup so
  // the backend always matches the user's choice. This runs once after the
  // store rehydrates from IndexedDB: it (a) writes the active profile to the
  // cold-start cache and (b) pushes it to the running gateway. No hardcoded
  // pin — the value is whatever the user last saved (or the sensible default).
  useEffect(() => {
    if (startupSyncDone) return;
    startupSyncDone = true;
    let cancelled = false;
    (async () => {
      await storeActions.restoreFromStorage();
      if (cancelled) return;
      const st = useHelixStore.getState();
      // Model setup counts as having completed first-run onboarding. Avoid a
      // first-use modal when the user already configured providers/models but
      // the old race never persisted hasOnboarded=true.
      if (!st.hasOnboarded) {
        const hasConfiguredModel =
          st.apiProfiles.length > 0 ||
          st.apiHistory.length > 0 ||
          st.providers.length > 0 ||
          !!(
            st.apiConfig?.baseUrl &&
            st.apiConfig?.model &&
            st.apiConfig?.apiKey
          );
        if (hasConfiguredModel) st.setHasOnboarded(true);
      }
      setRestoreReady(true);
      if (!isElectron()) return;
      const cfg = st.apiConfig;
      if (!cfg || !cfg.model) return;
      // 启动重申只推 model/provider/baseUrl——凭据以 pi 侧文件为准。带 key 会
      // 在每次重启时把缓存里的旧 key 重建进 models.json，覆盖用户在外部轮换
      // 过的 key（pushModelConfig 内部也会剥 key，这里显式不传）。
      pushModelConfig({
        model: cfg.model,
        provider:
          cfg.provider && cfg.provider !== "__custom__"
            ? cfg.provider
            : "custom",
        baseUrl: cfg.baseUrl,
      });
    })();
    return () => {
      cancelled = true;
    };
  }, [storeActions.restoreFromStorage]);

  // Sync agent settings to Helix via live config.set (no gateway restart).
  // personality + reasoningEffort + fastMode are pushed instantly.
  // Removed: temperature, maxOutputTokens, customInstructions, Chinese language injection.
  const agentSettingsSyncTimer = useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  useEffect(() => {
    if (!isElectron()) return;
    const pushAgentConfig = () => {
      const s = useHelixStore.getState();
      pushAgentConfigLive({
        personality: s.personality || undefined,
        reasoningEffort: s.reasoningEffort,
        fastMode: s.fastMode,
      });
    };
    pushAgentConfig();
    const unsub = useHelixStore.subscribe((state, prevState) => {
      const changed =
        state.personality !== prevState.personality ||
        state.reasoningEffort !== prevState.reasoningEffort ||
        state.fastMode !== prevState.fastMode;
      if (!changed) return;
      if (agentSettingsSyncTimer.current)
        clearTimeout(agentSettingsSyncTimer.current);
      agentSettingsSyncTimer.current = setTimeout(pushAgentConfig, 150);
    });
    return () => {
      unsub();
      if (agentSettingsSyncTimer.current)
        clearTimeout(agentSettingsSyncTimer.current);
    };
  }, []);

  // ── Reasoning-effort: live push via config.set (no restart, no translation) ──
  // Uses Helix native effort scale (none/minimal/low/medium/high/xhigh/max/ultra)
  // directly — no toBackendReasoningEffort translation needed.
  const reasoningFastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
    if (!isElectron()) return;
    const unsub = useHelixStore.subscribe((state, prevState) => {
      if (state.reasoningEffort === prevState.reasoningEffort) return;
      if (reasoningFastTimer.current) clearTimeout(reasoningFastTimer.current);
      reasoningFastTimer.current = setTimeout(() => {
        const effort = useHelixStore.getState().reasoningEffort;
        pushConfigKeyValue("agent.reasoning_effort", effort);
        // Live-update thinking level. Pi has no persistent thinking-level
        // config key, so we broadcast to every live instance; new sessions
        // get it re-applied at spawn time in Rust (pi_gateway). serve mode
        // honors agent.reasoning_effort via config.set instead.
        if (isServeActive()) {
          const gw = useGatewayStore.getState();
          getServeClient()
            ?.rpc("config.set", {
              key: "agent.reasoning_effort",
              value: effort,
              session_id: gw.helixSessionId,
            })
            .catch(() => {});
        } else {
          window.electron?.helix
            ?.piSetThinkingLevelAll?.(effort)
            .catch?.(() => {});
        }
      }, 150);
    });
    return () => {
      unsub();
      if (reasoningFastTimer.current) clearTimeout(reasoningFastTimer.current);
    };
  }, []);

  // ── Bridge: helix-ui useProviderStore → Helix useHelixStore ───────────────
  // The user can switch the active model from the helix-ui ProviderSettings /
  // ModelSelector panels (which write to useProviderStore and push to Helix).
  // Those are a SEPARATE store from useHelixStore (the one the input-bar model
  // selector reads). Without this bridge the input bar keeps showing the old
  // model even after a backend-side switch. Mirror the active model (and its
  // owning provider's config) into useHelixStore whenever it changes out-of-band.
  useEffect(() => {
    if (!isElectron()) return;
    // On the FIRST fire (which is the helix-ui hydration), the Helix store has
    // already restored its own active model — and unlike helix-ui it knows about
    // fetched-only models. If helix-ui hydrated to a declared default (pro) while
    // Helix restored a fetched model (flash), don't let helix-ui clobber Helix.
    // Instead sync helix-ui to Helix so the two agree, then return.
    let firstFire = true;
    const unsub = useProviderStore.subscribe((state, prev) => {
      const model = state.activeModel;
      if (model === prev.activeModel) return;
      if (!model) return;
      const helix = useHelixStore.getState();
      if (firstFire) {
        firstFire = false;
        const helixModel = helix.apiConfig?.model;
        if (helixModel && helixModel !== model) {
          useProviderStore.getState().setActiveModel(helixModel);
          return;
        }
      }
      // Reuse the canonical resolver so the mirrored config matches a normal
      // in-panel switch (credentials + session invalidation handled there).
      const provider = state.providers.find((p) => p.models.includes(model));
      if (provider) {
        // Mirror into Helix store via onModelSwitched so activeModel/activeProviderId
        // and apiConfig all stay consistent and the stale session is cancelled.
        helix.onModelSwitched(model);
        // Keep the selected provider's credentials in sync too, in case the
        // helix-ui provider carries a different key/baseUrl.
        const existing = helix.providers.find((p) => p.models.includes(model));
        if (
          existing &&
          (existing.apiKey !== provider.apiKey ||
            existing.baseUrl !== provider.baseUrl)
        ) {
          useHelixStore.setState({
            providers: helix.providers.map((p) =>
              p.id === existing.id
                ? { ...p, apiKey: provider.apiKey, baseUrl: provider.baseUrl }
                : p,
            ),
          });
        }
        // onModelSwitched only updates the store. Mirror the input-bar switch
        // path (agent-flow-panel.syncConfigToBackend): cancel any in-flight
        // session, drop the cached id, and push the resolved config so the
        // backend picks up the new key immediately. Without this, an out-of-band
        // switch (helix-ui ModelSelector / settings) only takes effect on the
        // next sendPrompt via the configHash check, and a run in flight keeps
        // streaming against the old endpoint.
        const gw = useGatewayStore.getState();
        const sid = gw.helixSessionId;
        if (sid) {
          try {
            electronHelix.notify("session/cancel", { session_id: sid });
          } catch { /* empty */}
        }
        gw.setHelixSessionId(null);
        const s = useHelixStore.getState();
        const cfg = s.apiConfig;
        // Key 不推送：凭据以 pi 侧文件（models.json/auth.json）为准，后端在
        // 未收到 key 时保留已存的。推缓存 key 会把轮换过的 key 覆盖回旧值。
        pushModelConfig({
          model: cfg.model,
          provider:
            cfg.provider && cfg.provider !== "__custom__"
              ? cfg.provider
              : "custom",
          baseUrl: cfg.baseUrl,
        });
      } else {
        // Model not declared in Helix providers (e.g. fetched list only) — at
        // least reflect it in apiConfig so the selector label updates, avoiding
        // a frozen "always same model" display. Also set activeModel so the
        // dropdown highlight and the backend-mirror guard (`activeModel ||
        // cur.model`) don't stay pinned to the previous model.
        useHelixStore.setState({
          activeModel: model,
          apiConfig: { ...useHelixStore.getState().apiConfig, model },
        });
      }
    });
    return () => {
      try {
        unsub();
      } catch { /* empty */}
    };
  }, []);

  useEffect(() => {
    if (chatMessages.length > 0) {
      setShowSidebar(true);
    }
  }, [chatMessages.length]);

  // ── System tray: "最近对话" menu item ────────────────────────────────
  useEffect(() => {
    const unlisten = listen("tray:show-recent", () => {
      setShowSidebar(true);
    });
    return () => {
      unlisten.then((fn) => fn());
    };
  }, []);

  // DiffPreview no longer auto-pops: per-file change stats (+green / -red) are
  // rendered inline in the conversation transcript (FileChangeSummary). The
  // top-right diff button still opens the review modal on demand.

  // Track window maximize/restore state via native events

  useEffect(() => {
    const win = (window as any).electron?.window;
    if (!win) return;
    win.isMaximized().then(setIsMaximized);
    const removeListener = win.onMaximizedChange((maximized: boolean) =>
      setIsMaximized(maximized),
    );
    return () => {
      try {
        removeListener?.();
      } catch { /* empty */}
    };
  }, []);

  // ── Helix gateway connection status ──────────────────────────────────
  // The connection dot next to the Settings button lives in the always-mounted
  // sidebar, but detection used to only live inside useHelix(), which is
  // mounted lazily (settings / skill panels). That is why the badge stayed on
  // "connecting" until the settings panel was opened. Detect here at the top
  // level so the badge reflects reality from startup onward.
  useEffect(() => {
    if (!isElectron()) return;
    const helix = (window as any).electron?.helix;
    if (!helix?.status) return;
    let timer: any = null;
    let startupTimer: any = null;
    let stopped = false;

    // 安排下一次探测（同一时刻只保留一个 timer）。
    const scheduleProbe = (delay: number, retries: number) => {
      if (stopped) return;
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      timer = setTimeout(() => {
        timer = null;
        void probe(retries);
      }, delay);
    };

    // 关键：连上之后也要保持低频心跳，而不是彻底停止探测。
    // 后端重启（例如设置里保存配置触发 respawn）时，gateway.ready 事件可能早于
    // 本订阅建立就被发出而丢失；一旦探测在"成功"时停止，又没有任何机制重启它，
    // 徽章就会永久停在"连接中"——尽管后端其实已经恢复、能够正常回复。
    const probe = async (retries = 0) => {
      if (stopped) return;
      let connected = false;
      try {
        const st = await helix.status();
        connected = !!st?.connected;
      } catch {
        connected = false;
      }
      if (stopped) return;
      if (connected) {
        useGatewayStore.getState().setHelixConnected(true);
        useGatewayStore.getState().setHelixError(null);
        useHelixStore.getState().setGatewayStatus("ready");
        if (startupTimer) {
          clearTimeout(startupTimer);
          startupTimer = null;
        }
        scheduleProbe(HEALTHY_HEARTBEAT_MS, 0);
      } else {
        useGatewayStore.getState().setHelixConnected(false);
        useHelixStore.getState().setGatewayStatus("connecting");
        // 未连上时用递增间隔重试：前 12 次 1.5s，之后 3s。
        scheduleProbe(retries < 12 ? 1500 : 3000, retries + 1);
      }
    };

    const unsubscribe = helix.onEvent?.((event: string, params?: any) => {
      if (event === "gateway.ready") {
        useGatewayStore.getState().setHelixConnected(true);
        useGatewayStore.getState().setHelixError(null);
        useHelixStore.getState().setGatewayStatus("ready");
        if (startupTimer) {
          clearTimeout(startupTimer);
          startupTimer = null;
        }
        scheduleProbe(HEALTHY_HEARTBEAT_MS, 0);
      } else if (event === "gateway.disconnected") {
        useGatewayStore.getState().setHelixConnected(false);
        useHelixStore.getState().setGatewayStatus("disconnected");
        scheduleProbe(1500, 0);
      } else if (event === "gateway.retry") {
        const phase = params?.phase as
          | "error"
          | "retrying"
          | "recovered"
          | undefined;
        if (phase === "recovered") {
          useGatewayStore.getState().setHelixConnected(true);
          useHelixStore.getState().setGatewayStatus("ready");
          scheduleProbe(HEALTHY_HEARTBEAT_MS, 0);
        } else {
          useGatewayStore.getState().setHelixConnected(false);
          useHelixStore.getState().setGatewayStatus("connecting");
          scheduleProbe(1500, 0);
        }
      }
    });
    void probe();
    // Startup safety timeout: if gateway never becomes ready within 60s,
    // transition to 'disconnected' so the user sees a retry button instead
    // of being stuck on the blocking overlay forever.
    startupTimer = setTimeout(() => {
      const current = useHelixStore.getState().gatewayStatus;
      if (current !== "ready") {
        useHelixStore.getState().setGatewayStatus("disconnected");
      }
    }, 60_000);
    return () => {
      stopped = true;
      try {
        unsubscribe?.();
      } catch { /* empty */}
      if (timer) clearTimeout(timer);
      if (startupTimer) clearTimeout(startupTimer);
    };
  }, []);

  const handleMaximizeToggle = useCallback(async () => {
    try {
      const win = (window as any).electron?.window;
      if (!win) return;
      const currentMaximized = await win.isMaximized();
      if (currentMaximized) {
        await win.unmaximize();
      } else {
        await win.maximize();
      }
    } catch (e) {
      console.error("[toggle] error:", e);
    }
  }, []);

  const handleOpenLocation = useCallback(async () => {
    if (!isElectron()) {
      return;
    }
    // If a project directory is already selected, open it in File Explorer.
    // Only fall back to the folder picker when nothing is selected yet.
    if (selectedWorkDir) {
      try {
        await electronShell.openPath(selectedWorkDir);
      } catch (e) {
        console.error("[handleOpenLocation] openPath failed:", e);
      }
      return;
    }
    const { electronDialog } = await import("@/lib/electron-bridge");
    const dir = await electronDialog.openDirectory(
      selectedWorkDir || undefined,
    );
    if (!dir) return;
    try {
      await storeActions.setWorkDir(dir);
    } catch {
      storeActions.setSelectedWorkDir(dir);
    }
  }, [
    storeActions.setWorkDir,
    storeActions.setSelectedWorkDir,
    storeActions.showToast,
    selectedWorkDir,
  ]);

  const handleNewChat = useCallback(() => {
    useHelixStore.getState().flushSessionPersist();
    storeActions.clearChat();
    useHelixStore.getState().clearExecutionFlow();
    useHelixStore.getState().setCurrentSessionId(null);
  }, [storeActions.clearChat]);

  // ── System tray: "新建对话" menu item ──────────────────────────────
  useEffect(() => {
    const unlisten = listen("tray:new-conversation", () => {
      handleNewChat();
    });
    return () => {
      unlisten.then((fn) => fn());
    };
  }, [handleNewChat]);

  // Window menu state
  const [windowMenuOpen, setWindowMenuOpen] = useState(false);
  const windowMenuButtonRef = useRef<HTMLButtonElement>(null);
  const windowMenuRef = useRef<HTMLDivElement>(null);

  // Help menu state
  const [helpMenuOpen, setHelpMenuOpen] = useState(false);
  const helpMenuButtonRef = useRef<HTMLButtonElement>(null);
  const helpMenuRef = useRef<HTMLDivElement>(null);
  const [appVersion, setAppVersion] = useState("");
  useEffect(() => {
    getCurrentVersion().then((v) => v && setAppVersion(v));
  }, []);

  // Browser "more" menu state (the ••• button next to the browser toggle)
  const [browserMenuOpen, setBrowserMenuOpen] = useState(false);
  const browserMenuButtonRef = useRef<HTMLButtonElement>(null);
  const browserMenuRef = useRef<HTMLDivElement>(null);

  const ZOOM_STEP = 0.1;
  const zoomIn = useCallback(() => {
    const current = parseFloat(document.documentElement.style.zoom || "1");
    document.documentElement.style.zoom = Math.min(
      current + ZOOM_STEP,
      2,
    ).toString();
  }, []);
  const zoomOut = useCallback(() => {
    const current = parseFloat(document.documentElement.style.zoom || "1");
    document.documentElement.style.zoom = Math.max(
      current - ZOOM_STEP,
      0.5,
    ).toString();
  }, []);
  const zoomReset = useCallback(() => {
    document.documentElement.style.zoom = "1";
  }, []);
  const toggleFullscreen = useCallback(() => {
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(() => {});
    } else {
      document.documentElement.requestFullscreen().catch(() => {});
    }
  }, []);

  const toggleWindowMenu = useCallback(() => setWindowMenuOpen((v) => !v), []);
  const closeWindowMenu = useCallback(() => setWindowMenuOpen(false), []);

  // Click outside to close window menu
  useEffect(() => {
    if (!windowMenuOpen) return;
    const handleMouseDown = (e: MouseEvent) => {
      const target = e.target as Node;
      if (
        windowMenuButtonRef.current?.contains(target) ||
        windowMenuRef.current?.contains(target)
      ) {
        return;
      }
      setWindowMenuOpen(false);
    };
    document.addEventListener("mousedown", handleMouseDown);
    return () => document.removeEventListener("mousedown", handleMouseDown);
  }, [windowMenuOpen]);

  // Click outside to close help menu
  useEffect(() => {
    if (!helpMenuOpen) return;
    const handleMouseDown = (e: MouseEvent) => {
      const target = e.target as Node;
      if (
        helpMenuButtonRef.current?.contains(target) ||
        helpMenuRef.current?.contains(target)
      ) {
        return;
      }
      setHelpMenuOpen(false);
    };
    document.addEventListener("mousedown", handleMouseDown);
    return () => document.removeEventListener("mousedown", handleMouseDown);
  }, [helpMenuOpen]);

  // Click outside to close browser menu
  useEffect(() => {
    if (!browserMenuOpen) return;
    const handleMouseDown = (e: MouseEvent) => {
      const target = e.target as Node;
      if (
        browserMenuButtonRef.current?.contains(target) ||
        browserMenuRef.current?.contains(target)
      ) {
        return;
      }
      setBrowserMenuOpen(false);
    };
    document.addEventListener("mousedown", handleMouseDown);
    return () => document.removeEventListener("mousedown", handleMouseDown);
  }, [browserMenuOpen]);

  // Window menu keyboard shortcuts
  useEffect(() => {
    const isInputFocused = (target: EventTarget | null) => {
      if (!(target instanceof HTMLElement)) return false;
      return (
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.isContentEditable
      );
    };
    const handler = (e: KeyboardEvent) => {
      if (isInputFocused(e.target)) return;
      if (e.key === "F11") {
        e.preventDefault();
        toggleFullscreen();
        return;
      }
      const isMod = e.ctrlKey || e.metaKey;
      if (!isMod) return;
      const shift = e.shiftKey;
      const alt = e.altKey;
      if (!shift && !alt && e.key.toLowerCase() === "b") {
        e.preventDefault();
        if (!showSidebarRef.current) {
          // If sidebar is hidden, show it as narrow strip
          setShowSidebarRef.current(true);
          setSidebarCollapsedRef.current(true);
        } else {
          // If sidebar is visible, toggle collapsed state
          setSidebarCollapsedRef.current((v) => !v);
        }
        return;
      }
      if (!shift && !alt && e.key.toLowerCase() === "l") {
        e.preventDefault();
        setShowSidebarRef.current((v) => !v);
        return;
      }
      if (!shift && !alt && e.key.toLowerCase() === "t") {
        e.preventDefault();
        (window as any).electron?.window?.newWindow();
        return;
      }
      if (shift && !alt && e.code === "Equal") {
        e.preventDefault();
        zoomIn();
        return;
      }
      if (!shift && !alt && e.code === "Minus") {
        e.preventDefault();
        zoomOut();
        return;
      }
      if (!shift && !alt && e.code === "Digit0") {
        e.preventDefault();
        zoomReset();
        return;
      }
      if (shift && !alt && e.code === "BracketLeft") {
        e.preventDefault();
        return;
      }
      if (shift && !alt && e.code === "BracketRight") {
        e.preventDefault();
        return;
      }
      // Ctrl+[ / Ctrl+] handled by keyboard-shortcuts.tsx (go-back / go-forward)
      if (!shift && alt && e.code === "KeyB") {
        e.preventDefault();
        storeActions.toggleSubAgentPanel();
        return;
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [storeActions, zoomIn, zoomOut, zoomReset, toggleFullscreen]);

  // Start global scheduled task runner
  useEffect(() => {
    startScheduledTaskRunner();
  }, []);

  // ── Task list ───────────────────────────────────────────────────────────
  // 后端没有任务清单 RPC（helix:getTasks 是空桩），任务清单 = 前端已接收的
  // live todos（来自 session/update 的 todo/plan 负载）。

  const windowMenuItems: (WindowMenuItem | { divider: true })[] = useMemo(
    () => [
      {
        label: "新建窗口",
        shortcut: "Ctrl+Shift+N",
        action: () => {
          window.open(window.location.href, "_blank");
          closeWindowMenu();
        },
      },
      {
        label: "关闭窗口",
        shortcut: "Ctrl+Shift+W",
        action: () => {
          window.close();
          closeWindowMenu();
        },
      },
      { divider: true },
      {
        label: "折叠侧边栏",
        shortcut: "Ctrl+B",
        action: () => {
          if (!showSidebar) {
            setShowSidebar(true);
            setSidebarCollapsed(true);
          } else {
            setSidebarCollapsed((v) => !v);
          }
          closeWindowMenu();
        },
      },
      {
        label: "切换侧边栏",
        shortcut: "Ctrl+L",
        action: () => {
          setShowSidebar((v) => !v);
          closeWindowMenu();
        },
      },
      {
        label: "打开终端",
        shortcut: shortcutLabel("toggle-terminal", customShortcuts),
        action: () => {
          useHelixStore.setState({ isTerminalOpen: true });
          closeWindowMenu();
        },
      },
      {
        label: "切换文件树",
        shortcut: shortcutLabel("toggle-file-tree", customShortcuts),
        action: () => {
          if (storeActions.selectedWorkDir)
            storeActions.toggleDirectoryProject(storeActions.selectedWorkDir);
          closeWindowMenu();
        },
      },
      {
        label: "打开代码编辑器",
        action: () => {
          storeActions.setRightSidebarTab("code");
          closeWindowMenu();
        },
      },
      { divider: true },
      {
        label: "设置",
        shortcut: "Ctrl+,",
        action: () => {
          storeActions.toggleSettings("api");
          closeWindowMenu();
        },
      },
      {
        label: "查找",
        shortcut: shortcutLabel("search-chat", customShortcuts),
        action: () => {
          window.dispatchEvent(new CustomEvent("helix:conversation-search"));
          closeWindowMenu();
        },
      },
      {
        label: "后退",
        shortcut: shortcutLabel("go-back", customShortcuts),
        action: () => {
          storeActions.navigateHistory("back");
          closeWindowMenu();
        },
      },
      {
        label: "前进",
        shortcut: shortcutLabel("go-forward", customShortcuts),
        action: () => {
          storeActions.navigateHistory("forward");
          closeWindowMenu();
        },
      },
      { divider: true },
      {
        label: "切换全屏",
        shortcut: "F11",
        action: () => {
          toggleFullscreen();
          closeWindowMenu();
        },
      },
    ],
    [
      setShowSidebar,
      storeActions,
      toggleFullscreen,
      closeWindowMenu,
      customShortcuts,
    ],
  );

  const sidebarExpanded = showSidebar;
  const sidebarPixelWidth = sidebarCollapsed
    ? SIDEBAR_COLLAPSED
    : sidebarWidth * (uiFontSize / 14);
  const titlebarPixelWidth =
    showSidebar && !showSettings ? sidebarPixelWidth : SIDEBAR_COLLAPSED;

  return (
    <div className="helix-app-backdrop relative h-screen w-screen flex flex-row overflow-hidden">
      <KeyboardShortcuts />
      <CommandPalette />
      <ContextMenuProvider />
      <ToastContainer />

      {/* Two-region layout: the titlebar and navigation sidebar form the left
          region; the conversation/settings area owns the right region. */}
      <div
        className={`flex flex-col overflow-hidden bg-sidebar ${showSettings ? "hidden" : ""}`}
      >
        {/* Title bar — head of the left sidebar region */}
        <div
          id="helix-titlebar"
          className="helix-app-titlebar flex items-center justify-between h-10 px-3 shrink-0 select-none"
          style={{ width: titlebarPixelWidth }}
        >
          {/* Left: navigation buttons */}
          <div
            className="flex items-center gap-0.5"
            style={{ WebkitAppRegion: "no-drag" } as any}
          >
            {!showSettings && (
              <button
                onClick={() => setShowSidebar((v) => !v)}
                className={`p-1.5 rounded-lg transition-colors ${showSidebar ? "text-primary bg-primary/10" : "text-foreground/40 hover:text-foreground/80 hover:bg-accent/50"}`}
                data-tip="侧边栏"
              >
                <PanelLeft className="size-5" />
              </button>
            )}
            {!showSettings && (
              <button
                onClick={() => storeActions.navigateHistory("back")}
                disabled={navigationIndex <= 0}
                className="p-1.5 text-foreground/50 hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors disabled:opacity-30"
                data-tip="后退"
              >
                <ArrowLeft className="size-5" />
              </button>
            )}
            <button
              onClick={() => storeActions.navigateHistory("forward")}
              disabled={navigationIndex >= navigationHistory.length - 1}
              className="p-1.5 text-foreground/50 hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors disabled:opacity-30"
              data-tip="前进"
            >
              <ArrowRight className="size-5" />
            </button>
            <button
              ref={windowMenuButtonRef}
              onClick={toggleWindowMenu}
              className="px-2 py-1 text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/50 hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors"
              data-tip="窗口"
            >
              窗口
            </button>
            <button
              ref={helpMenuButtonRef}
              onClick={() => setHelpMenuOpen((v) => !v)}
              className="px-2 py-1 text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/50 hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors"
              data-tip="帮助"
            >
              帮助
            </button>
            {helpMenuOpen &&
              typeof window !== "undefined" &&
              createPortal(
                <div
                  className="fixed z-[100]"
                  style={{
                    top:
                      (helpMenuButtonRef.current?.getBoundingClientRect()
                        .bottom ?? 0) + 4,
                    left:
                      helpMenuButtonRef.current?.getBoundingClientRect().left ??
                      0,
                  }}
                >
                  <div
                    ref={helpMenuRef}
                    className="w-56 bg-card border border-border/80 rounded-lg shadow-xl py-1"
                  >
                    <div className="px-3 py-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/60">
                      版本 v{appVersion || "0.1.2"}
                    </div>
                    <button
                      className="w-full px-3 py-2 text-[length:var(--helix-transcript-size)] text-left hover:bg-accent/60 transition-colors flex items-center gap-2"
                      onClick={async () => {
                        setHelpMenuOpen(false);
                        try {
                          // 检查 pi agent + npm 插件的更新（npm registry），
                          // 不再查 Helix 应用自身——后端 agent 是外部 pi 包。
                          const res = await (
                            window as any
                          ).electron?.helix?.piCheckUpdates?.();
                          if (!res) {
                            useHelixStore.getState().showToast({
                              type: "error",
                              title: "检查更新失败",
                              description: "更新检查不可用",
                            });
                            return;
                          }
                          const pi = res.pi || {};
                          const outdated = (res.packages || []).filter(
                            (p: any) => p.hasUpdate,
                          );
                          if (pi.hasUpdate && pi.latest) {
                            useHelixStore.getState().showToast({
                              type: "info",
                              title: "pi 有新版本可用",
                              description: `v${pi.installed} → v${pi.latest}${
                                outdated.length > 0
                                  ? `，另有 ${outdated.length} 个插件可更新`
                                  : ""
                              }`,
                              duration: 8000,
                              onClick: () =>
                                window.open(
                                  "https://www.npmjs.com/package/@earendil-works/pi-coding-agent",
                                  "_blank",
                                ),
                            });
                          } else if (outdated.length > 0) {
                            const names = outdated
                              .slice(0, 3)
                              .map(
                                (p: any) =>
                                  `${p.name} v${p.installed} → v${p.latest}`,
                              )
                              .join("\n");
                            useHelixStore.getState().showToast({
                              type: "info",
                              title: `有 ${outdated.length} 个插件可更新`,
                              description:
                                names +
                                (outdated.length > 3
                                  ? `\n…等 ${outdated.length} 个`
                                  : ""),
                              duration: 10000,
                            });
                          } else if (pi.installed) {
                            useHelixStore.getState().showToast({
                              type: "success",
                              title: "已是最新版本",
                              description: `pi v${pi.installed}（含全部插件）`,
                            });
                          } else {
                            useHelixStore.getState().showToast({
                              type: "error",
                              title: "检查更新失败",
                              description: "未找到 pi 安装",
                            });
                          }
                        } catch (e) {
                          useHelixStore.getState().showToast({
                            type: "error",
                            title: "检查更新失败",
                            description:
                              e instanceof Error ? e.message : "网络异常",
                          });
                        }
                      }}
                    >
                      <FileText className="size-5" />
                      检查更新
                    </button>
                  </div>
                </div>,
                document.body,
              )}
            {windowMenuOpen &&
              typeof window !== "undefined" &&
              createPortal(
                <div
                  className="fixed z-[100]"
                  style={{
                    top:
                      (windowMenuButtonRef.current?.getBoundingClientRect()
                        .bottom ?? 0) + 4,
                    left:
                      windowMenuButtonRef.current?.getBoundingClientRect()
                        .left ?? 0,
                  }}
                >
                  <div
                    ref={windowMenuRef}
                    className="w-56 bg-card border border-border/80 rounded-lg shadow-xl py-1"
                  >
                    {windowMenuItems.map((item, i) =>
                      "divider" in item ? (
                        <div key={i} className="h-px bg-border/60 my-1" />
                      ) : (
                        <button
                          key={i}
                          onClick={item.action}
                          className="w-full flex items-center justify-between px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/80 hover:bg-accent/60 transition-colors"
                        >
                          <span>{item.label}</span>
                          {item.shortcut && (
                            <span className="text-foreground/40 ml-4">
                              {item.shortcut}
                            </span>
                          )}
                        </button>
                      ),
                    )}
                  </div>
                </div>,
                document.body,
              )}
          </div>

          {/* Center: drag region (Tauri uses data-tauri-drag-region; the Electron
            -webkit-app-region CSS is a no-op on Tauri and leaves the window
            undraggable) */}
          <div className="flex-1 self-stretch" data-tauri-drag-region="" />
        </div>

        {/* Sidebar — hidden in settings mode (owned by ApiSettings there). */}
        {showSidebar && !showSettings && (
          <div
            className={`flex-1 shrink-0 overflow-hidden relative ${isDragging ? "" : "transition-[width] duration-200 ease-out"}`}
            style={{ width: sidebarPixelWidth }}
          >
            <div
              className="h-full overflow-hidden"
              style={{ width: sidebarPixelWidth }}
            >
              <Sidebar collapsed={sidebarCollapsed} />
            </div>

            {/* Resize handle — only visible when sidebar is expanded */}
            {!sidebarCollapsed && (
              <div
                className="absolute top-0 -right-1 w-2 h-full cursor-col-resize z-30 group"
                onPointerDown={handleDragStart}
              >
                {/* Visual grip line — hidden until hover */}
                <div className="absolute inset-y-0 left-1/2 -translate-x-1/2 w-0.5 bg-transparent group-hover:bg-border/40 transition-colors" />
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity">
                  <GripVertical className="size-3 text-primary/60" />
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Window controls — hoisted to the root (outside the left titlebar
          region) so the capsule stays visible in settings mode too, where the
          whole left region above is hidden. Pinned to the window's top-right
          corner via the relative `helix-app-backdrop` root. */}
      {/* Unified top-right icon row: conversation actions (任务清单 / 子 Agent /
          后台任务) + window controls (终端 / 更多操作 / min / max / close) all in
          ONE evenly-spaced flex. Conversation actions share the same gating as
          终端/更多操作 — hidden in settings & full-screen panel modes. */}
      <div className="absolute top-[2px] right-2 z-40 h-10 flex items-center gap-3">
        {!showSettings && !hideConversationActions && (
          <>
            {/* 统一工作面板：更改（含提交/推送）、任务清单、子 Agent 收进同一个下拉。仅在有内容时显示。 */}
            {(pendingPlanReview ||
              hasDelegations ||
              delegations.length > 0 ||
              subAgents.length > 0 ||
              helixTodos.length > 0 ||
              gitChangeStat) && (
            <div className="relative" ref={workPanelRef}>
              <button
                type="button"
                ref={workPanelBtnRef}
                onClick={() => setWorkPanelOpen((o) => !o)}
                className={`relative flex items-center gap-1.5 h-7 pl-2 pr-2.5 rounded-full border bg-card text-card-foreground shadow-sm select-none transition-colors ${
                  workPanelOpen
                    ? "border-primary/60 ring-1 ring-primary/20"
                    : "border-border/70 hover:border-border"
                }`}
                data-tip="工作面板"
              >
                {pendingPlanReview ? (
                  <>
                    <Pencil className="size-3.5 text-foreground/60 shrink-0" />
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/80">
                      计划
                    </span>
                    <span className="text-[calc(var(--helix-transcript-size)*0.7143)] px-1.5 py-px rounded-full bg-primary/10 text-primary">
                      待批准
                    </span>
                  </>
                ) : subAgents.length > 0 ? (
                  <>
                    <Users className="size-3.5 text-foreground/60 shrink-0" />
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/80">
                      子 Agent
                    </span>
                    <span className="flex items-center gap-1 text-[calc(var(--helix-transcript-size)*0.8571)] tabular-nums font-medium text-foreground/60">
                      {subAgents.some((a) => a.status === "running") && (
                        <span className="size-1.5 rounded-full bg-primary animate-pulse" />
                      )}
                      {subAgents.length}
                    </span>
                  </>
                ) : (hasDelegations && delegations.length > 0) ? (
                  <>
                    <Users className="size-3.5 text-foreground/60 shrink-0" />
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/80">
                      子 Agent
                    </span>
                    {delegations.length > 0 && (
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] tabular-nums font-medium text-foreground/60">
                      {delegations.length}
                    </span>
                    )}
                  </>
                ) : helixTodos.length > 0 ? (
                  <>
                    <ListTodo className="size-3.5 text-foreground/60 shrink-0" />
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/80">
                      任务
                    </span>
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] tabular-nums font-medium text-foreground/60">
                      {helixTodos.length}
                    </span>
                  </>
                ) : gitChangeStat ? (
                  <>
                    <FilePlus className="size-3.5 text-foreground/60 shrink-0" />
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/80">
                      更改
                    </span>
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] tabular-nums font-medium text-emerald-600 dark:text-emerald-400">
                      +{gitChangeStat.added}
                    </span>
                    <span className="text-[calc(var(--helix-transcript-size)*0.8571)] tabular-nums font-medium text-red-500 dark:text-red-400">
                      -{gitChangeStat.removed}
                    </span>
                  </>
                ) : (
                  <ListTodo className="size-[18px] text-foreground/60" />
                )}
              </button>
              {workPanelOpen && typeof window !== "undefined" && (() => {
                const btnRect = workPanelBtnRef.current?.getBoundingClientRect();
                const btnLeft = btnRect?.left ?? 0;
                const btnBottom = btnRect?.bottom ?? 0;
                const maxW = Math.min(320, window.innerWidth - btnLeft - 12);
                return createPortal(
                <div
                  ref={workPanelPortalRef}
                  className="fixed z-[100]"
                  style={{
                    top: btnBottom + 4,
                    left: btnLeft,
                    width: Math.max(200, maxW),
                  }}
                >
                <div className="w-full max-h-[70vh] overflow-y-auto overflow-x-hidden min-w-0 flex flex-col rounded-2xl border border-border bg-popover text-popover-foreground shadow-xl animate-scale-in">
                  {gitChangeStat && (
                    <section className="p-2 border-b border-border/60">
                      {/* 这里只给总体数字；整行可点 → 跳右侧栏「更改」看逐文件明细。 */}
                      <button
                        type="button"
                        onClick={() => {
                          storeActions.setRightSidebarTab("diff");
                          setWorkPanelOpen(false);
                        }}
                        className="w-full flex items-center gap-2.5 min-w-0 px-2.5 py-2 text-left rounded-lg hover:bg-accent/50 transition-colors"
                        data-tip="查看更改明细"
                      >
                        <FilePlus className="size-4 shrink-0 text-foreground/50" />
                        <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.8571)] font-medium">
                          更改
                        </span>
                        <span className="shrink-0 flex items-center gap-1.5 text-[calc(var(--helix-transcript-size)*0.7857)] tabular-nums font-medium">
                          <span className="text-emerald-600 dark:text-emerald-400">
                            +{gitChangeStat.added}
                          </span>
                          <span className="text-red-500 dark:text-red-400">
                            -{gitChangeStat.removed}
                          </span>
                        </span>
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          setCommitMessage(
                            `chore: auto-commit (${new Date().toLocaleString("zh-CN")})`,
                          );
                          setWorkPanelOpen(false);
                          setCommitDialogOpen(true);
                        }}
                        disabled={isCommitting}
                        className="mt-1 w-full inline-flex items-center justify-center gap-1.5 h-8 rounded-lg bg-primary/10 text-primary text-[calc(var(--helix-transcript-size)*0.8571)] font-medium hover:bg-primary/20 disabled:opacity-50 transition-colors"
                      >
                        <Send className="size-3.5" />
                        提交并推送
                      </button>
                    </section>
                  )}
                  {pendingPlanReview && (
                    <section className="p-2 border-b border-border/60">
                      <div className="flex items-center gap-2.5 min-w-0 px-2.5 py-2">
                        <Pencil className="size-4 shrink-0 text-foreground/50" />
                        <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.8571)] font-medium">
                          计划 · 待批准
                        </span>
                        <span className="shrink-0 text-[calc(var(--helix-transcript-size)*0.7143)] px-1.5 py-0.5 rounded-full bg-primary/10 text-primary">
                          计划模式
                        </span>
                      </div>
                      <div className="px-1.5 pb-1.5">
                        <div className="max-h-48 overflow-y-auto rounded-lg border border-border/30 bg-muted/30 px-3 py-2 text-[calc(var(--helix-transcript-size)*0.7857)] text-foreground/80 whitespace-pre-wrap break-words">
                          {pendingPlanReview.content}
                        </div>
                        <p className="mt-1.5 px-1 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground">
                          底部「计划审批」浮条可选择 批准执行 / 继续调整
                        </p>
                      </div>
                    </section>
                  )}
                  {helixTodos.length > 0 && (
                  <section className="p-2 border-b border-border/60">
                    {(() => {
                      const doneCount = helixTodos.filter(
                        (t) => t.status === "completed",
                      ).length;
                      const pct = Math.round(
                        (doneCount / helixTodos.length) * 100,
                      );
                      return (
                        <>
                          <div className="flex items-center gap-2.5 min-w-0 px-2.5 py-2">
                            <ListTodo className="size-4 shrink-0 text-foreground/50" />
                            <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.8571)] font-medium">
                              任务清单
                            </span>
                            <span className="shrink-0 text-[calc(var(--helix-transcript-size)*0.7857)] tabular-nums text-foreground/50">
                              {doneCount}/{helixTodos.length}
                            </span>
                          </div>
                          <div className="px-2.5 pb-2.5">
                            <div className="h-1 rounded-full bg-muted overflow-hidden">
                              <div
                                className="h-full rounded-full bg-primary transition-[width] duration-300"
                                style={{ width: `${pct}%` }}
                              />
                            </div>
                          </div>
                          <ul className="px-1 pb-1">
                            {helixTodos.map((todo) => (
                              <li
                                key={todo.id}
                                className="flex items-start gap-2 px-1.5 py-1.5 rounded-lg hover:bg-accent/40 transition-colors text-[calc(var(--helix-transcript-size)*0.8571)]"
                              >
                                {todo.status === "completed" ? (
                                  <CheckCircle2 className="size-4 text-emerald-500 shrink-0 mt-0.5" />
                                ) : todo.status === "in_progress" ? (
                                  <Loader2 className="size-4 text-primary shrink-0 mt-0.5 animate-spin" />
                                ) : todo.status === "cancelled" ? (
                                  <XCircle className="size-4 text-muted-foreground shrink-0 mt-0.5" />
                                ) : (
                                  <Circle className="size-4 text-foreground/40 shrink-0 mt-0.5" />
                                )}
                                <span
                                  className={`min-w-0 break-words ${
                                    todo.status === "completed"
                                      ? "line-through text-foreground/50"
                                      : todo.status === "cancelled"
                                        ? "line-through text-foreground/40"
                                        : "text-foreground/90"
                                  }`}
                                >
                                  {todo.content}
                                </span>
                              </li>
                            ))}
                          </ul>
                        </>
                      );
                    })()}
                  </section>
                  )}
                  {(subAgents.length > 0 || isElectron()) &&
                    (subAgents.length > 0 || delegations.length > 0) && (
                    <section className="p-2">
                      {(() => {
                        // 磁盘重建卡已并入 subAgents；历史区只渲染剩余的
                        // delegation，计数同口径（否则列表 1 个、计数 2）。
                        const diskOnlyDelegations = delegations.filter(
                          (del) => !subAgents.some((sa) => sa.id === del.id),
                        );
                        const running = subAgents.filter(
                          (a) => a.status === "running",
                        ).length;
                        const total = subAgents.length + diskOnlyDelegations.length;
                        return (
                          <div className="flex items-center gap-2.5 min-w-0 px-2.5 py-2">
                            <Users className="size-4 shrink-0 text-foreground/50" />
                            <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.8571)] font-medium">
                              子 Agent
                            </span>
                            {running > 0 ? (
                              <span className="shrink-0 flex items-center gap-1.5 text-[calc(var(--helix-transcript-size)*0.7857)] text-primary">
                                <span className="size-1.5 rounded-full bg-primary animate-pulse" />
                                {running} 运行
                                <span className="text-foreground/40">/</span>
                                <span className="tabular-nums text-foreground/50">
                                  {total}
                                </span>
                              </span>
                            ) : (
                              <span className="shrink-0 text-[calc(var(--helix-transcript-size)*0.7857)] tabular-nums text-foreground/50">
                                {total} 个
                              </span>
                            )}
                          </div>
                        );
                      })()}
                      <div className="max-h-72 overflow-auto px-1.5">
                        {/* 实时区：store.subAgents（subagent.* 事件驱动），同步/后台
                            agent 都能显示，磁盘 delegations 作历史兜底。 */}
                        {subAgents.map((sa) => {
                          // 运行中/完成都列出最近的真实工具调用（合成的
                          // progress/background 行不显示，避免"progress"被
                          // 当成工具名）。顶部是提示词（description），下方
                          // 才是执行内容，符合"先给什么任务、再看干了什么"。
                          const rows = (sa.toolCalls || []).filter(
                            (tc) => !isSyntheticSubAgentToolRow(tc.toolName),
                          );
                          const recentRows = rows.slice(-3);
                          const toolCount = rows.length;
                          return (
                          <button
                            key={`live-${sa.id}`}
                            type="button"
                            onClick={() => {
                              storeActions.openAgentView({
                                id: sa.id,
                                name: sa.description || sa.name,
                              });
                              setWorkPanelOpen(false);
                            }}
                            className="w-full text-left px-2 py-2 rounded-lg hover:bg-accent/50 transition-colors"
                            data-tip="在右侧栏查看工作内容"
                          >
                            <div className="flex items-start gap-2">
                              {sa.status === "running" ? (
                                <Loader2 className="size-3.5 text-primary shrink-0 animate-spin mt-0.5" />
                              ) : sa.status === "failed" ? (
                                <XCircle className="size-3.5 text-destructive shrink-0 mt-0.5" />
                              ) : (
                                <CheckCircle2 className="size-3.5 text-emerald-500 shrink-0 mt-0.5" />
                              )}
                              <div className="flex-1 min-w-0">
                                {/* 提示词（最上面）：给这个子 Agent 的任务描述 */}
                                <div
                                  className="text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/85 line-clamp-2"
                                  title={sa.description || sa.name}
                                >
                                  {sa.description || sa.name}
                                </div>
                                {/* 执行内容（下面）：最近几条真实工具调用 + 总数 */}
                                {(recentRows.length > 0 || sa.status === "running") && (
                                  <div className="mt-1 space-y-0.5">
                                    {recentRows.map((tc, i) => (
                                      <div
                                        key={i}
                                        className="flex items-center gap-1.5 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground"
                                      >
                                        <span className="font-mono truncate">
                                          {tc.toolName}
                                        </span>
                                        <span
                                          className={
                                            "shrink-0 " +
                                            (tc.status === "running"
                                              ? "text-primary"
                                              : tc.status === "success"
                                                ? "text-emerald-500"
                                                : "text-destructive")
                                          }
                                        >
                                          {tc.status === "running"
                                            ? "…"
                                            : tc.status === "success"
                                              ? "✓"
                                              : "✗"}
                                        </span>
                                        {tc.params && (
                                          <span className="truncate min-w-0 flex-1 text-foreground/50">
                                            {tc.params}
                                          </span>
                                        )}
                                      </div>
                                    ))}
                                    {sa.status === "running" && recentRows.length === 0 && (
                                      <div className="text-[calc(var(--helix-transcript-size)*0.7143)] text-primary">
                                        等待第一个工具调用…
                                      </div>
                                    )}
                                    {toolCount > recentRows.length && (
                                      <div className="text-[calc(var(--helix-transcript-size)*0.7143)] text-foreground/40">
                                        共 {toolCount} 次工具调用
                                      </div>
                                    )}
                                  </div>
                                )}
                                {sa.status !== "running" && sa.result && (
                                  <div className="mt-1 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground line-clamp-2">
                                    {sa.result}
                                  </div>
                                )}
                              </div>
                              <ChevronRight className="size-3.5 text-foreground/30 shrink-0 mt-0.5" />
                            </div>
                          </button>
                          );
                        })}
                        {/* 历史区：磁盘 live 日志（重建卡已并入上方实时区，按 id 去重） */}
                        {delegations
                          .filter(
                            (del) => !subAgents.some((sa) => sa.id === del.id),
                          )
                          .map((del) => (
                          <button
                            key={del.id}
                            type="button"
                            onClick={() => {
                              storeActions.openAgentView({
                                id: del.id,
                                name: del.id,
                              });
                              setWorkPanelOpen(false);
                            }}
                            className="w-full text-left px-2 py-2 rounded-lg hover:bg-accent/50 transition-colors"
                            data-tip="在右侧栏查看工作内容"
                          >
                            <div className="flex items-center gap-2">
                              <Terminal className="size-3.5 text-primary/60 shrink-0" />
                              <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.8571)] font-mono text-foreground/70">
                                {del.id}
                              </span>
                              <ChevronRight className="size-3.5 text-foreground/30 shrink-0" />
                            </div>
                            <div className="mt-0.5 pl-5 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground">
                              {(del.tasks || []).length} 个任务
                            </div>
                          </button>
                        ))}
                      </div>
                    </section>
                    )}
                    {/* 后台任务区：独立 section，不属于「子 Agent」——它们是
                        pi-background-tasks 的 shell 进程，不是子代理。
                        仅本会话用 background 工具启动的任务；其它会话的在
                        右上角「后台任务」按钮的全局面板里。 */}
                    {workPanelBgTasks.length > 0 && (
                      <section className="p-2">
                        <div className="flex items-center gap-2.5 min-w-0 px-2.5 py-2">
                          <Terminal className="size-4 shrink-0 text-foreground/50" />
                          <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.8571)] font-medium">
                            后台任务
                          </span>
                          <span className="shrink-0 text-[calc(var(--helix-transcript-size)*0.7857)] tabular-nums text-foreground/50">
                            {workPanelBgTasks.filter((t) => t.status === "running")
                              .length}{" "}
                            运行 / {workPanelBgTasks.length}
                          </span>
                        </div>
                        <div className="max-h-56 overflow-auto px-1.5">
                          {workPanelBgTasks.map((t) => (
                            <button
                              key={t.id}
                              type="button"
                              onClick={() => {
                                setBgTasksOpen(true);
                                setWorkPanelOpen(false);
                              }}
                              className="w-full text-left px-2 py-2 rounded-lg hover:bg-accent/50 transition-colors"
                              data-tip="在后台任务面板查看详情"
                            >
                              <div className="flex items-center gap-2">
                                {t.status === "running" ? (
                                  <Loader2 className="size-3.5 text-primary shrink-0 animate-spin" />
                                ) : t.status === "completed" ? (
                                  <CheckCircle2 className="size-3.5 text-emerald-500 shrink-0" />
                                ) : (
                                  <XCircle className="size-3.5 text-destructive shrink-0" />
                                )}
                                <span className="flex-1 min-w-0 truncate text-[calc(var(--helix-transcript-size)*0.8571)] font-mono text-foreground/80">
                                  {t.command}
                                </span>
                                <span className="shrink-0 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground">
                                  {t.status}
                                </span>
                              </div>
                            </button>
                          ))}
                        </div>
                      </section>
                    )}
                </div>
                </div>,
                document.body,
              );
            })()}
            </div>
            )}
            {/* 提交弹窗：点「提交并推送」弹出，含提交信息输入框 + 提交 / 提交并推送 两个动作 */}
            {commitDialogOpen && typeof window !== "undefined" && (
              <>
                <div
                  className="fixed inset-0 bg-black/30 z-[300]"
                  onClick={() => !isCommitting && setCommitDialogOpen(false)}
                />
                <div className="fixed z-[310] left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-[480px] max-h-[80vh] bg-card rounded-xl border border-border/50 shadow-2xl flex flex-col overflow-hidden">
                  <div className="shrink-0 px-5 pt-5 pb-3 flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <h3 className="text-[calc(var(--helix-transcript-size)*1.1429)] font-semibold text-foreground leading-tight">
                        提交更改
                      </h3>
                      <p className="mt-1 text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground tabular-nums">
                        {gitChangeStat?.files.length ?? 0} 个文件待提交 ·{" "}
                        <span className="text-emerald-600 dark:text-emerald-400">
                          +{gitChangeStat?.added ?? 0}
                        </span>{" "}
                        <span className="text-red-500 dark:text-red-400">
                          -{gitChangeStat?.removed ?? 0}
                        </span>
                      </p>
                    </div>
                    <button
                      onClick={() =>
                        !isCommitting && setCommitDialogOpen(false)
                      }
                      disabled={isCommitting}
                      className="shrink-0 p-1 rounded text-foreground/40 hover:text-foreground hover:bg-accent/50 transition-colors disabled:opacity-40"
                    >
                      <X className="size-4" />
                    </button>
                  </div>
                  <div className="shrink-0 px-5 pb-4">
                    <label className="block text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground mb-1.5">
                      提交信息
                    </label>
                    <textarea
                      value={commitMessage}
                      onChange={(e) => setCommitMessage(e.target.value)}
                      rows={3}
                      autoFocus
                      className="w-full resize-none rounded-lg border border-border/30 bg-muted/20 px-3 py-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground outline-none focus:border-primary/50 transition-colors"
                    />
                  </div>
                  <div className="shrink-0 px-5 pb-5 flex items-center justify-end gap-2.5">
                    <button
                      onClick={() => quickCommit(false, commitMessage)}
                      disabled={isCommitting}
                      className="px-4 py-2 rounded-lg text-[calc(var(--helix-transcript-size)*0.9286)] font-medium text-foreground/70 bg-muted/50 hover:bg-muted/80 transition-colors disabled:opacity-40 flex items-center gap-1.5"
                    >
                      {isCommitting ? (
                        <Loader2 className="size-4 animate-spin" />
                      ) : (
                        <GitCommit className="size-4" />
                      )}
                      提交
                    </button>
                    <button
                      onClick={() => quickCommit(true, commitMessage)}
                      disabled={isCommitting}
                      className="px-4 py-2 rounded-lg text-[calc(var(--helix-transcript-size)*0.9286)] font-medium text-primary-foreground bg-primary hover:bg-primary/90 transition-colors disabled:opacity-50 flex items-center gap-1.5"
                    >
                      {isCommitting ? (
                        <Loader2 className="size-4 animate-spin" />
                      ) : (
                        <Send className="size-4" />
                      )}
                      提交并推送
                    </button>
                  </div>
                </div>
              </>
            )}
            {(runningBgTasks.length > 0 || bgTasksOpen) && (
              <div className="relative" ref={bgTasksRef}>
                <button
                  onClick={() => setBgTasksOpen((v) => !v)}
                  className={`relative p-1.5 rounded-lg transition-colors ${bgTasksOpen ? "text-primary bg-primary/10" : "text-foreground/50 hover:text-foreground hover:bg-accent/60"}`}
                  data-tip="后台任务"
                >
                  <Loader2 className="size-[18px]" />
                  {runningBgTasks.length > 0 && (
                    <span className="absolute -top-0.5 -right-0.5 min-w-[14px] h-[14px] px-1 rounded-full bg-primary text-primary-foreground text-[calc(var(--helix-transcript-size)*0.6429)] font-medium flex items-center justify-center">
                      {runningBgTasks.length}
                    </span>
                  )}
                </button>
                {bgTasksOpen && (
                  <BackgroundTasksPanel
                    tasks={bgTasksAll}
                    activeSessionId={helixSessionId}
                    onClose={() => setBgTasksOpen(false)}
                    onRefresh={loadBgTasks}
                  />
                )}
              </div>
            )}
            <button
              onClick={() => storeActions.toggleTerminal()}
              className={`p-1.5 rounded-lg transition-colors ${isTerminalOpen ? "text-primary bg-primary/10" : "text-foreground/50 hover:text-foreground hover:bg-accent/60"}`}
              data-tip="终端"
            >
              <Terminal className="size-4" />
            </button>
            <button
              ref={browserMenuButtonRef}
              onClick={() => setBrowserMenuOpen((v) => !v)}
              className={`p-1.5 rounded-lg transition-colors ${browserMenuOpen ? "text-primary bg-primary/10" : "text-foreground/50 hover:text-foreground hover:bg-accent/60"}`}
              data-tip="更多操作"
            >
              <MoreHorizontal className="size-4" />
            </button>
          </>
        )}
        <button
          onClick={() => (window as any).electron?.window?.minimize()}
          className="p-1.5 text-foreground/40 hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors"
          data-tip="最小化"
        >
          <Minus className="size-4" />
        </button>
        <button
          onClick={handleMaximizeToggle}
          className="p-1.5 text-foreground/40 hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors"
          data-tip={isMaximized ? "还原" : "最大化"}
        >
          {isMaximized ? (
            <Copy className="size-4" />
          ) : (
            <Square className="size-4" />
          )}
        </button>
        <button
          onClick={() => (window as any).electron?.window?.close()}
          className="p-1.5 text-foreground/40 hover:text-foreground hover:bg-destructive/10 hover:text-destructive rounded-lg transition-colors"
          data-tip="关闭"
        >
          <X className="size-4" />
        </button>
      </div>

      {/* Right region: settings or conversation */}
      <div className="flex-1 flex overflow-hidden">
        {/* Floating cards container — settings mode owns its own sidebar +
            card and is rendered full-height (no inset); the main chat branch
            below applies its own mt/mb inset so the chat card floats. */}
        <div className="flex-1 flex flex-col overflow-hidden">
          {showSettings ? (
            <div className="helix-surface flex-1 flex flex-col overflow-hidden min-h-0">
              <PanelSuspense>
                <ApiSettings
                  themeStyle={themeStyle}
                  onSelectThemeStyle={setThemeStyle}
                  sidebarWidth={sidebarWidth}
                  setSidebarWidth={setSidebarWidth}
                  saveSidebarWidth={saveSidebarWidth}
                  showSidebar={showSidebar}
                  setShowSidebar={setShowSidebar}
                  sidebarCollapsed={sidebarCollapsed}
                  setSidebarCollapsed={setSidebarCollapsed}
                />
              </PanelSuspense>
            </div>
          ) : (
            <div className="flex-1 min-h-0 flex flex-col mr-px ml-0 overflow-hidden">
              <div className="flex-1 min-h-0 flex flex-row relative">
                {/* Floating card — main content. Hidden when the code panel is in
            fullscreen (the right sidebar takes over the main area). */}
                <div
                  className={`helix-surface flex-1 flex flex-col overflow-hidden ${codeFullscreen ? "hidden" : ""}`}
                >
                  {/* Main area */}
                  <div className="relative flex-1 h-full flex flex-col overflow-hidden">
                    <div
                      className={`flex-1 flex flex-row overflow-hidden ${sidePanelOpen ? "hidden" : ""}`}
                    >
                      <div className="flex-1 flex flex-col overflow-hidden min-w-0">
                        {/* Conversation header — only visible when an active conversation has messages */}
                        {chatMessages.length > 0 && !!currentSessionId && (
                          <div className="shrink-0 h-10 flex items-center justify-between gap-2 px-3 pr-44">
                            {!showSettings && !hideConversationActions && (
                              <div className="flex items-center gap-3 min-w-0 mt-[2px] ml-2">
                                {/* 项目外对话（activeSessionWorkDir 为空）不显示项目目录与分支 */}
                                {activeSessionWorkDir && (
                                  <button
                                    onClick={handleOpenLocation}
                                    className="flex items-center gap-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/70 hover:text-foreground hover:bg-accent/60 px-2 py-1 rounded-lg transition-colors shrink-0"
                                    data-tip={
                                      selectedWorkDir
                                        ? "在资源管理器中打开"
                                        : "选择位置"
                                    }
                                  >
                                    <Folder className="size-4 text-muted-foreground" />
                                    <span className="max-w-[200px] truncate">
                                      {selectedWorkDir
                                        ? (() => {
                                            const n =
                                              selectedWorkDir
                                                .split(/[/\\]/)
                                                .pop() || selectedWorkDir;
                                            return n.length > 8
                                              ? n.slice(0, 8) + "…"
                                              : n;
                                          })()
                                        : "未选择位置"}
                                    </span>
                                  </button>
                                )}
                                {branchPickerWorkDir && gitBranch && (
                                  <BranchPicker
                                    workDir={branchPickerWorkDir}
                                    currentBranch={gitBranch}
                                    onBranchChange={(b) => setGitBranch(b)}
                                    drop="down"
                                  />
                                )}
                              </div>
                            )}
                            <div className="flex items-center gap-1 shrink-0">
                              {browserMenuOpen &&
                                typeof window !== "undefined" &&
                                createPortal(
                                  <div
                                    className="fixed z-[100]"
                                    style={{
                                      top:
                                        (browserMenuButtonRef.current?.getBoundingClientRect()
                                          .bottom ?? 0) + 4,
                                      left: browserMenuButtonRef.current
                                        ? Math.max(
                                            8,
                                            browserMenuButtonRef.current.getBoundingClientRect()
                                              .right - 208,
                                          )
                                        : 0,
                                    }}
                                  >
                                    <div ref={browserMenuRef}>
                                      <MoreActionsMenu
                                        onToggleTab={(kind) => {
                                          if (rightSidebarTab !== kind)
                                            storeActions.setRightSidebarTab(
                                              kind,
                                            );
                                          setBrowserMenuOpen(false);
                                        }}
                                        onAddBrowser={() => {
                                          storeActions.requestAddBrowserPage();
                                          setBrowserMenuOpen(false);
                                        }}
                                      />
                                    </div>
                                  </div>,
                                  document.body,
                                )}
                            </div>
                          </div>
                        )}
                        <div className="flex-1 min-h-0 min-w-0 flex flex-col">
                          <AgentFlowPanel />
                        </div>
                      </div>
                    </div>
                  </div>
                  {showScheduledTasksPanel && (
                    <div className="helix-surface helix-surface-overlay z-20 rounded-2xl overflow-hidden flex flex-col">
                      <PanelSuspense>
                        <ScheduledTasksPanel />
                      </PanelSuspense>
                    </div>
                  )}
                  {showSkillPanel && (
                    <div className="helix-surface helix-surface-overlay z-20 rounded-2xl overflow-hidden flex flex-col">
                      <PanelSuspense>
                        <SkillPanel />
                      </PanelSuspense>
                    </div>
                  )}
                </div>
                {/* Floating card — right sidebar. Kept mounted at all times so switching
            tabs (and the browser <webview>) never rebuilds; visibility is toggled
            with the `hidden` class + width instead of a conditional mount, which
            removes the "flash / white-screen on first open and on every tab
            switch". */}
                <div
                  className={`relative ${codeFullscreen ? "flex-1 min-w-0" : "shrink-0"} ${rightSidebarTab && !(showSkillPanel || showScheduledTasksPanel || showRuntimePanel || showWorktreePanel || showSubAgentPanel) ? "" : "hidden"}`}
                  style={
                    codeFullscreen
                      ? undefined
                      : { width: rightSidebarTab ? rightSidebarWidth : 0 }
                  }
                >
                  {!codeFullscreen && (
                    <div
                      className="absolute top-0 -left-1 w-2 h-full cursor-col-resize z-30 group"
                      onPointerDown={handleRightDragStart}
                    >
                      <div className="absolute inset-y-0 left-1/2 -translate-x-1/2 w-0.5 bg-transparent group-hover:bg-border/40 transition-colors" />
                    </div>
                  )}
                  <div className="helix-surface h-full rounded-2xl overflow-hidden">
                    <PanelSuspense>
                      <RightSidebar />
                    </PanelSuspense>
                  </div>
                </div>
                {showRuntimePanel && (
                  <div className="absolute inset-0 z-20">
                    <PanelSuspense>
                      <RuntimePanel
                        onClose={() => storeActions.toggleRuntimePanel()}
                      />
                    </PanelSuspense>
                  </div>
                )}
                {showWorktreePanel && (
                  <div className="absolute inset-0 z-20">
                    <PanelSuspense>
                      <WorktreePanel
                        onClose={() => storeActions.toggleWorktreePanel()}
                      />
                    </PanelSuspense>
                  </div>
                )}
                <div
                  className={`absolute inset-0 z-20 ${showSubAgentPanel ? "" : "hidden"}`}
                >
                  <PanelSuspense>
                    <DelegationsPanel
                      onClose={() => storeActions.toggleSubAgentPanel()}
                    />
                  </PanelSuspense>
                </div>
              </div>
              {/* Terminal: a bottom panel of the whole main area (NOT inside the main
              conversation card), so it stays visible when the code editor is in
              fullscreen — which hides the conversation card. */}
              <TerminalPanel onClose={storeActions.toggleTerminal} />
            </div>
          )}
        </div>
      </div>
      {/* Overlay panels */}
      <Suspense fallback={null}>
        {showSessionManager && (
          <SessionManager onClose={() => storeActions.toggleSessionManager()} />
        )}
        {showCustomizePanel && (
          <CustomizePanel onClose={() => storeActions.toggleCustomizePanel()} />
        )}
        {/* New surfaces */}
        {showActivityFeed && (
          <ActivityFeed onClose={() => storeActions.toggleActivityFeed()} />
        )}
        {showArtifactsBrowser && (
          <ArtifactsBrowser
            onClose={() => storeActions.toggleArtifactsBrowser()}
          />
        )}
        {restoreReady && <Onboarding />}
        <BootOverlay />
        <GlobalTooltip />
        {/* Hidden same-origin snapshot iframe used by the pi browser tools
            (browser_read/click/type/press) — mounted at the layout root so it
            stays alive regardless of which side panel is open. */}
        <BrowserExecFrame html={browserExecHtml} />
      </Suspense>
    </div>
  );
}

"use client";

import { Plus, Trash2 } from "lucide-react";
import React, { useState, useEffect, useCallback } from "react";
import { Toggle, SettingGroup, SectionHeading } from "./settings-ui";
import { Button } from "@/components/ui/button";
import { isElectron } from "@/lib/electron-bridge";
import {
  type HookType,
  type HookConfig,
  type HooksSettings,
  HOOK_META,
  HOOK_TYPES,
  EMPTY_HOOKS_SETTINGS,
  generateHookId,
} from "@/lib/hooks-config";
import { isTauri } from "@/lib/tauri-bridge";

export function HookSettings() {
  const [settings, setSettings] = useState<HooksSettings>(EMPTY_HOOKS_SETTINGS);
  const [loaded, setLoaded] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveState, setSaveState] = useState<null | "ok" | "err">(null);

  const platformReady = isElectron() || isTauri();

  useEffect(() => {
    if (!platformReady) {
      setLoaded(true);
      return;
    }

    const loadConfig = async () => {
      try {
        let r: any;
        if (isTauri()) {
          const { invoke } = await import("@tauri-apps/api/core");
          r = await invoke("hooks_list");
        } else {
          r = await window.electron.hooks.getConfig();
        }

        if (r.ok && r.config) {
          const hooks: HookConfig[] = [];
          if (r.config.hooks && typeof r.config.hooks === "object") {
            for (const [event, handlers] of Object.entries(r.config.hooks)) {
              if (Array.isArray(handlers)) {
                for (const h of handlers) {
                  hooks.push({
                    id: generateHookId(),
                    type: event as HookType,
                    command: (h as any).command || "",
                    matcher: (h as any).matcher || "",
                    enabled: true,
                  });
                }
              }
            }
          }
          setSettings({ enabled: r.config.enabled !== false, hooks });
        }
      } catch { /* empty */}
    };

    loadConfig().finally(() => setLoaded(true));
  }, [platformReady]);

  const setMasterEnabled = (v: boolean) =>
    setSettings((s) => ({ ...s, enabled: v }));

  const hooksOfType = (type: HookType) =>
    settings.hooks.filter((h) => h.type === type);

  const addHook = (type: HookType) => {
    const newHook: HookConfig = {
      id: generateHookId(),
      type,
      command: "",
      matcher: "",
      enabled: true,
    };
    setSettings((s) => ({ ...s, hooks: [...s.hooks, newHook] }));
  };

  const removeHook = (id: string) => {
    setSettings((s) => ({ ...s, hooks: s.hooks.filter((h) => h.id !== id) }));
  };

  const updateHook = (id: string, patch: Partial<HookConfig>) => {
    setSettings((s) => ({
      ...s,
      hooks: s.hooks.map((h) => (h.id === id ? { ...h, ...patch } : h)),
    }));
  };

  const toggleHook = (id: string) => {
    setSettings((s) => ({
      ...s,
      hooks: s.hooks.map((h) =>
        h.id === id ? { ...h, enabled: !h.enabled } : h,
      ),
    }));
  };

  const save = useCallback(async () => {
    if (!platformReady) return;
    setSaving(true);
    try {
      const hooksConfig: Record<
        string,
        { command: string; matcher?: string }[]
      > = {};
      for (const hook of settings.hooks) {
        if (!hook.command.trim()) continue;
        if (!hooksConfig[hook.type]) hooksConfig[hook.type] = [];
        hooksConfig[hook.type].push({
          command: hook.command,
          ...(hook.matcher ? { matcher: hook.matcher } : {}),
        });
      }

      let r: any;
      if (isTauri()) {
        const { invoke } = await import("@tauri-apps/api/core");
        r = await invoke("hooks_save", {
          config: { enabled: settings.enabled, hooks: hooksConfig },
        });
      } else {
        r = await window.electron.hooks.setConfig({
          enabled: settings.enabled,
          hooks: hooksConfig,
        });
      }
      setSaveState(r.ok ? "ok" : "err");
    } catch {
      setSaveState("err");
    } finally {
      setSaving(false);
    }
  }, [settings, platformReady]);

  if (!platformReady) {
    return (
      <div className="max-w-3xl">
        <SectionHeading>Hooks</SectionHeading>
      </div>
    );
  }

  if (!loaded) {
    return (
      <div className="max-w-3xl">
        <SectionHeading>Hooks</SectionHeading>
        <p className="ui-text text-muted-foreground">加载 Hooks 配置中…</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <SectionHeading>Hooks</SectionHeading>

      <div className="flex items-center justify-between gap-3 px-1">
        <span className="ui-subtitle font-semibold text-foreground">
          启用 Hooks
        </span>
        <Toggle
          enabled={settings.enabled}
          onToggle={() => setMasterEnabled(!settings.enabled)}
        />
      </div>

      <SettingGroup>
        {HOOK_TYPES.map((type) => {
          const meta = HOOK_META[type];
          const hooks = hooksOfType(type);
          return (
            <div key={type} className="px-4 py-3">
              <div className="flex items-center justify-between gap-2">
                <h4 className="ui-text text-foreground">{meta.label}</h4>
                <Button
                  size="icon"
                  variant="outline"
                  onClick={() => addHook(type)}
                  aria-label="添加"
                >
                  <Plus className="size-4" />
                </Button>
              </div>
              <div className="mt-0.5 ui-text text-muted-foreground/60">
                {meta.desc}
              </div>
              <div className="mt-2 space-y-2">
                {hooks.map((hook) => (
                  <div
                    key={hook.id}
                    className="rounded-lg border border-border/30 bg-muted/10 px-3 py-2 space-y-1.5"
                  >
                    <div className="flex items-center gap-3">
                      <Toggle
                        enabled={hook.enabled}
                        onToggle={() => toggleHook(hook.id)}
                      />
                      <div className="flex-1 min-w-0 space-y-1">
                        <label className="block ui-text text-muted-foreground/70">
                          命令 Command
                        </label>
                        <input
                          value={hook.command}
                          onChange={(e) =>
                            updateHook(hook.id, { command: e.target.value })
                          }
                          placeholder="如 python3 ~/.pi/agent/helix/hooks/notify.py"
                          className="w-full px-2.5 py-1.5 bg-background/60 border border-border/20 rounded-md ui-text text-foreground text-center placeholder:text-muted-foreground/30 font-mono transition-colors"
                        />
                      </div>
                      <Button
                        size="icon"
                        variant="ghost"
                        className="size-8 shrink-0 text-muted-foreground/50 hover:text-destructive hover:bg-destructive/10"
                        onClick={() => removeHook(hook.id)}
                        aria-label="删除 hook"
                        data-tip="删除"
                      >
                        <Trash2 className="size-4" />
                      </Button>
                    </div>
                    {meta.supportsMatcher && (
                      <div className="space-y-1 pl-[52px]">
                        <label className="block ui-text text-muted-foreground/70">
                          Matcher 正则（工具名，留空 = 全部）
                        </label>
                        <input
                          value={hook.matcher}
                          onChange={(e) =>
                            updateHook(hook.id, { matcher: e.target.value })
                          }
                          placeholder="如 edit|write"
                          className="w-full px-2.5 py-1.5 bg-background/60 border border-border/20 rounded-md ui-text text-foreground text-center placeholder:text-muted-foreground/30 font-mono transition-colors"
                        />
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </SettingGroup>

      <div className="flex items-center justify-end gap-3 pt-4">
        <Button size="sm" variant="outline" onClick={save} disabled={saving}>
          {saving ? "保存并重启网关…" : "保存 Hooks 配置"}
        </Button>
        {saveState === "ok" && (
          <span className="ui-text text-primary">已保存，网关已重启</span>
        )}
        {saveState === "err" && (
          <span className="ui-text text-destructive">保存失败，请重试</span>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { PopupSelect, SettingGroup } from "./settings-ui";
import { Button } from "@/components/ui/button";
import { isElectron } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";

const IMAGE_PROVIDERS = [
  { id: "gemini", name: "Gemini" },
  { id: "zai", name: "Zhipu AI (z.ai) / GLM" },
  { id: "__custom__", name: "自定义" },
];

// 已知 endpoint 的 provider：自动填好 base_url，用户只需填 API Key
const PROVIDER_BASE_URLS: Record<string, string> = {
  gemini: "https://generativelanguage.googleapis.com/v1beta/openai/",
  zai: "https://open.bigmodel.cn/api/paas/v4",
};

export function ImageModelSettings() {
  const showToast = useHelixStore((s) => s.showToast);
  const [provider, setProvider] = useState("gemini");
  const [model, setModel] = useState("");
  const [baseUrl, setBaseUrl] = useState("");
  const [apiKey, setApiKey] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const load = async () => {
      if (!isElectron()) {
        const saved = localStorage.getItem("helix-image-model");
        if (saved) {
          try {
            const d = JSON.parse(saved);
            setProvider(d.provider || "gemini");
            setModel(d.model || "");
            setBaseUrl(d.baseUrl || "");
            setApiKey(d.apiKey || "");
          } catch {
            /* 本地缓存读取失败时静默降级，不影响后续保存 */
          }
        }
        return;
      }
      try {
        const api = (window as any).electron?.image;
        if (!api?.getConfig) return;
        const r = await api.getConfig();
        if (r?.ok && r.config) {
          setProvider(r.config.provider || "gemini");
          setModel(r.config.model || "");
          setBaseUrl(r.config.baseUrl || "");
          setApiKey(r.config.apiKey || "");
        }
      } catch (e) {
        console.error("[ImageModelSettings] load failed:", e);
      }
    };
    load();
  }, []);

  const knownBaseUrl = PROVIDER_BASE_URLS[provider];
  const showApiKey = provider !== "auto";
  const showBaseUrl = !knownBaseUrl && provider !== "auto";

  const save = async () => {
    setSaving(true);
    try {
      const config = {
        provider: provider === "__custom__" ? "custom" : provider,
        model,
        baseUrl: knownBaseUrl ? knownBaseUrl : showBaseUrl ? baseUrl : "",
        apiKey: showApiKey ? apiKey : "",
      };
      if (isElectron()) {
        const api = (window as any).electron?.image;
        if (api?.setConfig) await api.setConfig(config);
      } else {
        localStorage.setItem("helix-image-model", JSON.stringify(config));
      }
      showToast({ type: "success", title: "生图模型配置已保存" });
    } catch {
      showToast({ type: "error", title: "保存失败" });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-4">
      <SettingGroup>
        <div className="p-4 space-y-3">
          {/* Provider */}
          <div>
            <label className="block ui-text font-medium text-foreground mb-1.5">
              Provider
            </label>
            <PopupSelect
              value={provider}
              onChange={setProvider}
              placeholder="选择生图 Provider"
              className="w-full ui-text text-foreground border border-border/50 bg-muted/50 rounded-lg px-3 py-2"
              options={IMAGE_PROVIDERS.map((p) => ({
                label: p.name,
                value: p.id,
              }))}
            />
          </div>

          {/* Model：纯文本输入，不限制预设列表 */}
          <div>
            <label className="block ui-text font-medium text-foreground mb-1.5">
              模型名称
            </label>
            <input
              type="text"
              value={model}
              onChange={(e) => setModel(e.target.value)}
              placeholder=""
              className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
            />
          </div>

          {/* Base URL：已知 endpoint 自动填充（只读）；未知则手填 */}
          {knownBaseUrl ? (
            <div>
              <label className="block ui-text font-medium text-foreground mb-1.5">
                Base URL
              </label>
              <input
                type="text"
                value={knownBaseUrl}
                readOnly
                disabled
                className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground/70 font-mono cursor-not-allowed"
              />
            </div>
          ) : (
            showBaseUrl && (
              <div>
                <label className="block ui-text font-medium text-foreground mb-1.5">
                  Base URL
                </label>
                <input
                  type="text"
                  value={baseUrl}
                  onChange={(e) => setBaseUrl(e.target.value)}
                  placeholder=""
                  className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
                />
              </div>
            )
          )}

          {/* API Key */}
          {showApiKey && (
            <div>
              <label className="block ui-text font-medium text-foreground mb-1.5">
                API Key
              </label>
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                placeholder="sk-..."
                className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
              />
            </div>
          )}
        </div>
      </SettingGroup>

      <div className="flex justify-end pt-2">
        <Button size="sm" variant="outline" onClick={save} disabled={saving}>
          {saving ? "保存中..." : "保存"}
        </Button>
      </div>
    </div>
  );
}

"use client";

import { Copy, CheckCheck } from "lucide-react";
import React, { useState } from "react";
import { CodeCard } from "@/components/Helix/helix-markdown";
import { formatDurationSeconds } from "@/lib/format";
import { normalizeAcpContent, stripEmoji } from "@/lib/text-utils";
import {
  getToolDisplayLabel,
  extractCommandSnippet,
  extractToolPath,
} from "@/lib/tool-display-utils";
import type { ExecutionStep } from "@/stores/helix-store";

const TOOL_RESULT_CLAMP = 20_000;

// ── Sub-step grouping ───────────────────────────────────────────────────

const TOOL_CATEGORY: Record<string, string> = {
  open_browser: "浏览器",
  browser_navigate: "浏览器导航",
  browser_read: "浏览器读取",
  browser_click: "浏览器点击",
  browser_type: "浏览器输入",
  browser_scroll: "浏览器滚动",
  read: "读取",
  read_file: "读取",
  write: "写入",
  write_file: "写入",
  edit: "编辑",
  patch: "编辑",
  bash: "终端",
  execute_command: "终端",
  run_command: "终端",
  terminal: "终端",
  grep: "搜索",
  search: "搜索",
  glob: "搜索",
  list_directory: "列表",
  list_files: "列表",
  web_search: "网页搜索",
  web_fetch: "获取网页",
  fetch: "获取网页",
};

function getToolCategory(toolName: string): string {
  const name = (toolName || "").toLowerCase().replace(/[^a-z0-9]/g, "_");
  for (const [key, cat] of Object.entries(TOOL_CATEGORY)) {
    if (name.includes(key)) return cat;
  }
  return toolName || "工具";
}

interface SubStepGroup {
  category: string;
  count: number;
  items: ExecutionStep[];
  status: "completed" | "failed" | "running";
}

function groupSubSteps(steps: ExecutionStep[]): SubStepGroup[] {
  const groups: SubStepGroup[] = [];
  for (const step of steps) {
    const cat = getToolCategory(step.toolName || "");
    const last = groups[groups.length - 1];
    if (last && last.category === cat && last.status !== "failed") {
      last.count++;
      last.items.push(step);
    } else {
      groups.push({
        category: cat,
        count: 1,
        items: [step],
        status: step.status === "failed" ? "failed" : step.status === "running" ? "running" : "completed",
      });
    }
  }
  return groups;
}

// ── ANSI escape code stripper ───────────────────────────────────────────

const ANSI_ESCAPE = String.fromCharCode(27);
const ANSI_RE = new RegExp(
  `${ANSI_ESCAPE}\\[[0-9;]*[a-zA-Z]|${ANSI_ESCAPE}\\].*?${String.fromCharCode(7)}`,
  "g",
);
function stripAnsi(s: string): string {
  return s.replace(ANSI_RE, "");
}

// Helix 的 mktemp 包装（cache/terminal/helix-snap-*.sh.tmp.XXXX）若
// cache/terminal 目录缺失就会刷一行 mktemp: failed to create...。这是环境噪音
// 不是工具执行失败，从渲染内容里整行剥掉。
function stripMktempNoise(s: string): string {
  return s
    .split("\n")
    .filter(
      (line) => !/^\s*mktemp:\s+failed to create file via template/i.test(line),
    )
    .join("\n")
    .replace(/^\n+|\n+$/g, "");
}

// ── Result count extraction ──────────────────────────────────────────────

function extractResultCount(
  content: string,
  _toolName: string,
  params?: Record<string, unknown>,
): string {
  // Check params for explicit count fields
  if (params) {
    for (const key of [
      "count",
      "result_count",
      "match_count",
      "file_count",
      "total",
    ]) {
      const v = params[key];
      if (typeof v === "number" && v > 0) return `${v}`;
    }
  }
  // Scan content for "Found X results", "X matches", "X files", etc.
  const countMatch = content.match(
    /(?:Found|found|Total|total)\s+(\d+)\s+(results?|matches?|files?|entries?|items?|occurrences?)/i,
  );
  if (countMatch) return countMatch[1];
  // Match array-like patterns
  const lines = content
    .trim()
    .split("\n")
    .filter((l) => l.trim());
  if (lines.length > 3 && /^\d+\s*[│|]/.test(lines[1] || ""))
    return `${lines.length}`;
  return "";
}

/** 文本是否含 unified-diff 头行（--- file / +++ file / @@ hunk）。 */
function hasDiffHeader(line: string): boolean {
  return /^--- /.test(line) || /^\+\+\+ /.test(line) || /^@@ /.test(line);
}

/** 是否为真正的 unified diff：diff 头行出现在文本前部，
 *  且后文存在 + / - 改动行。普通命令/ls 输出不满足（无 @@ / ---++++ 头）。 */
function looksLikeUnifiedDiff(text: string): boolean {
  const lines = text.split("\n");
  const firstNonEmpty = lines.findIndex((l) => l.trim());
  if (firstNonEmpty === -1 || firstNonEmpty > 3) return false;
  const head = lines.slice(firstNonEmpty, firstNonEmpty + 4);
  if (!head.some(hasDiffHeader)) return false;
  return lines.some((l) => l.startsWith("+") || l.startsWith("-"));
}

// 统计统一 diff 里的 +N/−N：先验「这是 diff」，再逐行计数；
// 非 diff 文本（ls 结果、JSON、命令输出）返回 0/0 不出徽标。
function extractDiffStats(content: string): {
  added: number;
  removed: number;
} {
  if (!looksLikeUnifiedDiff(content)) return { added: 0, removed: 0 };
  let added = 0,
    removed = 0;
  for (const line of content.split("\n")) {
    if (line.startsWith("+") && !line.startsWith("+++")) added++;
    else if (line.startsWith("-") && !line.startsWith("---")) removed++;
  }
  return { added, removed };
}

// ── Content type detection ───────────────────────────────────────────────

type ResultKind = "diff" | "image" | "search" | "plain";

function detectResultKind(toolName: string, content: string): ResultKind {
  const name = (toolName || "").toLowerCase();

  // Diff detection
  if (
    name.includes("diff") ||
    name.includes("patch") ||
    name.includes("git_diff")
  )
    return "diff";
  // pi 的 edit 工具：真 diff 在 details.diff/patch（网关白名单外不带），
  // 拼在结果文本后段。必须按「真 diff 形态」验证再按 diff 着色——
  // 结果文本首行是 "Successfully replaced N block(s)"，若 edit 失败
  // 或输出被截断时按 diff 渲染会把普通文本行误染成 + 行。
  if (name === "edit" && looksLikeUnifiedDiff(content)) return "diff";
  // diff 头可能不在第一行（前面有 "Successfully replaced …" 一句），
  // 但必须满足「头行靠近开头 + 有 +/− 改动行」才算真 diff —— 普通命令输出
  // （ls、dir、JSON）里散落的 + 开头行不触发 diff 着色。
  if (looksLikeUnifiedDiff(content)) return "diff";
  if (
    content.startsWith(`${ANSI_ESCAPE}[`) &&
    /added|removed|modified/i.test(content)
  )
    return "diff";

  // Image detection
  if (/^data:image\//.test(content.trim())) return "image";
  if (/!\[.*?\]\(data:image\//.test(content)) return "image";

  // Search results (grep/glob/read_directory output with file:line patterns)
  if (
    name.includes("grep") ||
    name.includes("search") ||
    name.includes("list_directory")
  )
    return "search";
  if (/^\s*\d+\s*[│|]/.test(content) || /^[\w/.]+\.\w+:\d+/.test(content))
    return "search";

  // 工具输出一律按纯文本处理 —— 不解析 markdown（标题/表格/代码块原样显示）
  return "plain";
}

// ── Copy button ─────────────────────────────────────────────────────────

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* noop */
    }
  };
  return (
    <button
      onClick={handleCopy}
      className="p-0.5 rounded text-foreground/30 hover:text-foreground/60 hover:bg-muted/50 transition-colors"
      data-tip="复制"
    >
      {copied ? (
        <CheckCheck className="size-3 text-emerald-500" />
      ) : (
        <Copy className="size-3" />
      )}
    </button>
  );
}

// ── Result renderers ────────────────────────────────────────────────────

function ImageRenderer({ content }: { content: string }) {
  const [error, setError] = useState(false);
  if (error)
    return (
      <span className="text-[0.85em] text-muted-foreground">
        [图片加载失败]
      </span>
    );
  return (
    <div className="relative group/img">
      <img
        src={
          content.startsWith("data:")
            ? content
            : `data:image/png;base64,${content}`
        }
        alt="工具输出图片"
        className="max-w-xs max-h-48 rounded-md border border-border/30"
        onError={() => setError(true)}
      />
    </div>
  );
}

// ── Main component ──────────────────────────────────────────────────────
//
// ZCode-style flat layout: each tool call is its own card (icon + status +
// duration + action), expanded on click to reveal params / sub-steps / result.
// No whole-group collapse wrapper — a multi-tool turn reads as a flat stack.

// The tool's concrete action: the command/script for bash, the path for
// file tools, etc. — shown WITHOUT the Chinese action prefix.
export function toolActionText(step: ExecutionStep): string {
  // 非命令工具（GUI/浏览器/MCP 等）的参数经常把正文/代码/错误说明塞在 text/input
  // 里，直接拿它当标题会显示 "Clear the draft's responseBlocks" 这类内容。非命令
  // 工具只显示工具名，不拿参数当标题。
  const isCommandTool = /bash|terminal|shell|run|execute|command/i.test(
    step.toolName || "",
  );

  // 命令类工具优先取命令本体：extractToolPath 的 content 兜底正则会从
  // tool_output_delta 追加进来的输出文本里误抓"路径样"片段，把标题变成输出中
  // 的某个路径而非命令本身。
  if (isCommandTool) {
    const cmd = extractCommandSnippet(step.toolParams);
    if (cmd) {
      // 非命令工具（GUI/浏览器/MCP 等）的参数可能把错误文案放在 text/input 里，
      // 直接拿它当标题会变成 "指令完成 (gui.lock) prevented..."。明显是错误/拦截
      // 说明时不当作命令标题，回退到工具名。
      const looksLikeError =
        /^\(|prevented|failed|error|cannot|unable|permission|denied|timeout/i.test(
          cmd,
        );
      if (looksLikeError) return "";
      // bash/terminal：标题返回命令完整首行（不手动截断 50）——命令卡已不可
      // 展开、标题是唯一查看入口，截断太短会看不到命令本体；视觉过长由外层
      // CSS truncate 省略，完整命令放 title 悬停可见。
      return cmd.split("\n")[0];
    }
    return "";
  }

  const path = extractToolPath(step);
  if (path) return path;
  return "";
}

// Action verb shown before the concrete action, derived from the tool type:
// a command shows "执行", a search shows "搜索", a read shows "读取" — NOT a
// generic "执行中" that doesn't describe what the tool does.
export function toolVerb(toolName: string): string {
  const name = (toolName || "").toLowerCase();
  if (
    name.includes("grep") ||
    name.includes("search") ||
    name.includes("glob") ||
    name.includes("find")
  )
    return "搜索";
  if (
    name.includes("read") ||
    name.includes("view") ||
    name.includes("list") ||
    name.includes("directory")
  )
    return "读取";
  if (
    name.includes("write") ||
    name.includes("create") ||
    name.includes("edit") ||
    name.includes("patch")
  )
    return "写入";
  if (name.includes("fetch") || name.includes("web")) return "获取网页";
  if (name.includes("memory")) return "读取记忆";
  if (name.includes("git")) return "查看";
  // bash / terminal / run / execute / default
  return "执行";
}

// Pair tool_result / error steps with their preceding tool_call so the result
// renders inside that tool's card. An orphan result (no preceding call) becomes
// a standalone card.
function groupSteps(
  steps: ExecutionStep[],
): Array<{ call: ExecutionStep; results: ExecutionStep[] }> {
  const rows: Array<{ call: ExecutionStep; results: ExecutionStep[] }> = [];
  for (const s of steps) {
    if (s.type === "tool_call") {
      rows.push({ call: s, results: [] });
    } else if (rows.length > 0) {
      rows[rows.length - 1].results.push(s);
    } else {
      rows.push({ call: s, results: [] });
    }
  }
  return rows;
}

// 折叠摘要用：把一组 tool_group blocks 里所有 diff 结果的 +/- 行数汇总成
// 「+N −n」，供 ToolStreamFold 摘要行右侧展示（与工具卡标题同一套判据）。
export function summarizeGroupDiff(
  blocks: Array<{ type: string; steps?: ExecutionStep[] }>,
): { added: number; removed: number } {
  let added = 0;
  let removed = 0;
  for (const b of blocks) {
    if (b.type !== "tool_group" || !b.steps) continue;
    for (const { results } of groupSteps(b.steps)) {
      for (const r of results) {
        const raw = normalizeAcpContent(r.content || "");
        if (detectResultKind(r.toolName || "", raw) !== "diff") continue;
        const s = extractDiffStats(raw);
        added += s.added;
        removed += s.removed;
      }
    }
  }
  return { added, removed };
}

function ToolCard({
  step,
  results,
  isRunning,
}: {
  step: ExecutionStep;
  results: ExecutionStep[];
  isRunning: boolean;
}) {
  const [open, setOpen] = useState(false);
  const path = extractToolPath(step);
  const hasSubSteps = step.subSteps && step.subSteps.length > 0;
  const isCommandTool = /bash|terminal|shell|run|execute|command/i.test(
    step.toolName || "",
  );
  // 读文件类（read/read_file/list_directory…）**不支持展开**：标题/状态/错误外露即可，
  // 点击标题不再切换结果区、结果区也不渲染。
  const isReadTool = /read|view|list|directory/i.test(step.toolName || "");
  // 命令类 + 读文件类点击不展开（标题/状态/错误外露即可）；文件修改等其余工具保留展开。
  const canExpand = !isCommandTool && !isReadTool;
  // 紧凑工具：命令/搜索/罗列类工具，具体动作（命令/查询/路径）已经在标题里展示，
  // 参数区和结果区再平铺一遍纯属冗余。约定是"只显示标题/动作就够了"。
  const isCompactTool =
    isCommandTool || /grep|search|glob|list/i.test(step.toolName || "");
  const visibleParamEntries = isCompactTool
    ? []
    : step.toolParams
      ? Object.entries(step.toolParams).filter(
          ([, v]) => v !== null && v !== undefined && v !== "",
        )
      : [];
  const hasParams = !hasSubSteps && visibleParamEntries.length > 0;
  // 是否有可展开内容：参数 / 子步骤 / 结果 / 运行中实时输出。
  const hasExpandableContent =
    hasParams || hasSubSteps || results.length > 0 || !!step.content;
  // 点击标题是否切换结果区：读取类恒不切换（图片结果例外 —— 不展开就看不到图）。
  const hasImageResult = results.some(
    (r) => detectResultKind(r.toolName || "", r.content || "") === "image",
  );
  const expandable = hasExpandableContent && (!isReadTool || hasImageResult);
  const stepStatus =
    results.length > 0
      ? step.status === "failed"
        ? "failed"
        : "completed"
      : step.status ||
        (step.finishedAt
          ? "completed"
          : step.startedAt
            ? "running"
            : undefined);
  const running = stepStatus === "running" && isRunning;
  const failed = stepStatus === "failed";
  const action = toolActionText(step);
  // 动词固定不随状态变化("搜索/读取/执行"),完成态不再加"已"前缀——
  // 组折叠摘要已经表达完成语义,行内前缀"已/正在"切换只会让列宽抖动。
  const verb = toolVerb(step.toolName || "");
  const verbText = verb;
  // 完整标题（verb + action/label）：action 为空时回退到工具显示名。title 属性
  // 用于悬停查看全文——命令类标题可能被 CSS truncate 视觉截断。
  const titleLabel =
    action ||
    getToolDisplayLabel(
      step.toolName || "",
      step.toolKind,
      path,
      step.toolParams,
    );
  // 卡片首部文本（"输入"）：命令类 → `$ 命令`；其余工具 → 参数。与结果合并为同一张
  // 卡片，避免"参数卡 + 结果卡"分裂成两张。单参数且其值已作为标题展示（如 read/list
  // 的 path、grep 的 query）时不再重复，仅在输入尚未见于标题时才并入卡片首部。
  const headerText = (() => {
    if (isCommandTool) {
      const cmd = (extractCommandSnippet(step.toolParams) || "").trim();
      return cmd ? `$ ${cmd}` : "";
    }
    const entries = visibleParamEntries.filter(
      ([, v]) => !(typeof v === "string" && action && v === action),
    );
    if (entries.length === 0) return "";
    if (entries.length === 1) {
      const [, v] = entries[0];
      return typeof v === "string" ? v : JSON.stringify(v, null, 2);
    }
    return entries
      .map(([k, v]) => `${k}: ${typeof v === "string" ? v : JSON.stringify(v)}`)
      .join("\n");
  })();

  return (
    <div className="group">
      {/* Tool title row — click to expand/collapse.
          固定宽动词列 + 动作列:动词承担动作分类,动作列显示命令/路径/工具名。 */}
      <button
        type="button"
        onClick={() => {
          if (expandable) setOpen((prev) => !prev);
        }}
        className={`w-full flex items-center gap-1.5 text-left text-[0.9em] text-foreground/80 ${expandable ? "" : "cursor-default"}`}
      >
        {failed ? (
          <span className="tool-glyph tool-glyph-failed" aria-hidden>
            ✕
          </span>
        ) : (
          <span className={`tool-glyph${running ? " tool-glyph-running" : ""}`} aria-hidden>
            ⏺
          </span>
        )}
        <span
          className={`flex-1 min-w-0 truncate text-foreground/60 ${running ? "text-foreground/85" : ""}`}
        >
          {verbText} {titleLabel}
        </span>
        {step.duration_s != null && step.duration_s > 0 && (
          <span className="text-[0.72em] text-muted-foreground shrink-0">
            {formatDurationSeconds(step.duration_s)}
          </span>
        )}
        {(() => {
          const count = step.content
            ? extractResultCount(
                step.content,
                step.toolName || "",
                step.toolParams,
              )
            : "";
          return count ? (
            <span className="text-[0.72em] text-muted-foreground/50 shrink-0">
              {count}
            </span>
          ) : null;
        })()}
        {(() => {
          // 真正的统一 diff 在 tool_result 步骤（results[r].content），不在 tool_call
          // 的流式预览 step.content（那是进度叙述文本，无 +- 行）。从所有 diff 类结果里
          // 汇总 +N −n；结果里没有 diff 时再回退到 step.content（兼容个别把 diff 直接
          // 流进预览的工具）。
          let added = 0,
            removed = 0;
          for (const r of results) {
            const raw = normalizeAcpContent(r.content || "");
            if (detectResultKind(r.toolName || "", raw) !== "diff") continue;
            const s = extractDiffStats(raw);
            added += s.added;
            removed += s.removed;
          }
          if (added === 0 && removed === 0) {
            const fb = step.content ? extractDiffStats(step.content) : null;
            if (!fb || (fb.added === 0 && fb.removed === 0)) return null;
            return (
              <span className="text-[0.72em] shrink-0 flex items-center gap-1">
                {fb.added > 0 && (
                  <span className="text-emerald-500/70">+{fb.added}</span>
                )}
                {fb.removed > 0 && (
                  <span className="text-rose-500/70">−{fb.removed}</span>
                )}
              </span>
            );
          }
          return (
            <span className="text-[0.72em] shrink-0 flex items-center gap-1">
              {added > 0 && (
                <span className="text-emerald-500/70">+{added}</span>
              )}
              {removed > 0 && (
                <span className="text-rose-500/70">−{removed}</span>
              )}
            </span>
          );
        })()}
      </button>

      {/* 命令类不可展开：运行中的实时输出与失败错误直接外露在标题下，不依赖展开。 */}
      {!canExpand && running && step.content && (
        <div className="ml-1 mt-1 text-[0.85em] text-foreground/40 font-mono max-h-16 overflow-hidden leading-relaxed whitespace-pre-wrap break-all">
          {stripAnsi(step.content.slice(-200))}
        </div>
      )}
      {!canExpand && results.some((r) => r.type === "error") && (
        <div className="ml-1 mt-1 flex items-start gap-1">
          <div className="flex-1 min-w-0 text-[0.8em] text-red-500/80 font-mono whitespace-pre-wrap break-all leading-relaxed">
            {results
              .filter((r) => r.type === "error")
              .map((r) =>
                stripMktempNoise(
                  stripEmoji(normalizeAcpContent(r.content || "")),
                ),
              )
              .filter(Boolean)
              .join("\n")}
          </div>
        </div>
      )}

      {expandable && open && (
        <div className="tool-result-panel space-y-1.5">
          {/* Streaming output preview — shown while tool is running.
              tool.progress → tool_call_update(in_progress) → tool_output_delta 把
              实时输出追加到 step.content（agent-flow-panel），这里显示它的末尾。 */}
          {running && step.content && (
            <div className="text-[0.85em] text-foreground/40 font-mono max-h-16 overflow-hidden leading-relaxed whitespace-pre-wrap break-all">
              {stripAnsi(step.content.slice(-200))}
            </div>
          )}
          {/* Sub-agent sub-steps */}
          {hasSubSteps && (
            <div className="space-y-1">
              {(() => {
                const filtered = step.subSteps!.filter((sub) => sub.toolName !== "progress");
                const groups = groupSubSteps(filtered);
                return groups.map((g, gi) => {
                  const isRunning = g.status === "running";
                  const isFailed = g.status === "failed";
                  const label = g.count > 1 ? `${g.category} · ${g.count} 次` : g.category;
                  return (
                    <div key={gi} className="flex items-center gap-1.5 text-[0.85em]">
                      {isFailed ? (
                        <span className="tool-glyph tool-glyph-failed !text-[0.8em]" aria-hidden>✕</span>
                      ) : (
                        <span className={`tool-glyph !text-[0.8em]${isRunning ? " tool-glyph-running" : ""}`} aria-hidden>⏺</span>
                      )}
                      <span className={`${isRunning ? "text-foreground/70" : "text-foreground/50"}`}>
                        {label}
                      </span>
                      {isRunning ? (
                        <span className="text-[0.85em] text-primary/70 shrink-0 flowing-text">执行中</span>
                      ) : isFailed ? (
                        <span className="text-[0.85em] text-red-500/80 shrink-0">失败</span>
                      ) : (
                        <span className="text-[0.85em] text-emerald-500/70 shrink-0">✓</span>
                      )}
                    </div>
                  );
                });
              })()}
            </div>
          )}
          {/* 参数与结果合并成同一张卡片：参数作为首部"输入"行，结果紧随其后。
              外层 ⎿ 面板已带 bg-inset 底与折角线，内部只渲染一张代码卡。 */}
          {(headerText || results.length > 0) && (
            <div className="space-y-1.5 divide-y divide-border/20">
              {results.map((r, ri) => {
                if (r.type === "error") {
                  const errFiltered = stripMktempNoise(
                    stripEmoji(normalizeAcpContent(r.content || "")),
                  );
                  if (!errFiltered) return null;
                  return (
                    <div key={r.id} className="flex items-start gap-1 pt-1.5">
                      <div className="flex-1 min-w-0 text-[0.85em] text-red-500/80 font-mono whitespace-pre-wrap break-all leading-relaxed">
                        {errFiltered}
                      </div>
                      <CopyButton text={errFiltered} />
                    </div>
                  );
                }
                // 紧凑工具（搜索/罗列）只显示标题，正常结果不展开；
                // 命令类工具例外——展开后要能看到非 error 的运行结果。
                // Note: r.type is typed as ExecutionStep['type'] which doesn't include 'error',
                // but the runtime value might be 'error' from legacy code. Use type assertion.
                if (
                  (r.type as string) !== "error" &&
                  isCompactTool &&
                  !isCommandTool
                )
                  return null;
                const raw = stripMktempNoise(
                  stripEmoji(normalizeAcpContent(r.content || "")),
                );
                if (!raw) return null;
                const fullText = raw;
                const isImage =
                  detectResultKind(r.toolName || "", raw) === "image";

                // 图片结果不是代码块，保持原样渲染。
                if (isImage) {
                  return (
                    <div key={r.id} className="relative pt-1.5">
                      <div className="absolute top-2 right-2 z-10">
                        <CopyButton text={fullText} />
                      </div>
                      <ImageRenderer content={raw} />
                    </div>
                  );
                }

                // 其余结果（diff / plain 文本）统一走代码卡片：语法高亮 + 卡片外框。
                // 工具结果一律不折叠（collapsible=false）、且不渲染头部栏
                // （showHeader=false）——去掉顶部那条「语言标签 + 复制」灰底大边框，
                // 内容直接铺开；工具输出不是正文，无需收起。
                const resultLang =
                  detectResultKind(r.toolName || "", raw) === "diff"
                    ? "diff"
                    : "text";
                // 卡片首部（"输入"）：命令 → `$ 命令`，其余工具 → 参数行。与结果合并
                // 成同一张卡 —— 即"上面输入、下面输出"。只加在首个非 error 结果上；
                // diff 结果不加（首行前缀会破坏 DiffView 的逐行解析）。
                const firstResultIdx = results.findIndex(
                  (x) => (x.type as string) !== "error",
                );
                const withHeader =
                  headerText && resultLang === "text" && ri === firstResultIdx
                    ? `${headerText}\n\n`
                    : "";
                const codeText = withHeader + raw;
                const clamped =
                  codeText.length > TOOL_RESULT_CLAMP
                    ? codeText.slice(0, TOOL_RESULT_CLAMP) +
                      `\n\n… (${codeText.length - TOOL_RESULT_CLAMP} 字符已截断)`
                    : codeText;

                return (
                  <div key={r.id} className="pt-1.5">
                    <div className="helix-md">
                      <CodeCard
                        language={resultLang}
                        code={clamped}
                        showRunButton={false}
                        collapsible={false}
                        showHeader={false}
                        className="!leading-snug !my-0"
                      />
                    </div>
                  </div>
                );
              })}
              {/* 仅有"输入"、暂无结果（运行中）：把输入单独渲染成一张卡，
                  保持"始终一张卡"的视觉，避免空面板。命令类由上方实时输出预览覆盖。 */}
              {results.length === 0 && headerText && !isCommandTool && (
                <div className="pt-1.5">
                  <div className="helix-md">
                    <CodeCard
                      language="text"
                      code={headerText}
                      showRunButton={false}
                      showHeader={false}
                      collapsible={false}
                      className="!leading-snug !my-0"
                    />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export function InlineToolGroup({
  steps,
  isRunning,
  fontSize = 14,
}: {
  steps: ExecutionStep[];
  isRunning: boolean;
  fontSize?: number;
}) {
  const visible = steps ?? [];
  if (visible.length === 0) {
    // 防御：steps 为空的 tool_group 绝不能塌成零高度隐形间隙（否则两段文字之间
    // 看起来像被截断）。始终渲染一行可见占位，标明此处有工具执行，而不是留空白。
    return (
      <div className="my-2 flex items-center gap-1.5 text-[0.85em] text-muted-foreground/70 select-none">
        <span className="tool-glyph" aria-hidden>
          ⏺
        </span>
        <span>工具执行</span>
      </div>
    );
  }

  const rows = groupSteps(visible);

  return (
    <div className="my-2 space-y-1.5" style={{ fontSize }}>
      {rows.map(({ call, results }) => (
        <ToolCard
          key={call.id}
          step={call}
          results={results}
          isRunning={isRunning}
        />
      ))}
    </div>
  );
}

"use client";

import React, { useCallback, useEffect } from "react";
import { useHelixStore } from "@/stores/helix-store";

// Parse key string like "Ctrl+Shift+X" into a normalized format
function parseKeyString(keys: string[]): {
  ctrl: boolean;
  shift: boolean;
  alt: boolean;
  meta: boolean;
  key: string;
} {
  let ctrl = false,
    shift = false,
    alt = false,
    meta = false,
    key = "";
  for (const k of keys) {
    const lower = k.toLowerCase();
    if (lower === "ctrl" || lower === "control") ctrl = true;
    else if (lower === "shift") shift = true;
    else if (lower === "alt") alt = true;
    else if (lower === "meta" || lower === "cmd" || lower === "command")
      meta = true;
    else key = k.length === 1 ? k.toLowerCase() : k;
  }
  return { ctrl, shift, alt, meta, key };
}

function matchShortcut(e: KeyboardEvent, shortcutKeys: string[]): boolean {
  const parsed = parseKeyString(shortcutKeys);
  const isMod = e.ctrlKey || e.metaKey;

  // Check modifier keys
  if (parsed.ctrl !== isMod) return false;
  if (parsed.shift !== e.shiftKey) return false;
  if (parsed.alt !== e.altKey) return false;

  // Check main key
  if (!parsed.key) return false;
  const eventKey = e.key.length === 1 ? e.key.toLowerCase() : e.key;
  return eventKey === parsed.key.toLowerCase();
}

// Action handlers map
function createActionHandler(state: ReturnType<typeof useHelixStore.getState>) {
  return {
    // Panel toggles
    "toggle-command-palette": () => state.toggleCommandPalette(),

    "toggle-skill-panel": () => state.toggleSkillPanel(),
    "toggle-scheduled-tasks-panel": () => state.toggleScheduledTasksPanel(),
    "toggle-terminal": () => state.toggleTerminal(),
    "toggle-settings": () => state.toggleSettings(),
    "toggle-file-tree": () => {
      if (state.selectedWorkDir)
        state.toggleDirectoryProject(state.selectedWorkDir);
    },
    settings: () => state.toggleSettings(),
    "show-shortcuts": () => {},
    "command-palette": () => state.toggleCommandPalette(),

    // Chat
    "new-chat": () => state.clearChat(),
    "archive-chat": () => state.clearChat(),
    "rename-chat": () => {
      const sessionId = state.currentSessionId;
      if (sessionId)
        window.dispatchEvent(
          new CustomEvent("helix:rename-session", { detail: { sessionId } }),
        );
    },
    "search-chats": () => state.toggleSessionManager(),
    "prev-chat": () => state.toggleSessionManager(),
    "go-back": () => state.navigateHistory("back"),
    "go-forward": () => state.navigateHistory("forward"),

    // Tabs
    "prev-tab": () => {
      const tabs = state.openTabs;
      if (tabs.length > 1) {
        const idx = tabs.findIndex((t) => t.id === state.activeTabId);
        state.setActiveTab(tabs[(idx - 1 + tabs.length) % tabs.length].id);
      }
    },

    // Approve/decline
    "approve-request": () => {
      window.dispatchEvent(
        new CustomEvent("helix:approve-request", {
          detail: { approved: true },
        }),
      );
    },
    "decline-request": () => {
      window.dispatchEvent(
        new CustomEvent("helix:approve-request", {
          detail: { approved: false },
        }),
      );
    },

    // Navigation & misc
    "quick-chat": () => state.clearChat(),
    "search-chat": () =>
      window.dispatchEvent(new CustomEvent("helix:conversation-search")),
    "next-recent-chat": () => state.toggleSessionManager(),
    "prev-recent-chat": () => state.toggleSessionManager(),
    "open-review": () => state.toggleCommandPalette(),
    "force-reload": () => window.location.reload(),
    "new-window": () => window.open(window.location.href, "_blank"),
    "model-picker": () => state.toggleSettings("api"),

    // No-op for actions not yet implemented
    default: () => {},
  };
}

export function KeyboardShortcuts() {
  const storeState = useHelixStore();
  const {
    activeTabId,
    closeTab,
    openTabs,
    setActiveTab,
    markTabSaved,
    showToast,
    customShortcuts,
    toggleSessionManager,
    toggleSkillPanel,
    toggleScheduledTasksPanel,
  } = storeState;

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      const isMod = e.ctrlKey || e.metaKey;
      const target = e.target as HTMLElement;
      const isInputFocused =
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.isContentEditable;

      // Check custom shortcuts first (always active)
      for (const [id, shortcut] of Object.entries(customShortcuts)) {
        if (matchShortcut(e, shortcut.keys)) {
          e.preventDefault();
          // Dispatch action
          const action = shortcut.action;
          const handlerMap = createActionHandler(useHelixStore.getState());
          const handler =
            handlerMap[
              action as keyof ReturnType<typeof createActionHandler>
            ] || handlerMap["default"];
          handler();
          return;
        }
      }

      // Ctrl+Shift+P: Toggle skill panel
      if (isMod && e.shiftKey && e.key === "P") {
        e.preventDefault();
        toggleSkillPanel();
        return;
      }

      // Ctrl+Shift+T: Toggle scheduled tasks panel
      if (isMod && e.shiftKey && e.key === "T") {
        e.preventDefault();
        toggleScheduledTasksPanel();
        return;
      }

      // Skip remaining shortcuts if input is focused
      if (isInputFocused) return;

      // Ctrl+S: Save
      if (isMod && e.key === "s") {
        e.preventDefault();
        if (activeTabId) {
          markTabSaved(activeTabId);
          const state = useHelixStore.getState();
          const tab = state.openTabs.find((t) => t.id === activeTabId);
          if (tab) {
            state.addTerminalOutput(`\x1b[32m[保存] ${tab.name} 已保存\x1b[0m`);
          }
        }
        return;
      }

      // Ctrl+W: Close active tab
      if (isMod && e.key === "w") {
        e.preventDefault();
        if (activeTabId) closeTab(activeTabId);
        return;
      }

      // Ctrl+Shift+C: Copy file path
      if (isMod && e.shiftKey && e.key === "C") {
        e.preventDefault();
        const state = useHelixStore.getState();
        const tab = state.openTabs.find((t) => t.id === state.activeTabId);
        if (tab) {
          const path = state.getFilePath(tab.fileId);
          navigator.clipboard.writeText(path);
        }
        return;
      }

      // Ctrl+1 to Ctrl+9: Switch to tab N
      if (isMod && e.key >= "1" && e.key <= "9") {
        e.preventDefault();
        const num = parseInt(e.key);
        const state = useHelixStore.getState();
        if (num <= state.openTabs.length) {
          setActiveTab(state.openTabs[num - 1].id);
        }
        return;
      }

      // F2: Rename active file
      if (e.key === "F2") {
        e.preventDefault();
        const state = useHelixStore.getState();
        const tab = state.openTabs.find((t) => t.id === state.activeTabId);
        if (tab) {
          const newName = prompt("重命名文件：", tab.name);
          if (newName?.trim() && newName.trim() !== tab.name) {
            state.renameFile(tab.fileId, newName.trim());
          }
        }
        return;
      }

      // F12: Toggle DevTools
      if (e.key === "F12") {
        e.preventDefault();
        (window as any).electron?.window?.toggleDevTools();
        return;
      }

      // Delete: Delete selected file
      if (e.key === "Delete") {
        const state = useHelixStore.getState();
        if (state.selectedFileId) {
          const file = state.getFileById(state.selectedFileId);
          if (file && confirm(`确定要删除 ${file.name} 吗？`)) {
            state.deleteFile(state.selectedFileId);
          }
        }
        return;
      }
    },
    [
      activeTabId,
      closeTab,
      openTabs,
      setActiveTab,
      markTabSaved,
      showToast,
      customShortcuts,
      toggleSessionManager,
      toggleSkillPanel,
      toggleScheduledTasksPanel,
    ],
  );

  useEffect(() => {
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  return null;
}

"use client";

import {
  X,
  ChevronLeft,
  ChevronRight,
  RotateCw,
  ExternalLink,
  MousePointer2,
  Globe,
} from "lucide-react";
import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { isRealElectron } from "@/lib/electron-bridge";
import { cleanUrl } from "@/lib/url-utils";
import { useHelixStore } from "@/stores/helix-store";

// ---------------------------------------------------------------------------
// Suppress benign <webview> navigation-abort noise.
//
// When the Electron <webview> guest redirects, or a newer navigation supersedes
// an in-flight load, Chromium aborts the previous loadURL with ERR_ABORTED
// (-3). Electron surfaces this as a rejected `GUEST_VIEW_MANAGER_CALL` IPC which
// Next.js's dev overlay prints to the console as an "Unexpected error while
// loading URL" unhandled rejection. The page always finishes loading, so this
// is purely cosmetic — we swallow it globally here (registered once per module
// load, guarded so HMR re-imports don't stack listeners).
// ---------------------------------------------------------------------------
if (
  typeof window !== "undefined" &&
  !(window as any).__helixWebviewErrSuppressed
) {
  (window as any).__helixWebviewErrSuppressed = true;
  const isBenignNavError = (e: any): boolean => {
    const msg =
      e?.reason?.message || e?.message || String(e?.reason ?? e ?? "");
    return (
      msg.includes("GUEST_VIEW_MANAGER_CALL") ||
      msg.includes("ERR_ABORTED") ||
      msg.includes("(-3)")
    );
  };
  window.addEventListener("unhandledrejection", (e: any) => {
    if (isBenignNavError(e)) {
      e.preventDefault();
      e.stopImmediatePropagation?.();
    }
  });
  window.addEventListener("error", (e: any) => {
    if (isBenignNavError(e)) {
      e.preventDefault();
      e.stopImmediatePropagation?.();
    }
  });
}

/**
 * A single browser page rendered by RightSidebar. It shows one <webview>/<iframe>
 * for the given `url`, a navigation toolbar (back / forward / refresh), an
 * inline-editable address, and the imported bookmark bar.
 *
 * In Electron we use a real <webview> so sites that forbid iframing
 * (X-Frame-Options / CSP frame-ancestors) still render. Outside Electron we
 * fall back to a plain <iframe>.
 */

function cleanInput(raw: string): string {
  let t = raw.trim();
  const linkMatch = t.match(/^\[[^\]]*\]\(([^)]+)\)$/);
  if (linkMatch) t = linkMatch[1].trim();
  t = t.replace(/^<([^>]+)>$/, "$1");
  t = t.replace(/[*_`]/g, "");
  t = t.replace(/[.,;:!?。，；！？)…'"\]}»>]+$/, "");
  return t.trim();
}

function normalizeUrl(raw: string): string {
  const t = cleanInput(raw);
  if (!t) return "";
  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(t)) return t;
  if (
    t.startsWith("localhost") ||
    /^\d{1,3}(\.\d{1,3}){3}/.test(t) ||
    t.startsWith("[")
  )
    return `http://${t}`;
  return `https://${t}`;
}

export function summarizeUrl(url: string): string {
  if (!url) return "";
  try {
    const u = new URL(url);
    if (u.protocol === "file:") {
      const name = decodeURIComponent(u.pathname).split("/").pop();
      return name || url;
    }
    return u.hostname || url;
  } catch {
    return url;
  }
}

export function BrowserView({
  url,
  onUrlChange,
  onPageTitle,
}: {
  url: string;
  onUrlChange: (url: string) => void;
  onPageTitle?: (title: string) => void;
}) {
  const [loaded, setLoaded] = useState(cleanUrl(url));
  const loadedRef = useRef(loaded);
  loadedRef.current = loaded;
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const webviewRef = useRef<any>(null);
  const inElectron = isRealElectron();

  // Sync when the controlled `url` prop changes (external link / page switch).
  useEffect(() => {
    const u = cleanUrl(url);
    if (u !== loadedRef.current) setLoaded(u);
  }, [url]);

  const goBack = () => {
    try {
      webviewRef.current?.goBack?.();
    } catch { /* empty */}
  };
  const goForward = () => {
    try {
      webviewRef.current?.goForward?.();
    } catch { /* empty */}
  };
  const reload = () => {
    try {
      webviewRef.current?.reload?.();
    } catch { /* empty */}
  };

  const commitUrl = (raw?: string) => {
    const input = (raw ?? "").trim();
    const u = cleanUrl(normalizeUrl(input));
    if (!u) return;
    // 地址栏导航 → 必须退出选取模式（否则 iframe 仍停留在 srcdoc 渲染的
    // 选取页面，新链接不会加载，表现为"地址栏输入链接没反应"）
    exitPick();
    setLoaded(u);
    setError("");
    onUrlChange(u);
  };

  const [editingUrl, setEditingUrl] = useState(false);
  const [urlDraft, setUrlDraft] = useState("");
  const startUrlEdit = () => {
    exitPick();
    setUrlDraft(loaded);
    setEditingUrl(true);
  };
  const submitUrlEdit = () => {
    commitUrl(urlDraft);
    setEditingUrl(false);
  };
  const cancelUrlEdit = () => setEditingUrl(false);

  // ── "选取元素加入聊天" ─────────────────────────────────────────────────
  // 跨域 iframe 无法从父页面访问 DOM，所以进入选择模式时先用 Rust
  // page_fetch 拉取页面 HTML，用 <iframe srcdoc> 渲染（继承父 origin），
  // 注入选择脚本：hover 高亮、点击选取、parent.postMessage 回传元素信息。
  const [pickMode, setPickMode] = useState(false);
  const [pickSrcDoc, setPickSrcDoc] = useState<string | null>(null);
  const [pickError, setPickError] = useState("");
  const pickErrorTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [pickedCount, setPickedCount] = useState(0);
  const pickedCountRef = useRef(0);

  const exitPick = () => {
    setPickMode(false);
    setPickSrcDoc(null);
    setPickedCount(0);
    pickedCountRef.current = 0;
  };

  const enterPick = async () => {
    if (!loaded) return;
    setPickError("");
    setPickMode(true);
    try {
      const res = await (window as any).__TAURI_INTERNALS__?.invoke?.(
        "page_fetch",
        { url: loaded },
      );
      if (!res || typeof res.html !== "string") throw new Error("fetch failed");
      setPickSrcDoc(res.html);
    } catch (e: any) {
      exitPick();
      setPickError(`无法载入页面进行选取：${e?.message || e || "未知错误"}`);
      if (pickErrorTimer.current) clearTimeout(pickErrorTimer.current);
      pickErrorTimer.current = setTimeout(() => setPickError(""), 5000);
    }
  };

  // 接收选取结果 → 注入聊天输入框 → 退出选择模式
  useEffect(() => {
    const onMsg = (e: MessageEvent) => {
      const data = e?.data;
      if (!data || typeof data !== "object") return;
      if (data.type === "HELIX_PICKED") {
        const info = data.info || {};
        const text = String(info.text || "").trim();
        const link = String(info.href || info.src || "").trim();
        if (link) {
          // 链接不再以纯文本塞进输入框（多个会拥挤），改为底部"网页链接"卡片
          useHelixStore.getState().addLinkAttachment({
            id: `link-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            url: link,
            title: text.slice(0, 80) || "",
          });
          pickedCountRef.current += 1;
          const n = pickedCountRef.current;
          setPickedCount(n);
          useHelixStore.getState().showToast({
            type: "info",
            title: `已添加 ${n} 个网页链接`,
            duration: 1200,
          });
        }
      } else if (data.type === "HELIX_PICKED_CANCEL") {
        exitPick();
      }
    };
    window.addEventListener("message", onMsg);
    return () => window.removeEventListener("message", onMsg);
     
  }, [loaded]);

  // Esc 退出选择模式
  useEffect(() => {
    if (!pickMode) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") exitPick();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [pickMode]);

  return (
    <div className="flex-1 min-h-0 flex flex-col bg-card">
      {/* Navigation toolbar */}
      <div className="flex items-center gap-1 px-2.5 py-1.5 border-b border-border/20 shrink-0 bg-card">
        <button
          onClick={goBack}
          disabled={!inElectron}
          className="p-1 rounded text-foreground/60 hover:text-foreground hover:bg-accent/60 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
          data-tip="后退"
        >
          <ChevronLeft className="size-4" />
        </button>
        <button
          onClick={goForward}
          disabled={!inElectron}
          className="p-1 rounded text-foreground/60 hover:text-foreground hover:bg-accent/60 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
          data-tip="前进"
        >
          <ChevronRight className="size-4" />
        </button>
        <button
          onClick={reload}
          disabled={!inElectron}
          className="p-1 rounded text-foreground/60 hover:text-foreground hover:bg-accent/60 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
          data-tip="刷新"
        >
          <RotateCw className="size-3.5" />
        </button>
        <div className="flex-1 min-w-0 px-2">
          {editingUrl ? (
            <input
              autoFocus
              value={urlDraft}
              onChange={(e) => setUrlDraft(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") submitUrlEdit();
                if (e.key === "Escape") cancelUrlEdit();
              }}
              onBlur={submitUrlEdit}
              spellCheck={false}
              className="w-full px-2 py-1 text-[calc(var(--helix-transcript-size)*0.7857)] bg-muted/40 border border-border/50 rounded-md text-foreground outline-none text-center"
            />
          ) : (
            <button
              onClick={startUrlEdit}
              className="w-full flex items-center justify-center gap-1.5 px-2 py-1 text-[calc(var(--helix-transcript-size)*0.7857)] text-foreground/80 bg-muted/30 border border-border/40 rounded-md hover:bg-muted/50 hover:border-border/60 hover:text-foreground transition-colors"
              data-tip={loaded}
            >
              <Globe className="size-3 text-muted-foreground/70 shrink-0" />
              <span className="truncate">{summarizeUrl(loaded)}</span>
            </button>
          )}
        </div>
        {/* 选取元素加入聊天（放在地址栏右侧，远离刷新/后退，避免误触） */}
        <button
          onClick={() => {
            if (!loaded) {
              useHelixStore.getState().showToast({
                type: "info",
                title: "没有可选取的页面",
                description: "请先在地址栏输入网址，加载后再选取元素",
              });
              return;
            }
            pickMode ? exitPick() : enterPick();
          }}
          className={`p-1 rounded transition-colors ${pickMode ? "text-primary bg-primary/10" : "text-foreground/60 hover:text-foreground hover:bg-accent/60"}`}
          data-tip={loaded ? "选取网页元素加入聊天" : "请先打开网页再选取元素"}
        >
          <MousePointer2 className="size-3.5" />
        </button>
        <button
          onClick={() => {
            if (loaded) {
              import("@/lib/electron-bridge").then(({ electronShell }) => {
                electronShell.open(loaded);
              });
            }
          }}
          className="p-1 rounded text-foreground/60 hover:text-foreground hover:bg-accent/60 transition-colors"
          data-tip="在外部浏览器中打开"
        >
          <ExternalLink className="size-3.5" />
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 min-h-0 bg-card relative">
        {pickMode ? (
          <WebviewFrame
            url={url}
            active
            srcdoc={pickSrcDoc ?? undefined}
            pickMode
            onLoading={setLoading}
            onError={(e) => {
              setError(e);
              setLoading(false);
            }}
            onNavigate={(u) => {
              setLoaded(u);
            }}
            onWebviewRef={(el) => {
              webviewRef.current = el;
            }}
            onPageTitle={onPageTitle}
          />
        ) : url ? (
          <WebviewFrame
            url={url}
            active
            onLoading={setLoading}
            onError={(e) => {
              setError(e);
              setLoading(false);
            }}
            onNavigate={(u) => {
              setLoaded(u);
            }}
            onWebviewRef={(el) => {
              webviewRef.current = el;
            }}
            onPageTitle={onPageTitle}
          />
        ) : (
          <div className="absolute inset-0 flex items-center justify-center text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/40 pointer-events-none">
            点击消息中的链接以预览
          </div>
        )}
        {pickError && (
          <div className="absolute inset-x-0 top-0 z-10 px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.7857)] text-red-500 bg-red-50/90 border-b border-red-100">
            {pickError}
          </div>
        )}
        {loading && (
          <div className="absolute top-2 right-2 z-10 px-2 py-0.5 text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/70 bg-card/80 rounded pointer-events-none">
            加载中…
          </div>
        )}
        {error && (
          <div className="absolute inset-x-0 top-0 z-10 px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.7857)] text-red-500 bg-red-50/90 border-b border-red-100">
            {error}
          </div>
        )}
      </div>
    </div>
  );
}

/** A single webview/iframe frame + its lifecycle listeners and resize sizing. */
function WebviewFrame({
  url,
  active,
  srcdoc,
  pickMode,
  onLoading,
  onError,
  onNavigate,
  onWebviewRef,
  onPageTitle,
}: {
  url: string;
  active: boolean;
  srcdoc?: string;
  pickMode?: boolean;
  onLoading: (loading: boolean) => void;
  onError: (error: string) => void;
  onNavigate: (url: string) => void;
  onWebviewRef?: (el: any) => void;
  onPageTitle?: (title: string) => void;
}) {
  const webviewRef = useRef<any>(null);
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const inElectron = isRealElectron();
  // Freeze the INITIAL src to `about:blank` so the <webview> guest process is
  // created exactly once. We must NOT bind `src` to the live `url` — every
  // `src` change makes Electron call loadURL internally, whose ERR_ABORTED
  // rejection is an UN-catchable console error (the GUEST_VIEW_MANAGER_CALL
  // noise). All real navigations go through our own loadURL below, which
  // swallows ERR_ABORTED ourselves.
  const initialSrcRef = useRef<string>("about:blank");
  const urlRef = useRef(url);
  urlRef.current = url;
  // The last url we actually asked the guest to load. Prevents duplicate loads
  // (a duplicate loadURL is exactly what produces the benign ERR_ABORTED -3).
  const lastLoadedRef = useRef<string | null>(null);
  const [guestReady, setGuestReady] = useState(false);
  // Keep callbacks fresh without re-running the mount-once listener effect.
  const onLoadingRef = useRef(onLoading);
  const onErrorRef = useRef(onError);
  const onNavigateRef = useRef(onNavigate);
  const onPageTitleRef = useRef(onPageTitle);
  onLoadingRef.current = onLoading;
  onErrorRef.current = onError;
  onNavigateRef.current = onNavigate;
  onPageTitleRef.current = onPageTitle;
  const setWebviewRef = (el: any) => {
    webviewRef.current = el;
    onWebviewRef?.(el);
  };

  // Electron's <webview> doesn't reflow on container resize (known flex-parent
  // bug). Size it imperatively to the wrapper; ResizeObserver keeps it correct
  // (including when the frame becomes visible again after being hidden).
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap || typeof ResizeObserver === "undefined") return;
    const apply = () => {
      const rect = wrap.getBoundingClientRect();
      const wv = webviewRef.current;
      if (wv && rect.width > 0) {
        wv.style.width = `${rect.width}px`;
        wv.style.height = `${rect.height}px`;
      }
    };
    apply();
    const ro = new ResizeObserver(apply);
    ro.observe(wrap);
    return () => ro.disconnect();
  }, []);

  // Our own loadURL wrapper — the promise is ours, so we can swallow ERR_ABORTED.
  const doLoad = (target: string) => {
    if (!target || lastLoadedRef.current === target) return;
    const el = webviewRef.current;
    if (!el) return;
    lastLoadedRef.current = target;
    onLoadingRef.current(true);
    try {
      el.loadURL(target).catch((err: any) => {
        // ERR_ABORTED (-3): a newer navigation superseded this one (the site
        // redirected, a link was clicked, or a refresh interrupted an in-flight
        // load). Benign — the page always finishes loading. The error arrives
        // serialized across the GUEST_VIEW_MANAGER_CALL IPC, so the `code`
        // property is not always preserved; match on code OR message.
        const msg = err?.message || "";
        const benign =
          err?.code === "ERR_ABORTED" ||
          err?.errno === -3 ||
          msg.includes("ERR_ABORTED") ||
          msg.includes("(-3)");
        if (!benign) onErrorRef.current(err?.message || "页面加载失败");
        onLoadingRef.current(false);
      });
    } catch {
      onLoadingRef.current(false);
    }
  };

  // Lifecycle listeners (Electron <webview> only). Attached once on mount.
  useEffect(() => {
    if (!inElectron) return;
    const el = webviewRef.current;
    if (!el || typeof el.addEventListener !== "function") return;
    const onStart = () => onLoadingRef.current(true);
    const onStop = () => onLoadingRef.current(false);
    const onDomReady = () => {
      setGuestReady(true);
      doLoad(urlRef.current);
    };
    const onNav = (e: any) => {
      if (e?.url) onNavigateRef.current(e.url);
    };
    const onTitle = (e: any) => {
      if (e?.title) onPageTitleRef.current?.(e.title);
    };
    const onFail = (e: any) => {
      // ERR_ABORTED (-3) is a benign navigation supersede — never surface it.
      if (e?.errorCode && e.errorCode !== -3) {
        onErrorRef.current(e?.errorDescription || "页面加载失败");
        onLoadingRef.current(false);
      }
    };
    el.addEventListener("did-start-loading", onStart);
    el.addEventListener("did-stop-loading", onStop);
    el.addEventListener("dom-ready", onDomReady);
    el.addEventListener("did-navigate", onNav);
    el.addEventListener("page-title-updated", onTitle);
    el.addEventListener("did-fail-load", onFail);
    // If the guest is already live (dom-ready fired before React attached the
    // listener, e.g. after an HMR remount), load now — otherwise dom-ready will.
    try {
      if (
        typeof el.getWebContentsId === "function" &&
        el.getWebContentsId() != null
      )
        onDomReady();
    } catch {
      /* guest not ready yet; dom-ready will fire */
    }
    return () => {
      el.removeEventListener("did-start-loading", onStart);
      el.removeEventListener("did-stop-loading", onStop);
      el.removeEventListener("dom-ready", onDomReady);
      el.removeEventListener("did-navigate", onNav);
      el.removeEventListener("page-title-updated", onTitle);
      el.removeEventListener("did-fail-load", onFail);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Load whenever the controlled `url` prop changes (user input / external link).
  // Gated on guestReady so we never call loadURL before the guest exists.
  useEffect(() => {
    if (!inElectron || !guestReady) return;
    const el = webviewRef.current;
    if (!el || !url) return;
    doLoad(url);
  }, [url, guestReady, inElectron]);

  if (!url && !srcdoc) return null;

  return (
    <div ref={wrapRef} className={`absolute inset-0 ${active ? "" : "hidden"}`}>
      {inElectron ? (
        React.createElement(
          "webview",
          {
            ref: setWebviewRef,
            src: initialSrcRef.current,
            allowpopups: "true",
            className: "w-full h-full border-0",
          } as any,
          null,
        )
      ) : (
        <iframe
          ref={setWebviewRef as any}
          src={srcdoc ? undefined : url}
          srcDoc={srcdoc || undefined}
          onLoad={() => {
            // 选择模式：srcdoc iframe 继承父 origin，加载后注入选择脚本
            if (pickMode && srcdoc) {
              const doc = (webviewRef.current as any)?.contentDocument;
              if (doc) injectPickScript(doc);
            }
          }}
          className="w-full h-full border-0"
          sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
          data-tip="Preview"
        />
      )}
    </div>
  );
}

/** 在 srcdoc iframe 的 document 里注入元素选择脚本：hover 高亮、点击选取、
 *  结果通过 parent.postMessage 回传给宿主页面。 */
function injectPickScript(doc: Document) {
  try {
    // 防重复 append（父页面视角）。脚本内部的防重入用 __helixPickerListening。
    if ((doc.defaultView as any)?.__helixPickerInstalled) return;
    (doc.defaultView as any).__helixPickerInstalled = true;
    const script = doc.createElement("script");
    script.textContent = `
      (function() {
        // 注意：用独立的标志名 —— 父页面 injectPickScript 已设
        // __helixPickerInstalled（防重复 append），脚本内部若检查同一个标志
        // 会因已 true 而直接 return，事件监听器一个都不注册（hover 无高亮、
        // 点击无响应）。这里用 __helixPickerListening 区分。
        if (window.__helixPickerListening) return;
        window.__helixPickerListening = true;
        try { parent.postMessage({ type: 'HELIX_PICKER_READY' }, '*'); } catch (e) {}
        var current = null;
        document.addEventListener('mouseover', function(e) {
          var el = e.target;
          if (!el || el === current) return;
          if (current && current.style) current.style.outline = '';
          current = el;
          if (el.style) { el.style.outline = '2px solid #f59e0b'; el.style.outlineOffset = '-2px'; }
        }, true);
        document.addEventListener('click', function(e) {
          e.preventDefault(); e.stopPropagation();
          var el = e.target;
          if (!el) return;
          if (current && current.style) current.style.outline = '';
          var text = (el.innerText || el.textContent || '').trim().slice(0, 8000);
          var html = (el.outerHTML || '').slice(0, 20000);
          var href = '';
          var src = '';
          try {
            href = el.href || el.getAttribute('href') || '';
            src = el.src || el.getAttribute('src') || '';
          } catch (err) {}
          parent.postMessage({ type: 'HELIX_PICKED', info: {
            tag: (el.tagName || '').toLowerCase(),
            text: text,
            html: html,
            href: href,
            src: src,
            title: document.title || ''
          } }, '*');
        }, true);
        document.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') {
            if (current && current.style) current.style.outline = '';
            parent.postMessage({ type: 'HELIX_PICKED_CANCEL' }, '*');
          }
        }, true);
        document.body.style.cursor = 'crosshair';
      })();
    `;
    (doc.head || doc.documentElement).appendChild(script);
  } catch {
    /* cross-origin guard — picker just won't attach */
  }
}

"use client";

import { Globe, Plus, X, Maximize2, Minimize2, Terminal } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { AgentWorkPanel } from "./agent-work-panel";
import { CodeEditorPanel } from "./code-editor-panel";
import { DiffSidebarPanel } from "./diff-sidebar-panel";
import { MoreActionsMenu } from "./more-actions-menu";
import { BrowserView } from "./preview-rail";
import { cleanUrl } from "@/lib/url-utils";
import { summarizeUrl } from "@/lib/url-utils";
import { useHelixStore } from "@/stores/helix-store";

type PageKind = "browser" | "code" | "diff" | "agent";
interface PanelPage {
  id: string;
  kind: PageKind;
  url: string;
  title?: string;
}

// 挂在 globalThis 上：HMR 重新求值本模块时模块作用域的计数器会归零，
// 但 React Fast Refresh 保留 pages state（旧 id 还在），两者错位会让新页
// 拿到与旧页重复的 id → pages 里出现两条相同 id → isActive 同时命中两块
// → flex-1 平分高度 → 侧边栏上下分栏。挂 globalThis 后计数器跨 HMR 持久，
// id 不会再重复。
const newPageId = () => {
  const g = globalThis as unknown as { __helixPageSeq?: number };
  if (g.__helixPageSeq === undefined) g.__helixPageSeq = 0;
  return `pg-${++g.__helixPageSeq}`;
};

/**
 * Right-hand sidebar as a tabbed workspace. The single header tab strip holds:
 *  - browser pages  → one BrowserView (one URL) each
 *  - the diff page  → the git diff view
 *  - every open code file → its own tab (the in-editor per-file tab bar was
 *    removed to avoid a duplicate "file name" row; the editor just shows the
 *    active file now).
 * All tabs can be switched / closed independently; the "+" menu creates a new
 * page (browser / diff / terminal).
 */
export function RightSidebar() {
  const tab = useHelixStore((s) => s.rightSidebarTab);
  const setTab = useHelixStore((s) => s.setRightSidebarTab);
  const previewRailUrl = useHelixStore((s) => s.previewRailUrl);
  const codeFullscreen = useHelixStore((s) => s.codeFullscreen);
  const toggleCodeFullscreen = useHelixStore((s) => s.toggleCodeFullscreen);
  const toggleTerminal = useHelixStore((s) => s.toggleTerminal);
  const isTerminalOpen = useHelixStore((s) => s.isTerminalOpen);
  const editorTabs = useHelixStore((s) => s.editorTabs);
  const activeEditorTabId = useHelixStore((s) => s.activeEditorTabId);
  const activeAgentView = useHelixStore((s) => s.activeAgentView);

  const [pages, setPages] = useState<PanelPage[]>(() => {
    const start = cleanUrl(previewRailUrl ?? "") || "";
    if (tab === "diff") return [{ id: newPageId(), kind: "diff", url: "" }];
    if (tab === "agent") return [{ id: newPageId(), kind: "agent", url: "" }];
    if (tab === "browser")
      return [{ id: newPageId(), kind: "browser", url: start }];
    return [];
  });
  const [activePageId, setActivePageId] = useState<string>(
    () => pages[0]?.id ?? "",
  );

  // Ref to the whole sidebar.
  const sidebarRef = useRef<HTMLDivElement>(null);

  // "Fullscreen" (codeFullscreen, a global store flag) makes this panel fill the
  // MAIN area in the layout flow (handled by helix-layout): the LEFT sidebar
  // stays visible and the conversation card is hidden. Escape exits it. This is
  // a CSS layout expansion, NOT the OS Fullscreen API (which would hide the app
  // title bar and the Windows taskbar).
  useEffect(() => {
    if (!codeFullscreen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") toggleCodeFullscreen();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [codeFullscreen, toggleCodeFullscreen]);

  // "+" panel-switcher dropdown.
  const [plusMenuOpen, setPlusMenuOpen] = useState(false);
  const titlePlusRef = useRef<HTMLButtonElement>(null);
  const plusMenuRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!plusMenuOpen) return;
    const onDown = (e: MouseEvent) => {
      const target = e.target as Node;
      if (
        titlePlusRef.current?.contains(target) ||
        plusMenuRef.current?.contains(target)
      )
        return;
      setPlusMenuOpen(false);
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [plusMenuOpen]);

  const activePageIdRef = useRef(activePageId);
  activePageIdRef.current = activePageId;

  const pagesRef = useRef(pages);
  pagesRef.current = pages;

  // 待激活的浏览器页 id（navSeq effect 新建页面后写入，渲染后激活）。
  // 不能用 setState updater 内的局部变量同步读：React 的 updater 是异步
  // 执行的（渲染时才跑），updater 外读永远是 null → 新建的页面永远不会被
  // 激活 → 「关闭页签后立刻点链接没反应，等两秒再点才行」。
  const pendingActivateRef = useRef<string | null>(null);

  // Keep the active view in sync with the selected sidebar tab WITHOUT remounting
  // (the header "目录/更改/浏览器" menu just sets `rightSidebarTab`). This replaces
  // the old `key={rightSidebarTab}` remount that rebuilt the whole panel — and the
  // browser <webview> — on every tab switch (the white flash). Code is shown via
  // the editor's own tabs (editorTabs), so selecting "code" just reveals the code
  // view (activePageId = '' means "no browser/diff page active → show code").
  useEffect(() => {
    if (tab === "code") {
      activePageIdRef.current = "";
      setActivePageId("");
      return;
    }
    const kind =
      tab === "diff"
        ? "diff"
        : tab === "browser"
          ? "browser"
          : tab === "agent"
            ? "agent"
            : null;
    if (!kind) return;
    const existing = pagesRef.current.find((p) => p.kind === kind);
    if (existing) {
      // Update the ref synchronously so the previewRailUrl effect (which runs
      // right after this one in the same commit) navigates THIS page in place
      // instead of creating a second, duplicate browser tab.
      activePageIdRef.current = existing.id;
      setActivePageId(existing.id);
      return;
    }
    // browser 页不在这里新建：它的创建只由两条专用路径负责——链接点击走
    // navSeq effect（更新/新建）、「更多操作 → 浏览器」走 browserAddSeq effect
    // （多开新建）。若这里也新建，点「更多操作 → 浏览器」时 requestAddBrowserPage
    // 同批触发 tab effect + browserAddSeq effect，会各建一个 → 弹出两个浏览器。
    // 只激活已有页；diff 页仍由本 effect 新建（无其他创建入口）。
    if (kind === "browser") return;
    const np: PanelPage = { id: newPageId(), kind, url: "" };
    activePageIdRef.current = np.id;
    setPages((prev) => [...prev, np]);
    setActivePageId(np.id);
     
  }, [tab]);

  // External link (e.g. a message link click) → open / navigate a browser page.
  // Keyed off the monotonically increasing nav sequence (NOT the URL value), so
  // RE-clicking the same link still navigates: when the value is unchanged the
  // freshly-created blank page (from the tab effect) would otherwise be left
  // empty. seq 0 is the initial mount value — skipping it avoids hijacking other
  // tabs (e.g. the diff panel) with a stale previewRailUrl on first render.
  const previewRailNavSeq = useHelixStore((s) => s.previewRailNavSeq);
  useEffect(() => {
    if (previewRailNavSeq === 0) return;
    const url = cleanUrl(previewRailUrl ?? "");
    if (!url) return;
    // React 的 setState updater 在渲染阶段才执行，updater 内赋值的局部变量
    // 在 effect 同步代码里读不到 → 用 ref 记录待激活的 id，渲染后激活。
    // 点击链接时 tab effect 已先建了一个空 url 的 browser 页并同步更新了
    // activePageIdRef（同一渲染批内 effect 按声明顺序执行），这里更新它即可。
    // 当前激活的页不是 browser（diff / code / 无页）→ 新建一个 browser 页，
    // 这样「更多操作 → 浏览器」每次都能开新的浏览器标签（多开）。
    setPages((prev) => {
      const active = prev.find((p) => p.id === activePageIdRef.current);
      if (active?.kind === "browser") {
        if (active.url === url) return prev;
        return prev.map((p) => (p.id === active.id ? { ...p, url } : p));
      }
      const np = { id: newPageId(), kind: "browser" as const, url };
      pendingActivateRef.current = np.id;
      return [...prev, np];
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [previewRailNavSeq]);

  // 渲染后：navSeq effect 新建的浏览器页在这里激活（updater 已执行完，
  // pendingActivateRef 里有值）。不能在上面的 effect 里同步 setActivePageId
  // —— 那会读到 null。依赖 pages 而非 seq，确保新建的页面已进入 state。
  useEffect(() => {
    const id = pendingActivateRef.current;
    if (!id) return;
    pendingActivateRef.current = null;
    activePageIdRef.current = id;
    setActivePageId(id);
     
  }, [pages]);

  const updatePageUrl = (id: string, url: string) =>
    setPages((prev) => prev.map((p) => (p.id === id ? { ...p, url } : p)));

  const updatePageTitle = (id: string, title: string) =>
    setPages((prev) =>
      prev.map((p) =>
        p.id === id ? (p.title === title ? p : { ...p, title }) : p,
      ),
    );

  const closePage = (id: string) => {
    const idx = pages.findIndex((p) => p.id === id);
    if (idx === -1) return;
    const next = pages.filter((p) => p.id !== id);
    setPages(next);
    if (id === activePageId) {
      if (next.length > 0) {
        setActivePageId(next[Math.min(idx, next.length - 1)].id);
      } else {
        // No browser/diff pages left — fall back to the code view if any files
        // are open, otherwise clear the active selection (shell shows).
        setActivePageId("");
      }
    }
  };

  // Close one open file tab (from the header strip). Dirty tabs open the
  // unsaved-changes confirmation (handled inside CodeEditorPanel) instead of
  // closing immediately.
  const closeCodeTab = (id: string) => {
    const st = useHelixStore.getState();
    const tab = st.editorTabs.find((t) => t.id === id);
    if (tab?.dirty) {
      st.setPendingCloseId(id);
      return;
    }
    st.closeEditorTab(id);
  };

  // 「更多操作 / ＋ → 浏览器」：总是新建一个浏览器页（多开）。两个菜单都通过
  // store 的 requestAddBrowserPage 递增 browserAddSeq，这里统一监听信号新建。
  const browserAddSeq = useHelixStore((s) => s.browserAddSeq);
  useEffect(() => {
    if (browserAddSeq === 0) return;
    const np = { id: newPageId(), kind: "browser" as const, url: "" };
    setPages((prev) => [...prev, np]);
    activePageIdRef.current = np.id;
    setActivePageId(np.id);
     
  }, [browserAddSeq]);

  // Close the whole code view (empty-state "关闭编辑器" button).
  const closeCodeView = () => {
    useHelixStore.getState().closeAllEditorTabs();
    if (pages.length > 0) setActivePageId(pages[0].id);
    else doRetract();
  };

  // When the last open file is closed while a browser/diff page was the active
  // view, fall back to another page so we don't render a blank panel. (Retracting
  // the whole sidebar when everything is closed is handled separately below.)
  useEffect(() => {
    if (
      editorTabs.length === 0 &&
      pages.length > 0 &&
      !pages.some((p) => p.id === activePageId)
    ) {
      setActivePageId(pages[0].id);
    }
  }, [editorTabs.length, pages, activePageId]);

  // Track whether the panel has EVER shown content in this session. We use this
  // to distinguish "the user closed the last tab" (→ retract) from "the code view
  // was opened directly with no file yet" (→ keep open, show empty state).
  const everHadContentRef = useRef(false);
  useEffect(() => {
    if (pages.length > 0 || editorTabs.length > 0)
      everHadContentRef.current = true;
  }, [pages.length, editorTabs.length]);

  // Retract the sidebar when every tab is gone. The panel's visibility in the
  // layout is driven by `rightSidebarTab` (null → hidden). Closing the last
  // browser/diff page and/or the last open file must clear the selection so the
  // sidebar collapses instead of sitting open as a blank card.
  //
  // IMPORTANT: also exit fullscreen mode here. If codeFullscreen is still true
  // when we retract, BOTH the conversation card (hidden by codeFullscreen) AND
  // the right sidebar (hidden by rightSidebarTab=null) become invisible —
  // producing a blank screen where nothing renders at all.
  const doRetract = () => {
    setTab(null);
    if (codeFullscreen) toggleCodeFullscreen();
  };

  // 用 pagesRef / editorTabsRef 判断「是否还有页签」而不是 effect 闭包里的
  // pages/editorTabs：点击链接时会 setRightSidebarTab('browser') 与页面创建
  // 同时发生，同一渲染里 pages.length 还是 0 —— 用旧闭包值判断会让 doRetract
  // 误触发把 tab 收回 null，导致「第一次点链接没反应，第二次才跳转」。
  // pagesRef 每次渲染同步更新，effect 里读到的是最新值。
  const editorTabsRef = useRef(editorTabs);
  editorTabsRef.current = editorTabs;
  // 记录上一次的 tab 值：tab 刚从 null 变为非 null = 正在打开侧边栏（页面尚在
  // effect 中创建，pages 暂时为空）→ 绝不能 retract。只有 tab 保持非 null 且
  // 页签真的被关光时才收回。
  const prevTabRef = useRef(tab);
  useEffect(() => {
    const prevTab = prevTabRef.current;
    prevTabRef.current = tab;
    if (prevTab === null && tab !== null) return; // 正在打开侧边栏，跳过收回
    if (
      tab !== null &&
      everHadContentRef.current &&
      pagesRef.current.length === 0 &&
      editorTabsRef.current.length === 0
    ) {
      doRetract();
    }
  }, [tab, pages, editorTabs]);

  // The sidebar is always mounted (the parent toggles visibility via the `hidden`
  // class). Render a minimal shell when there are no pages AND no open files so
  // the component stays alive — but this early return MUST come AFTER every hook
  // above, otherwise the hooks defined below it would be skipped on the
  // empty-pages render, producing a different hook count than the non-empty
  // render ("Rendered fewer hooks than expected"). All hooks run on every render;
  // only the rendered output differs.
  if (pages.length === 0 && editorTabs.length === 0) {
    return <div ref={sidebarRef} className="h-full w-full bg-card" />;
  }

  // The header strip holds browser/diff pages PLUS every open code file.
  const stripPages = pages.filter((p) => p.kind !== "code");
  const codeViewActive = !pages.some((p) => p.id === activePageId);

  return (
    <div
      ref={sidebarRef}
      className="h-full w-full bg-card flex flex-col overflow-hidden"
    >
      {/* Unified tab strip: browser / diff pages AND every open file share ONE
          row (the editor's own per-file tab bar was removed so the file name is
          never shown twice). Tabs compress / truncate as more are added. */}
      {(stripPages.length > 0 || editorTabs.length > 0) && (
        <div className="flex items-end gap-0.5 px-1 mt-10 h-9 shrink-0 bg-card border-b border-border/40">
          {stripPages.map((p) => {
            const label =
              p.kind === "browser"
                ? p.title || summarizeUrl(p.url) || "网页"
                : p.kind === "agent"
                  ? activeAgentView?.name || "子 Agent"
                  : "更改";
            const active = p.id === activePageId;
            return (
              <div
                key={p.id}
                onClick={() => setActivePageId(p.id)}
                data-tip={label}
                className={`group relative flex items-center gap-1.5 pl-3 pr-4 py-1.5 flex-1 min-w-0 max-w-[200px] rounded-t-md overflow-hidden cursor-pointer text-[calc(var(--helix-transcript-size)*0.8571)] border-b-2 transition-colors ${active ? "bg-primary/10 border-primary text-foreground" : "bg-muted/40 border-transparent text-foreground/60 hover:bg-accent/50"}`}
              >
                {p.kind === "browser" && (
                  <Globe className="size-3.5 shrink-0 opacity-60" />
                )}
                <span className="flex-1 min-w-0 truncate">{label}</span>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    closePage(p.id);
                  }}
                  data-tip="关闭"
                  className={`absolute right-0.5 top-1/2 -translate-y-1/2 rounded p-0.5 transition-opacity ${active ? "opacity-60 hover:opacity-100 hover:text-destructive hover:bg-destructive/10" : "opacity-0 group-hover:opacity-60 hover:!opacity-100 hover:text-destructive hover:bg-destructive/10"}`}
                >
                  <X className="size-3" />
                </button>
              </div>
            );
          })}
          {editorTabs.map((t) => {
            const active = t.id === activeEditorTabId && codeViewActive;
            return (
              <div
                key={t.id}
                onClick={() => {
                  useHelixStore.getState().setActiveEditorTab(t.id);
                  setActivePageId("");
                }}
                data-tip={t.path}
                className={`group relative flex items-center gap-1.5 pl-3 pr-4 py-1.5 flex-1 min-w-0 max-w-[200px] rounded-t-md overflow-hidden cursor-pointer text-[calc(var(--helix-transcript-size)*0.8571)] border-b-2 transition-colors ${active ? "bg-primary/10 border-primary text-foreground" : "bg-muted/40 border-transparent text-foreground/60 hover:bg-accent/50"}`}
              >
                <span className="flex-1 min-w-0 truncate">{t.name}</span>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    closeCodeTab(t.id);
                  }}
                  data-tip="关闭"
                  className={`absolute right-0.5 top-1/2 -translate-y-1/2 rounded p-0.5 transition-opacity ${active ? "opacity-60 hover:opacity-100 hover:text-destructive hover:bg-destructive/10" : "opacity-0 group-hover:opacity-60 hover:!opacity-100 hover:text-destructive hover:bg-destructive/10"}`}
                >
                  <X className="size-3" />
                </button>
              </div>
            );
          })}
          <button
            ref={titlePlusRef}
            onClick={() => setPlusMenuOpen((v) => !v)}
            className="ml-0.5 mb-0.5 p-1.5 rounded text-foreground/50 hover:text-foreground hover:bg-accent/50 transition-colors shrink-0 self-end"
            data-tip="更多操作"
          >
            <Plus className="size-3.5" />
          </button>
          <button
            onClick={() => toggleCodeFullscreen()}
            className={`mb-0.5 p-1.5 rounded transition-colors shrink-0 self-end ${codeFullscreen ? "text-primary bg-primary/10" : "text-foreground/50 hover:text-foreground hover:bg-accent/50"}`}
            data-tip={codeFullscreen ? "退出全屏" : "展开全屏"}
          >
            {codeFullscreen ? (
              <Minimize2 className="size-3.5" />
            ) : (
              <Maximize2 className="size-3.5" />
            )}
          </button>
        </div>
      )}

      {/* Content: keep every page mounted (hidden if inactive) so switching tabs
          preserves each page's state — same as the old multi-tab browser. The
          file tree lives in the LEFT sidebar (full-area directory view); this
          panel shows the active browser/diff page, or the code editor when no
          browser/diff page is active.
          NOTE: inactive pages rely on `display:none`. We ALSO set it inline so a
          non-active page can never show even if the Tailwind `hidden` utility is
          missing/overridden in a given build — otherwise two stacked browser
          panels (the active one + a leftover blank one) can appear. */}
      {/* `min-w-0` on every flex link is load-bearing: without it a page's
          min-content (e.g. a long path row or the diff header's stats) makes the
          column lay out WIDER than the panel box, and the panel's
          `overflow-hidden` then silently cuts the right-hand side — which is
          where +/- counts live. */}
      <div className="flex-1 min-h-0 min-w-0 flex">
        <div className="flex-1 min-h-0 min-w-0 flex flex-col">
          {/* 用 findIndex 取“第一个”命中 activePageId 的下标：即使 pages 里
              出现两条相同 id（HMR 计数器错位的历史遗留），也只会有一块进
              active 分支，物理上不可能再上下分栏。 */}
          {(() => {
            const activeIdx = pages.findIndex((p) => p.id === activePageId);
            return pages.map((p, i) => {
              const isActive = i === activeIdx;
              return (
              <div
                key={p.id}
                className={
                  isActive ? "flex-1 min-h-0 min-w-0 flex flex-col" : "hidden"
                }
                style={isActive ? undefined : { display: "none" }}
              >
                {p.kind === "browser" && (
                  <BrowserView
                    url={p.url}
                    onUrlChange={(u) => updatePageUrl(p.id, u)}
                    onPageTitle={(t) => updatePageTitle(p.id, t)}
                  />
                )}
                {p.kind === "diff" && <DiffSidebarPanel />}
                {p.kind === "agent" && <AgentWorkPanel />}
              </div>
            );
            });
          })()}
          {editorTabs.length > 0 && codeViewActive && (
            <div className="flex-1 min-h-0 min-w-0 flex flex-col">
              <CodeEditorPanel onClose={closeCodeView} />
            </div>
          )}
        </div>
      </div>

      {plusMenuOpen &&
        typeof window !== "undefined" &&
        createPortal(
          <div
            className="fixed z-[200]"
            style={{
              top:
                (titlePlusRef.current?.getBoundingClientRect().bottom ?? 0) + 4,
              right:
                typeof window !== "undefined"
                  ? window.innerWidth -
                    (titlePlusRef.current?.getBoundingClientRect().right ?? 0)
                  : 0,
            }}
          >
            <div ref={plusMenuRef}>
              <MoreActionsMenu
                onToggleTab={(kind) => {
                  // 已打开的页签再次点击 → 只聚焦对应页，不关闭、不收起侧边栏
                  // （关闭走页签的 ✕）。尚未打开 → 打开。
                  if (tab === kind) {
                    const target = pagesRef.current.find(
                      (p) => p.kind === kind,
                    );
                    if (target) setActivePageId(target.id);
                  } else {
                    setTab(kind);
                  }
                  setPlusMenuOpen(false);
                }}
                onAddBrowser={() => {
                  useHelixStore.getState().requestAddBrowserPage();
                  setPlusMenuOpen(false);
                }}
              />
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

"use client";

import {
