    toggleScheduledTask,
    showToast,
    selectedWorkDir,
  } = useHelixStore();
  const [search, setSearch] = useState("");
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isAdding, setIsAdding] = useState(false);

  // Pull scheduled tasks from Helix backend on mount
  useEffect(() => {
    const load = async () => {
      try {
        const electron = (window as any).electron;
        if (!electron?.scheduledTasks?.list) return;
        const res = await electron.scheduledTasks.list();
        if (!res.ok || !Array.isArray(res.tasks)) return;
        const backendTasks = res.tasks as ScheduledTask[];
        useHelixStore.setState((state) => {
          const existingIds = new Set(state.scheduledTasks.map((t) => t.id));
          const merged = [...state.scheduledTasks];
          for (const task of backendTasks) {
            if (!existingIds.has(task.id)) {
              merged.push(task);
            } else {
              const idx = merged.findIndex((t) => t.id === task.id);
              if (idx >= 0) merged[idx] = { ...merged[idx], ...task };
            }
          }
          return { scheduledTasks: merged };
        });
      } catch (e) {
        console.error("Failed to load backend scheduled tasks:", e);
      }
    };
    load();
  }, []);

  const handleAdd = useCallback(
    async (label: string, prompt: string, schedule: string) => {
      const parsed = parseSchedule(schedule);
      const cronExpression = parsed.kind === "cron" ? parsed.expr : undefined;
      const nextRunAt = parsed.kind === "once" ? parsed.runAt : undefined;
      let backendId: string | undefined;
      let backendNextRun: number | null = parsed.nextRun;
      try {
        const electron = (window as any).electron;
        if (electron?.scheduledTasks?.create) {
          const res = await electron.scheduledTasks.create({
            name: label,
            prompt,
            scheduleText: schedule,
            cronExpression,
            nextRunAt,
          });
          if (res.ok && res.id) {
            backendId = res.id;
            if (res.nextRunAt) backendNextRun = res.nextRunAt;
          }
        }
      } catch (e) {
        console.error("Failed to create backend scheduled task:", e);
      }
      addScheduledTask({
        id: backendId,
        label,
        prompt,
        scheduleText: schedule,
        cronExpression,
        enabled: true,
        lastRunAt: null,
        nextRunAt: backendNextRun,
      });
      if (parsed.error) showToast({ type: "warning", title: parsed.error });
      setIsAdding(false);
    },
    [addScheduledTask, showToast],
  );

  const handleRunNow = useCallback(async (task: ScheduledTask) => {
    try {
      const { addChatMessage, updateScheduledTask, showToast } =
        useHelixStore.getState();
      const { helixSessionId } = useGatewayStore.getState();
      addChatMessage({
        role: "system",
        content: `[定时任务] ${task.label}: ${task.prompt}`,
      });
      if (helixSessionId) {
        try {
          await helixApi()!.send("session/prompt", {
            session_id: helixSessionId,
            prompt: [{ type: "text", text: task.prompt }],
          });
        } catch (e) {
          console.error("[ScheduledTask] Failed to dispatch to Helix:", e);
        }
      }
      updateScheduledTask(task.id, { lastRunAt: Date.now() });
      const parsed = parseSchedule(task.scheduleText);
      if (parsed.nextRun)
        updateScheduledTask(task.id, { nextRunAt: parsed.nextRun });
      showToast({ type: "info", title: `定时任务 "${task.label}" 已触发` });
    } catch (e) {
      console.error("Failed to run scheduled task:", e);
    }
  }, []);

  // Sync toggle/delete to Helix backend
  const handleToggle = useCallback(
    async (task: ScheduledTask) => {
      toggleScheduledTask(task.id);
      try {
        const electron = (window as any).electron;
        if (electron?.scheduledTasks?.update) {
          await electron.scheduledTasks.update({
            id: task.id,
            enabled: !task.enabled,
          });
        }
      } catch (e) {
        console.error("Failed to sync toggle to backend:", e);
      }
    },
    [toggleScheduledTask],
  );

  const handleDelete = useCallback(
    async (task: ScheduledTask) => {
      removeScheduledTask(task.id);
      try {
        const electron = (window as any).electron;
        if (electron?.scheduledTasks?.remove) {
          await electron.scheduledTasks.remove({ id: task.id });
        }
      } catch (e) {
        console.error("Failed to sync delete to backend:", e);
      }
    },
    [removeScheduledTask],
  );

  const handleToggleSelect = useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const handleDeleteSelected = useCallback(async () => {
    const electron = (window as any).electron;
    for (const id of selectedIds) {
      removeScheduledTask(id);
      try {
        if (electron?.scheduledTasks?.remove) {
          await electron.scheduledTasks.remove({ id });
        }
      } catch (e) {
        console.error("Failed to sync delete to backend:", e);
      }
    }
    setSelectedIds(new Set());
  }, [selectedIds, removeScheduledTask]);

  const filteredTasks = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return scheduledTasks;
    return scheduledTasks.filter(
      (t) =>
        t.label.toLowerCase().includes(q) ||
        t.prompt.toLowerCase().includes(q) ||
        t.scheduleText.toLowerCase().includes(q),
    );
  }, [scheduledTasks, search]);

  const enabledCount = useMemo(
    () => scheduledTasks.filter((t) => t.enabled).length,
    [scheduledTasks],
  );

  const handleSelectAll = useCallback(() => {
    if (selectedIds.size === filteredTasks.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredTasks.map((t) => t.id)));
    }
  }, [selectedIds.size, filteredTasks, filteredTasks.length]);

  return (
    <div className="h-full w-full flex flex-col bg-background">
      {/* Header — big title + add action, search below (same layout as the
          plugin center). 40px top padding clears the window controls. */}
      <div className="px-6 pt-10 pb-4 shrink-0 border-b border-border/40">
        <div className="flex items-center justify-between">
          <h1 className="ui-title font-semibold text-foreground tracking-tight">
            计划任务
          </h1>
          <button
            onClick={() => setIsAdding(true)}
            className="p-1.5 rounded hover:bg-accent/60 text-muted-foreground hover:text-foreground transition-colors"
            data-tip="添加计划"
          >
            <Plus className="size-4" />
          </button>
        </div>

        <div className="relative mt-3 flex justify-center">
          <Search className="absolute left-[calc(2.5%+12px)] top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="搜索计划任务"
            className="w-[95%] h-10 pl-10 pr-4 rounded-full border border-border/60 bg-background text-[length:var(--helix-transcript-size)] transition-all"
          />
        </div>
      </div>

      <ScrollArea className="flex-1">
        <div className="max-w-3xl mx-auto px-6 pt-4 pb-8">
          {/* Current section */}
          <div>
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <h2 className="text-[length:var(--helix-transcript-size)] font-semibold text-foreground">
                  当前
                </h2>
                {filteredTasks.length > 0 && (
                  <label className="flex items-center gap-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground cursor-pointer">
                    <input
                      type="checkbox"
                      checked={
                        selectedIds.size === filteredTasks.length &&
                        filteredTasks.length > 0
                      }
                      onChange={handleSelectAll}
                      className="size-3.5 rounded border-border/60 text-primary"
                    />
                    全选
                  </label>
                )}
              </div>
              <div className="flex items-center gap-2">
                {selectedIds.size > 0 && (
                  <button
                    onClick={handleDeleteSelected}
                    className="flex items-center gap-1 text-[calc(var(--helix-transcript-size)*0.8571)] text-red-500 hover:text-red-600 transition-colors"
                  >
                    <Trash2 className="size-3" />
                    删除 ({selectedIds.size})
                  </button>
                )}
                <span className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground">
                  {enabledCount} 运行中
                </span>
              </div>
            </div>

            <div className="space-y-2">
              {filteredTasks.length === 0 && !isAdding ? (
                <div className="text-center py-14">
                  <Clock className="size-10 text-muted-foreground/20 mx-auto mb-3" />
                  <p className="text-[length:var(--helix-transcript-size)] text-muted-foreground">
                    暂无定时任务
                  </p>
                  <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/60 mt-1">
                    添加定时任务，agent 将按时自动执行
                  </p>
                </div>
              ) : (
                <>
                  {filteredTasks.map((task) => (
                    <TaskItem
                      key={task.id}
                      task={task}
                      selectedWorkDir={selectedWorkDir}
                      onToggle={() => handleToggle(task)}
                      onDelete={() => handleDelete(task)}
                      onUpdate={(updates) =>
                        updateScheduledTask(task.id, updates)
                      }
                      onRunNow={() => handleRunNow(task)}
                      isSelected={selectedIds.has(task.id)}
                      onToggleSelect={() => handleToggleSelect(task.id)}
                    />
                  ))}
                  {isAdding && (
                    <AddTaskForm
                      onCancel={() => setIsAdding(false)}
                      onAdd={handleAdd}
                    />
                  )}
                </>
              )}
            </div>
          </div>
        </div>
      </ScrollArea>
    </div>
  );
}

﻿"use client";

import {
  FolderOpen,
  Trash2,
  Download,
  DownloadCloud,
  Upload,
  X,
  Bot,
  Loader2,
  Search,
  AlertTriangle,
} from "lucide-react";
import React, { useState, useEffect, useCallback, useRef } from "react";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { timeAgo } from "@/lib/format";
import { persistence, type PersistedSession } from "@/lib/persist";
import { useGatewayStore } from "@/stores/gateway-store";
import { useHelixStore } from "@/stores/helix-store";

export function SessionManager({ onClose }: { onClose: () => void }) {
  const [sessions, setSessions] = useState<PersistedSession[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<PersistedSession | null>(
    null,
  );
  const [exportMenuSession, setExportMenuSession] =
    useState<PersistedSession | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const loadSessions = useCallback(async () => {
    setLoading(true);
    try {
      const list = await persistence.loadSessions();
      setSessions(list.sort((a, b) => b.savedAt - a.savedAt));
    } catch (e) {
      console.error("Failed to load sessions:", e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadSessions();
  }, [loadSessions]);

  const handleConfirmDelete = async () => {
    if (!deleteTarget) return;
    try {
      await persistence.deleteSession(deleteTarget.id);
      setDeleteTarget(null);
      await loadSessions();
    } catch (e) {
      console.error("Failed to delete session:", e);
    }
  };

  const handleExportSession = async (
    session: PersistedSession,
    format: "json" | "markdown" = "json",
  ) => {
    try {
      let data: string;
      let ext: string;
      let mime: string;
      if (format === "markdown") {
        data = await persistence.exportSessionAsMarkdown(session);
        ext = "md";
        mime = "text/markdown";
      } else {
        data = await persistence.exportSessionAsJson(session);
        ext = "json";
        mime = "application/json";
      }
      const blob = new Blob([data], { type: mime });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `helix-session-${session.label || session.id}.${ext}`;
      a.click();
      URL.revokeObjectURL(url);
      useHelixStore
        .getState()
        .showToast({ type: "success", title: "导出成功" });
    } catch (e) {
      console.error("Export failed:", e);
      useHelixStore.getState().showToast({ type: "error", title: "导出失败" });
    }
  };

  const handleExportAll = async () => {
    try {
      const data = JSON.stringify(sessions, null, 2);
      const blob = new Blob([data], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `helix-sessions-all-${new Date().toISOString().slice(0, 10)}.json`;
      a.click();
      URL.revokeObjectURL(url);
      useHelixStore.getState().showToast({
        type: "success",
        title: `已导出 ${sessions.length} 个会话`,
      });
    } catch (e) {
      console.error("Export all failed:", e);
      useHelixStore
        .getState()
        .showToast({ type: "error", title: "批量导出失败" });
    }
  };

  const handleImportSession = async (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    let imported = 0;
    let failed = 0;
    for (const file of Array.from(files)) {
      try {
        const text = await file.text();
        if (file.name.endsWith(".md") || file.name.endsWith(".markdown")) {
          const session = await persistence.importSessionFromMarkdown(text);
          if (session) {
            imported++;
          } else {
            failed++;
          }
        } else {
          // JSON: 支持单会话包裹格式、裸单会话，以及「导出全部」裸数组 / {sessions:[...]}
          const data = JSON.parse(text);
          const arr = Array.isArray(data)
            ? data
            : data && Array.isArray((data as any).sessions)
              ? (data as any).sessions
              : null;
          if (arr && arr.length > 0) {
            for (const item of arr) {
              const wrapped =
                typeof item === "string"
                  ? item
                  : JSON.stringify({ type: "helix-session", session: item });
              const s = await persistence.importSessionFromJson(wrapped);
              if (s) {
                imported++;
              } else {
                failed++;
              }
            }
          } else {
            const jsonStr =
              data.type === "helix-session" ? text : JSON.stringify(data);
            const session = await persistence.importSessionFromJson(jsonStr);
            if (session) {
              imported++;
            } else {
              failed++;
            }
          }
        }
      } catch {
        failed++;
      }
    }
    await loadSessions();
    // 通知左侧边栏（sidebar）刷新：sidebar 监听 sessionSaveVersion，import 走 persist 直接写库、不经过 store action，需手动 bump
    useHelixStore.setState((st) => ({
      sessionSaveVersion: (st.sessionSaveVersion || 0) + 1,
    }));
    if (files.length === 1) {
      useHelixStore.getState().showToast({
        type: imported > 0 ? "success" : "error",
        title: imported > 0 ? "会话已导入" : "导入失败",
      });
    } else {
      useHelixStore.getState().showToast({
        type: imported > 0 ? "success" : "error",
        title: `导入完成：${imported} 成功，${failed} 失败`,
      });
    }
    e.target.value = "";
  };

  const handleOpenSession = useCallback(
    async (session: PersistedSession) => {
      try {
        const state = useHelixStore.getState();
        await state.flushSessionPersist();
        state.clearExecutionFlow();
        useGatewayStore.getState().setHelixSessionId(null);
        const all = await persistence.loadSessions();
        const fresh = all.find((s) => s.id === session.id) || session;
        // 丢弃 draft-partial 占位（同 sidebar/navigateSession）：并发下切换/打开
        // 会话不中断后台 run，占位消息不应展示（会与最终提交的完整回复重复）。
        const seen = new Set<string>();
        const msgs = fresh.chatMessages
          .filter((msg) => {
            if (seen.has(msg.id)) return false;
            seen.add(msg.id);
            if (
              typeof msg.id === "string" &&
              msg.id.startsWith("draft-partial-")
            )
              return false;
            return true;
          })
          .map((msg) => ({
            id: msg.id,
            role: msg.role as "user" | "assistant" | "system",
            content: msg.content,
            images: msg.images,
            timestamp: msg.timestamp,
            reasoning: msg.reasoning,
            steps: msg.steps,
            fileChanges: msg.fileChanges,
            blocks: msg.blocks,
          }));
        // 内存合并而非整体覆盖：done 提交 + persistSessionNow 是 fire-and-forget，
        // 磁盘快照可能落后几百 ms——整体替换会让"后台刚完成的回复"三处（内存/
        // draft/磁盘）同时缺席，切回来输出消失。以磁盘为基底，该会话仍在内存的
        // 消息按 id 覆盖（内存是 done 刚提交的新鲜副本）；其他会话的消息原样保留。
        const live = useHelixStore.getState().chatMessages;
        const byId = new Map<string, (typeof msgs)[number]>();
        for (const m of msgs) byId.set(m.id, m);
        for (const m of live) {
          if (!m.sessionId || m.sessionId !== session.id) continue;
          if (typeof m.id === "string" && m.id.startsWith("draft-partial-"))
            continue;
          byId.set(m.id, m as (typeof msgs)[number]);
        }
        const merged = [
          // 其他会话的消息不动（并发 run 的载体）
          ...live.filter((m) => m.sessionId && m.sessionId !== session.id),
          // 本会话：磁盘快照 + 内存覆盖，按时间排序
          ...[...byId.values()],
        ];
        merged.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));
        useHelixStore.setState({
          chatMessages: merged,
          activeSessionWorkDir: fresh.workDir ?? null,
        });
        // selectedWorkDir 同步到对话所属项目，让 Git 分支选择器等 UI 跟随对话。
        if (fresh.workDir) {
          useHelixStore.getState().setSelectedWorkDir(fresh.workDir);
        }
        useHelixStore.getState().setCurrentSessionId(session.id);
        await useHelixStore.getState().persistToStorage();
        onClose();
      } catch (e) {
        console.error("Failed to open session:", e);
        useHelixStore
          .getState()
          .showToast({ type: "error", title: "加载失败" });
      }
    },
    [onClose],
  );

  useEffect(() => {
    if (sessions.length > 0) {
      const t = setTimeout(() => searchInputRef.current?.focus(), 50);
      return () => clearTimeout(t);
    }
  }, [sessions.length]);

  const filteredSessions = sessions.filter((s) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    if (s.label?.toLowerCase().includes(q)) return true;
    const allText = s.chatMessages
      .map((m) => m.content)
      .join(" ")
      .toLowerCase();
    return allText.includes(q);
  });

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/60"
        onClick={onClose}
      />
      <div className="relative bg-card border border-border/60 rounded-2xl shadow-2xl w-full max-w-lg mx-4 max-h-[80vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border/60">
          <div className="flex items-center gap-2">
            <FolderOpen className="size-4 text-amber-400" />
            <h2 className="text-[length:var(--helix-transcript-size)] font-semibold">
              会话管理
            </h2>
            <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground bg-muted/50 px-1.5 py-0.5 rounded-full">
              {sessions.length} 个会话
            </span>
          </div>
          <div className="flex items-center gap-1">
            {sessions.length > 0 && (
              <button
                className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border border-border/50 text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/70 hover:bg-accent/50 cursor-pointer transition-colors h-7"
                onClick={handleExportAll}
              >
                <DownloadCloud className="size-3" />
                全部导出
              </button>
            )}
            <label className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border border-border/50 text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-foreground/70 hover:bg-accent/50 cursor-pointer transition-colors h-7">
              <Upload className="size-3" />
              导入
              <input
                type="file"
                accept=".json,.md,.markdown"
                multiple
                className="hidden"
                onChange={handleImportSession}
              />
            </label>
            <Button
              variant="ghost"
              size="icon"
              className="size-7"
              onClick={onClose}
            >
              <X className="size-4" />
            </Button>
          </div>
        </div>

        {/* Search */}
        {sessions.length > 0 && (
          <div className="px-5 py-2 border-b border-border/50">
            <div className="relative">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground" />
              <input
                ref={searchInputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="搜索会话（按名称或内容）..."
                className="w-full pl-8 pr-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] bg-muted/50 border border-border/50 rounded-lg"
              />
            </div>
          </div>
        )}

        {/* Session list */}
        <ScrollArea className="flex-1">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="size-5 animate-spin text-muted-foreground" />
            </div>
          ) : filteredSessions.length === 0 ? (
            <div className="px-5 py-12 text-center">
              <FolderOpen className="size-8 text-muted-foreground/20 mx-auto mb-3" />
              <p className="text-[length:var(--helix-transcript-size)] text-muted-foreground">
                {searchQuery ? "没有匹配的会话" : "暂无保存的会话"}
              </p>
            </div>
          ) : (
            <div className="p-2">
              {filteredSessions.map((session) => (
                <div
                  key={session.id}
                  onClick={() => handleOpenSession(session)}
                  className="group flex items-center gap-3 px-3 py-2.5 hover:bg-accent/30 rounded-xl transition-colors cursor-pointer"
                >
                  <div className="w-8 h-8 rounded-xl bg-amber-500/10 flex items-center justify-center shrink-0">
                    <Bot className="size-4 text-amber-400" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium truncate">
                      {session.label}
                    </p>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground">
                        {timeAgo(session.savedAt)}
                      </span>
                      <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/50">
                        {session.chatMessages.length} 条消息
                      </span>
                    </div>
                  </div>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="size-6 text-muted-foreground/70 hover:text-foreground transition-colors"
                    onClick={(e) => {
                      e.stopPropagation();
                      setExportMenuSession(
                        exportMenuSession?.id === session.id ? null : session,
                      );
                    }}
                    data-tip="导出"
                  >
                    <Download className="size-3" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="size-6 opacity-0 group-hover:opacity-100 transition-opacity"
                    onClick={(e) => {
                      e.stopPropagation();
                      setDeleteTarget(session);
                    }}
                    data-tip="删除"
                  >
