/**
 * 数字输入：内部维护字符串草稿，只在 blur / Enter 时提交，
 * 避免每敲一个字符就往后端 PUT 一次（也避免清空输入框瞬间被回填成 0）。
 * 与「记忆预算」等数字输入保持同一套样式（淡边框 + 淡背景）。
 */
export function NumberField({
  value,
  onCommit,
  min,
  max,
  suffix,
  disabled,
  small,
}: {
  value: number;
  onCommit: (v: number) => void;
  min: number;
  max: number;
  suffix?: string;
  disabled?: boolean;
  small?: boolean;
}) {
  const [draft, setDraft] = useState(String(value));
  useEffect(() => {
    setDraft(String(value));
  }, [value]);

  const commit = () => {
    const n = Number(draft);
    if (!Number.isFinite(n)) {
      setDraft(String(value));
      return;
    }
    const clamped = Math.min(max, Math.max(min, Math.round(n)));
    setDraft(String(clamped));
    if (clamped !== value) onCommit(clamped);
  };

  return (
    <div className="flex items-center gap-1.5">
      <input
        type="number"
        value={draft}
        disabled={disabled}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === "Enter") (e.target as HTMLInputElement).blur();
        }}
        className={`w-24 px-2 py-1 rounded-lg bg-muted/50 ${small ? "ui-text-sm2" : "ui-text"} text-foreground text-center border border-border disabled:cursor-not-allowed`}
      />
      {suffix && (
        <span className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/60 w-8">
          {suffix}
        </span>
      )}
    </div>
  );
}

export interface PopupSelectOption {
  label: string;
  value: string | number;
  hint?: string;
}

interface PopupSelectProps {
  value: string;
  onChange: (v: string) => void;
  options: PopupSelectOption[];
  placeholder?: string;
  className?: string;
  popupWidth?: number;
  disabled?: boolean;
}

/**
 * 下拉/弹层打开时锁定最近的背景滚动容器。弹层多为 position:fixed，背景滚动容器
 * （如设置内容卡片）滚动时触发器会移动而弹层留在视口原位，导致两者错位；锁住背景
 * 滚动并补偿滚动条宽度（隐藏滚动条后避免布局横向跳动），关闭时还原。
 */
export function useLockScrollOnOpen(
  open: boolean,
  btnRef: React.RefObject<HTMLElement | null>,
) {
  useEffect(() => {
    if (!open) return;
    let el: HTMLElement | null = btnRef.current;
    let scroller: HTMLElement | null = null;
    while (el && el !== document.body && el !== document.documentElement) {
      const s = getComputedStyle(el);
      if (
        s.overflowY === "auto" ||
        s.overflowY === "scroll" ||
        s.overflowY === "overlay"
      ) {
        scroller = el;
        break;
      }
      el = el.parentElement;
    }
    if (!scroller) return;
    const prevOverflow = scroller.style.overflowY;
    const prevPadR = scroller.style.paddingRight;
    const sbw = scroller.offsetWidth - scroller.clientWidth;
    if (sbw > 0) scroller.style.paddingRight = `${sbw}px`;
    scroller.style.overflowY = "hidden";
    return () => {
      if (!scroller) return;
      scroller.style.overflowY = prevOverflow;
      scroller.style.paddingRight = prevPadR;
    };
  }, [open, btnRef]);
}

/**
 * 自定义下拉选择。原生 `<select>` 的弹出列表在 WebKitGTK 下不可靠
 * （配色风格选择器因此改用 HTML 列表），这里做成通用组件：触发器 +
 * 固定定位的 HTML 弹出列表，点击外部 / Escape 关闭，选中项高亮打勾，
 * 展开样式与「配色风格」选择器保持一致。
 */
export function PopupSelect({
  value,
  onChange,
  options,
  placeholder = "请选择",
  className = "w-56",
  popupWidth = 224,
  disabled = false,
}: PopupSelectProps) {
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState<{
    left: number;
    top: number;
    width: number;
    maxHeight: number;
  } | null>(null);
  const btnRef = useRef<HTMLButtonElement>(null);
  const popRef = useRef<HTMLDivElement>(null);

  const current = options.find((o) => String(o.value) === value);
  const currentLabel = current?.label ?? placeholder;

  // 点击外部 / Escape 关闭。
  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (btnRef.current?.contains(e.target as Node)) return;
      if (popRef.current?.contains(e.target as Node)) return;
      setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        setOpen(false);
        (document.activeElement as HTMLElement)?.blur?.();
      }
    };
    const t = setTimeout(() => {
      document.addEventListener("mousedown", onDown);
      document.addEventListener("keydown", onKey);
    }, 0);
    return () => {
      clearTimeout(t);
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  // 锚定在触发器下方、右对齐；宽度与触发器一致。
  useEffect(() => {
    if (!open) return;
    const btn = btnRef.current;
    if (!btn) return;
    const r = btn.getBoundingClientRect();
    const w = r.width || popupWidth;
    // 向下展开时的可用空间（留 8px 底部边距）
    const downMaxH = Math.max(120, window.innerHeight - r.bottom - 8);
    setPos({
      left: r.right - w,
      top: r.bottom + 4,
      width: w,
      maxHeight: downMaxH,
    });
  }, [open, popupWidth]);

  useEffect(() => {
    if (!open || !pos || !popRef.current) return;
    const pr = popRef.current.getBoundingClientRect();
    let top = pos.top;
    let maxHeight = pos.maxHeight;
    // 弹窗底部超出视口 且 向下空间确实不够（<200px）→ 翻到触发器上方。
    // 动态 maxHeight 已限制弹窗高度，轻微超出（几像素舍入）不应触发翻转。
    const downSpaceTooSmall = pos.maxHeight < 200;
    if (
      pr.bottom > window.innerHeight - 8 &&
      downSpaceTooSmall &&
      btnRef.current
    ) {
      const br = btnRef.current.getBoundingClientRect();
      top = Math.max(8, br.top - pr.height - 4);
      // 向上展开时的可用空间（留 8px 顶部边距）
      maxHeight = Math.max(120, br.top - 8);
    }
    const left = Math.max(
      8,
      Math.min(pos.left, window.innerWidth - pr.width - 8),
    );
    popRef.current.style.top = `${top}px`;
    popRef.current.style.left = `${left}px`;
    popRef.current.style.maxHeight = `${maxHeight}px`;
    // 同步回 state 以防后续重渲染覆盖 inline style
    setPos((prev) => (prev ? { ...prev, top, maxHeight } : prev));
  }, [open, pos]);

  // 展开期间锁定背景滚动容器，避免 fixed 弹窗与触发器错位（见 useLockScrollOnOpen）。
  useLockScrollOnOpen(open, btnRef);

  return (
    <div className="relative">
      <button
        ref={btnRef}
        type="button"
        disabled={disabled}
        onClick={() => setOpen((v) => !v)}
        className={`${className} flex items-center justify-between gap-2 text-left disabled:opacity-50 disabled:cursor-not-allowed`}
      >
        <span className="truncate">{currentLabel}</span>
        <ChevronDown
          className={`size-3.5 shrink-0 text-muted-foreground/60 transition-transform ${open ? "rotate-180" : ""}`}
        />
      </button>

      {open && pos && (
        <div
          ref={popRef}
          className="fixed z-50 bg-popover border border-border rounded-xl shadow-xl py-1 overflow-y-auto overscroll-contain"
          style={{
            left: pos.left,
            top: pos.top,
            width: pos.width,
            maxHeight: pos.maxHeight,
          }}
        >
          {options.map((o) => {
            const selected = String(o.value) === value;
            return (
              <button
                key={String(o.value)}
                type="button"
                onClick={() => {
                  onChange(String(o.value));
                  setOpen(false);
                  btnRef.current?.focus({ preventScroll: true });
                }}
                className={`w-full flex items-center gap-2 px-3 py-1.5 ui-text-sm2 transition-colors text-left ${
                  selected
                    ? "bg-accent text-accent-foreground"
                    : "text-foreground hover:bg-accent/50"
                }`}
              >
                <span className="flex-1 min-w-0">
                  <span className="block truncate">{o.label}</span>
                  {o.hint && (
                    <span className="block text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/60 truncate">
                      {o.hint}
                    </span>
                  )}
                </span>
                {selected && <Check className="size-3.5 shrink-0" />}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * Syntax-highlighted code body — ported from the upstream agent
 * shiki-highlighter.tsx. Renders a fence's code through shiki's `codeToHtml`
 * with the official dual theme (`github-light-default` / `github-dark-dimmed`,
 * `defaultColor="light-dark()"` so the app's `.light`/`.dark` color-scheme
 * drives the palette). Falls back to plain preformatted text until the shiki
 * chunk loads, and skips highlighting entirely past the budget guard.
 *
 * shiki (grammars + themes) is the heaviest dependency in the renderer, so it
 * is dynamic-imported here on first highlighted block — never in the entry
 * chunk. The highlight HTML is built off-thread in the effect and injected
 * through `dangerouslySetInnerHTML`; no per-token React elements are needed.
 */

import { memo, useEffect, useState } from "react";

// GitHub's lower-contrast dark palette — the vivid `github-dark-default`
// tokens read harsh at small code size. Shared by the diff renderer. The
// light-mode comment remap bumps `#6e7781` (borderline unreadable for shell
// comments) to GitHub's darker muted gray `#57606a`. Keyed per theme so the
// bump only applies in light.
const SHIKI_THEMES = {
  dark: "github-dark-dimmed",
  light: "github-light-default",
} as const;
const SHIKI_COLOR_REPLACEMENTS: Record<string, Record<string, string>> = {
  "github-light-default": { "#6e7781": "#57606a" },
};

const MAX_HIGHLIGHT_CHARS = 150_000;
const MAX_HIGHLIGHT_LINES = 3_000;

export function exceedsHighlightBudget(code: string): boolean {
  if (code.length > MAX_HIGHLIGHT_CHARS) {
    return true;
  }

  let lines = 1;
  let index = code.indexOf("\n");

  while (index !== -1) {
    if ((lines += 1) > MAX_HIGHLIGHT_LINES) {
      return true;
    }

    index = code.indexOf("\n", index + 1);
  }

  return false;
}

type ShikiModule = typeof import("shiki");

let shikiPromise: Promise<ShikiModule> | null = null;

function loadShiki(): Promise<ShikiModule> {
  if (!shikiPromise) {
    shikiPromise = import("shiki");
  }

  return shikiPromise;
}

// ── Highlight cache ─────────────────────────────────────────────────────────
// Switching conversations remounts every message (new chatMessages objects
// defeat React.memo), which used to re-run shiki's codeToHtml for EVERY code
// block in the target conversation — the "切换对话卡顿" bottleneck. Cache the
// highlight result per (language, code) so a re-mount just reads the finished
// promise instead of re-highlighting. Values are promises so concurrent mounts
// of the same block share one highlight; bounded LRU-style so long sessions
// can't grow it without limit.
const HIGHLIGHT_CACHE_MAX = 200;
const highlightCache = new Map<string, Promise<string>>();

function cacheHighlight(key: string, p: Promise<string>): Promise<string> {
  highlightCache.delete(key); // refresh insertion order (LRU)
  highlightCache.set(key, p);
  if (highlightCache.size > HIGHLIGHT_CACHE_MAX) {
    const oldest = highlightCache.keys().next().value;
    if (oldest !== undefined && oldest !== key) highlightCache.delete(oldest);
  }
  return p;
}

/** Pull just the `<code>…</code>` token markup out of shiki's full `<pre>` output. */
function codeInnerHtml(html: string): string {
  const codeOpen = html.indexOf("<code");
  const codeStart = html.indexOf(">", codeOpen) + 1;
  const codeEnd = html.lastIndexOf("</code>");

  if (
    codeOpen === -1 ||
    codeStart === -1 ||
    codeEnd === -1 ||
    codeEnd < codeStart
  ) {
    return html;
  }

  return html.slice(codeStart, codeEnd);
}

interface HighlightedCodeProps {
  code: string;
  language: string;
}

export const HighlightedCode = memo(function HighlightedCode({
  code,
  language,
}: HighlightedCodeProps) {
  const [html, setHtml] = useState<string | null>(null);

  const trimmed = code.replace(/^\n+/, "").trimEnd();

  useEffect(() => {
    if (
      !trimmed ||
      !language ||
      language === "text" ||
      exceedsHighlightBudget(trimmed)
    ) {
      setHtml(null);

      return;
    }

    let cancelled = false;
    const key = `${language}\u0000${trimmed}`;
    const apply = (rendered: string) => {
      if (!cancelled) setHtml(codeInnerHtml(rendered));
    };
    const fail = () => {
      if (!cancelled) setHtml(null);
    };

    let highlight: Promise<string> | undefined = highlightCache.get(key);
    if (!highlight) {
      // Miss → run codeToHtml once, share the promise with any concurrent
      // mount of the same block, and drop the entry on failure so a later
      // mount can retry instead of pinning a dead promise.
      highlight = cacheHighlight(
        key,
        loadShiki().then((shiki) =>
          shiki.codeToHtml(trimmed, {
            lang: language,
            themes: SHIKI_THEMES,
            defaultColor: "light-dark()",
            colorReplacements: SHIKI_COLOR_REPLACEMENTS,
          }),
        ),
      );
      highlight.catch(() => {
        highlightCache.delete(key);
      });
    }
    highlight.then(apply).catch(fail);

    return () => {
      cancelled = true;
    };
  }, [language, trimmed]);

  if (html) {
    return (
      <code
        dir="ltr"
        className="block whitespace-pre-wrap break-words"
        dangerouslySetInnerHTML={{ __html: html }}
      />
    );
  }

  return (
    <code dir="ltr" className="block whitespace-pre-wrap break-words">
      {trimmed}
    </code>
  );
});

"use client";

import React, { useState, useCallback, useEffect, useRef } from "react";
import { useHelixStore, DEFAULT_SHORTCUTS } from "@/stores/helix-store";

export function ShortcutsPage() {
  const { customShortcuts, updateCustomShortcut, showToast } = useHelixStore();

  const shortcuts = Object.entries(customShortcuts);
  const defaultIds = Object.keys(DEFAULT_SHORTCUTS);
  const noopActions = new Set([
    "archive-chat",
    "rename-chat",
    "search-chats",
    "next-chat",
    "prev-chat",
  ]);
  const systemShortcuts = shortcuts
    .filter(([id]) => defaultIds.includes(id) && !noopActions.has(id))
    .filter(([, s]) => s.keys.length > 0);

  // Editing state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [recording, setRecording] = useState(false);
  const [pendingKeys, setPendingKeys] = useState<string[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const startRecording = (id: string) => {
    setEditingId(id);
    setPendingKeys(customShortcuts[id]?.keys || []);
    setRecording(true);
    setTimeout(() => inputRef.current?.focus(), 50);
  };

  const handleRecordKeyDown = useCallback((e: KeyboardEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const keys: string[] = [];
    if (e.ctrlKey) keys.push("Ctrl");
    if (e.shiftKey) keys.push("Shift");
    if (e.altKey) keys.push("Alt");
    if (e.metaKey) keys.push("Meta");
    const key = e.key.length === 1 ? e.key.toUpperCase() : e.key;
    if (!["Control", "Shift", "Alt", "Meta"].includes(key)) {
      keys.push(key);
    }
    if (keys.length > 0) {
      setPendingKeys(keys);
    }
  }, []);

  const confirmRecording = () => {
    if (editingId && pendingKeys.length > 0) {
      updateCustomShortcut(editingId, {
        ...customShortcuts[editingId],
        keys: pendingKeys,
      });
    }
    setRecording(false);
    setEditingId(null);
    setPendingKeys([]);
  };

  useEffect(() => {
    if (recording) {
      window.addEventListener("keydown", handleRecordKeyDown, {
        capture: true,
      });
      return () =>
        window.removeEventListener("keydown", handleRecordKeyDown, {
          capture: true,
        });
    }
  }, [recording, handleRecordKeyDown]);

  const cancelRecording = () => {
    setRecording(false);
    setEditingId(null);
    setPendingKeys([]);
  };

  return (
    <div className="space-y-6">
      {systemShortcuts.length > 0 && (
        <section className="space-y-3">
          <h3 className="ui-title font-semibold text-foreground">快捷键</h3>
          <div className="rounded-xl border border-border/50 bg-card/50 shadow-sm overflow-hidden">
            <div className="divide-y divide-border/50">
              {systemShortcuts.map(([id, s]) => (
                <div
                  key={id}
                  className="flex items-center px-4 py-2.5 hover:bg-accent/20 transition-colors group"
                >
                  <span className="ui-text font-medium text-foreground/80">
                    {s.description}
                  </span>
                  <span className="ml-auto ui-text font-mono text-foreground/80 bg-muted px-2.5 py-1 rounded shrink-0">
                    {s.keys.join(" + ")}
                  </span>
                  <button
                    onClick={() => startRecording(id)}
                    className="ml-3 px-1.5 py-1 rounded text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/20 hover:text-blue-500 opacity-0 group-hover:opacity-100 transition-all"
                    data-tip="编辑快捷键"
                  >
                    编辑
                  </button>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Recording overlay */}
      {recording && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="bg-card border border-border rounded-xl p-6 shadow-xl max-w-sm w-full">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-3 h-3 rounded-full bg-blue-500 animate-pulse" />
              <span className="ui-text font-medium text-foreground">
                正在录制快捷键
              </span>
            </div>
            <div className="flex items-center justify-center gap-2 py-4 bg-muted rounded-lg mb-4">
              <input
                ref={inputRef}
                type="text"
                readOnly
                value={pendingKeys.length > 0 ? pendingKeys.join(" + ") : ""}
                placeholder="按快捷键..."
                className="bg-transparent text-center text-[calc(var(--helix-transcript-size)*1.2857)] font-mono text-foreground/80 outline-none w-full"
              />
            </div>
            <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-foreground/40 text-center mb-3">
              按下新的按键组合，然后点击确定保存
            </p>
            <div className="flex gap-2">
              <button
                onClick={cancelRecording}
                className="flex-1 py-2 ui-text text-foreground/60 hover:text-foreground rounded-lg hover:bg-muted transition-colors"
              >
                取消
              </button>
              <button
                onClick={confirmRecording}
                disabled={pendingKeys.length === 0}
                className="flex-1 py-2 ui-text font-medium text-white bg-blue-500 hover:bg-blue-600 disabled:opacity-40 disabled:cursor-not-allowed rounded-lg transition-colors"
              >
                确定
              </button>
            </div>
          </div>
        </div>
      )}

      {shortcuts.length === 0 && (
        <p className="ui-text text-muted-foreground/50 text-center py-4">
          暂无快捷键
        </p>
      )}
    </div>
  );
}

﻿"use client";

import {
  X,
  Search,
  Trash2,
  Puzzle,
  Zap,
  FileText,
  Download,
  Loader2,
  Check,
  Wrench,
} from "lucide-react";
import React, {
  useState,
  useMemo,
  useEffect,
  useCallback,
  useRef,
} from "react";
import { ScrollArea } from "@/components/ui/scroll-area";
import { helixApi } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";

interface SkillPanelProps {}

interface InstalledItem {
  name: string;
  type: "extension" | "skill" | "prompt" | "tool" | "package";
  source: "pi" | "pi-rpc" | "pi-package" | "pi-npm" | "pi-tool" | "helix";
  description?: string;
  version?: string;
  path?: string;
  location?: string;
  /** npm: package id ("npm:<name>") for toggling via settings.json. */
  packageId?: string;
  /** Actual npm backend when a `-lite` wrapper is folded into its card. */
  packageName?: string;
  packagePath?: string;
  /** Whether the plugin's resources are currently loaded. */
  enabled?: boolean;
}

interface HelixSkill {
  id: string;
  name: string;
  description: string;
  isBuiltin: boolean;
  /** Where pi loads the skill from: "pi" (user root ~/.pi/agent/skills)
   * or the bundling npm package name. */
  source?: string;
  path: string;
  callCount: number;
}

interface PackageResult {
  name: string;
  description: string;
  version: string;
  type: "extension" | "skill" | "theme" | "prompt" | "package";
  author: string;
  npmUrl: string;
  installCmd: string;
  downloads: number;
  date: string;
}

type TabKey = "plugins" | "skills";

const typeLabels: Record<
  string,
  { label: string; color: string; icon: React.ReactNode }
> = {
  extension: {
    label: "扩展",
    color: "bg-violet-500/10 text-violet-500",
    icon: <Puzzle className="size-3" />,
  },
  skill: {
    label: "技能",
    color: "bg-emerald-500/10 text-emerald-500",
    icon: <Zap className="size-3" />,
  },
  prompt: {
    label: "提示模板",
    color: "bg-amber-500/10 text-amber-500",
    icon: <FileText className="size-3" />,
  },
  tool: {
    label: "工具",
    color: "bg-sky-500/10 text-sky-500",
    icon: <Wrench className="size-3" />,
  },
  package: {
    label: "包",
    color: "bg-blue-500/10 text-blue-500",
    icon: <Puzzle className="size-3" />,
  },
};

// eslint-disable-next-line no-empty-pattern
export function SkillPanel({}: SkillPanelProps) {
  const [activeTab, setActiveTab] = useState<TabKey>("plugins");
  const [searchQuery, setSearchQuery] = useState("");
  const [showBrowse, setShowBrowse] = useState(false);
  const [sortBy, setSortBy] = useState<"downloads" | "date">("downloads");
  const [filterType, setFilterType] = useState<string>("all");

  // Plugins state
  const [items, setItems] = useState<InstalledItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Browse state
  const [browseQuery, setBrowseQuery] = useState("");
  const [searchResults, setSearchResults] = useState<PackageResult[]>([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const [installing, setInstalling] = useState<string | null>(null);
  const searchTimerRef = useRef<ReturnType<typeof setTimeout>>(null);

  // Skills state
  const [skills, setSkills] = useState<HelixSkill[]>([]);
  const [skillsLoading, setSkillsLoading] = useState(false);

  // ── Plugins ──
  // 插件更新检查：piCheckUpdates 一次拿回全部 npm 插件的最新版本，
  // 有更新的卡片在开关右侧显示「更新」按钮。
  const [latestMap, setLatestMap] = useState<Record<string, string>>({});
  // 点击「更新」按钮后弹确认框：name → {installed, latest}
  const [updateFound, setUpdateFound] = useState<{
    name: string;
    installed: string;
    latest: string;
  } | null>(null);

  const loadItems = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const api = helixApi();
      if (!api?.piListInstalled) throw new Error("Pi 网关不可用");
      const res = await api.piListInstalled();
      const list: InstalledItem[] = Array.isArray(res?.items) ? res.items : [];
      const seen = new Set<string>();
      setItems(
        list.filter((item) => {
          const key = `${item.type}:${item.name}`;
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        }),
      );
      // 插件更新检查已禁用
      setLatestMap({});
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }, []);

  const doSearch = useCallback(async (query: string) => {
    if (!query.trim()) {
      setSearchResults([]);
      return;
    }
    setSearchLoading(true);
    try {
      const api = helixApi();
      if (!api?.piSearchPackages) return;
      // npm 搜索 API 将 "-" 视为分隔符，所以搜索 "lens" 不会匹配到 "pi-lens"。
      // 为了提高搜索结果的准确性，我们同时搜索原始查询和替换 "-" 为空格后的查询，
      // 然后合并结果并去重。
      const normalizedQuery = query.replace(/-/g, " ");
      const [res1, res2] = await Promise.all([
        api.piSearchPackages(query),
        normalizedQuery !== query
          ? api.piSearchPackages(normalizedQuery)
          : null,
      ]);
      const packages1 = Array.isArray(res1?.packages) ? res1.packages : [];
      const packages2 = Array.isArray(res2?.packages) ? res2.packages : [];
      const seen = new Set<string>();
      const merged: PackageResult[] = [];
      for (const pkg of [...packages1, ...packages2]) {
        if (!seen.has(pkg.name)) {
          seen.add(pkg.name);
          merged.push(pkg);
        }
      }
      setSearchResults(merged);
    } catch {
      setSearchResults([]);
    } finally {
      setSearchLoading(false);
    }
  }, []);

  const handleBrowseSearchChange = useCallback(
    (value: string) => {
      setBrowseQuery(value);
      if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
      searchTimerRef.current = setTimeout(() => void doSearch(value), 400);
    },
    [doSearch],
  );

  const handleInstall = useCallback(
    async (pkgName: string) => {
      setInstalling(pkgName);
      try {
        const api = helixApi();
        if (!api?.piInstallPackage) return;
        await api.piInstallPackage(pkgName);
        await loadItems();
      } catch (e) {
        setError(e instanceof Error ? e.message : String(e));
      } finally {
        setInstalling(null);
      }
    },
    [loadItems],
  );

  const handleUninstall = useCallback(
    async (item: InstalledItem) => {
      const pkgName = item.packageName ?? item.name;
      setInstalling(item.name);
      try {
        const api = helixApi();
        if (!api?.piUninstallPackage) return;
        await api.piUninstallPackage(pkgName);
        await loadItems();
      } catch (e) {
        setError(e instanceof Error ? e.message : String(e));
      } finally {
        setInstalling(null);
      }
    },
    [loadItems],
  );

  // 「更新」按钮确认后的实际更新：`pi install npm:<pkg>` 对已安装包就是升级
  // 到最新，复用 piInstallPackage。更新后 pi 会重新加载插件。
  const handleUpdatePlugin = useCallback(
    async (pkgName: string) => {
      setUpdateFound(null);
      setInstalling(pkgName);
      try {
        const api = helixApi();
        if (!api?.piInstallPackage) return;
        await api.piInstallPackage(pkgName);
        await loadItems();
      } catch (e) {
        setError(e instanceof Error ? e.message : String(e));
      } finally {
        setInstalling(null);
      }
    },
    [loadItems],
  );

  const isInstalled = useCallback(
    (pkgName: string) =>
      items.some((i) => i.name === pkgName || i.packageName === pkgName),
    [items],
  );

  // ── 启用/禁用插件 ──
  // 点击开关后写入 ~/.pi/agent/settings.json（后端负责重启网关生效）。
  // 支持两类插件：
  // - pi-npm：传 packageId（"npm:<name>"），由后端改 packages 列表；
  // - pi / pi-package（本地扩展）：传相对 agent 目录的路径 pattern
  //   （如 "extensions/foo.ts"），后端用 +/- 覆盖模式写 extensions 数组。
  const [togglingName, setTogglingName] = useState<string | null>(null);
  const toggleEnabled = useCallback(
    async (item: InstalledItem, next: boolean) => {
      // 计算传给后端的标识：优先 packageId，其次本地扩展的相对路径
      let identifier = item.packageId;
      if (!identifier) {
        if (item.source === "pi-npm") {
          identifier = `npm:${item.name}`;
        } else if (
          (item.source === "pi" || item.source === "pi-package") &&
          item.path
        ) {
          // 本地扩展 / 本地扩展包：转为 ~/.pi/agent 相对路径（posix 风格）。
          // 这些是自动发现的顶级资源，由 settings.json 的 extensions 数组
          // （+/- 覆盖模式）控制，而非 packages 列表。
          const marker = ".pi/agent/";
          const posix = item.path.replace(/\\/g, "/");
          const idx = posix.lastIndexOf(marker);
          if (idx !== -1) {
            identifier = posix.slice(idx + marker.length);
          }
        }
      }
      if (!identifier) return;

      setTogglingName(item.name);
      try {
        const api = helixApi();
        if (!api?.piSetPackageEnabled) {
          throw new Error("当前后端不支持插件启停");
        }
        // 乐观更新：先切状态，失败再回滚
        setItems((prev) =>
          prev.map((i) =>
            i.name === item.name && i.type === item.type
              ? { ...i, enabled: next }
              : i,
          ),
        );
        await api.piSetPackageEnabled(identifier, next);
        await loadItems();
      } catch (e) {
        // 回滚
        setItems((prev) =>
          prev.map((i) =>
            i.name === item.name && i.type === item.type
              ? { ...i, enabled: !next }
              : i,
          ),
        );
        const msg = e instanceof Error ? e.message : String(e);
        useHelixStore.getState().showToast({
          type: "error",
          title: next ? "启用失败" : "禁用失败",
          description: msg,
        });
      } finally {
        setTogglingName(null);
      }
    },
    [loadItems],
  );

  // ── Skills ──
  const loadSkills = async () => {
    setSkillsLoading(true);
    try {
      const list = await window.electron?.helixSkills.listSkills();
      if (Array.isArray(list)) setSkills(list);
    } catch (e) {
      console.error("loadSkills error:", e);
    }
    setSkillsLoading(false);
  };

  useEffect(() => {
    if (activeTab === "plugins") {
      void loadItems();
    } else {
      void loadSkills();
    }
  }, [activeTab, loadItems]);

  useEffect(() => {
    const handleFocus = () => {
      if (activeTab === "skills") void loadSkills();
    };
    window.addEventListener("focus", handleFocus);
    return () => window.removeEventListener("focus", handleFocus);
  }, [activeTab]);

  const onDeleteSkill = async (skill: HelixSkill) => {
    if (skill.isBuiltin) return;
    setSkillsLoading(true);
    try {
      await window.electron?.helixSkills.deleteDir(skill.path);
      await loadSkills();
    } catch (e) {
      console.error("deleteSkill error:", e);
    }
    setSkillsLoading(false);
  };

  // ── Filtered data ──
  const filteredItems = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    return items.filter((item) => {
      // Only extensions are listed here; skills, prompts and registerTool tools are hidden.
      if (item.type !== "extension") return false;
      if (!q) return true;
      return (
        item.name.toLowerCase().includes(q) ||
        (item.description || "").toLowerCase().includes(q)
      );
    });
  }, [items, searchQuery]);

  const filteredSkills = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    return skills.filter((s) => {
      if (!q) return true;
      return (
        s.name.toLowerCase().includes(q) ||
        (s.description || "").toLowerCase().includes(q)
      );
    });
  }, [skills, searchQuery]);

  const extensions = filteredItems.filter((i) => i.type === "extension");

  // ── Browse: filtered + sorted results ──
  const filteredResults = useMemo(() => {
    let list = [...searchResults];
    if (filterType !== "all") {
      list = list.filter((pkg) => pkg.type === filterType);
    }
    list.sort((a, b) => {
      if (sortBy === "downloads")
        return (b.downloads || 0) - (a.downloads || 0);
      if (sortBy === "date") return (b.date || "").localeCompare(a.date || "");
      return 0;
    });
    return list;
  }, [searchResults, filterType, sortBy]);

  // ── Render helpers ──
  const renderItem = (item: InstalledItem, idx: number) => {
    const meta = typeLabels[item.type] ?? typeLabels.extension;
    // 有可用更新的 npm 插件：在开关右侧显示「更新」按钮（打开确认弹窗）。
    const updateName = item.packageName ?? item.name;
    const latest = latestMap[updateName];
    const hasUpdate =
      item.source === "pi-npm" &&
      !!item.version &&
      !!latest &&
      latest !== item.version;
    // 启停开关：npm 包（pi-npm）与本地扩展（pi/pi-package）支持；
    // pi-rpc（提示模板）、helix 源与 tool（registerTool 静态声明）不支持——
    // 工具的开关等同于关闭宿主扩展本身。
    const canToggle =
      item.type === "extension" &&
      (item.source === "pi-npm" ||
        item.source === "pi-package" ||
        (item.source === "pi" && !!item.path));
    const isTool = item.type === "tool";
    const isEnabled = item.enabled !== false;
    const isToggling = togglingName === item.name;
    return (
      <div
        key={`${item.type}:${item.name}:${idx}`}
        className={`flex items-start gap-3 p-3 rounded-xl border border-border/50 bg-card/50 hover:bg-accent/30 transition-colors ${!isEnabled ? "opacity-50" : ""}`}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-[length:var(--helix-transcript-size)] font-medium text-foreground">
              {item.name}
            </span>
            {!isEnabled && (
              <span className="text-[calc(var(--helix-transcript-size)*0.7143)] px-1.5 py-0.5 rounded bg-muted/60 text-muted-foreground/70">
                已禁用
              </span>
            )}
          </div>
          {item.description && (
            <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/70 mt-0.5">
              {item.description}
            </p>
          )}
        </div>
        <div className="shrink-0 flex items-center gap-2">
          {hasUpdate && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                setUpdateFound({
                  name: updateName,
                  installed: item.version ?? "",
                  latest: latest!,
                });
              }}
              className="shrink-0 flex items-center gap-1 px-2 py-1 rounded-lg text-[calc(var(--helix-transcript-size)*0.7143)] text-primary bg-primary/10 hover:bg-primary/20 transition-colors"
              title={`更新至 v${latest}`}
            >
              <Download className="size-3.5" />
              更新
            </button>
          )}
          {canToggle && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                if (!isToggling) void toggleEnabled(item, !isEnabled);
              }}
              disabled={isToggling}
              className={`relative w-10 h-6 rounded-full transition-colors duration-200 ${
                isEnabled ? "bg-primary" : "bg-muted-foreground/20"
              } disabled:opacity-50`}
              title={isEnabled ? "点击禁用插件" : "点击启用插件"}
            >
              <span
                className={`absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow-sm transition-transform duration-200 ${
                  isEnabled ? "translate-x-4" : ""
                }`}
              />
            </button>
          )}
          {item.source !== "helix" &&
            !isTool &&
            item.type !== "skill" &&
            item.type !== "prompt" && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  void handleUninstall(item);
                }}
                disabled={installing === item.name}
                className="shrink-0 p-1.5 rounded text-muted-foreground/40 hover:text-red-500 hover:bg-red-500/10 transition-colors disabled:opacity-50"
                title="卸载"
              >
                {installing === item.name ? (
                  <Loader2 className="size-3.5 animate-spin" />
                ) : (
                  <Trash2 className="size-3.5" />
                )}
              </button>
            )}
        </div>
      </div>
    );
  };

  const renderSection = (
    title: string,
    sectionItems: InstalledItem[],
    icon: React.ReactNode,
  ) => {
    if (sectionItems.length === 0) return null;
    return (
      <div className="space-y-1.5">
        <div className="flex items-center gap-2 px-1 pb-1">
          {icon}
          <h3 className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium text-muted-foreground/70">
            {title}
          </h3>
          <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/40 font-mono">
            {sectionItems.length}
          </span>
        </div>
        {sectionItems.map((item, i) => renderItem(item, i))}
      </div>
    );
  };

  const renderPackageResult = (pkg: PackageResult) => {
    const installed = isInstalled(pkg.name);
    const pkgType = pkg.type || "package";
    const meta = typeLabels[pkgType] ?? typeLabels.extension;
    const formatDownloads = (n: number) => {
      if (n >= 1000000) return `${(n / 1000000).toFixed(1)}M`;
      if (n >= 1000) return `${(n / 1000).toFixed(1)}K`;
      return String(n);
    };
    const formatDate = (d: string) => {
      if (!d) return "";
      const date = new Date(d);
      const now = new Date();
      const diff = now.getTime() - date.getTime();
      const days = Math.floor(diff / (1000 * 60 * 60 * 24));
      if (days === 0) return "今天";
      if (days === 1) return "昨天";
      if (days < 7) return `${days}天前`;
      if (days < 30) return `${Math.floor(days / 7)}周前`;
      if (days < 365) return `${Math.floor(days / 30)}月前`;
      return `${Math.floor(days / 365)}年前`;
    };
    return (
      <div
        key={pkg.name}
        className="flex items-start gap-3 p-3 rounded-xl border border-border/50 bg-card/50 hover:bg-accent/30 transition-colors"
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-[length:var(--helix-transcript-size)] font-medium text-foreground">
              {pkg.name}
            </span>
            <span
              className={`text-[calc(var(--helix-transcript-size)*0.7143)] px-1.5 py-0.5 rounded ${meta.color}`}
            >
              {meta.label}
            </span>
            {pkg.version && (
              <span className="text-[calc(var(--helix-transcript-size)*0.7143)] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-mono">
                v{pkg.version}
              </span>
            )}
            {pkg.author && (
              <span className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/50">
                by {pkg.author}
              </span>
            )}
          </div>
          {pkg.description && (
            <p className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground/70 mt-0.5">
              {pkg.description}
            </p>
          )}
          <div className="flex items-center gap-3 mt-1">
            {pkg.downloads > 0 && (
