                </p>
              </div>
            </div>
            <div className="flex justify-between gap-2">
              <button
                onClick={() => void handleUpdatePlugin(updateFound.name)}
                disabled={installing === updateFound.name}
                className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.9286)] text-primary-foreground bg-primary hover:bg-primary/90 rounded-lg transition-colors disabled:opacity-50 flex items-center gap-1.5"
              >
                {installing === updateFound.name && (
                  <Loader2 className="size-3.5 animate-spin" />
                )}
                更新
              </button>
              <button
                onClick={() => setUpdateFound(null)}
                className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.9286)] text-foreground/70 hover:text-foreground hover:bg-accent rounded-lg transition-colors"
              >
                稍后再说
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { FitAddon } from "@xterm/addon-fit";
import { Terminal as XTerm } from "@xterm/xterm";
import { Plus, Terminal, X } from "lucide-react";
import React, { useState, useRef, useEffect, useCallback } from "react";
import { isElectron, electronTerminal, helixApi } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";
import "@xterm/xterm/css/xterm.css";

interface TerminalPanelProps {
  onClose: () => void;
}

/** Windows `std::fs::canonicalize` returns verbatim `\\?\`-prefixed paths; strip
 *  the namespace prefix so the terminal prompt / cd commands stay clean. */
function stripVerbatimPrefix(
  p: string | null | undefined,
): string | null | undefined {
  if (typeof p !== "string") return p;
  if (p.startsWith("\\\\?\\UNC\\")) return "\\\\" + p.slice(8);
  if (p.startsWith("\\\\?\\")) return p.slice(4);
  return p;
}

// ── No-project terminal default ────────────────────────────────────────────
// Fetched once from the backend (getSessionsDir → ~/.pi/agent/sessions),
// then "/default" is appended. This is the stable cwd for project-less chats.
let _noProjectDefaultDir: string | null = null;
async function getNoProjectDefaultDir(): Promise<string> {
  if (_noProjectDefaultDir) return _noProjectDefaultDir;
  try {
    const { electronApp } = await import("@/lib/electron-bridge");
    const { sessionsDir } = await electronApp.getSessionsDir();
    const dir = sessionsDir ? sessionsDir.replace(/[/\\]$/, "") + "/default" : "";
    if (dir) _noProjectDefaultDir = dir;
    return dir;
  } catch {
    return "C:\\Users\\hyt\\.pi\\agent\\sessions\\default";
  }
}
const LIGHT_THEME = {
  background: "#ffffff",
  foreground: "#333333",
  cursor: "#333333",
  cursorAccent: "#ffffff",
  selectionBackground: "#cfe3ff",
  black: "#000000",
  red: "#cd3131",
  green: "#0dbc79",
  yellow: "#8a8a8a",
  blue: "#2472c8",
  magenta: "#bc3fbc",
  cyan: "#11a8cd",
  white: "#e5e5e5",
  brightBlack: "#666666",
  brightRed: "#f14c4c",
  brightGreen: "#23d18b",
  brightYellow: "#9a9a9a",
  brightBlue: "#3b8eea",
  brightMagenta: "#d670d6",
  brightCyan: "#29b8db",
  brightWhite: "#ffffff",
};

// Transparent theme — blends with the app background
const TRANSPARENT_THEME = {
  background: "rgba(255,255,255,0.7)",
  foreground: "#333333",
  cursor: "#333333",
  cursorAccent: "rgba(255,255,255,0.7)",
  selectionBackground: "rgba(147,197,253,0.4)",
  black: "#000000",
  red: "#cd3131",
  green: "#0dbc79",
  yellow: "#8a8a8a",
  blue: "#2472c8",
  magenta: "#bc3fbc",
  cyan: "#11a8cd",
  white: "#e5e5e5",
  brightBlack: "#666666",
  brightRed: "#f14c4c",
  brightGreen: "#23d18b",
  brightYellow: "#9a9a9a",
  brightBlue: "#3b8eea",
  brightMagenta: "#d670d6",
  brightCyan: "#29b8db",
  brightWhite: "#ffffff",
};

interface TerminalTabViewProps {
  id: number;
  isActive: boolean;
}

/**
 * One terminal tab. Kept mounted permanently (like the old single-terminal
 * panel) so each tab keeps its full scrollback and live shell across
 * conversation switches and tab switches. The PTY is only spawned once the tab
 * first becomes visible, and is killed when the tab is closed.
 */
function TerminalTabView({ id, isActive }: TerminalTabViewProps) {
  const { activeSessionWorkDir, isTerminalOpen } =
    useHelixStore();
  // No-project conversations pin to ~/.pi/agent/sessions/default — resolved
  // asynchronously from the backend; falls back to null until loaded.
  const [noProjectDefaultDir, setNoProjectDefaultDir] = useState<string | null>(null);
  useEffect(() => {
    let cancelled = false;
    getNoProjectDefaultDir().then((d) => {
      if (!cancelled && d) setNoProjectDefaultDir(d);
    });
    return () => { cancelled = true; };
  }, []);
  const terminalCwd = activeSessionWorkDir ?? noProjectDefaultDir;
  const [electronReady, setElectronReady] = useState(false);
  const [terminalError, setTerminalError] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);
  const termRef = useRef<XTerm | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const bufferRef = useRef("");
  const lastCwdRef = useRef<string | null>(null);
  const startedRef = useRef(false);

  // Create the xterm instance exactly once. The PTY itself is started lazily
  // when the tab first becomes active (hidden tabs have a 0-size container).
  useEffect(() => {
    if (!isElectron()) {
      setElectronReady(false);
      return;
    }
    setElectronReady(true);

    const term = new XTerm({
      fontFamily:
        'Consolas, "Cascadia Code", "Microsoft YaHei Mono", monospace',
      fontSize: 13,
      cursorBlink: true,
      theme: TRANSPARENT_THEME,
      scrollback: 5000,
    });
    const fitAddon = new FitAddon();
    term.loadAddon(fitAddon);
    term.open(containerRef.current!);
    termRef.current = term;
    fitRef.current = fitAddon;

    const fitAndResize = () => {
      if (!isActive) return;
      try {
        fitAddon.fit();
        electronTerminal.resize(id, term.cols, term.rows);
      } catch {
        /* element not laid out yet */
      }
    };

    // Restore previous session output if we switched away and came back.
    if (bufferRef.current) {
      try {
        term.write(bufferRef.current);
      } catch {
        /* ignore */
      }
    }

    // ── Paste de-dup gate ────────────────────────────────────────────────
    // Electron fires paste through SEVERAL channels at once for a single Ctrl+V:
    //   1) xterm's own textarea paste listener (→ term.onData),
    //   2) the native `paste` ClipboardEvent on the container,
    //   3) Electron's insertText injection (also → term.onData),
    //   4) our Ctrl+V handler reading the clipboard.
    // All of (1)(3) funnel through term.onData, which writes RAW keystrokes too —
    // so we can't just gate onData. Instead: gate EVERY multi-char write that
    // reaches the PTY within a short window. A real keystroke is 1-2 chars; a
    // paste is a burst of the SAME text from multiple channels near-simultaneously.
    // We collapse identical bursts within 250ms into ONE PTY write.
    let lastPasteText = "";
    let lastPasteAt = 0;
    let editingLine = "";
    let lastWriteWasEnter = false;
    const PASTE_DEDUP_MS = 250;
    const writePty = (d: string) => {
      electronTerminal.write(id, d);
    };
    const erasePreviousChar = () => {
      term.write("\b \b");
    };
    const writePasteOnce = (text: string) => {
      if (!text) return;
      const now = Date.now();
      if (text === lastPasteText && now - lastPasteAt < PASTE_DEDUP_MS) return;
      lastPasteText = text;
      lastPasteAt = now;
      editingLine += text;
      writePty(text);
    };
    // A multi-char burst arriving via onData that duplicates a just-handled paste
    // (xterm's own paste listener / Electron insertText) is swallowed; genuine
    // typed input (1-2 chars, or different text) passes straight through.
    const isDupPasteBurst = (d: string) => {
      if (d.length < 2) return false;
      const now = Date.now();
      if (d === lastPasteText && now - lastPasteAt < PASTE_DEDUP_MS)
        return true;
      // Record multi-char bursts so a subsequent channel for the SAME burst dedups.
      if (now - lastPasteAt < PASTE_DEDUP_MS) return d === lastPasteText;
      lastPasteText = d;
      lastPasteAt = now;
      return false;
    };

    // Forward raw keystrokes from xterm to the PTY (native line editing).
    // xterm owns keystrokes here; paste is handled separately below so it is
    // never double-fed into the PTY.
    term.onData((d) => {
      if (isDupPasteBurst(d)) return;
      if (d === "\r") {
        writePty(d);
        editingLine = "";
        lastWriteWasEnter = true;
        return;
      }
      if (d === "\u007f" || d === "\b") {
        if (lastWriteWasEnter) return;
        if (!editingLine) return;
        editingLine = editingLine.slice(0, -1);
        erasePreviousChar();
        return;
      }
      if (d.length === 1 && !lastWriteWasEnter) {
        editingLine += d;
        writePty(d);
        return;
      }
      writePty(d);
      if (!lastWriteWasEnter) editingLine += d;
    });

    // ── Copy / paste ────────────────────────────────────────────────────
    // Copy the current selection to the system clipboard whenever it changes.
    const onSelectionChange = () => {
      const sel = term.getSelection();
      if (sel) {
        try {
          navigator.clipboard.writeText(sel).catch(() => {});
        } catch {
          /* clipboard unavailable */
        }
      }
    };
    term.onSelectionChange(onSelectionChange);

    // Single authoritative paste path. Listen on the DOCUMENT in the capture
    // phase (not just the xterm container) so a native paste that lands when the
    // terminal isn't focused is still intercepted before Electron falls back to
    // insertText injection. Only hijack the event when its target is inside our
    // terminal — otherwise let other inputs/outputs handle their own paste.
    const onPasteCapture = (e: ClipboardEvent) => {
      const container = containerRef.current;
      if (!container || !container.contains(e.target as Node)) return;
      e.preventDefault();
      e.stopPropagation();
      const text = e.clipboardData?.getData("text") ?? "";
      writePasteOnce(text);
    };
    document.addEventListener("paste", onPasteCapture, true);

    // Ctrl+C: if there is a selection, copy it (don't forward to the shell);
    // otherwise let it through as SIGINT. Ctrl+V: read the clipboard ourselves
    // and paste exactly once; return false so xterm never emits ^V or triggers
    // its own paste (that was the source of the triple-paste).
    term.attachCustomKeyEventHandler((ev) => {
      if (!ev.ctrlKey || ev.altKey || ev.metaKey) return true;
      if (ev.key === "c" && !ev.shiftKey) {
        const sel = term.getSelection();
        if (sel) {
          try {
            navigator.clipboard.writeText(sel);
          } catch {
            /* ignore */
          }
          return false; // consume: copy, do not send SIGINT
        }
        return true; // no selection → let Ctrl+C be SIGINT
      }
      if (ev.key === "v" && !ev.shiftKey) {
        try {
          navigator.clipboard
            .readText()
            .then((text) => writePasteOnce(text))
            .catch(() => {});
        } catch {
          /* ignore */
        }
        return false; // consume: we own paste
      }
      return true;
    });

    // Keep the PTY size in sync with the container while this tab is visible.
    const ro = new ResizeObserver(() => fitAndResize());
    ro.observe(containerRef.current!);
    const raf = requestAnimationFrame(fitAndResize);

    // Only dispose when the tab is closed (component is never unmounted on
    // conversation switch, so the terminal survives session changes).
    return () => {
      ro.disconnect();
      cancelAnimationFrame(raf);
      document.removeEventListener("paste", onPasteCapture, true);
      term.dispose();
      termRef.current = null;
      // Stop the backend session for this tab.
      electronTerminal.kill(id).catch(() => {});
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  // Start the PTY + fit whenever this tab becomes visible or the default dir
  // has resolved. Hidden tabs have a 0-size container, so the shell is only
  // spawned once the tab shows AND we know the right cwd.
  useEffect(() => {
    if (!isActive || !isTerminalOpen) return;
    // Don't start yet if we still need the no-project default and haven't got it.
    if (!terminalCwd) return;
    const term = termRef.current;
    const fitAddon = fitRef.current;
    if (!term || !fitAddon) return;
    const raf = requestAnimationFrame(() => {
      try {
        fitAddon.fit();
        electronTerminal.resize(id, term.cols, term.rows);
      } catch {
        /* not laid out yet */
      }
      if (startedRef.current) return;
      startedRef.current = true;
      // Start the PTY with the current dimensions + the project path as cwd.
      // Never use a bare drive root as cwd; fall back to the main process workDir.
      // When no project is active, use the fixed no-project default dir.
      const raw = stripVerbatimPrefix(terminalCwd);
      const dir =
        raw && typeof raw === "string" ? raw : undefined;
      const isDriveRoot =
        typeof dir === "string" && /^[a-zA-Z]:[\\/]?$/.test(dir);
      const cwd = dir && !isDriveRoot ? dir : undefined;
      lastCwdRef.current = cwd || null;
      electronTerminal
        .start(id, term.cols, term.rows, cwd)
        .then((res) => {
          if (res?.ok) {
            setTerminalError("");
          } else {
            setTerminalError(res?.error || "Terminal failed to start");
          }
        })
        .catch((e) => setTerminalError(String(e)));
    });
    return () => cancelAnimationFrame(raf);
     
  }, [id, isActive, isTerminalOpen, terminalCwd]);

  // Pipe backend output for THIS tab into its xterm instance.
  useEffect(() => {
    return electronTerminal.onData((payload) => {
      if (payload.id !== id) return;
      const term = termRef.current;
      if (!term) return;
      term.write(payload.data);
      bufferRef.current += payload.data;
    });
  }, [id]);

  // When the project directory changes, tell the running shell to cd there.
  // This keeps the terminal in sync with the conversation/project context.
  useEffect(() => {
    if (!isActive || !isTerminalOpen || !terminalCwd) return;
    const dir = stripVerbatimPrefix(terminalCwd);
    if (!dir) return;
    const isDriveRoot = /^[a-zA-Z]:[\\/]?$/.test(dir);
    if (isDriveRoot) return;
    if (lastCwdRef.current === dir) return;
    // Escape embedded quotes and issue a cd command. On Windows, `cd` does
    // NOT switch drive letters, so send the bare drive letter first — otherwise
    // the terminal label shows the new project while pwd stays on the old drive.
    const safeDir = dir.replace(/"/g, '\\"');
    const driveMatch = dir.match(/^([a-zA-Z]):[\\/]/);
    if (driveMatch) {
      electronTerminal.write(id, `${driveMatch[1]}:\r\n`);
    }
    electronTerminal.write(id, `cd "${safeDir}"\r\n`);
    lastCwdRef.current = dir;
  }, [id, isActive, isTerminalOpen, terminalCwd]);

  return (
    <div className={`flex-1 min-h-0 flex flex-col ${isActive ? "" : "hidden"}`}>
      {/* xterm.js terminal */}
      <div
        ref={containerRef}
        className="flex-1 overflow-hidden bg-transparent px-1 py-1"
        onClick={() => termRef.current?.focus()}
      />

      {!electronReady && (
        <div className="px-3 py-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-[#999]">
          Terminal not available in browser mode
        </div>
      )}
      {terminalError && (
        <div className="px-3 py-2 text-[calc(var(--helix-transcript-size)*0.8571)] text-red-500">
          {terminalError}
        </div>
      )}
    </div>
  );
}

export function TerminalPanel({ onClose }: TerminalPanelProps) {
  const { selectedWorkDir, isTerminalOpen } = useHelixStore();
  const [tabs, setTabs] = useState<{ id: number }[]>([]);
  const [activeId, setActiveId] = useState<number | null>(null);
  const nextIdRef = useRef(1);

  // Ensure at least one tab exists whenever the panel is open.
  useEffect(() => {
    if (isTerminalOpen && tabs.length === 0) {
      const id = nextIdRef.current++;
      setTabs([{ id }]);
      setActiveId(id);
    }
  }, [isTerminalOpen, tabs.length]);

  const addTab = useCallback(() => {
    const id = nextIdRef.current++;
    setTabs((prev) => [...prev, { id }]);
    setActiveId(id);
  }, []);

  const closeTab = useCallback(
    (id: number) => {
      setTabs((prev) => prev.filter((t) => t.id !== id));
      setActiveId((prev) => {
        if (prev !== id) return prev;
        const remaining = tabs.filter((t) => t.id !== id);
        if (remaining.length) return remaining[remaining.length - 1].id;
        return null;
      });
    },
    [tabs],
  );

  const handleCloseAll = useCallback(() => {
    // Unmounting every tab runs its cleanup, killing the backend sessions.
    setTabs([]);
    setActiveId(null);
    onClose();
  }, [onClose]);

  const projectName = selectedWorkDir
    ? selectedWorkDir.split(/[\\/]/).pop() || "终端"
    : "终端";

  return (
    <div
      className={`shrink-0 h-64 flex flex-col bg-card border-t border-border/40 rounded-t-lg overflow-hidden ${isTerminalOpen ? "" : "hidden"}`}
    >
      {/* Tab bar — Windows Terminal style */}
      <div className="flex items-center h-8 bg-muted shrink-0 select-none">
        <div className="flex items-center gap-1 px-1 h-full min-w-0 overflow-x-auto scrollbar-hide">
          {tabs.map((tab, i) => {
            const isActive = tab.id === activeId;
            const label =
              tabs.length > 1 ? `${projectName} ${i + 1}` : projectName;
            return (
              <div
                key={tab.id}
                onClick={() => setActiveId(tab.id)}
                className={`flex items-center gap-2 h-full px-3 border-t-2 cursor-pointer whitespace-nowrap transition-colors ${isActive ? "bg-white/60 border-primary text-foreground" : "border-transparent text-muted-foreground hover:text-foreground hover:bg-white/30"}`}
              >
                <Terminal className="size-3.5" />
                <span className="max-w-[140px] truncate text-[calc(var(--helix-transcript-size)*0.8571)]">
                  {label}
                </span>
                {tabs.length > 1 && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      closeTab(tab.id);
                    }}
                    className="p-0.5 rounded text-muted-foreground/50 hover:text-foreground hover:bg-black/10 transition-colors"
                    data-tip="关闭终端"
                  >
                    <X className="size-3" />
                  </button>
                )}
              </div>
            );
          })}
        </div>
        <div className="flex-1" />
        <button
          onClick={addTab}
          className="px-2.5 h-full flex items-center text-muted-foreground hover:text-foreground hover:bg-black/5 transition-colors"
          data-tip="新建终端"
        >
          <Plus className="size-3.5" />
        </button>
        <button
          onClick={handleCloseAll}
          className="px-2.5 h-full flex items-center text-muted-foreground hover:text-foreground hover:bg-black/5 transition-colors"
          data-tip="关闭并清空终端"
        >
          <X className="size-3.5" />
        </button>
      </div>

      {/* Terminal area — only the active tab is visible */}
      <div className="flex-1 min-h-0 flex">
        {tabs.map((tab) => (
          <TerminalTabView
            key={tab.id}
            id={tab.id}
            isActive={tab.id === activeId}
          />
        ))}
      </div>
    </div>
  );
}

"use client";

import { Check, X, AlertTriangle, Info, XCircle } from "lucide-react";
import React, { useEffect, useState } from "react";
import { useHelixStore } from "@/stores/helix-store";

function ToastIcon({ type }: { type: string }) {
  switch (type) {
    case "success":
      return (
        <div className="w-4 h-4 rounded-full bg-emerald-500/20 flex items-center justify-center shrink-0">
          <Check className="size-2.5 text-emerald-400" />
        </div>
      );
    case "error":
      return (
        <div className="w-4 h-4 rounded-full bg-red-500/20 flex items-center justify-center shrink-0">
          <XCircle className="size-2.5 text-red-400" />
        </div>
      );
    case "warning":
      return (
        <div className="w-4 h-4 rounded-full bg-amber-500/20 flex items-center justify-center shrink-0">
          <AlertTriangle className="size-2.5 text-amber-400" />
        </div>
      );
    default:
      return (
        <div className="w-4 h-4 rounded-full bg-blue-500/20 flex items-center justify-center shrink-0">
          <Info className="size-2.5 text-blue-400" />
        </div>
      );
  }
}

export function ToastContainer() {
  const { toasts, dismissToast } = useHelixStore();
  const [exiting, setExiting] = useState<Set<string>>(new Set());

  const handleClose = (id: string) => {
    setExiting((prev) => new Set(prev).add(id));
    setTimeout(() => {
      dismissToast(id);
      setExiting((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
    }, 200);
  };

  if (toasts.length === 0) return null;

  return (
    <div className="fixed top-14 right-4 z-[60] flex flex-col gap-1.5 max-w-xs">
      {toasts.map((toast) => (
        <div
          key={toast.id}
          role={toast.onClick ? "button" : undefined}
          onClick={() => toast.onClick?.()}
          className={`flex items-center gap-2 bg-card border border-border rounded-xl shadow-lg px-3 py-2 transition-all duration-300 ${
            toast.onClick ? "cursor-pointer hover:bg-accent/50" : ""
          } ${
            exiting.has(toast.id)
              ? "opacity-0 -translate-y-2 scale-95"
              : "opacity-100 translate-y-0 scale-100"
          }`}
        >
          <ToastIcon type={toast.type} />
          <div className="flex-1 min-w-0">
            <p className="text-[calc(var(--helix-transcript-size)*0.8571)] font-medium">
              {toast.title}
            </p>
            {toast.description && (
              <p className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground mt-0.5 leading-relaxed">
                {toast.description}
              </p>
            )}
          </div>
          <button
            onClick={(e) => {
              e.stopPropagation();
              handleClose(toast.id);
            }}
            className="p-0.5 hover:bg-accent rounded shrink-0 text-muted-foreground hover:text-foreground transition-colors"
          >
            <X className="size-3" />
          </button>
        </div>
      ))}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { PopupSelect, SettingGroup } from "./settings-ui";
import { Button } from "@/components/ui/button";
import { isElectron } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";

const VISION_PROVIDERS = [
  { id: "gemini", name: "Gemini" },
  { id: "zai", name: "Zhipu AI (z.ai) / GLM" },
  { id: "__custom__", name: "自定义" },
];

// 已知 endpoint 的 provider：自动填好 base_url，用户只需填 API Key
const PROVIDER_BASE_URLS: Record<string, string> = {
  gemini: "https://generativelanguage.googleapis.com/v1beta/openai/",
  zai: "https://open.bigmodel.cn/api/paas/v4",
};

export function VisionModelSettings() {
  const showToast = useHelixStore((s) => s.showToast);
  const [provider, setProvider] = useState("gemini");
  const [model, setModel] = useState("");
  const [baseUrl, setBaseUrl] = useState("");
  const [apiKey, setApiKey] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const load = async () => {
      if (!isElectron()) {
        const saved = localStorage.getItem("helix-vision-model");
        if (saved) {
          try {
            const d = JSON.parse(saved);
            setProvider(d.provider || "gemini");
            setModel(d.model || "");
            setBaseUrl(d.baseUrl || "");
            setApiKey(d.apiKey || "");
          } catch { /* empty */}
        }
        return;
      }
      try {
        const api = (window as any).electron?.vision;
        if (!api?.getConfig) return;
        const r = await api.getConfig();
        if (r?.ok && r.config) {
          setProvider(r.config.provider || "gemini");
          setModel(r.config.model || "");
          setBaseUrl(r.config.baseUrl || "");
          setApiKey(r.config.apiKey || "");
        }
      } catch (e) {
        console.error("[VisionModelSettings] load failed:", e);
      }
    };
    load();
  }, []);

  const knownBaseUrl = PROVIDER_BASE_URLS[provider];
  const showApiKey = provider !== "auto";
  const showBaseUrl = !knownBaseUrl && provider !== "auto";

  const save = async () => {
    setSaving(true);
    try {
      const config = {
        provider: provider === "__custom__" ? "custom" : provider,
        model,
        baseUrl: knownBaseUrl ? knownBaseUrl : showBaseUrl ? baseUrl : "",
        apiKey: showApiKey ? apiKey : "",
      };
      if (isElectron()) {
        const api = (window as any).electron?.vision;
        if (api?.setConfig) await api.setConfig(config);
      } else {
        localStorage.setItem("helix-vision-model", JSON.stringify(config));
      }
      showToast({ type: "success", title: "视觉模型配置已保存" });
    } catch (e) {
      showToast({ type: "error", title: "保存失败" });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-4">
      <SettingGroup>
        <div className="p-4 space-y-3">
          {/* Provider */}
          <div>
            <label className="block ui-text font-medium text-foreground mb-1.5">
              Provider
            </label>
            <PopupSelect
              value={provider}
              onChange={setProvider}
              placeholder="选择视觉 Provider"
              className="w-full ui-text text-foreground border border-border/50 bg-muted/50 rounded-lg px-3 py-2"
              options={VISION_PROVIDERS.map((p) => ({
                label: p.name,
                value: p.id,
              }))}
            />
          </div>

          {/* Model：纯文本输入，不限制预设列表 */}
          <div>
            <label className="block ui-text font-medium text-foreground mb-1.5">
              模型名称
            </label>
            <input
              type="text"
              value={model}
              onChange={(e) => setModel(e.target.value)}
              placeholder=""
              className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
            />
          </div>

          {/* Base URL：已知 endpoint 自动填充（只读）；未知则手填 */}
          {knownBaseUrl ? (
            <div>
              <label className="block ui-text font-medium text-foreground mb-1.5">
                Base URL
              </label>
              <input
                type="text"
                value={knownBaseUrl}
                readOnly
                disabled
                className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground/70 font-mono cursor-not-allowed"
              />
            </div>
          ) : (
            showBaseUrl && (
              <div>
                <label className="block ui-text font-medium text-foreground mb-1.5">
                  Base URL
                </label>
                <input
                  type="text"
                  value={baseUrl}
                  onChange={(e) => setBaseUrl(e.target.value)}
                  placeholder=""
                  className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
                />
              </div>
            )
          )}

          {/* API Key：除 auto 外都显示 */}
          {showApiKey && (
            <div>
              <label className="block ui-text font-medium text-foreground mb-1.5">
                API Key
              </label>
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                placeholder="sk-..."
                className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg ui-text text-foreground placeholder:text-muted-foreground/40 font-mono"
              />
            </div>
          )}
        </div>
      </SettingGroup>

      <div className="flex justify-end pt-2">
        <Button size="sm" variant="outline" onClick={save} disabled={saving}>
          {saving ? "保存中..." : "保存"}
        </Button>
      </div>
    </div>
  );
}

"use client";

import {
  GitBranch,
  Plus,
  Trash2,
  Lock,
  Unlock,
  FolderOpen,
  RefreshCw,
  Check,
  Loader2,
  AlertCircle,
  ChevronRight,
} from "lucide-react";
import React, { useState, useEffect, useCallback } from "react";
import { isElectron, electronGit } from "@/lib/electron-bridge";
import { useHelixStore } from "@/stores/helix-store";

interface WorktreeInfo {
  path: string;
  head?: string;
  branch?: string;
  bare?: boolean;
  detached?: boolean;
  locked?: boolean;
  prunable?: boolean;
  isMain?: boolean;
}

interface WorktreePanelProps {
  onClose: () => void;
}

export function WorktreePanel({ onClose }: WorktreePanelProps) {
  const [worktrees, setWorktrees] = useState<WorktreeInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newPath, setNewPath] = useState("");
  const [newBranch, setNewBranch] = useState("");
  const [createFromBranch, setCreateFromBranch] = useState("");
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const showToast = useHelixStore((s) => s.showToast);
  const setWorkDir = useHelixStore((s) => s.setWorkDir);

  const selectedWorkDir = useHelixStore((s) => s.selectedWorkDir);

  const loadWorktrees = useCallback(async () => {
    if (!isElectron()) return;
    if (!selectedWorkDir) {
      setError("未选择工作目录");
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const result = await electronGit.worktreeList();
      if (result.ok) {
        setWorktrees(result.worktrees || []);
      } else {
        setError(result.error || "无法获取 worktree 列表");
      }
    } catch (e) {
      const msg = String(e);
      if (msg.includes("not a git repository")) {
        setError("当前目录不是 git 仓库");
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  }, [selectedWorkDir]);

  useEffect(() => {
    loadWorktrees();
  }, [loadWorktrees]);

  const handleAdd = async () => {
    if (!newPath.trim()) return;
    setActionLoading("add");
    try {
      const result = await electronGit.worktreeAdd({
        path: newPath.trim(),
        branch: newBranch.trim() || undefined,
        newBranch: createFromBranch.trim() || undefined,
      });
      if (result.ok) {
        setShowAddForm(false);
        setNewPath("");
        setNewBranch("");
        setCreateFromBranch("");
        await loadWorktrees();
      } else {
        showToast({
          type: "error",
          title: "创建失败",
          description: result.error,
        });
      }
    } catch (e) {
      showToast({ type: "error", title: "创建失败", description: String(e) });
    } finally {
      setActionLoading(null);
    }
  };

  const handleRemove = async (wt: WorktreeInfo) => {
    if (wt.isMain) {
      showToast({ type: "warning", title: "无法删除主工作树" });
      return;
    }
    setActionLoading(wt.path);
    try {
      const result = await electronGit.worktreeRemove(wt.path);
      if (result.ok) {
        await loadWorktrees();
      } else {
        showToast({
          type: "error",
          title: "删除失败",
          description: result.error,
        });
      }
    } catch (e) {
      showToast({ type: "error", title: "删除失败", description: String(e) });
    } finally {
      setActionLoading(null);
    }
  };

  const handleToggleLock = async (wt: WorktreeInfo) => {
    setActionLoading(wt.path);
    try {
      const fn = wt.locked
        ? electronGit.worktreeUnlock
        : electronGit.worktreeLock;
      const result = await fn(wt.path);
      if (result.ok) {
        showToast({ type: "success", title: wt.locked ? "已解锁" : "已锁定" });
        await loadWorktrees();
      } else {
        showToast({
          type: "error",
          title: "操作失败",
          description: result.error,
        });
      }
    } catch (e) {
      showToast({ type: "error", title: "操作失败", description: String(e) });
    } finally {
      setActionLoading(null);
    }
  };

  const handlePrune = async () => {
    setActionLoading("prune");
    try {
      const result = await electronGit.worktreePrune();
      if (result.ok) {
        await loadWorktrees();
      }
    } catch (e) {
      showToast({ type: "error", title: "清理失败", description: String(e) });
    } finally {
      setActionLoading(null);
    }
  };

  const handleSwitchTo = async (wt: WorktreeInfo) => {
    try {
      await setWorkDir(wt.path);
    } catch (e) {
      showToast({ type: "error", title: "切换失败", description: String(e) });
    }
  };

  if (!isElectron()) {
    return (
      <div className="h-full flex items-center justify-center">
        <p className="text-[length:var(--helix-transcript-size)] text-muted-foreground">
          Worktree 功能仅在桌面版可用
        </p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-background select-none">
      {/* Header */}
      <div className="shrink-0 px-4 pr-36 py-3 border-b border-border/40 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <GitBranch className="size-4 text-muted-foreground" />
          <h2 className="text-[length:var(--helix-transcript-size)] font-semibold text-foreground">
            Worktree 管理
          </h2>
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={handlePrune}
            disabled={actionLoading === "prune"}
            className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors disabled:opacity-50"
            data-tip="清理过期 worktree"
          >
            {actionLoading === "prune" ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <RefreshCw className="size-3.5" />
            )}
          </button>
          <button
            onClick={() => setShowAddForm((v) => !v)}
            className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors"
            data-tip="添加 worktree"
          >
            <Plus className="size-3.5" />
          </button>
          <button
            onClick={onClose}
            className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-accent/60 rounded-lg transition-colors"
          >
            <span className="text-[calc(var(--helix-transcript-size)*0.8571)]">
              关闭
            </span>
          </button>
        </div>
      </div>

      {/* Add form */}
      {showAddForm && (
        <div className="shrink-0 px-4 py-3 border-b border-border/40 bg-muted/20 space-y-2">
          <input
            type="text"
            value={newPath}
            onChange={(e) => setNewPath(e.target.value)}
            placeholder="路径 (e.g. ../project-feature)"
            className="w-full px-3 py-2 bg-muted/50 border border-border/50 rounded-lg text-[length:var(--helix-transcript-size)] text-foreground placeholder:text-muted-foreground/40 font-mono"
          />
          <div className="flex gap-2">
            <input
              type="text"
              value={newBranch}
              onChange={(e) => setNewBranch(e.target.value)}
              placeholder="已有分支名 (留空=detached)"
              className="flex-1 px-3 py-2 bg-muted/50 border border-border/50 rounded-lg text-[length:var(--helix-transcript-size)] text-foreground placeholder:text-muted-foreground/40 font-mono"
            />
            <input
              type="text"
              value={createFromBranch}
              onChange={(e) => setCreateFromBranch(e.target.value)}
              placeholder="新建分支 (可选)"
              className="flex-1 px-3 py-2 bg-muted/50 border border-border/50 rounded-lg text-[length:var(--helix-transcript-size)] text-foreground placeholder:text-muted-foreground/40 font-mono"
            />
          </div>
          <div className="flex justify-end gap-2">
            <button
              onClick={() => setShowAddForm(false)}
              className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground hover:text-foreground rounded-lg hover:bg-accent/60 transition-colors"
            >
              取消
            </button>
            <button
              onClick={handleAdd}
              disabled={!newPath.trim() || actionLoading === "add"}
              className="px-3 py-1.5 text-[calc(var(--helix-transcript-size)*0.8571)] bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 transition-colors disabled:opacity-50"
            >
              {actionLoading === "add" ? (
                <Loader2 className="size-3 animate-spin" />
              ) : (
                "创建"
              )}
            </button>
          </div>
        </div>
      )}

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-3">
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="size-5 animate-spin text-muted-foreground" />
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center py-12 gap-2 text-red-500">
            <AlertCircle className="size-5" />
            <p className="text-[length:var(--helix-transcript-size)]">
              {error}
            </p>
            <button
              onClick={loadWorktrees}
              className="text-[calc(var(--helix-transcript-size)*0.8571)] text-muted-foreground hover:text-foreground"
            >
              重试
            </button>
          </div>
        ) : worktrees.length === 0 ? (
          <p className="text-[length:var(--helix-transcript-size)] text-muted-foreground/60 text-center py-12">
            暂无 worktree
          </p>
        ) : (
          <div className="space-y-2">
            {worktrees.map((wt) => (
              <div
                key={wt.path}
                className="rounded-xl border border-border/50 bg-card/50 overflow-hidden"
              >
                <div className="flex items-center gap-3 px-4 py-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      {wt.isMain && (
                        <span className="px-1.5 py-0.5 text-[calc(var(--helix-transcript-size)*0.7143)] rounded bg-primary/10 text-primary font-medium">
                          主
                        </span>
                      )}
                      {wt.locked && <Lock className="size-3 text-amber-500" />}
                      {wt.detached && (
                        <span className="px-1.5 py-0.5 text-[calc(var(--helix-transcript-size)*0.7143)] rounded bg-muted text-muted-foreground">
                          detached
                        </span>
                      )}
                      {wt.prunable && (
                        <span className="px-1.5 py-0.5 text-[calc(var(--helix-transcript-size)*0.7143)] rounded bg-red-500/10 text-red-500">
                          可清理
                        </span>
                      )}
                      {wt.branch && (
                        <span className="flex items-center gap-1 text-[calc(var(--helix-transcript-size)*0.8571)] font-mono text-foreground/70">
                          <GitBranch className="size-3" />
                          {wt.branch}
                        </span>
                      )}
                    </div>
                    <p className="text-[calc(var(--helix-transcript-size)*0.7857)] text-muted-foreground/60 font-mono truncate mt-1">
                      {wt.path}
                    </p>
                    {wt.head && (
                      <p className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/40 font-mono mt-0.5">
                        {wt.head.slice(0, 8)}
                      </p>
                    )}
                  </div>

                  <div className="flex items-center gap-1 shrink-0">
                    {!wt.isMain && (
                      <button
                        onClick={() => handleSwitchTo(wt)}
                        className="p-1.5 text-muted-foreground/40 hover:text-primary hover:bg-primary/10 rounded-lg transition-colors"
                        data-tip="切换到此目录"
                      >
                        <FolderOpen className="size-3.5" />
                      </button>
                    )}
                    <button
                      onClick={() => handleToggleLock(wt)}
                      disabled={actionLoading === wt.path}
                      className="p-1.5 text-muted-foreground/40 hover:text-amber-500 hover:bg-amber-500/10 rounded-lg transition-colors disabled:opacity-50"
                      data-tip={wt.locked ? "解锁" : "锁定"}
                    >
                      {actionLoading === wt.path ? (
                        <Loader2 className="size-3.5 animate-spin" />
                      ) : wt.locked ? (
                        <Unlock className="size-3.5" />
                      ) : (
                        <Lock className="size-3.5" />
                      )}
                    </button>
                    {!wt.isMain && (
                      <button
                        onClick={() => handleRemove(wt)}
                        disabled={actionLoading === wt.path}
                        className="p-1.5 text-muted-foreground/40 hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-colors disabled:opacity-50"
                        data-tip="删除"
                      >
                        <Trash2 className="size-3.5" />
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Footer info */}
      <div className="shrink-0 px-4 py-2 border-t border-border/40">
        <p className="text-[calc(var(--helix-transcript-size)*0.7143)] text-muted-foreground/40">
          {worktrees.length} 个工作树 · 在不同分支上并行工作
        </p>
      </div>
    </div>
  );
}

/**
 * Minimal `process` shim so legacy renderer code that reads process.env (the
 * debug logger, provider env-key lookup) degrades to `undefined` instead of
 * throwing ReferenceError in the browser. import.meta.env.MODE mirrors the old
 * `process.env.NODE_ENV` (development / production).
 *
 * `cwd` is a no-op returning '' — the renderer has no filesystem cwd (Tauri
 * runs the Rust main process, not Node). Without it, `typeof process !==
 * 'undefined' ? process.cwd() : ''` guards in session/new workDir fallbacks
 * *throw* ("process.cwd is not a function"), aborting the send before any
 * session is created → model never replies.
 */
(globalThis as any).process = {
  env: {
    NODE_ENV: import.meta.env.MODE,
  },
  cwd: () => "",
};

export {};

"use client";

import { useEffect } from "react";
import { useHelixStore } from "@/stores/helix-store";

let checked = false;

/**
 *与更新检查无关（更新检查查的是 pi agent）。
 */
export async function getCurrentVersion(): Promise<string | null> {
  try {
    const info = await (window as any).electron?.app?.getInfo?.();
    const v = info?.piVersion || info?.version;
    if (v) return String(v);
  } catch { /* empty */}
  return null;
}

/**
 * 启动时静默检查 pi agent 更新（npm registry）。后端 agent 是外部的
 * pi 包（@earendil-works/pi-coding-agent）
 */
export function useCheckUpdate() {
  useEffect(() => {
    if (checked) return;
    checked = true;

    const check = async () => {
      try {
        const res = await (window as any).electron?.helix?.piCheckUpdates?.();
        const pi = res?.pi;
        if (pi?.hasUpdate && pi.latest) {
          const state = useHelixStore.getState();
          state.showToast({
            type: "info",
            title: "pi 有新版本可用",
            description: `v${pi.installed} → v${pi.latest}`,
            duration: 8000,
            onClick: () =>
              window.open(
                "https://www.npmjs.com/package/@earendil-works/pi-coding-agent",
                "_blank",
              ),
          });
          state.setPendingUpdate?.(pi.latest as string);
        }
      } catch {
        // Silent fail — startup check must never nag
      }
    };

    const timer = setTimeout(check, 5000);
    return () => clearTimeout(timer);
  }, []);
}

/**
 * Browser automation executor for the pi-extension request-response protocol.
 *
 * The pi model's browser tools (browser_read / browser_click / browser_type /
 * browser_press) arrive as `helix:browser-request` events (see helix.rs
 * poll_browser_requests). Tauri's main webview cannot script a cross-origin
 * page directly, so — exactly like the "pick element" feature — we fetch the
 * page HTML via the Rust `page_fetch` command, render it into a hidden
 * same-origin `<iframe srcdoc>`, inject an executor script, and receive the
 * result via `window.postMessage`.
 *
 * Execution model: one hidden iframe per request (create → wait HELIX_EXEC_READY
 * → run op → wait HELIX_EXEC_RESULT → cleanup). The snapshot is static HTML:
 * reads see structure/text/interactive elements; clicks on links/submits fire
 * native navigations that surface through the browser panel's normal URL flow.
 * SPA-rendered content is invisible to this path — the model falls back to
 * `navigate` (real webview) when that matters.
 */

import { useCallback, useEffect, useRef, useState } from "react";

export interface BrowserExecRequest {
  op: "read" | "click" | "type" | "press" | "back" | "forward" | "refresh";
  url?: string;
  reqId: string;
  params?: {
    selector?: string;
    ref?: string;
    text?: string;
    submit?: boolean;
    key?: string;
  };
}

export interface BrowserExecResult {
  ok: boolean;
  error?: string;
  url?: string;
  title?: string;
  text?: string;
  elements?: Array<{
    ref: string;
    tag: string;
    role?: string;
    label?: string;
    text?: string;
    href?: string;
    type?: string;
  }>;
  clicked?: string;
  typed?: string;
  navigated?: string;
}

const EXEC_TIMEOUT_MS = 15_000;

/** Declarative script injected into the srcdoc iframe. Serialized as a string
 *  because srcdoc iframes don't share module scope with the host document.
 *  It installs a one-shot message listener, applies the op to the DOM, and
 *  posts the result back to the parent. */
const EXECUTOR_SCRIPT = `
<script>
(function() {
  if (window.__helixExecInstalled) return;
  window.__helixExecInstalled = true;

  // Ref registry: every interactive element gets a stable "eN" id assigned in
  // DOM order. Rebuilt per read; clicks resolve refs against the live DOM.
  function isVisible(el) {
    if (!el.getBoundingClientRect) return false;
    var r = el.getBoundingClientRect();
    if (r.width <= 0 && r.height <= 0) return false;
    var s = (window.getComputedStyle ? getComputedStyle(el) : el.style) || {};
    if (s.display === 'none' || s.visibility === 'hidden') return false;
    return true;
  }
  function labelOf(el) {
    var t = (el.innerText || el.textContent || '').trim().replace(/\\s+/g, ' ');
    if (t) return t.slice(0, 120);
    var v = el.getAttribute && (el.getAttribute('value') || '');
    if (v) return String(v).slice(0, 120);
    var ph = el.getAttribute && el.getAttribute('placeholder');
    if (ph) return String(ph).slice(0, 120);
    var aria = el.getAttribute && el.getAttribute('aria-label');
    if (aria) return String(aria).slice(0, 120);
    var forId = el.getAttribute && el.getAttribute('for');
    if (forId) {
      var lab = document.querySelector('label[for="' + forId + '"]');
      if (lab) return (lab.innerText || '').trim().slice(0, 120);
    }
    return '';
  }
  function interactiveElements(selector) {
    var nodes = selector
      ? Array.prototype.slice.call(document.querySelectorAll(selector))
      : Array.prototype.slice.call(
          document.querySelectorAll('a[href], button, input, select, textarea, [role="button"], [role="link"], [role="tab"], [onclick], summary')
        );
    return nodes.filter(function (el) { return isVisible(el); });
  }
  function readAll(selector) {
    var els = interactiveElements(selector);
    var out = [];
    els.forEach(function (el, i) {
      var ref = 'e' + (i + 1);
      try { el.setAttribute('data-helix-ref', ref); } catch (e) {}
      out.push({
        ref: ref,
        tag: (el.tagName || '').toLowerCase(),
        role: el.getAttribute && el.getAttribute('role') || undefined,
        label: labelOf(el) || undefined,
        text: ((el.innerText || el.textContent || '').trim().slice(0, 200)) || undefined,
        href: (el.getAttribute && el.getAttribute('href')) || undefined,
        type: (el.getAttribute && el.getAttribute('type')) || undefined
      });
    });
    var bodyText = ((document.body && document.body.innerText) || '')
      .trim()
      .replace(/\\n{3,}/g, '\\n\\n');
    return { text: bodyText.slice(0, 12000), elements: out };
  }
  function findByRefOrSelector(params) {
    if (params && params.ref) {
      var byRef = document.querySelector('[data-helix-ref="' + params.ref + '"]');
      if (byRef) return byRef;
      // Ref registry not built for THIS page yet (fresh srcdoc) — a ref without
      // a prior read can't resolve; fall through to selector if present.
    }
    if (params && params.selector) {
      try { return document.querySelector(params.selector) || null; } catch (e) { return null; }
    }
    return null;
  }
  function doClick(params) {
    var el = findByRefOrSelector(params);
    if (!el) return { ok: false, error: '找不到目标元素' + (params && (params.ref || params.selector) ? ': ' + (params.ref || params.selector) : '') };
    var desc = labelOf(el) || (el.tagName || '').toLowerCase();
    el.scrollIntoView({ block: 'center' });
    el.click();
    var href = el.getAttribute && (el.tagName === 'A' ? el.getAttribute('href') : null);
    return { ok: true, clicked: desc.slice(0, 200), navigated: href || undefined };
  }
  function doType(params) {
    var el = findByRefOrSelector(params);
    if (!el) return { ok: false, error: '找不到目标输入框' + (params && (params.ref || params.selector) ? ': ' + (params.ref || params.selector) : '') };
    el.scrollIntoView({ block: 'center' });
    el.focus();
    // Native value setter bypasses React's value tracking so the page's
    // listeners actually see the change.
    var setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
    var taSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value');
    var proto = el instanceof HTMLTextAreaElement
      ? window.HTMLTextAreaElement.prototype
      : window.HTMLInputElement.prototype;
    var d = el instanceof HTMLTextAreaElement ? taSetter : setter;
    if (d && d.set) d.set.call(el, params.text || '');
    else el.value = params.text || '';
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    if (params.submit) {
      if (el.form && typeof el.form.requestSubmit === 'function') {
        try { el.form.requestSubmit(); return { ok: true, typed: (params.text || '').slice(0, 120), navigated: 'form-submit' }; } catch (e) {}
      }
      var ke = new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true });
      el.dispatchEvent(ke);
      return { ok: true, typed: (params.text || '').slice(0, 120), navigated: 'enter' };
    }
    return { ok: true, typed: (params.text || '').slice(0, 120) };
  }
  function doPress(params) {
    var key = (params && params.key) || 'Enter';
    var el = document.activeElement || document.body;
    var ev;
    try {
      ev = new KeyboardEvent('keydown', { key: key, bubbles: true, cancelable: true });
    } catch (e) {
      ev = document.createEvent('KeyboardEvent');
      ev.initKeyboardEvent('keydown', true, true, null, key, 0, '', '', '', '');
    }
    el.dispatchEvent(ev);
    return { ok: true, pressed: key };
  }

  window.addEventListener('message', function (e) {
    var d = e.data;
    if (!d || d.type !== 'HELIX_EXEC_RUN') return;
    var res;
    try {
      if (d.op === 'read') {
        var r = readAll(d.params && d.params.selector);
        res = { ok: true, url: d.url, title: document.title || '', text: r.text, elements: r.elements };
      } else if (d.op === 'click') {
        res = doClick(d.params);
        if (res.ok) { res.url = d.url; res.title = document.title || ''; }
      } else if (d.op === 'type') {
        res = doType(d.params);
        if (res.ok) { res.url = d.url; res.title = document.title || ''; }
      } else if (d.op === 'press') {
        res = doPress(d.params);
      } else {
        res = { ok: false, error: 'unknown op: ' + d.op };
      }
    } catch (err) {
      res = { ok: false, error: String((err && err.message) || err) };
    }
    parent.postMessage({ type: 'HELIX_EXEC_RESULT', reqId: d.reqId, result: res }, '*');
  });

  parent.postMessage({ type: 'HELIX_EXEC_READY' }, '*');
})();
</script>
`;

/** Fetch a page's HTML through the Rust page_fetch command (server-side fetch:
 *  bypasses CORS entirely). Returns null on failure. */
async function fetchPageHtml(url: string): Promise<string | null> {
  try {
    const internals = (
      window as unknown as {
        __TAURI_INTERNALS__?: {
          invoke?: (cmd: string, args: Record<string, unknown>) => Promise<unknown>;
        };
      }
    ).__TAURI_INTERNALS__;
    const res = (await internals?.invoke?.("page_fetch", { url })) as
      | { html?: unknown }
      | null
      | undefined;
    if (res && typeof res.html === "string" && res.html) return res.html;
    return null;
  } catch {
    return null;
  }
}

/** Inject the executor script into fetched HTML. Kept simple: append to the
 *  end of <body> (or the document end) so the DOM is parsed when it runs. */
function withExecutor(html: string): string {
  if (/<body[^>]*>/i.test(html)) {
    return html.replace(/<\/body>/i, EXECUTOR_SCRIPT + "</body>");
  }
  return html + EXECUTOR_SCRIPT;
}

/**
 * React hook mounting a hidden automation iframe + a request queue. The
 * layout component feeds each `helix:browser-request` into `enqueue`; the
 * hook executes it against the page snapshot and posts the result back via
 * the `browserWriteResult` Rust command. Only ONE op runs at a time — ops
 * against the same conversation should serialize anyway, and pi's tools
 * await each result before issuing the next request.
 */
export function useBrowserAutomation() {
  const [pending, setPending] = useState<BrowserExecRequest | null>(null);
  const [frameHtml, setFrameHtml] = useState<string | null>(null);

  // Result listener bound at parent scope: receives from the srcdoc iframe.
  // `pending` drives the effect that OWNS the current request; `pendingRef`
  // tracks it so cleanup can settle a request that outlived the unmount
  // (otherwise the pi tool would block for its 20s result timeout).
  const pendingRef = useRef<BrowserExecRequest | null>(null);
  useEffect(() => {
    pendingRef.current = pending;
  }, [pending]);
  useEffect(
    () => () => {
      const cur = pendingRef.current;
      if (!cur) return;
      pendingRef.current = null;
      import("@/lib/electron-bridge").then(({ electronApp }) => {
        electronApp.browserWriteResult?.(cur.reqId, {
          ok: false,
          error: `执行环境已卸载（${cur.op}）：Helix 界面重载了，请重新发起操作`,
        } as BrowserExecResult);
      });
    },
    [],
  );
  useEffect(() => {
    if (!pending) return;
    let done = false;
    const finish = (result: BrowserExecResult) => {
      if (done) return;
      done = true;
      const reqId = pending.reqId;
      import("@/lib/electron-bridge").then(({ electronApp }) => {
        electronApp.browserWriteResult?.(reqId, result);
      });
      setPending(null);
      setFrameHtml(null);
    };
    const onMsg = (e: MessageEvent) => {
      const d = e.data as
        | {
            type?: string;
            reqId?: string;
            result?: BrowserExecResult;
          }
        | null;
      if (!d || typeof d !== "object" || !d.reqId) return;
      if (d.type === "HELIX_EXEC_RESULT" && d.reqId === pending.reqId) {
        finish(d.result as BrowserExecResult);
      }
    };
    window.addEventListener("message", onMsg);
    const timer = setTimeout(
      () =>
        finish({
          ok: false,
          error: `执行超时（${pending.op}）`,
        } as BrowserExecResult),
      EXEC_TIMEOUT_MS,
    );
    return () => {
      window.removeEventListener("message", onMsg);
      clearTimeout(timer);
    };
  }, [pending]);

  // Drive the iframe: load snapshot HTML for the request's URL, then run the
  // op once the iframe signals HELIX_EXEC_READY.
  //
  // Two paths: `frameHtml` starts null for each request, so on the first pass
  // we fetch the snapshot and arm the iframe via setState. On subsequent
  // passes (pending or frameHtml changed after the fetch resolved) the iframe
  // element already exists in the DOM and is polled synchronously — without
  // the extra render round-trip (and its potential staleness) the ready
  // signal can arrive between poll ticks and be missed.
  useEffect(() => {
    if (!pending || !pending.url) return;
    let cancelled = false;
    const fail = (error: string) => {
      if (cancelled || pendingRef.current?.reqId !== pending.reqId) return;
      pendingRef.current = null;
      import("@/lib/electron-bridge").then(({ electronApp }) => {
        electronApp.browserWriteResult?.(pending.reqId, {
          ok: false,
          error,
        } as BrowserExecResult);
      });
      setPending(null);
      setFrameHtml(null);
    };

    // Arm the iframe and wait for the injected script to report ready.
    const armAndRun = () => {
      if (cancelled || pendingRef.current?.reqId !== pending.reqId) return;
      const started = Date.now();
      const tick = () => {
        if (cancelled || pendingRef.current?.reqId !== pending.reqId) return;
        const frame = document.getElementById(
          "helix-browser-exec-frame",
        ) as HTMLIFrameElement | null;
        const win = frame?.contentWindow as
          | (Window & { __helixExecInstalled?: boolean })
          | null
          | undefined;
        if (win && win.__helixExecInstalled) {
          win.postMessage(
            {
              type: "HELIX_EXEC_RUN",
              op: pending.op,
              reqId: pending.reqId,
              url: pending.url,
              params: pending.params ?? {},
            },
            "*",
          );
          return;
        }
        if (Date.now() - started > EXEC_TIMEOUT_MS) {
          fail("页面快照注入脚本超时未就绪");
          return;
        }
        setTimeout(tick, 80);
      };
      setTimeout(tick, 60);
    };

    if (frameHtml !== null) {
      // Snapshot already armed by a prior effect pass — poll the live frame.
      armAndRun();
      return;
    }

    // First pass: fetch the snapshot, arm the iframe; the frameHtml state
    // change re-runs this effect into the polling path above.
    (async () => {
      const html = await fetchPageHtml(pending.url!);
      if (cancelled || pendingRef.current?.reqId !== pending.reqId) return;
      if (!html) {
        fail(`无法抓取页面（page_fetch 失败）：${pending.url}`);
        return;
      }
      setFrameHtml(withExecutor(html));
    })();
    return () => {
      cancelled = true;
    };
    // frameHtml intentionally re-triggers this effect (arm-then-poll split).
  }, [pending, frameHtml]);

  // `enqueue` keeps its identity for the parent's ref pattern; functional
  // update means the queue never drops a request for a finished one.
  const enqueue = useCallback((req: BrowserExecRequest) => {
    setPending((prev) => prev ?? req);
  }, []);

  return { enqueue, frameHtml };
}

/**
 * The hidden automation iframe. Mount once in the layout; it only renders
 * while a request with a URL is in flight (click/type/press target the page
 * from the preceding read — the pi tools always read first, so the URL rides
 * along on every request via the layout dispatcher).
 */
export function BrowserExecFrame({ html }: { html: string | null }) {
  if (!html) return null;
  return (
    <iframe
      id="helix-browser-exec-frame"
      srcDoc={html}
      style={{
        position: "fixed",
        left: "-9999px",
        top: "0",
        width: "1280px",
        height: "800px",
        border: "0",
        display: "block",
        zIndex: -1,
        pointerEvents: "none",
      }}
      sandbox="allow-scripts allow-same-origin allow-forms"
      title="helix-browser-exec"
      aria-hidden="true"
      tabIndex={-1}
    />
  );
}

/**
 * Config sync — live push via config.set IPC (no gateway restart).
 *
 * Unlike the old approach (write config.yaml → restart gateway), this module
 * pushes config changes via the gateway's config.set RPC, which applies
 * changes to the live session without restart.
 *
 * Model/provider changes still go through setModel + session recreation
 * (because the backend snapshots credentials at session creation time).
 */

"use client";

import { isElectron } from "@/lib/electron-bridge";
import {
  isServeActive,
  getServeClient,
  getGatewayMode,
  initServeGateway,
} from "@/lib/serve-gateway";

type ConfigValue = string | number | boolean | null | undefined;

let pushCooldown: ReturnType<typeof setTimeout> | null = null;
let lastPushJson = "";

/**
 * Push a config key/value pair to the Helix backend in real-time.
 * No gateway restart required — takes effect on the next prompt.
 */
export function pushConfigKeyValue(
  key: string,
  value: ConfigValue,
  sessionId?: string,
) {
  // Tauri mode: use tauri bridge via window.electron.helix
  if (!isElectron()) {
    const helix = (window as any).electron?.helix;
    if (helix?.setConfigKeyValue) {
      const payload = { key, value, session_id: sessionId };
      const json = JSON.stringify(payload);
      if (json === lastPushJson) return;
      lastPushJson = json;

      if (pushCooldown) clearTimeout(pushCooldown);
      pushCooldown = setTimeout(() => {
        pushCooldown = null;
        helix.setConfigKeyValue(payload).catch(() => {});
      }, 150);
    }
    return;
  }

  const serve = isServeActive() ? getServeClient() : null;
  const helix = window.electron?.helix as any;
  if (!serve && !helix?.setConfigKeyValue) return;

  const payload = { key, value, session_id: sessionId };
  const json = JSON.stringify(payload);
  if (json === lastPushJson) return;
  lastPushJson = json;

  // Debounce rapid changes (e.g. slider drag)
  if (pushCooldown) clearTimeout(pushCooldown);
  pushCooldown = setTimeout(() => {
    pushCooldown = null;
    if (serve) {
      // serve 模式：官方 WS config.set，live 生效，无需重启网关
      serve
        .rpc("config.set", { key, value, session_id: sessionId })
        .catch(() => {});
    } else {
      helix
        .setConfigKeyValue({ key, value, session_id: sessionId })
        .catch(() => {});
    }
  }, 150);
}

/**
 * Push model/provider config to the backend.
 * This writes config.yaml AND may trigger gateway restart (model switch
 * requires session creation with new credentials).
 *
 * The apiKey is deliberately NOT forwarded: pi's own files (models.json /
 * auth.json) are the single source of truth for credentials. Forwarding the
 * cached apiConfig key on every startup re-created provider entries with a
 * STALE key, clobbering keys rotated outside Helix. apply_pi_model_config
 * preserves the existing stored key when none is given. Callers that just
 * saved a FRESH key in the settings page still pass it through `pushApiKey`
 * (one-time), never via this generic path.
 */
export function pushModelConfig(payload: {
  model?: string;
  provider?: string;
  baseUrl?: string;
  apiKey?: string;
}) {
  // Strip the key: credentials live in pi's own files; this generic (startup
  // re-assert / model-switch) path must never carry a cached key.
  const modelPayload: {
    model?: string;
    provider?: string;
    baseUrl?: string;
  } = {
    model: payload.model,
    provider: payload.provider,
    baseUrl: payload.baseUrl,
  };
  const hasModelPayload = !!(
    modelPayload.model ||
    modelPayload.baseUrl ||
    modelPayload.provider
  );
  if (!hasModelPayload) return;

  // Tauri mode: use tauri bridge via window.electron.helix
  if (!isElectron()) {
    const helix = (window as any).electron?.helix;
    if (helix?.setConfig) {
      helix.setConfig(modelPayload).catch((e: unknown) => {
        console.warn("[config-sync] tauri setConfig 失败:", e);
      });
    }
    return;
  }

  // Electron mode: serve vs IPC
  const mode = getGatewayMode();

  // 按"模式"分流，而不是按"连接状态"（isServeActive）分流。
  // 关键竞态：App 启动时 helix-layout 立即调本函数，此刻 serve 还在冷启动、
  // WS 未连上 → isServeActive()===false → 若据此落 IPC，会触发
  // helix:setConfig 直写 config.yaml（原样写入私有 provider 名）并
  // restartGatewayDebounced 杀掉 serve → 新实例读坏配置 → agent 构建 30s 超时。
  // getGatewayMode 从第一秒起就能拿到真实模式（pending 也返回 mode），
  // serve 模式下等网关就绪后走 REST，绝不落 IPC。
  void (async () => {
    const mode = await getGatewayMode();
    if (mode === "serve") {
      if (!hasModelPayload) return;
      try {
        const c = isServeActive() ? getServeClient() : await initServeGateway();
        if (!c) {
          console.warn(
            "[config-sync] serve 网关不可用，模型配置推送跳过（将由建会话预同步兜底）",
          );
          return;
        }
        await c.setModel({
          ...modelPayload,
          model: modelPayload.model || "",
        });
      } catch (e) {
        console.warn("[config-sync] serve setModel 失败（不回落 IPC）:", e);
      }
      return;
    }
    pushModelConfigViaIpc(modelPayload, hasModelPayload);
  })();
}

/**
 * One-time push of a FRESHLY-SAVED api key (settings page save). Unlike
 * pushModelConfig this carries the key — it must only be called from an
 * explicit user save action, never from startup re-assertions.
 */
export function pushModelConfigWithKey(payload: {
  model?: string;
  provider?: string;
  baseUrl?: string;
  apiKey?: string;
}) {
  if (!isElectron()) {
    // Tauri mode: setConfig carries the key once (backend keeps it in
    // models.json / auth.json from here on).
    const helix = (window as any).electron?.helix;
    if (helix?.setConfig) {
      helix.setConfig(payload).catch((e: unknown) => {
        console.warn("[config-sync] tauri setConfig(key) 失败:", e);
      });
    }
    return;
  }
  // Electron acp mode: reuse the IPC path (carries the key once).
  pushModelConfigViaIpc(payload, true);
}

/** acp 模式的原有链路：冷启动缓存 + IPC setConfig（会写 config.yaml 并重启网关） */
function pushModelConfigViaIpc(
  payload: {
    model?: string;
    provider?: string;
    baseUrl?: string;
    apiKey?: string;
  },
  hasModelPayload: boolean,
) {
  const helix = window.electron?.helix;
  const profile = window.electron?.profile;
  if (!hasModelPayload) return;

  try {
    if (
      profile?.cacheConfig &&
      (payload.model || payload.baseUrl || payload.provider)
    ) {
      profile.cacheConfig({
        model: payload.model,
        provider: payload.provider,
        baseUrl: payload.baseUrl,
        apiKey: payload.apiKey,
      });
    }
  } catch { /* empty */}
  try {
    if (
      helix?.setConfig &&
      (payload.model || payload.baseUrl || payload.apiKey || payload.provider)
    ) {
      helix.setConfig({
        model: payload.model,
        provider: payload.provider,
        baseUrl: payload.baseUrl,
        apiKey: payload.apiKey,
      });
    }
  } catch { /* empty */}
}

/**
 * Push agent config (personality, reasoning effort, etc.) via live config.set.
 * These take effect immediately without gateway restart.
 */
export function pushAgentConfigLive(payload: {
  personality?: string;
  reasoningEffort?: string;
  fastMode?: boolean;
}) {
  const helix = (window as any).electron?.helix as any;
  const isTauri = !isElectron() && !!helix?.setConfigKeyValue;

  if (!isElectron() && !isTauri) return;

  if (payload.personality !== undefined) {
    pushConfigKeyValue("display.personality", payload.personality);
  }
  if (payload.reasoningEffort !== undefined) {
    pushConfigKeyValue("agent.reasoning_effort", payload.reasoningEffort);
  }
  if (payload.fastMode !== undefined) {
    pushConfigKeyValue(
      "agent.service_tier",
      payload.fastMode ? "fast" : "default",
    );
  }
}

/**
 * API Key encryption.
 *
 * Primary mechanism: Electron `safeStorage` (OS keychain — DPAPI on Windows,
 * Keychain on macOS, libsecret on Linux), invoked over IPC from the main
 * process. The OS key is bound to the user account, so a DB dump alone can't
 * recover the key. Ciphertext from safeStorage is stored with an `ss:`
 * marker so we can tell it apart from the legacy Web Crypto format below.
 *
 * Legacy / fallback: the previous scheme derived an AES-GCM key from a fixed
 * salt + `navigator.userAgent.length` (effectively public). We keep it ONLY to
 * (a) decrypt values written by older builds during a one-time migration, and
 * (b) cover pure-browser runs where safeStorage is unavailable. As soon as a
 * value is re-saved it is re-encrypted with safeStorage, so legacy blobs age
 * out automatically.
 */

const SAFE_MARKER = "ss:";

function electronSecure(): null | {
  encrypt: (p: string) => Promise<string | null>;
  decrypt: (b: string) => Promise<string | null>;
} {
  const e =
    typeof window !== "undefined" ? (window as any).electron : undefined;
  if (e?.secure) return e.secure;
  return null;
}

// ── Legacy Web Crypto (migration / browser fallback) ───────────────────────
const SALT = "helix-api-key-encryption-salt-v1";
const ALGO = "AES-GCM";
const KEY_LENGTH = 256;

let cachedLegacyKey: CryptoKey | null = null;

async function getLegacyKey(): Promise<CryptoKey> {
  if (cachedLegacyKey) return cachedLegacyKey;
  const encoder = new TextEncoder();
  const salt = encoder.encode(SALT);
  const password = encoder.encode(
    `helix-${typeof navigator !== "undefined" ? navigator.userAgent.length : 42}`,
  );
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    password,
    "PBKDF2",
    false,
    ["deriveKey"],
  );
  cachedLegacyKey = await crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations: 100000, hash: "SHA-256" },
    keyMaterial,
    { name: ALGO, length: KEY_LENGTH },
    false,
    ["encrypt", "decrypt"],
  );
  return cachedLegacyKey;
}

async function legacyEncrypt(plaintext: string): Promise<string> {
  const key = await getLegacyKey();
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encoded = new TextEncoder().encode(plaintext);
  const ciphertext = await crypto.subtle.encrypt(
    { name: ALGO, iv },
    key,
    encoded,
  );
  const combined = new Uint8Array(
    iv.length + new Uint8Array(ciphertext).length,
  );
  combined.set(iv, 0);
  combined.set(new Uint8Array(ciphertext), iv.length);
  return btoa(String.fromCharCode(...combined));
}

async function legacyDecrypt(encrypted: string): Promise<string> {
  const key = await getLegacyKey();
  const combined = Uint8Array.from(atob(encrypted), (c) => c.charCodeAt(0));
  const iv = combined.slice(0, 12);
  const ciphertext = combined.slice(12);
  const decrypted = await crypto.subtle.decrypt(
    { name: ALGO, iv },
    key,
    ciphertext,
  );
  return new TextDecoder().decode(decrypted);
}

function isBase64(str: string): boolean {
  try {
    return btoa(atob(str)) === str;
  } catch {
    return false;
  }
}

// ── Public API ──────────────────────────────────────────────────────────────

export async function encryptApiKey(plaintext: string): Promise<string> {
  if (!plaintext) return "";
  const secure = electronSecure();
  if (secure) {
    try {
      const b64 = await secure.encrypt(plaintext);
      if (b64) return SAFE_MARKER + b64;
    } catch {
      /* fall through to legacy */
    }
  }
  // Browser or safeStorage unavailable — legacy fallback (weak, but better
  // than plaintext). Only reached when not running inside Electron.
  try {
    return await legacyEncrypt(plaintext);
  } catch {
    return plaintext;
  }
}

export async function decryptApiKey(stored: string): Promise<string> {
  if (!stored) return "";

  // New format: safeStorage blob.
  if (stored.startsWith(SAFE_MARKER)) {
    const secure = electronSecure();
    const b64 = stored.slice(SAFE_MARKER.length);
    if (secure) {
      try {
        const plain = await secure.decrypt(b64);
        if (plain !== null) return plain;
      } catch {
        /* fall through — may be cross-account/cross-machine blob */
      }
    }
    // Can't decrypt (unavailable, or moved across OS account). Surface empty
    // so the caller treats it as "key needs re-entry" rather than leaking the
    // ciphertext as if it were the plaintext.
    return "";
  }

  // Legacy format: base64(iv+ciphertext) from the old Web Crypto scheme.
  if (!isBase64(stored)) return stored; // genuinely plain — return as-is
  try {
    return await legacyDecrypt(stored);
  } catch {
    return "";
  }
}

import { getServeHelixFacade } from "@/lib/serve-gateway";
import { installTauriBridge, isTauri } from "@/lib/tauri-bridge";
import type { ElectronAPI } from "@/types/electron";

/**
 * Check if running in Electron (or the Tauri build, which shims the same
 * `window.electron` surface).
 */
export function isElectron(): boolean {
  if (typeof window === "undefined") return false;
  if (window.electron?.isElectron) return true;
  // Tauri: install the invoke-backed bridge lazily so any consumer (even one
  // that only checks `isElectron()` first) sees a consistent environment.
  if (isTauri()) {
    installTauriBridge();
    return true;
  }
  return false;
}

/**
 * True ONLY in a real Electron runtime (where the contextBridge exposed
 * `window.electron.isElectron === true`). Distinct from `isElectron()`:
 * in the Tauri build `isElectron()` is forced true (shim) but Tauri's WebView2
 * engine does NOT support the Electron `<webview>` *guest* tag, so any code that
 * needs a real Electron webview (the embedded browser in preview-rail) must use
 * this guard and fall back to `<iframe>` in Tauri.
 */
export function isRealElectron(): boolean {
  if (typeof window === "undefined") return false;
  // The Tauri bridge also sets window.electron.isElectron = true (shim), so the
  // flag alone can't distinguish runtimes — must exclude Tauri explicitly.
  if (isTauri()) return false;
  return !!window.electron?.isElectron;
}

// serve 模式下包裹 window.electron 的 Proxy 缓存：
// 拦截 `.helix` 返回网关门面，其余属性透传原 contextBridge 对象。
// （contextBridge 暴露的 window.electron 不可重赋值，只能在读取层分流。）
//
// 关键坑：contextBridge 暴露的对象属性是 non-writable + non-configurable，
// JS Proxy 不变量要求 get 陷阱对这类属性必须原样返回 target 上的值——
// 直接以 window.electron 为 target 并对 `helix` 返回门面会抛
// "property 'helix' is a read-only and non-configurable data property..."。
// 解法：以空对象为 target（无自有属性 → 不受不变量约束），闭包转发到真实 api。
let serveProxyCache: ElectronAPI | null = null;

function wrapWithServeProxy(api: ElectronAPI): ElectronAPI {
  if (serveProxyCache) return serveProxyCache;
  serveProxyCache = new Proxy({} as Record<string | symbol, unknown>, {
    get(_target, prop: string | symbol) {
      if (prop === "helix") {
        const facade = getServeHelixFacade();
        if (facade) return facade;
      }
      return (api as any)[prop as any];
    },
    has(_target, prop: string | symbol) {
      return prop in (api as any);
    },
  }) as unknown as ElectronAPI;
  return serveProxyCache;
}

/**
 * Get Electron API
 * serve 网关激活时返回 Proxy（`.helix` 分流到网关门面），否则原样返回。
 */
export function getElectronAPI(): ElectronAPI | null {
  if (isElectron()) {
    if (getServeHelixFacade()) return wrapWithServeProxy(window.electron!);
    return window.electron!;
  }
  return null;
}

/**
 * 获取 helix API（模式感知）。
 * serve 模式 → 网关门面（WS/REST 直连）；acp 模式 → 原 IPC 桥。
 * 渲染层所有直摸 `window.electron.helix` 的调用点应改用本函数。
 */
export function helixApi(): ElectronAPI["helix"] | null {
  const facade = getServeHelixFacade();
  if (facade) return facade;
  return (
    (typeof window !== "undefined" ? window.electron?.helix : null) ?? null
  );
}

/**
 * File system operations that work in both browser and Electron
 * In browser: uses IndexedDB via existing persist.ts
 * In Electron: uses IPC to main process
 */
export const electronFS = {
  async readFile(filePath: string): Promise<string> {
    const api = getElectronAPI();
    if (api) {
      return api.fs.read(filePath);
    }
    throw new Error("File system not available in browser mode");
  },

  async writeFile(filePath: string, content: string): Promise<void> {
    const api = getElectronAPI();
    if (api) {
      await api.fs.write(filePath, content);
      return;
    }
    throw new Error("File system not available in browser mode");
  },

  async editFile(
    filePath: string,
    oldString: string,
    newString: string,
  ): Promise<void> {
    const api = getElectronAPI();
    if (api) {
      await api.fs.edit(filePath, oldString, newString);
      return;
    }
    throw new Error("File system not available in browser mode");
  },

  async readDir(
    dirPath: string,
  ): Promise<Array<{ name: string; isDirectory: boolean }>> {
    const api = getElectronAPI();
    if (api) {
      return api.fs.readdir(dirPath);
    }
    throw new Error("File system not available in browser mode");
  },

  // Absolute Helix memory directory, computed in the main process.
  // Use this instead of deriving the path from process.env in the renderer
  // (which is undefined in a Next.js client bundle).
  async memoryDir(): Promise<string | null> {
    const api = getElectronAPI();
    if (api && typeof api.fs.helixMemoryDir === "function") {
      return api.fs.helixMemoryDir();
    }
    return null;
  },

  async stat(filePath: string) {
    const api = getElectronAPI();
    if (api) {
      return api.fs.stat(filePath);
    }
    throw new Error("File system not available in browser mode");
  },

  async rename(oldPath: string, newPath: string): Promise<void> {
    const api = getElectronAPI();
    if (api) {
      await api.fs.rename(oldPath, newPath);
      return;
    }
    throw new Error("File system not available in browser mode");
  },

  async deleteFile(filePath: string): Promise<void> {
    const api = getElectronAPI();
    if (api) {
      await api.fs.delete(filePath);
      return;
    }
    throw new Error("File system not available in browser mode");
  },

  async scanTree(
    dirPath?: string,
  ): Promise<
    Array<{ id: string; name: string; type: string; children?: any[] }>
  > {
    const api = getElectronAPI();
    if (api && typeof api.fs.scanTree === "function") {
      return api.fs.scanTree(dirPath);
    }
    // 旧 preload 可能未暴露 scanTree：返回空树，避免 setWorkDir 抛错。
    return [];
  },
};

