      return api.app.proxySet(url);
    }
    throw new Error("App not available in browser mode");
  },

  /** Poll pending pi-extension browser requests (emits helix:browser-request
   *  events with the full payload; navigate also emits the legacy
   *  helix:open-browser for the sidebar-open path). */
  async pollBrowserRequests(): Promise<{ ok: boolean; opened: string[] }> {
    const api = getElectronAPI();
    if (api && typeof api.app.pollBrowserRequests === "function") {
      return api.app.pollBrowserRequests();
    }
    return { ok: true, opened: [] };
  },

  /** Write a browser automation result (<reqId>.result.json) for the pi
   *  extension's request-response protocol. Best-effort: failures are
   *  swallowed (the pi tool times out on its side). */
  async browserWriteResult(
    reqId: string,
    result: unknown,
  ): Promise<{ ok: boolean; error?: string }> {
    const api = getElectronAPI();
    if (api && typeof api.app.browserWriteResult === "function") {
      try {
        return await api.app.browserWriteResult(reqId, result);
      } catch {
        return { ok: false };
      }
    }
    return { ok: false };
  },
};

/**
 * Helix bridge (Electron only) — JSON-RPC send / notify.
 *
 * `notify` is a JSON-RPC notification (no response expected). It is only
 * available in preload builds that expose `helix.notify`. If the running
 * app has an older preload (not yet restarted after a code change), calling
 * `notify` directly throws "is not a function" and white-screens the UI.
 * This wrapper degrades gracefully: it no-ops with a warning instead of
 * crashing, so the app keeps working until the user restarts Helix.
 */
export const electronHelix = {
  async send(method: string, params?: any): Promise<any> {
    const api = getElectronAPI();
    if (api?.helix) {
      return api.helix.send(method, params);
    }
    return null;
  },

  notify(method: string, params?: any): void {
    const api = getElectronAPI();
    const h = api?.helix as any;
    if (h?.notify) {
      h.notify(method, params);
      return;
    }
    console.warn(
      `[electron-bridge] helix.notify unavailable; skipped "${method}". Restart Helix to enable.`,
    );
  },

  async interrupt(sessionId: string): Promise<void> {
    const api = getElectronAPI();
    const h = api?.helix as any;
    if (h?.interrupt) {
      await h.interrupt(sessionId);
    }
  },

  async update(): Promise<{ ok: boolean; message: string }> {
    const api = getElectronAPI();
    const h = api?.helix as any;
    if (h?.update) {
      return h.update();
    }
    return { ok: false, message: "更新通道不可用" };
  },

  /** Live config push: set a single key/value pair without gateway restart */
  async setConfigKeyValue(
    key: string,
    value: any,
    sessionId?: string,
  ): Promise<void> {
    const api = getElectronAPI();
    const h = api?.helix as any;
    if (h?.setConfigKeyValue) {
      await h.setConfigKeyValue({ key, value, session_id: sessionId });
    }
  },

  /** Respond to an approval request from the backend */
  async approvalRespond(params: {
    session_id?: string;
    tool_call_id?: string;
    choice: string;
  }): Promise<void> {
    const api = getElectronAPI();
    const h = api?.helix as any;
    if (h?.approvalRespond) {
      await h.approvalRespond(params);
    }
  },
};

