/**
 * Schedule parsing utilities — extracted from agent-flow-panel.tsx.
 * Detects scheduled task definitions in LLM output and syncs them to the backend.
 */
import { useHelixStore } from "@/stores/helix-store";

/**
 * Parse a human schedule description into a next-run timestamp.
 */
export function parseScheduleForTask(text: string): { nextRun: number | null } {
  const lower = text.toLowerCase().trim();
  const minMatch = lower.match(/every\s+(\d+)\s*min(?:ute)?s?/);
  if (minMatch) return { nextRun: Date.now() + parseInt(minMatch[1]) * 60000 };
  const hourMatch = lower.match(/every\s+(\d+)\s*hour(?:s)?/);
  if (hourMatch)
    return { nextRun: Date.now() + parseInt(hourMatch[1]) * 3600000 };
  const dayMatch = lower.match(/every\s+day\s+at\s+(\d{1,2}):(\d{2})/);
  if (dayMatch) {
    const now = new Date();
    const target = new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate(),
      parseInt(dayMatch[1]),
      parseInt(dayMatch[2]),
    );
    if (target.getTime() <= now.getTime()) target.setDate(target.getDate() + 1);
    return { nextRun: target.getTime() };
  }
  if (lower.includes("every hour")) return { nextRun: Date.now() + 3600000 };
  if (lower.includes("every day")) return { nextRun: Date.now() + 86400000 };
  if (lower.includes("every week")) return { nextRun: Date.now() + 604800000 };
  const inMinMatch = lower.match(/in\s+(\d+)\s*min(?:ute)?s?/);
  if (inMinMatch)
    return { nextRun: Date.now() + parseInt(inMinMatch[1]) * 60000 };
  // Chinese natural-language time (e.g. 今天下午1:30 / 明天上午10点) → delegate.
  if (/[一-鿿]/.test(text)) return { nextRun: parseChineseSchedule(text) };
  return { nextRun: Date.now() + 86400000 };
}

/**
 * Parse Chinese natural-language time expressions like
 * "明天（2026年7月13日）上午 10:00", "今天下午3点", "2026年7月13日 22:00".
 */
export function parseChineseSchedule(text: string): number {
  const now = new Date();
  let base = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  let hour = 9;
  let minute = 0;
  const dateM = text.match(/(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日/);
  if (dateM) {
    base = new Date(
      parseInt(dateM[1]),
      parseInt(dateM[2]) - 1,
      parseInt(dateM[3]),
    );
  } else if (/后天/.test(text)) {
    base.setDate(base.getDate() + 2);
  } else if (/明天/.test(text)) {
    base.setDate(base.getDate() + 1);
  }
  let ampm = 0;
  if (/(下午|晚上|傍晚)/.test(text)) ampm = 12;
  else if (/(中午)/.test(text)) hour = 12;
  const hm = text.match(/(\d{1,2})\s*[:：]\s*(\d{1,2})/);
  const hDot = text.match(/(\d{1,2})\s*点/);
  if (hm) {
    hour = parseInt(hm[1]);
    minute = parseInt(hm[2]);
  } else if (hDot) {
    hour = parseInt(hDot[1]);
    minute = 0;
  }
  if (ampm && hour < 12) hour += ampm;
  const result = new Date(
    base.getFullYear(),
    base.getMonth(),
    base.getDate(),
    hour,
    minute,
  );
  if (!dateM && result.getTime() <= now.getTime()) {
    result.setDate(result.getDate() + 1);
  }
  return result.getTime();
}

/**
 * A scheduled task detected in assistant output but NOT yet created. Creation
 * only happens after the user confirms (via the Scheduled Task confirm dialog).
 */
export interface DetectedTask {
  label: string;
  prompt: string;
  scheduleText: string;
  nextRunAt: number | null;
  sessionId?: string;
}

/**
 * Fire-and-forget sync of a created scheduled task to Helix backend jobs.json.
 */
export function syncTaskToBackend(
  label: string,
  prompt: string,
  scheduleText: string,
  nextRunAt: number | null,
) {
  try {
    const electron = (window as any).electron;
    if (electron?.scheduledTasks?.create) {
      electron.scheduledTasks
        .create({
          name: label,
          prompt,
          scheduleText,
          cronExpression: undefined,
          nextRunAt: nextRunAt ?? undefined,
        })
        .catch((e: any) =>
          console.error("sync scheduled task to backend failed:", e),
        );
    }
  } catch (e) {
    console.error("sync scheduled task to backend error:", e);
  }
}

/**
 * Detect ```scheduled-task JSON blocks AND natural-language "已创建定时任务 /
 * 名称： / 时间：" patterns in assistant output, returning the cleaned text
 * (blocks stripped) plus the tasks that were detected.
 *
 * Tasks are NOT auto-created here — the caller shows a confirm dialog and only
 * creates them once the user approves. This avoids silently spamming duplicate
 * tasks on every AI reply (the old behaviour we removed).
 */
export function detectScheduledTasks(text: string): {
  cleaned: string;
  tasks: DetectedTask[];
} {
  const tasks: DetectedTask[] = [];
  let cleaned = text;
  // 1) Structured ```scheduled-task JSON blocks (label/prompt/schedule or aliases)
  const re = /```(\w*)\s*\n([\s\S]*?)```/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) !== null) {
    const block = m[0];
    const jsonStr = m[2];
    try {
      const data = JSON.parse(jsonStr);
      const label = String(data.label || data.name || data.title || "").trim();
      const prompt = String(
        data.prompt || data.task || data.content || data.message || "",
      ).trim();
      const schedule = String(
        data.schedule || data.when || data.time || "",
      ).trim();
      if (label && prompt && schedule) {
        const parsed = parseScheduleForTask(schedule);
        tasks.push({
          label,
          prompt,
          scheduleText: schedule,
          nextRunAt: parsed.nextRun,
        });
        cleaned = cleaned.replace(block, "");
      }
    } catch {
      // not a JSON block, ignore
    }
  }
  // 2) Natural-language fallback: AI confirmed creation with 名称:/时间: lines.
  const confirmRe =
    /(已成功为你创建|已为你创建|已创建(安排|定时任务|提醒)|已帮你创建|创建成功|已安排)/;
  if (confirmRe.test(text)) {
    const nameMatch = text.match(/名称[：:]\s*([^\n]+)/);
    const timeMatch = text.match(/时间[：:]\s*([^\n]+)/);
    if (nameMatch && timeMatch) {
      const label = nameMatch[1].trim().replace(/\s+/g, " ");
      const timeText = timeMatch[1].trim();
      const nextRun = parseChineseSchedule(timeText);
      if (!tasks.some((t) => t.label === label)) {
        tasks.push({
          label,
          prompt: label,
          scheduleText: timeText,
          nextRunAt: nextRun,
        });
      }
    }
  }
  cleaned = cleaned.replace(/\n{3,}/g, "\n\n").replace(/^\n+|\n+$/g, "");
  return { cleaned, tasks };
}

/**
 * Global scheduled task runner — runs independently of any component mount.
 * Checks every 30 seconds for due tasks and dispatches them to a DEDICATED
 * Helix session so they never interrupt or pollute the active conversation.
 *
 * Also re-reads ~/.pi/agent/helix/cron/jobs.json (the shared source of truth
 * that the pi-scheduled-tasks extension writes) so tasks created by the agent
 * are picked up and dispatched here even when the 计划 panel isn't open.
 */
import { helixApi } from "@/lib/electron-bridge";
import { parseScheduleForTask } from "@/lib/schedule-utils";
import { useHelixStore, type ScheduledTask } from "@/stores/helix-store";

let _started = false;
// Cached Helix session ID for scheduled tasks (separate from any conversation).
let _taskSessionId: string | null = null;

async function getOrCreateTaskSession(): Promise<string | null> {
  if (_taskSessionId) return _taskSessionId;
  try {
    const res = (await helixApi()!.send("session/new", {
      cwd: useHelixStore.getState().selectedWorkDir || "",
      mcpServers: [],
    })) as any;
    const sid =
      res?._meta?.helix?.sessionProvenance?.acpSessionId ||
      res?.session_id ||
      res?.sessionID ||
      (typeof res === "string" ? res : null);
    if (sid) {
      _taskSessionId = sid;
      return sid;
    }
  } catch (e) {
    console.error("[ScheduledTask] Failed to create task session:", e);
  }
  return null;
}

async function runTask(task: {
  id: string;
  label: string;
  prompt: string;
  scheduleText?: string;
}) {
  const { updateScheduledTask, showToast } = useHelixStore.getState();

  // Create / reuse a DEDICATED Helix session for background tasks — NEVER the
  // active conversation's session.  This prevents the task from polluting the
  // user's current conversation context or interrupting a running agent.
  const taskSid = await getOrCreateTaskSession();
  if (!taskSid) {
    showToast({
      type: "error",
      title: `定时任务 "${task.label}" 失败`,
      description: "无法创建后台会话",
    });
    updateScheduledTask(task.id, { lastRunAt: Date.now() });
    return;
  }

  // Send the prompt to the DEDICATED session — NOT the active conversation.
  // The response events arrive with this session_id, which no active conversation's
  // onEvent handler claims (they filter by their own session_id), so the UI stays
  // untouched.  The task runs silently in the background.
  try {
    await helixApi()!.send("session/prompt", {
      session_id: taskSid,
      prompt: [{ type: "text", text: task.prompt }],
    });
  } catch (e) {
    console.error("[ScheduledTask] Failed to dispatch:", e);
    // Session may have been invalidated (gateway restart) — reset and retry next cycle.
    _taskSessionId = null;
  }

  updateScheduledTask(task.id, { lastRunAt: Date.now() });

  const taskState = useHelixStore.getState().scheduledTasks.find((t) => t.id === task.id);
  const storedNextRunAt = taskState?.nextRunAt ?? null;

  // Trust the backend/extension-advanced nextRunAt when present.
  // Only recompute from scheduleText when the stored value is absent or
  // already in the past (meaning the task fired but the backend didn't
  // advance it — e.g. a frontend-created task that has no cron expr).
  if (storedNextRunAt && storedNextRunAt > Date.now()) {
    // Already advanced by Rust poller / extension — keep it.
  } else {
    const parsed = parseScheduleForTask(task.scheduleText || task.label || "");
    if (parsed.nextRun) {
      updateScheduledTask(task.id, { nextRunAt: parsed.nextRun });
    }
  }

  // NOTE: intentionally NO per-run info toast. It fired every 30s and was pure
  // noise. Failures still surface via the error toast in the session branch above.
}

/**
 * Re-read jobs.json from the Rust backend and merge any NEW backend tasks into
 * the in-memory store. Called each tick so the pi extension's writes show up
 * even when the 计划 panel has never been opened this session.
 *
 * Idempotent: the panel's own load() does the same merge, so opening the
 * panel after this runs is a no-op for already-merged ids.
 */
async function refreshFromBackend() {
  try {
    const electron = (window as any).electron;
    if (!electron?.scheduledTasks?.list) return;
    const res = await electron.scheduledTasks.list();
    if (!res?.ok || !Array.isArray(res.tasks)) return;
    const backendTasks = res.tasks as Array<
      Omit<ScheduledTask, "createdAt" | "updatedAt"> & {
        createdAt?: number;
        updatedAt?: number;
      }
    >;
    const state = useHelixStore.getState();
    const existing = new Set(state.scheduledTasks.map((t) => t.id));
    const now = Date.now();
    const merged: ScheduledTask[] = [...state.scheduledTasks];
    for (const bt of backendTasks) {
      // The Rust reader omits createdAt/updatedAt when absent — fill so the
      // type stays satisfied.
      const task: ScheduledTask = {
        id: bt.id,
        label: bt.label,
        prompt: bt.prompt,
        scheduleText: bt.scheduleText,
        cronExpression: bt.cronExpression,
        enabled: bt.enabled,
        lastRunAt: bt.lastRunAt ?? null,
        nextRunAt: bt.nextRunAt ?? null,
        createdAt: bt.createdAt ?? now,
        updatedAt: bt.updatedAt ?? now,
      };
      if (existing.has(task.id)) {
        const i = merged.findIndex((t) => t.id === task.id);
        if (i >= 0) merged[i] = task;
      } else {
        merged.push(task);
      }
    }
    useHelixStore.setState({ scheduledTasks: merged });
  } catch (e) {
    console.error("[ScheduledTask] refreshFromBackend failed:", e);
  }
}

export function startScheduledTaskRunner() {
  if (_started) return;
  _started = true;

  // Immediate first read so tasks created before this session are visible.
  void refreshFromBackend();

  setInterval(() => {
    void refreshFromBackend().then(() => {
      const state = useHelixStore.getState();
      const now = Date.now();
      for (const task of state.scheduledTasks) {
        if (task.enabled && task.nextRunAt && task.nextRunAt <= now) {
          runTask(task);
        }
      }
    });
  }, 30_000); // Check every 30 seconds
}

