        persistence.saveSetting("selectedWorkDir", state.selectedWorkDir),
        persistence.saveSetting("hasOnboarded", state.hasOnboarded),
      ]);
    } catch (e) {
      logError("Failed to persist:", e);
      get().showToast({
        type: "error",
        title: "设置保存失败",
        description: "配置未能写入本地存储，请重试",
      });
    }
  },

  restoreFromStorage: async () => {
    try {
      const { persistence } = await import("@/lib/persist");
      const sessionId = "current-session";

      // MCP config is now managed by Helix
      const fileMcpConfig: Record<string, any> = {};

      // Helper: load a setting without throwing — a single corrupted key
      // must not fail the entire restore (common on Windows after crashes).
      const safeLoad = <T>(
        promise: Promise<T | null>,
        key: string,
      ): Promise<T | null> =>
        promise.catch((e) => {
          logError(`[restore] failed to load ${key}:`, e);
          return null;
        });

      // Try loading the latest saved session first (full state)
      const sessions =
        (await safeLoad(persistence.loadSessions(), "sessions")) || [];
      const archivedSessions = sessions.filter((s) => s.isArchived);
      const latestSession =
        sessions.filter((s) => !s.isArchived).length > 0
          ? sessions
              .filter((s) => !s.isArchived)
              .sort((a, b) => b.savedAt - a.savedAt)[0]
          : null;

      // Load individual pieces for settings and non-session state
      const [
        memories,
        tasks,
        checkpoints,
        notes,
        chatMessages,
        goal,
        apiConfig,
        apiHistory,
        apiProfiles,
        fontFamily,
        fontSize,
        interfaceFont,
        transcriptFontSize,
        themeStyle,
        sessionUsageStats,
        dailyUsage,
        scheduledTasks,
        mcpServers,
        customShortcuts,
        customizedIdsArr,
        agentMaxIterations,
        autoCompactContext,
        autoSaveSession,
        availableModels,
        providerModels,
        reasoningEffort,
        personality,
        fastMode,
        terminalShell,
        editorTheme,
        gitAutoCommit,
        gitAutoPush,
        gitPushConfirm,
        gitAutoBranch,
        gitRemoteUrl,
        gitCommitTemplate,
        gitBranchPrefix,
        approvalMode,
        approvalModeBySession,
        startupGreeting,
        providers,
        activeModel,
        activeProviderId,
        savedSessionHistory,
        savedSessionHistoryIndex,
        savedSelectedWorkDir,
        loadedHasOnboarded,
        contextUsage,
        externalServices,
      ] = await Promise.all([
        safeLoad(persistence.loadMemories(), "memories"),
        safeLoad(persistence.loadTasks(), "tasks"),
        safeLoad(persistence.loadCheckpoints(), "checkpoints"),
        safeLoad(persistence.loadNotes(), "notes"),
        safeLoad(
          persistence.loadChatMessagesBySession(sessionId),
          "chatMessages",
        ),
        safeLoad(persistence.loadSetting<string | null>("goal"), "goal"),
        safeLoad(persistence.loadSetting<ApiConfig>("apiConfig"), "apiConfig"),
        safeLoad(
          persistence.loadSetting<ApiConfig[]>("apiHistory"),
          "apiHistory",
        ),
        safeLoad(
          persistence.loadSetting<ApiProfile[]>("apiProfiles"),
          "apiProfiles",
        ),
        safeLoad(persistence.loadSetting<string>("fontFamily"), "fontFamily"),
        safeLoad(persistence.loadSetting<number>("fontSize"), "fontSize"),
        safeLoad(
          persistence.loadSetting<string>("interfaceFont"),
          "interfaceFont",
        ),
        safeLoad(
          persistence.loadSetting<number>("transcriptFontSize"),
          "transcriptFontSize",
        ),
        safeLoad(persistence.loadSetting<string>("themeStyle"), "themeStyle"),
        safeLoad(
          persistence.loadSetting<{
            requestCount: number;
            totalTokens: number;
            inputTokens: number;
            outputTokens: number;
            thoughtTokens: number;
            cachedReadTokens: number;
            cachedWriteTokens: number;
          }>("sessionUsageStats"),
          "sessionUsageStats",
        ),
        safeLoad(
          persistence.loadSetting<Record<string, DailyUsageEntry>>(
            "dailyUsage",
          ),
          "dailyUsage",
        ),
        safeLoad(
          persistence.loadSetting<any[]>("scheduledTasks"),
          "scheduledTasks",
        ),
        safeLoad(
          persistence.loadSetting<Record<string, McpServerConfig>>(
            "mcpServers",
          ),
          "mcpServers",
        ),
        safeLoad(
          persistence.loadSetting<
            Record<
              string,
              { keys: string[]; action: string; description: string }
            >
          >("customShortcuts"),
          "customShortcuts",
        ),
        safeLoad(
          persistence.loadSetting<string[]>("customizedShortcutIds"),
          "customizedShortcutIds",
        ),
        safeLoad(
          persistence.loadSetting<number>("agentMaxIterations"),
          "agentMaxIterations",
        ),
        safeLoad(
          persistence.loadSetting<boolean>("autoCompactContext"),
          "autoCompactContext",
        ),
        safeLoad(
          persistence.loadSetting<boolean>("autoSaveSession"),
          "autoSaveSession",
        ),
        safeLoad(
          persistence.loadSetting<string[]>("availableModels"),
          "availableModels",
        ),
        safeLoad(
          persistence.loadSetting<Record<string, string[]>>("providerModels"),
          "providerModels",
        ),
        safeLoad(
          persistence.loadSetting<string>("reasoningEffort"),
          "reasoningEffort",
        ),
        safeLoad(persistence.loadSetting<string>("personality"), "personality"),
        safeLoad(persistence.loadSetting<boolean>("fastMode"), "fastMode"),
        safeLoad(
          persistence.loadSetting<"auto" | "cmd" | "pwsh" | "powershell">(
            "terminalShell",
          ),
          "terminalShell",
        ),
        safeLoad(persistence.loadSetting<string>("editorTheme"), "editorTheme"),
        safeLoad(
          persistence.loadSetting<boolean>("gitAutoCommit"),
          "gitAutoCommit",
        ),
        safeLoad(
          persistence.loadSetting<boolean>("gitAutoPush"),
          "gitAutoPush",
        ),
        safeLoad(
          persistence.loadSetting<boolean>("gitPushConfirm"),
          "gitPushConfirm",
        ),
        safeLoad(
          persistence.loadSetting<boolean>("gitAutoBranch"),
          "gitAutoBranch",
        ),
        safeLoad(
          persistence.loadSetting<string>("gitRemoteUrl"),
          "gitRemoteUrl",
        ),
        safeLoad(
          persistence.loadSetting<string>("gitCommitTemplate"),
          "gitCommitTemplate",
        ),
        safeLoad(
          persistence.loadSetting<string>("gitBranchPrefix"),
          "gitBranchPrefix",
        ),
        safeLoad(
          persistence.loadSetting<string>("approvalMode"),
          "approvalMode",
        ),
        safeLoad(
          persistence.loadSetting<Record<string, ApprovalMode>>(
            "approvalModeBySession",
          ),
          "approvalModeBySession",
        ),
        safeLoad(
          persistence.loadSetting<string>("startupGreeting"),
          "startupGreeting",
        ),
        safeLoad(
          persistence.loadSetting<ProviderConfig[]>("providers"),
          "providers",
        ),
        safeLoad(
          persistence.loadSetting<string | null>("activeModel"),
          "activeModel",
        ),
        safeLoad(
          persistence.loadSetting<string | null>("activeProviderId"),
          "activeProviderId",
        ),
        safeLoad(
          persistence.loadSetting<string[]>("sessionHistory"),
          "sessionHistory",
        ),
        safeLoad(
          persistence.loadSetting<number>("sessionHistoryIndex"),
          "sessionHistoryIndex",
        ),
        safeLoad(
          persistence.loadSetting<string | null>("selectedWorkDir"),
          "selectedWorkDir",
        ),
        safeLoad(
          persistence.loadSetting<boolean>("hasOnboarded"),
          "hasOnboarded",
        ),
        safeLoad(
          persistence.loadSetting<{ size: number; used: number } | null>(
            "contextUsage",
          ),
          "contextUsage",
        ),
        safeLoad(
          persistence.loadSetting<ExternalService[]>("externalServices"),
          "externalServices",
        ),
      ]);

      // 启动时恢复上次打开的会话及其历史，模型重新建会话时会用这些消息
      // 作为 seed history，避免每次重启都像新对话一样丢失上下文。
      const defaults = {
        provider: "custom" as const,
        apiKey: "",
        baseUrl: "",
        model: "",
      };
      let defaultSessionsDir: string | null = null;
      try {
        defaultSessionsDir = await getDefaultSessionsDir();
      } catch {
        // Electron bridge unavailable — leave default empty
      }
      // Restore which named profile was active before the restart, so the selection
      // survives a cold start (the profile list itself is persisted to IndexedDB).
      const loadedActiveProfileId =
        (await safeLoad(
          persistence.loadSetting<string | null>("activeProfileId"),
          "activeProfileId",
        )) ?? null;

      // ── Build multi-provider config for the flattened model selector ──
      // Always rebuild `builtProviders` from the authoritative declared sources
      // (apiProfiles / apiConfig). We do NOT trust the persisted `providers`
      // field as a source of truth — it is a *runtime output* mirror that was
      // historically polluted by merged fetched-model lists and would re-seed
      // the pollution on every restart. The legacy apiProfiles / apiConfig
      // backfill keeps older installs working without data loss.
      //
      // SELF-HEAL for already-polluted installs: earlier builds unioned every
      // endpoint's fetched models into a single profile's `models` (via
      // handleSaveApi), so existing profiles in IndexedDB may carry models that
      // don't belong to their endpoint — which is what makes the input-bar
      // dropdown show "一堆放一起". When we have the clean per-endpoint fetched
      // list for a profile (providerModels[pid]), we treat it as authoritative
      // and REPLACE the profile's models with it (plus the profile's own
      // configured model). This scrubs cross-endpoint pollution on next restart
      // without needing the user to clear data. When no fetched list exists for a
      // profile, we leave its declared models untouched (can't verify), but the
      // fixed write path (handleSaveApi) will no longer re-pollute it.
      const deriveProviderName = (
        baseUrl?: string,
        fallback?: string,
      ): string => {
        if (!baseUrl) return fallback || "配置";
        try {
          const host = new URL(baseUrl).hostname.toLowerCase();
          if (host.includes("deepseek")) return "DeepSeek";
          if (host.includes("openai")) return "OpenAI";
          if (host.includes("anthropic")) return "Anthropic";
          if (host.includes("google")) return "Gemini";
          return host.replace(/^www\./, "") || fallback || "配置";
        } catch {
          return fallback || "配置";
        }
      };
      const cleanedProviderModels: Record<string, string[]> = {};
      for (const [pid, models] of Object.entries(providerModels || {})) {
        if (models && models.length) cleanedProviderModels[pid] = models;
      }
      const cleanProfileModels = (p: ApiProfile): string[] => {
        const own = p.config?.model ? [p.config.model] : [];
        const fetched = cleanedProviderModels[p.id] || [];
        if (fetched.length > 0) {
          return Array.from(new Set([...own, ...fetched].filter(Boolean)));
        }
        return Array.from(new Set(own.filter(Boolean)));
      };
      const builtProviders: ProviderConfig[] =
        apiProfiles && apiProfiles.length > 0
          ? apiProfiles.map((p, i) => {
              // Scrub cross-endpoint pollution; if that leaves a profile with
              // NO models, re-seed it from its own history endpoint so a
              // deepseek profile that had its models polluted by another
              // supplier's list still surfaces the correct model
              // (e.g. deepseek-v4-pro) instead of going empty.
              let models = cleanProfileModels(p);
              if (models.length === 0 && p.config?.baseUrl) {
                const histModels = Array.from(
                  new Set(
                    (apiHistory || [])
                      .filter((h) => h.baseUrl === p.config!.baseUrl && h.model)
                      .map((h) => h.model as string),
                  ),
                );
                if (histModels.length) models = histModels;
              }
              return {
                id: p.id || `p-${i}`,
                name: p.name,
                baseUrl: p.config?.baseUrl || "",
                apiKey: p.config?.apiKey || "",
                models,
                isDefault: p.id === loadedActiveProfileId,
              };
            })
          : apiConfig && apiConfig.baseUrl && apiConfig.model
            ? [
                {
                  id: "p-default",
                  name: apiConfig.provider || "default",
                  baseUrl: apiConfig.baseUrl,
                  apiKey: apiConfig.apiKey,
                  models: [apiConfig.model],
                  isDefault: true,
                },
              ]
            : [];
      // ── Include history-only endpoints as providers ──
      // An endpoint the user has only ever used via "添加模型" (landing in
      // apiHistory) but never saved as an apiProfile has NO provider entry. On
      // restoreFromStorage the persisted activeModel then can't be validated by
      // any provider and silently falls back to the default provider's first
      // model (e.g. Ling) — so clicking a deepseek/kimi history item appears to
      // "switch to Ling" after a refresh. Synthesize a provider for every
      // history endpoint not already covered by a named profile, so the active
      // model stays pinned to the endpoint it belongs to.
      const historyProviders: ProviderConfig[] = [];
      {
        const seenBase = new Set(builtProviders.map((p) => p.baseUrl));
        const hist = (apiHistory || []) as Array<{
          baseUrl?: string;
          apiKey?: string;
          model?: string;
          provider?: string;
        }>;
        // Single O(n) pass: group history entries by endpoint instead of the old
        // O(n²) approach that re-filtered the whole list per unique baseUrl.
        const byBase = new Map<
          string,
          { apiKey: string; provider?: string; models: Set<string> }
        >();
        for (const h of hist) {
          if (!h.baseUrl || !h.model) continue;
          if (seenBase.has(h.baseUrl)) continue;
          let entry = byBase.get(h.baseUrl);
          if (!entry) {
            entry = {
              apiKey: h.apiKey || "",
              provider: h.provider,
              models: new Set<string>(),
            };
            byBase.set(h.baseUrl, entry);
            seenBase.add(h.baseUrl);
          }
          entry.models.add(h.model);
        }
        for (const [baseUrl, entry] of byBase) {
          historyProviders.push({
            id: `hist-${historyProviders.length}`,
            name:
              deriveProviderName(baseUrl, entry.provider) ||
              entry.provider ||
              "配置",
            baseUrl,
            apiKey: entry.apiKey,
            models: Array.from(entry.models),
            isDefault: false,
          });
        }
      }
      const allBuiltProviders = [...builtProviders, ...historyProviders];
      // Merge the persisted per-provider fetched model lists (providerModels)
      // into each provider's candidate `models` pool. This keeps a single source
      // of truth so a model selected from "获取模型列表" survives a cold restart:
      // without it, `activeModel` would be rejected by the check below (not in
      // `providers[].models`) and silently fall back to the default model.
      const mergedProviders: ProviderConfig[] = allBuiltProviders.map((p) => {
        const fetched = cleanedProviderModels[p.id];
        if (fetched && fetched.length > 0) {
          const models = Array.from(new Set([...p.models, ...fetched]));
          return { ...p, models };
        }
        return p;
      });
      // Canonical restore logic: the active model is whatever IndexedDB persisted
      // as `activeModel`. If that model is not declared by any provider, fall
      // back to the default provider's first model.
      // Honor the persisted active model even when it is only present in a
      // fetched list (providerModels) and not in the declared `models[]` yet —
      // e.g. a model picked from "获取模型列表". The previous logic dropped it
      // back to the default provider's `models[0]` (deepseek-v4-pro) whenever
      // the fetched list hadn't hydrated at restore time, which reverted every
      // launch to pro. Keeping the user's explicit choice here is safe.
      const builtActiveModel: string | null =
        // 以用户最后选择的 activeModel 为准；profile 只在没有 activeModel 时兜底，
        // 避免“手动选了新模型，重启后又被 profile 里的旧模型覆盖”。
        (() => {
          if (activeModel) return activeModel;
          if (loadedActiveProfileId) {
            const prof = (apiProfiles || []).find(
              (p) => p.id === loadedActiveProfileId,
            );
            if (prof?.config?.model) return prof.config.model;
          }
          return mergedProviders.length > 0
            ? mergedProviders.find(
                (p) => p.isDefault && (p.models?.length || 0) > 0,
              )?.models[0] ||
                mergedProviders.find((p) => (p.models?.length || 0) > 0)
                  ?.models[0] ||
                null
            : null;
        })();
      // Resolve the active provider: prefer the owner of the active model, then
      // a saved id that still exists (only when it agrees with that owner or the
      // model has no clear owner), then the default/first provider.
      const builtActiveProviderId: string | null = (() => {
        // Re-anchor to the active model's OWNER first. A saved activeProviderId
        // can be stale — handleSaveApi/applyProfile used to sync activeModel
        // without re-anchoring it, leaving the id pointing at an older provider
        // (e.g. an older provider) while the active model belongs to another
        // endpoint (e.g. DeepSeek). The stale id then scoped providerModels writes and the chat
        // dropdown's open-refetch to the WRONG endpoint, collapsing the fetched
        // list to the single declared model. Trusting the saved id only when it
        // points at the same endpoint as the model owner keeps them in lockstep.
        if (builtActiveModel) {
          const owner = mergedProviders.find((p) =>
            p.models.includes(builtActiveModel),
          );
          if (owner) {
            if (!activeProviderId) return owner.id;
            const saved = mergedProviders.find(
              (p) => p.id === activeProviderId,
            );
            if (!saved || saved.baseUrl === owner.baseUrl) return owner.id;
            warn(
              "[restoreFromStorage] activeProviderId stale, re-anchoring to model owner:",
              activeProviderId,
              "→",
              owner.id,
            );
            return owner.id;
          }
          // Fallback: locate the owner via providerModels when the model isn't
          // present in the merged declared+fetched pool (e.g. providerModels
          // loaded but not yet merged), so the active provider scope stays
          // correct instead of drifting to the default/first provider.
          for (const p of mergedProviders) {
            if ((providerModels?.[p.id] || []).includes(builtActiveModel))
              return p.id;
          }
        }
        if (
          activeProviderId &&
          mergedProviders.some((p) => p.id === activeProviderId)
        ) {
          return activeProviderId;
        }
        return (
          mergedProviders.find((p) => p.isDefault)?.id ||
          mergedProviders[0]?.id ||
          null
        );
      })();

      // Prune sessionHistory: remove IDs that no longer exist in IndexedDB
      const validSessionIds = new Set(sessions.map((s) => s.id));
      const prunedHistory = Array.isArray(savedSessionHistory)
        ? savedSessionHistory.filter((id) => validSessionIds.has(id))
        : [];
      const prunedIndex =
        savedSessionHistoryIndex != null &&
        savedSessionHistoryIndex < prunedHistory.length
          ? savedSessionHistoryIndex
          : prunedHistory.length - 1;
      const restoredSessionId = latestSession?.id ?? null;
      const restoredHistory =
        latestSession && !prunedHistory.includes(latestSession.id)
          ? [latestSession.id, ...prunedHistory]
          : prunedHistory;
      const restoredIndex = latestSession
        ? prunedHistory.includes(latestSession.id)
          ? prunedIndex
          : 0
        : prunedIndex;

      // 恢复导航栈：优先用持久化的 navigationHistory/navigationIndex（含
      // 设置页条目）；旧版本/缺失时用 sessionHistory 重建 chat-only 栈。
      const [savedNavHistory, savedNavIndex] = await Promise.all([
        safeLoad(
          persistence.loadSetting<
            Array<
              | { type: "chat"; sessionId: string }
              | { type: "settings"; page: string }
            >
          >("navigationHistory"),
          "navigationHistory",
        ),
        safeLoad(
          persistence.loadSetting<number>("navigationIndex"),
          "navigationIndex",
        ),
      ]);
      const navHistory =
        Array.isArray(savedNavHistory) && savedNavHistory.length > 0
          ? savedNavHistory
          : restoredHistory.map((id) => ({
              type: "chat" as const,
              sessionId: id,
            }));
      const navIndex =
        typeof savedNavIndex === "number" &&
        savedNavIndex >= 0 &&
        Array.isArray(savedNavHistory) &&
        savedNavHistory.length > 0
          ? savedNavIndex
          : restoredIndex;
      get().restoreNavigation(navHistory, navIndex, validSessionIds);

      set({
        // memories are global and owned by the Helix backend (memories/MEMORY.md);
        // do NOT overwrite them from a per-session snapshot.
        tasks: tasks as TaskNode[],
        checkpoints: checkpoints as SessionCheckpoint[],
        notes: notes || "",
        goal: goal,
        // 恢复上次打开的会话和它的历史，避免重启后模型/界面都变成新对话。
        currentSessionId: restoredSessionId,
        activeSessionWorkDir: latestSession?.workDir ?? null,
        sessionHistory: restoredHistory,
        sessionHistoryIndex: restoredIndex,
        // 没选项目时默认使用 Helix sessions 目录；恢复会话时跟随会话自己的目录。
        selectedWorkDir: latestSession?.workDir ?? defaultSessionsDir,
        // Never downgrade a fresh true set while restore was still loading.
        // Startup renders from the default false before IndexedDB finishes;
        // clicking "skip/start" in that window must not be overwritten by the
        // stale restored false.
        hasOnboarded: get().hasOnboarded || loadedHasOnboarded === true,
        apiConfig: (() => {
          const resolve = (cfg: any) => {
            // Validation gate: reject stale/bad profiles so a poisoned IndexedDB
            // entry can never re-enter the store and get pushed to Helix.
            if (!cfg || !cfg.baseUrl) {
              return { ...defaults };
            }
            const merged = { ...defaults, ...cfg };
            return merged;
          };
          // Prefer the active provider built from providers/activeModel — this is
          // what the model selector treats as current, so apiConfig must agree.
          const activeProv = builtActiveProviderId
            ? mergedProviders.find((p) => p.id === builtActiveProviderId)
            : undefined;
          if (activeProv && activeProv.baseUrl) {
            return resolve({
              provider: activeProv.name,
              baseUrl: activeProv.baseUrl,
              apiKey: activeProv.apiKey,
              model:
                builtActiveModel ||
                activeProv.models[0] ||
                activeProv.defaultModel ||
                "",
            });
          }
          if (loadedActiveProfileId) {
            const prof = (apiProfiles || []).find(
              (p) => p.id === loadedActiveProfileId,
            );
            if (prof && prof.config) {
              return resolve(prof.config);
            }
          }
          const p = apiConfig;
          if (!p || !p.baseUrl) {
            return { ...defaults };
          }
          return resolve(p);
        })(),
        apiHistory: (() => {
          const raw = apiHistory || [];
          // Deduplicate by baseUrl + apiKey: one CONFIG is one history entry
          // (the list groups by baseUrl and entries within a group differ by
          // apiKey). Model changes on the same connection update that entry in
          // place, so persisted duplicates from older builds — several entries
          // with the same endpoint+key but different models — collapse here.
          // The list is ordered most-recent-first, so the first occurrence kept
          // is the newest model for that config.
          const seen = new Set<string>();
          const normKey = (k?: string) => (k ?? "").trim();
          return raw.filter((h) => {
            if (!h.model || !h.baseUrl) return false;
            const key = `${h.baseUrl}|${normKey(h.apiKey)}`;
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
          });
        })(),
        apiProfiles: (() => {
          const loaded = apiProfiles || [];
          if (loaded.length > 0) {
            // Backfill + SELF-HEAL models[] for existing profiles. We reuse
            // cleanProfileModels() so a profile's models are scrubbed of
            // cross-endpoint pollution (using providerModels[pid] when present)
            // and rewritten to IndexedDB below via persistToStorage on the next
            // save — permanently removing "一堆放一起" without user action.
            return loaded.map((p) => ({
              ...p,
              models: cleanProfileModels(p),
            }));
          }
          if (apiHistory && apiHistory.length > 0) {
            // Group history entries by baseUrl so each endpoint becomes its own
            // provider. This prevents a single "配置 · xxx" profile from owning
            // models that clearly belong to different endpoints (e.g. Kimi and
            // DeepSeek models mixed together after repeated saves).
            const groups = new Map<string, typeof apiHistory>();
            for (const h of apiHistory) {
              const key = h.baseUrl || `unknown-${groups.size}`;
              if (!groups.has(key)) groups.set(key, []);
              groups.get(key)!.push(h);
            }
            return Array.from(groups.entries()).map(([baseUrl, entries], i) => {
              const primary = entries[0];
              const models = Array.from(
                new Set(entries.map((h) => h.model).filter(Boolean)),
              );
              return {
                id: generateId(),
                name: deriveProviderName(baseUrl, `配置 ${i + 1}`),
                config: { ...defaults, ...primary },
                models,
              };
            });
          }
          return [];
        })(),
        // Multi-provider config backing the flattened model selector.
        // Write `mergedProviders` (declared + per-provider fetched) so that each
        // provider's `models` array survives a restart even if `providerModels`
        // fails to load. Without this, `cleanProfileModels` falls back to
        // [config.model] (1 item) when no fetched list exists, and the model
        // dropdown shows only one model after every restart.
        // The merge is strictly per-provider (providerModels[p.id] → provider p),
        // so there is NO cross-endpoint pollution.
        providers: mergedProviders,
        activeModel: builtActiveModel,
        activeProviderId: builtActiveProviderId,
        activeProfileId: (() => {
          const id = loadedActiveProfileId;
          if (!id) return null;
          const prof = (apiProfiles || []).find((p) => p.id === id);
          if (!prof) return null;
          return id;
        })(),
        chatMessages: (latestSession?.chatMessages ?? []).map((m) => ({
          ...m,
          role: m.role as "user" | "assistant" | "system",
          isStreaming: !!m.isStreaming,
        })),
        files: get().files,
        openTabs: get().openTabs,
        fontFamily:
          fontFamily ||
          (typeof localStorage !== "undefined"
            ? localStorage.getItem("helix-font-family")
            : null) ||
          get().fontFamily,
        fontSize:
          fontSize ||
          (typeof localStorage !== "undefined"
            ? Number(localStorage.getItem("helix-font-size")) || get().fontSize
            : get().fontSize),
        interfaceFont:
          interfaceFont ||
          (typeof localStorage !== "undefined"
            ? localStorage.getItem("helix-interface-font")
            : null) ||
          get().interfaceFont,
        transcriptFontSize:
          transcriptFontSize ||
          (typeof localStorage !== "undefined"
            ? Number(localStorage.getItem("helix-transcript-size")) ||
              get().transcriptFontSize
            : get().transcriptFontSize),
        themeStyle:
          themeStyle ||
          (typeof localStorage !== "undefined"
            ? localStorage.getItem("helix-theme-style")
            : null) ||
          get().themeStyle,
        sessionUsageStats:
          sessionUsageStats &&
          typeof sessionUsageStats === "object" &&
          typeof (sessionUsageStats as { requestCount?: unknown })
            .requestCount === "number"
            ? // Restore the persisted cumulative token stats verbatim. Previously a
              // "one-time migration" gated this on dailyUsage having a `models`
              // subfield; that wrongly discarded valid historical stats whenever
              // dailyUsage was empty or predated per-model tracking, so the panel
              // showed "尚未获取到用量数据" after every cold restart. Cumulative
              // usage is inherently persistent, so we keep it whenever it was saved.
              sessionUsageStats
            : {
                requestCount: 0,
                totalTokens: 0,
                inputTokens: 0,
                outputTokens: 0,
                thoughtTokens: 0,
                cachedReadTokens: 0,
                cachedWriteTokens: 0,
              },
        // Rehydrate the last persisted context-window usage snapshot so the
        // indicator no longer resets to zero on every cold start. The backend
        // does not report a session's accumulated token count on launch and the
        // in-memory field is only refreshed by runtime events, so we persist it
        // (see setContextUsage / persistToStorage) and restore it here. A fresh
        // `message.complete` from the backend overwrites it with the live value.
        contextUsage:
          contextUsage &&
          typeof contextUsage === "object" &&
          !Array.isArray(contextUsage)
            ? (contextUsage as unknown as Record<
                string,
                { size: number; used: number }
              >)
            : {},
        dailyUsage:
          dailyUsage &&
          typeof dailyUsage === "object" &&
          Object.keys(dailyUsage).length > 0
            ? // Restore the persisted daily breakdown verbatim. The old `hasDailyModels`
              // gate dropped every day entry that lacked the newer `models` subfield,
              // which silently emptied the chart on restart for pre-per-model data.
              dailyUsage
            : {},
        scheduledTasks: (scheduledTasks as ScheduledTask[]) || [],
        mcpServers: {
          ...fileMcpConfig,
          ...(mcpServers || {}),
        },
        externalServices: (externalServices || []).filter(
          (s) => s && typeof s.id === "string" && typeof s.host === "string",
        ),
        customShortcuts: (() => {
          const customizedIds = new Set(customizedIdsArr || []);
          const defaults = { ...DEFAULT_SHORTCUTS };
          if (customShortcuts && Object.keys(customShortcuts).length > 0) {
            // Only apply shortcuts the user actually customized;
            // new defaults always take effect for the rest.
            for (const id of Object.keys(customShortcuts)) {
              if (customizedIds.has(id)) {
                defaults[id] = customShortcuts[id];
              }
            }
          }
          return defaults;
        })(),
        customizedShortcutIds: new Set(customizedIdsArr || []),
        agentMaxIterations: agentMaxIterations ?? get().agentMaxIterations,
        autoCompactContext: autoCompactContext ?? get().autoCompactContext,
        autoSaveSession: autoSaveSession ?? get().autoSaveSession,
        reasoningEffort: (reasoningEffort as any) || get().reasoningEffort,
        personality: personality || get().personality,
        fastMode: fastMode ?? get().fastMode,
        terminalShell:
          terminalShell === "cmd" ||
          terminalShell === "pwsh" ||
          terminalShell === "powershell"
            ? terminalShell
            : "auto",
        availableModels: availableModels || [],
        providerModels: cleanedProviderModels,
        editorTheme:
          (editorTheme as "vs-dark" | "light" | null | undefined) ??
          get().editorTheme,
        gitAutoCommit: gitAutoCommit ?? get().gitAutoCommit,
        gitAutoPush: gitAutoPush ?? get().gitAutoPush,
        gitPushConfirm: gitPushConfirm ?? get().gitPushConfirm,
        gitAutoBranch: gitAutoBranch ?? get().gitAutoBranch,
        gitRemoteUrl: gitRemoteUrl || get().gitRemoteUrl,
        gitCommitTemplate: gitCommitTemplate || get().gitCommitTemplate,
        gitBranchPrefix: gitBranchPrefix || get().gitBranchPrefix,
        approvalMode: (approvalMode as any) || get().approvalMode,
        approvalModeBySession:
          approvalModeBySession ?? get().approvalModeBySession,
        startupGreeting: startupGreeting || get().startupGreeting,
        browserHomeUrl: "",
      });

      // Permanently scrub the pollution from IndexedDB: write back the cleaned
      // apiProfiles and the unpolluted providers list. Without this, the on-disk
      // copies keep the old jumbled `models` and only the in-memory state would be
      // clean until the next write. Doing it here makes the "一堆放一起" fix stick
      // after a single restart, with no manual data clearing required.
      try {
        const healed = get();
        // Skip the redundant IndexedDB writes when nothing actually changed.
        // After the first "heal" restart the on-disk data is already clean, so
        // re-writing identical blobs on every subsequent startup is pure I/O.
        const prevModels = providerModels || {};
        // A stale persisted activeProviderId (pointing at a different endpoint
        // than the active model's owner) is healed by builtActiveProviderId
        // above; write the corrected value back so the next cold start doesn't
        // have to re-heal it and doesn't scope fetches to the wrong provider.
        const healedActiveProviderId = healed.activeProviderId;
        const providerIdChanged = healedActiveProviderId !== activeProviderId;
        const changed =
          JSON.stringify(healed.apiProfiles) !==
            JSON.stringify(apiProfiles || []) ||
          JSON.stringify(healed.providers) !==
            JSON.stringify(providers || []) ||
          JSON.stringify(cleanedProviderModels) !==
            JSON.stringify(prevModels) ||
          providerIdChanged;
        if (changed) {
          await persistence.saveSetting("apiProfiles", healed.apiProfiles);
          await persistence.saveSetting("providers", healed.providers);
          await persistence.saveSetting(
            "providerModels",
            cleanedProviderModels,
          );
          if (providerIdChanged && healedActiveProviderId !== null) {
            await persistence.saveSetting(
              "activeProviderId",
              healedActiveProviderId,
            );
          }
        }
      } catch (persistErr) {
        logError("Failed to persist healed model lists:", persistErr);
      }

      // Auto-detect AGENTS.md / CLAUDE.md from project root as fallback
      // Custom instructions are now managed by Helix
      // No local API call needed

      // Set default workDir from the main process (not renderer process.cwd(),
      // which can resolve to a bare drive root like D:\).
      const currentDir = get().selectedWorkDir;
      const isDriveRoot =
        typeof currentDir === "string" && /^[a-zA-Z]:[\\/]?$/.test(currentDir);
      if (
        !currentDir ||
        currentDir === "/" ||
        currentDir === "\\" ||
        isDriveRoot
      ) {
        const fallbackDir = await getDefaultSessionsDir();
        let info = { workDir: fallbackDir };
        if (isElectron()) {
          try {
            info = await electronApp.getInfo();
          } catch {
            /* fall through to fallbackDir */
          }
        }
        set({ selectedWorkDir: info.workDir || fallbackDir });
      }

      // Re-apply font CSS variables after restore so the DOM matches the
      // persisted values (not the static defaults that ship with the bundle).
      const s = useHelixStore.getState();
      document.documentElement.style.setProperty(
        "--helix-font-family",
        s.fontFamily,
      );
      document.body.style.fontFamily = s.fontFamily;
      document.documentElement.style.setProperty(
        "--helix-font-size",
        `${s.fontSize}px`,
      );
      document.documentElement.style.setProperty(
        "--helix-interface-font",
        s.interfaceFont,
      );
      document.documentElement.style.setProperty(
        "--helix-transcript-size",
        `${s.transcriptFontSize}px`,
      );
    } catch (e) {
      logError("Failed to restore:", e);
      get().showToast({
        type: "error",
        title: "数据恢复失败",
        description: "本地存储读取异常，部分设置可能未加载",
      });
    }
  },

  saveCheckpointChat: async () => {
    try {
      const { persistence } = await import("@/lib/persist");
      const state = get();
      const sessionId = "checkpoint-" + Date.now();
      const messages = state.chatMessages;
      if (messages.length === 0) return;
      await persistence.saveChatMessages(
        messages.map((m) => ({
          id: m.id,
          sessionId,
          role: m.role,
          content: m.content,
          timestamp: m.timestamp,
          isStreaming: false,
          duration: m.duration,
          thinkingTime: m.thinkingTime,
          totalTokens: m.totalTokens,
        })),
        sessionId,
      );
    } catch (e) {
      logError("Failed to save checkpoint:", e);
    }
  },

  // Helpers
  getAllFiles: () => {
    const result: FileNode[] = [];
    const collect = (nodes: FileNode[]) => {
      for (const n of nodes) {
        if (n.type === "file") result.push(n);
        if (n.children) collect(n.children);
      }
    };
    collect(get().files);
    return result;
  },

  getFilePath: (fileId) => {
    const findPath = (nodes: FileNode[], path: string[]): string | null => {
      for (const n of nodes) {
        const currentPath = [...path, n.name];
        if (n.id === fileId) return currentPath.join("/");
        if (n.children) {
          const found = findPath(n.children, currentPath);
          if (found) return found;
        }
      }
      return null;
    };
    return findPath(get().files, []) || "";
  },

  findFileByPath: (path) => {
    const segments = path.split("/");
    const fileName = segments.pop();
    let nodes = get().files;
    for (const seg of segments) {
      const folder = nodes.find((n) => n.type === "folder" && n.name === seg);
      if (!folder?.children) return null;
      nodes = folder.children;
    }
    return nodes.find((n) => n.name === fileName) || null;
  },

  getMemoryContext: () => {
    const state = get();
    if (state.memories.length === 0 && !state.notes) return "";
    let ctx = "\n\n--- 项目记忆 ---\n";
    if (state.memories.length > 0) {
      ctx += "项目知识：\n";
      state.memories.forEach((m) => {
        ctx += `  [${m.category}] ${m.content}\n`;
      });
    }
    if (state.notes) {
      ctx += `\n会话笔记：\n${state.notes}\n`;
    }
    return ctx;
  },

  getTaskContext: () => {
    const state = get();
    if (state.tasks.length === 0 && state.subAgents.length === 0) return "";
    let ctx = "\n--- 当前任务 ---\n";
    const renderTasks = (tasks: TaskNode[], prefix = "") => {
      for (const t of tasks) {
        const statusIcon =
          t.status === "done"
            ? ""
            : t.status === "in_progress"
              ? ""
              : t.status === "blocked"
                ? ""
                : "";
        ctx += `${prefix}${statusIcon} ${t.label}\n`;
        if (t.children) renderTasks(t.children, prefix + "  ");
      }
    };
    renderTasks(state.tasks);
    if (state.goal) {
      ctx += `\n目标: ${state.goal}\n`;
    }
    // Sub-agent context
    if (state.subAgents.length > 0) {
      ctx += "\n--- 子 Agent 状态 ---\n";
      for (const a of state.subAgents) {
        const statusIcon =
          a.status === "running"
            ? ""
            : a.status === "completed"
              ? ""
              : a.status === "failed"
                ? ""
                : "";
        ctx += `${statusIcon} ${a.name}: ${a.description}\n`;
        if (a.result && a.status === "completed") {
          ctx += `   结果: ${a.result.slice(0, 200)}\n`;
        }
      }
    }
    return ctx;
  },
}));

/**
 * API configuration slice — provider, model, profiles, history.
 */
import type { StateCreator } from "zustand";
import type { ApiConfig, ApiProfile, ProviderConfig } from "../helix-types";
import { generateId } from "@/lib/format";
import { warn } from "@/lib/logger";

/** Provider ids currently auto-fetching their model lists (in-flight guard). */
const fetchingProviderModels = new Set<string>();

export interface ApiConfigSlice {
  apiConfig: ApiConfig;
  apiHistory: ApiConfig[];
  apiProfiles: ApiProfile[];
  activeProfileId: string | null;
  availableModels: string[];
  /** Base URL the current `availableModels` was fetched from (provenance tag,
   *  so the model dropdown never mixes one provider's models into another). */
  availableModelsBaseUrl: string | null;
  /** Per-provider fetched model lists. Key = provider id. Clicking "获取模型列表"
   *  for a provider stores its models here, so switching providers automatically
   *  shows that provider's own list — no global cross-provider mixing. */
  providerModels: Record<string, string[]>;
  /** Multi-provider config backing the flattened model selector. */
  providers: ProviderConfig[];
  /** Currently selected model name (flat list item), */
  activeModel: string | null;
  /** The provider currently active in the model selector. The model dropdown
   *  shows ONLY this provider's models (requirement: no cross-provider mixing).
   *  Kept in sync with `activeModel` — whenever a model is selected, this is
   *  updated to the provider that owns it. */
  activeProviderId: string | null;
  setAvailableModels: (
    models: string[],
    baseUrl?: string,
    providerId?: string,
  ) => void;
  setApiConfig: (config: Partial<ApiConfig>) => void;
  getApiConfig: () => ApiConfig;
  /** Find which profile owns a given model name (reverse-lookup). */
  findProfileByModel: (model: string) => ApiProfile | undefined;
  addApiHistory: (config: ApiConfig) => void;
  removeApiHistory: (index: number) => void;
  selectApiHistory: (index: number) => void;
  addApiProfile: (name: string, config: ApiConfig, models?: string[]) => string;
  updateApiProfileConfig: (
    id: string,
    config: ApiConfig,
    models?: string[],
  ) => void;
  renameApiProfile: (id: string, name: string) => void;
  removeApiProfile: (id: string) => void;
  setActiveProfile: (id: string | null) => void;
  // ── Multi-provider actions ──
  /** Reverse-lookup the provider owning `model` and resolve the active config. */
  resolveActiveApiConfig: () => ApiConfig | null;
  /** Select a model: updates activeModel + mirrors the resolved config into apiConfig. */
  setActiveModel: (model: string) => void;
  /** Fetch a provider's model list from its endpoint and cache it (providerModels).
   *  No-op / resolves [] when the provider lacks baseUrl+apiKey or a fetch is
   *  already in flight. Used for auto-populating the model dropdown on switch. */
  fetchProviderModels: (providerId: string) => Promise<string[]>;
  /** Drop the cached fetched model list for a provider so the next open of the
   *  model selector re-fetches live instead of relying on a possibly-stale
   *  persisted list. Called on save to keep stored config free of a stale list. */
  clearProviderModels: (providerId: string) => void;
  /** Switch the active provider. If the current model doesn't belong to the new
   *  provider, reselect its defaultModel (or models[0]). Mirrors the new
   *  provider's credentials + model into apiConfig. */
  setActiveProvider: (id: string) => void;
  /** Create or update a provider (used by the Provider settings editor). */
  upsertProvider: (
    input: Omit<ProviderConfig, "id"> & { id?: string },
  ) => string;
  /** Remove a provider; reselects activeModel if it belonged to the removed one. */
  removeProvider: (id: string) => void;
  /**
   * Unified handler invoked by the model selector on switch.
   * 1) sets activeModel (which re-resolves apiConfig so Helix uses the new key);
   * 2) interrupts any in-flight session via session/cancel so the next prompt
   *    is built on a fresh session (use-helix detects the apiConfig hash change
   *    and repushes config + recreates the session).
   */
  onModelSwitched: (model: string) => void;
}

export const createApiConfigSlice: StateCreator<
  ApiConfigSlice,
  [],
  [],
  ApiConfigSlice
> = (set, get) => ({
  apiConfig: {
    provider: "custom",
    apiKey: "",
    baseUrl: "",
    model: "",
  },
  apiHistory: [],
  apiProfiles: [],
  activeProfileId: null,
  availableModels: [],
  availableModelsBaseUrl: null,
  providerModels: {},
  providers: [],
  activeModel: null,
  activeProviderId: null,

  setAvailableModels: (models, baseUrl, providerId) => {
    // Resolve the provider id that scopes this fetched list. Priority:
    // explicit param → match by baseUrl → active provider. This guarantees
    // the saved key equals what the model selector reads (providerModels[pid]
    // where pid === activeProvider.id), so the list survives a restart.
    // baseUrl MUST be preferred over activeProviderId: the latter can be stale
    // (handleSaveApi/applyProfile don't always re-anchor it), and keying the
    // fetched list under the wrong provider hides those models from the
    // selector — the "获取到 2 个模型，切换后只剩 1 个" bug.
    const resolvePid = (state: any): string | undefined => {
      if (providerId) return providerId;
      if (baseUrl) {
        const match = state.providers.find((p: any) => p.baseUrl === baseUrl);
        if (match) return match.id;
      }
      if (state.activeProviderId) return state.activeProviderId;
      return undefined;
    };
    set((state) => {
      const pid = resolvePid(state);
      // Only overwrite the fetched list when we actually have models. An empty
      // array is a "reset display" signal (e.g. switching providers / profiles)
      // and must NOT wipe the persisted fetched list, or it would be lost on the
      // next persistToStorage / restart.
      const providerModels =
        pid && models.length > 0
          ? { ...state.providerModels, [pid]: models }
          : state.providerModels;
      // NOTE: We intentionally do NOT merge fetched models into
      // providers[].models here. The provider's `models` field is the
      // *declared* list (static); providerModels[pid] is the *fetched*
      // list (dynamic, per-endpoint). Merging them would pollute a
      // single provider's model array with models from unrelated
      // endpoints whenever the caller reuses activeProviderId as the
      // key — which is exactly what caused "all models from every
      // supplier showing in one dropdown". Instead, keep them separate
      // and consult providerModels at read-time (setActiveModel /
      // resolveActiveApiConfig / restoreFromStorage).
      return {
        availableModels: models,
        availableModelsBaseUrl: baseUrl ?? null,
        providerModels,
      };
    });
    import("@/lib/persist").then(({ persistence }) => {
      persistence.saveSetting("availableModels", models);
      // Persist the per-provider fetched model lists so they survive a restart.
      // Without this, `providerModels` resets to {} on every cold start and the
      // selector falls back to the single `config.model`, forcing the user to
      // re-click "获取模型列表" after each restart.
      const pid = resolvePid(get());
      if (pid && models.length > 0) {
        const next = { ...get().providerModels, [pid]: models };
        persistence.saveSetting("providerModels", next);
      }
    });
  },

  setApiConfig: (config) =>
    set((state) => {
      const apiConfig = { ...state.apiConfig, ...config };
      // Keep the target endpoint's provider credentials in sync with manual
      // edits from settings. We match by apiConfig.baseUrl, NOT by the previous
      // activeModel. Using activeModel would rewrite the provider that owns the
      // old model  to the new endpoint URL, polluting its
      // baseUrl and causing the dropdown to keep showing the old supplier's
      // models while the button shows the new model name.
      let providers = state.providers;
      if (apiConfig.baseUrl) {
        providers = providers.map((p) =>
          p.baseUrl === apiConfig.baseUrl
            ? { ...p, apiKey: apiConfig.apiKey }
            : p,
        );
      }
      return { apiConfig, providers };
    }),
  getApiConfig: () => get().apiConfig,

  findProfileByModel: (model) => {
    return get().apiProfiles.find(
      (p) => (p.models || []).includes(model) || p.config.model === model,
    );
  },

  addApiHistory: (config) =>
    set((state) => {
      // A history entry represents one CONFIG = baseUrl + apiKey (the list is
      // grouped by baseUrl, with entries inside a group differing by apiKey).
      // Switching models on the SAME connection must NOT create a new entry —
      // it updates that config's model in place. Dedup by baseUrl + apiKey.
      // Normalize empty/undefined values so they collapse together.
      const normKey = (k?: string) => (k ?? "").trim();
      const dupIndex = state.apiHistory.findIndex(
        (h) =>
          h.baseUrl === config.baseUrl &&
          normKey(h.apiKey) === normKey(config.apiKey),
      );
      if (dupIndex !== -1) {
        // Same connection → update the entry's model/provider to the latest
        // selection and move it to the front (most recently used).
        const updated = { ...state.apiHistory[dupIndex], ...config };
        const rest = state.apiHistory.filter((_, i) => i !== dupIndex);
        return { apiHistory: [updated, ...rest].slice(0, 20) };
      }
      const newHistory = [config, ...state.apiHistory].slice(0, 20);
      return { apiHistory: newHistory };
    }),

  removeApiHistory: (index) =>
    set((state) => ({
      apiHistory: state.apiHistory.filter((_, i) => i !== index),
    })),

  selectApiHistory: (index) =>
    set((state) => {
      const config = state.apiHistory[index];
      if (!config) return state;
      return { apiConfig: { ...config } };
    }),

  addApiProfile: (name, config, models?) => {
    const id = generateId();
    set((state) => ({
      apiProfiles: [...state.apiProfiles, { id, name, config, models }],
    }));
    return id;
  },
  updateApiProfileConfig: (id, config, models?) =>
    set((state) => ({
      apiProfiles: state.apiProfiles.map((p) =>
        p.id === id ? { ...p, config, ...(models ? { models } : {}) } : p,
      ),
    })),
  renameApiProfile: (id, name) =>
    set((state) => ({
      apiProfiles: state.apiProfiles.map((p) =>
        p.id === id ? { ...p, name } : p,
      ),
    })),
  removeApiProfile: (id) =>
    set((state) => ({
      apiProfiles: state.apiProfiles.filter((p) => p.id !== id),
      activeProfileId:
        state.activeProfileId === id ? null : state.activeProfileId,
    })),
  setActiveProfile: (id) => set({ activeProfileId: id }),

  // ── Multi-provider actions ──
  resolveActiveApiConfig: () => {
    const { activeModel, providers, providerModels } = get();
    if (!activeModel) return null;
    const provider =
      providers.find((p) => p.models.includes(activeModel)) ||
      providers.find((p) => (providerModels[p.id] || []).includes(activeModel));
    if (!provider) return null;
    return {
      provider: provider.name,
      apiKey: provider.apiKey,
      baseUrl: provider.baseUrl,
      model: activeModel,
    };
  },

  setActiveModel: (model) => {
    const providers = get().providers;
    // A model may live in the fetched per-provider list (providerModels[pid])
    // rather than the provider's declared `models` array — e.g. after "获取模型列表".
    // Resolve the owning provider from BOTH sources so selecting a fetched model
    // works instead of silently no-op'ing (which made the input-bar selector look
    // frozen on the previous model).
    let provider = providers.find((p) => p.models.includes(model));
    if (!provider) {
      const { providerModels, activeProviderId } = get();
      const search = (pid?: string | null) =>
        pid && providerModels[pid]?.includes(model)
          ? providers.find((p) => p.id === pid)
          : undefined;
      provider =
        search(activeProviderId) ||
        providers.find((p) => (providerModels[p.id] || []).includes(model));
    }
    if (!provider) {
      // Final fallback: match by the current backend URL for hand-typed /
      // fetched-only models that don't appear in any provider's declared
      // `models` array. We HONOR the user's explicit selection and do NOT snap
      // to a different model — that snap was the cause of "selecting
      // deepseek-v4-flash reverts to deepseek-v4-pro" when flash only lived in
      // the fetched model list (providerModels) and never in static models.
      // Credentials still come from the baseUrl-matched provider; only the model
      // name is kept exactly as chosen.
      const currentUrl = get().apiConfig?.baseUrl;
      const urlProvider = currentUrl
        ? providers.find((p) => p.baseUrl === currentUrl)
        : undefined;
      if (!urlProvider) {
        // No provider known for this endpoint at all — trust the selection and
        // mirror it straight into apiConfig without rewriting the model name.
        const fallbackId = get().apiConfig.provider || "custom";
        set({
          activeModel: model,
          activeProviderId: fallbackId,
          apiConfig: {
            ...get().apiConfig,
            model,
            baseUrl: currentUrl || get().apiConfig.baseUrl,
          },
        });
        // Record the activation into apiHistory so the settings model list can
        // highlight it. Without this, models activated through paths that bypass
        // the chat dropdown (bridge / helix-ui onModelSwitched / fallback
        // resolution) never appear in the history list — the active model is
        // selected but no entry matches it, so nothing highlights.
        get().addApiHistory({ ...get().apiConfig, model });
        import("@/lib/persist").then(({ persistence }) => {
          persistence.saveSetting("activeModel", model);
          persistence.saveSetting("activeProviderId", fallbackId);
        });
        try {
          localStorage.setItem("helix-active-model", model);
          localStorage.setItem("helix-active-provider-id", fallbackId);
        } catch { /* empty */}
        return;
      }
      // Provider resolved by baseUrl — keep `model` exactly as the user selected.
      provider = urlProvider;
    }
    if (!provider) {
      warn(
        "[api-config-slice] setActiveModel: 找不到包含模型",
        model,
        "的 Provider",
      );
      return;
    }
    // Mirror the resolved provider config into apiConfig (what Helix backend reads).
    // Keep activeProviderId in sync so the dropdown stays scoped to this provider.
    set({
      activeModel: model,
      activeProviderId: provider.id,
      apiConfig: {
        ...get().apiConfig,
        provider: provider.name,
        baseUrl: provider.baseUrl,
        apiKey: provider.apiKey,
        model,
      },
    });
    // Keep the settings model list in sync: the model just activated must show
    // up (highlighted) on the config page. addApiHistory dedups by baseUrl +
    // apiKey + model, so re-activating the same model is idempotent.
    get().addApiHistory({ ...get().apiConfig, model });
    import("@/lib/persist").then(({ persistence }) => {
      persistence.saveSetting("activeModel", model);
      persistence.saveSetting("activeProviderId", provider.id);
    });
    // Synchronous backup — if the async IndexedDB write above is still pending
    // when the app exits, we lose the last model. localStorage.setItem is
    // synchronous on the main thread, so it's a reliable fallback for the next
    // cold start.
    try {
      localStorage.setItem("helix-active-model", model);
      localStorage.setItem("helix-active-provider-id", provider.id);
    } catch { /* empty */}
    // Auto-fetch the newly-active provider's model list when we have no cached
    // copy yet, so the input-bar dropdown shows its full list without the user
    // having to open settings and click "获取模型列表".
    if (
      provider.baseUrl &&
      provider.apiKey &&
      !(get().providerModels?.[provider.id] ?? []).length
    ) {
      get().fetchProviderModels(provider.id);
    }
  },

  // ── Auto-fetch provider model lists ──────────────────────────────────────
  fetchProviderModels: async (providerId) => {
    const provider = get().providers.find((p) => p.id === providerId);
    if (!provider?.baseUrl || !provider.apiKey) return [];
    if (fetchingProviderModels.has(providerId)) {
      // Already fetching — return whatever cache we have now (the in-flight
      // fetch will update providerModels when it lands).
      return get().providerModels?.[providerId] ?? [];
    }
    fetchingProviderModels.add(providerId);
    try {
      if (
        typeof window === "undefined" ||
        !(window as any).electron?.helix?.fetchModels
      )
        return [];
      const result = await (window as any).electron.helix.fetchModels({
        baseUrl: provider.baseUrl,
        apiKey: provider.apiKey,
      });
      if (result?.error) throw new Error(result.error);
      const models = Array.isArray(result?.models)
        ? result.models.filter((m: unknown) => typeof m === "string" && m)
        : [];
      if (models.length > 0) {
        get().setAvailableModels(models, provider.baseUrl, provider.id);
      }
      return models;
    } catch (e) {
      warn("[api-config-slice] 自动获取模型失败:", provider.name, e);
      return [];
    } finally {
      fetchingProviderModels.delete(providerId);
    }
  },

  clearProviderModels: (providerId) => {
    set((state) => {
      const next = { ...state.providerModels };
      delete next[providerId];
      return { providerModels: next };
    });
  },

  setActiveProvider: (id) => {
    const provider = get().providers.find((p) => p.id === id);
    if (!provider) {
      warn("[api-config-slice] setActiveProvider: 找不到 Provider", id);
      return;
    }
    // Keep the current model if it still belongs to the new provider; otherwise
    // reselect the provider's default (or first) model. A provider with no models
    // leaves activeModel null — the UI shows the "no models" placeholder.
    // Consult the fetched list (providerModels) as well as the declared models,
    // since a model selected from "获取模型列表" may only live in providerModels.
    const cur = get().activeModel;
    const ownsModel = (pid: string, m?: string | null) =>
      !!m &&
      (provider.models.includes(m) ||
        (get().providerModels[pid] || []).includes(m));
    const keepModel = ownsModel(provider.id, cur);
    const model = keepModel
      ? cur
      : provider.defaultModel || provider.models[0] || null;
    set({
      activeProviderId: id,
      activeModel: model,
      apiConfig: {
        ...get().apiConfig,
        provider: provider.name,
        baseUrl: provider.baseUrl,
        apiKey: provider.apiKey,
        model: model || "",
      },
    });
    import("@/lib/persist").then(({ persistence }) => {
      persistence.saveSetting("activeProviderId", id);
      if (model) persistence.saveSetting("activeModel", model);
    });
  },

  upsertProvider: (input) => {
    const id = input.id || generateId();
    const providers = get().providers;
    const exists = providers.some((p) => p.id === id);
    const next = exists
      ? providers.map((p) => (p.id === id ? { ...p, ...input, id } : p))
      : [...providers, { ...input, id }];
    set({ providers: next });
    // If nothing is selected yet, auto-pick this provider's default model.
    if (!get().activeModel && next.length > 0) {
      const idx = exists
        ? providers.findIndex((p) => p.id === id)
        : next.length - 1;
      const def = next[idx];
      const firstModel = def?.models?.[0];
      if (firstModel) get().setActiveModel(firstModel);
      else if (def && !get().activeProviderId)
        set({ activeProviderId: def.id });
    }
    import("@/lib/persist").then(({ persistence }) => {
      persistence.saveSetting("providers", next);
    });
    return id;
  },

  removeProvider: (id) => {
    const providers = get().providers.filter((p) => p.id !== id);
    set({ providers });
    const active = get().activeModel;
    const activeStillValid =
      !!active && providers.some((p) => p.models.includes(active));
    if (activeStillValid) {
      // The model survived in another provider — re-anchor activeProviderId to it.
      const owner = providers.find((p) => p.models.includes(active!));
      if (owner && get().activeProviderId !== owner.id)
        set({ activeProviderId: owner.id });
    } else {
      const first = providers[0];
      if (first?.models?.length) get().setActiveModel(first.models[0]);
      else set({ activeModel: null, activeProviderId: null });
    }
    import("@/lib/persist").then(({ persistence }) => {
      persistence.saveSetting("providers", providers);
    });
  },

  onModelSwitched: (model) => {
    // 1) Re-resolve apiConfig for the new model (Helix will use the new key).
    get().setActiveModel(model);
    // 2) Interrupt any in-flight session so the next prompt is built fresh.
    //    (use-helix detects the apiConfig hash change on next send → invalidate + repush.)
    // 3) Persist the switch (apiConfig + apiHistory + activeModel). This path is
    //    reached by the helix-layout bridge for OUT-OF-BAND switches (helix-ui
    //    ModelSelector), which otherwise never call persistToStorage — leaving a
    //    restart with an apiHistory that doesn't contain the newly-selected model.
    import("@/lib/persist").then(({ persistence }) => {
      const s = get();
      persistence.saveSetting("apiHistory", s.apiHistory);
      persistence.saveSetting("apiConfig", s.apiConfig);
      persistence.saveSetting("activeModel", s.activeModel);
      persistence.saveSetting("activeProviderId", s.activeProviderId);
    });
  },
});
